export type VorlageTemplate = {
  id: string;
  slug: string;
  companyId?: string | null;
  sourceTemplateId?: string | null;
  title: string;
  description: string;
  categoryKey: string;
  categoryLabel: string;
  language: string;
  outputType: string;
  content: string;
  variables: string[];
  tags: string[];
  isStandard: boolean;
  isProtected: boolean;
  version: number;
  usageCount: number;
  favorite: boolean;
  updatedAt: string;
};

type CategoriesResponse = {
  ok: true;
  totalStandard: number;
  categories: VorlageCategory[];
};

type ListResponse = {
  ok: true;
  total: number;
  page: number;
  pageSize: number;
  pages: number;
  templates: VorlageTemplate[];
};

type TemplateResponse = {
  ok: true;
  template: VorlageTemplate;
};

type CompileResponse = {
  ok: true;
  title: string;
  compiledContent: string;
  values: Record<string, string>;
};

function getAuthToken(): string | null {
  const keys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc.auth.token",
    "rlc_mobile_token",
  ];
  for (const key of keys) {
    const value = localStorage.getItem(key);
    if (value?.trim()) return value.trim();
  }
  try {
    const auth = JSON.parse(localStorage.getItem("rlc_auth") || "null") as {
      token?: string;
      accessToken?: string;
    } | null;
    return auth?.token || auth?.accessToken || null;
  } catch {
    return null;
  }
}

function authHeaders(json = false): Record<string, string> {
  const token = getAuthToken();
  return {
    Accept: "application/json",
    ...(json ? { "Content-Type": "application/json" } : {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function request<T>(
  path: string,
  init: RequestInit = {}
): Promise<T> {
  const response = await fetch(apiUrl(path), {
    credentials: "include",
    ...init,
    headers: {
      ...authHeaders(Boolean(init.body)),
      ...(init.headers as Record<string, string> | undefined),
    },
  });
  const payload = (await response.json().catch(() => null)) as
    | (T & { error?: string })
    | null;
  if (!response.ok || !payload) {
    throw new Error(payload?.error || `Vorlagen-API Fehler (${response.status})`);
  }
  return payload;
}

export function fetchVorlageCategories(): Promise<CategoriesResponse> {
  return request<CategoriesResponse>("/api/vorlagen/categories");
}

export function fetchVorlagen(filters: {
  search?: string;
  category?: string;
  favorites?: boolean;
  page?: number;
  pageSize?: number;
}): Promise<ListResponse> {
  const query = new URLSearchParams();
  if (filters.search) query.set("search", filters.search);
  if (filters.category) query.set("category", filters.category);
  if (filters.favorites) query.set("favorites", "true");
  query.set("page", String(filters.page || 1));
  query.set("pageSize", String(filters.pageSize || 48));
  return request<ListResponse>(`/api/vorlagen?${query.toString()}`);
}

