  const pos = String(r.posNr || "").trim();
  const text = String(r.kurztext || "").trim();

  if (pos && text) return `Pos. ${pos} – ${text.slice(0, 70)}`;
  if (pos) return `Pos. ${pos}`;
  if (text) return text.slice(0, 80);

  return String(r.id || "Position");
}

