  function normalizeNavigationText(value: string): string {
    return String(value || "").
    toLowerCase().
    normalize("NFD").
    replace(/[\u0300-\u036f]/g, "").
    replace(/ß/g, "ss").
    replace(/ä/g, "ae").
    replace(/ö/g, "oe").
    replace(/ü/g, "ue").
    replace(/[^a-z0-9]+/g, " ").
    replace(/\s+/g, " ").
    trim();
  }

