    );
    if (lvStats.missingUnits)
    warnings.push(`${lvStats.missingUnits} Position(en) ohne Einheit.`);
    if (lvStats.missingQty)
    warnings.push(
      `${lvStats.missingQty} Position(en) ohne Menge oder mit Menge 0.`
    );
