    totalSize,
    openTasks,
    eventsNext7,
  };
}

function resetDemo() {
  state = createDemoState();
  notify();
}

/* ------------------------------- Hook React ------------------------------ */

function useBuro<T>(selector: (s: BuroState) => T): T {
  const [, force] = useReducer((x: number) => x + 1, 0);

  useEffect(() => {
    return subscribe(() => {
      force();
    });
  }, []);

  return selector(state);
}

