// Kleiner Mock-Speicher für CAD Import / Export / Dokumente
// Später wird hier API-Anbindung (DB, Backend) ergänzt

export type CADDocument = {
  id: string;
  name: string;
  type: string; // DWG, DXF, PDF, LandXML …
  uploadedAt: string; // ISO / yyyy-mm-dd
  sizeKb: number;
};

const STORAGE_KEY = "rlc.cad.store.v1";

const demoDocs: CADDocument[] = [
  {
    id: "1",
    name: "Bestandsplan.dwg",
    type: "DWG",
    uploadedAt: "2025-10-01",
    sizeKb: 1450,
  },
  {
    id: "2",
    name: "Trasse.xml",
    type: "LandXML",
    uploadedAt: "2025-10-02",
    sizeKb: 320,
  },
];

function safeLoad(): CADDocument[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return demoDocs;

    const parsed = JSON.parse(raw) as CADDocument[];
    if (!Array.isArray(parsed)) return demoDocs;

    return parsed;
  } catch {
    return demoDocs;
  }
}

function persist(next: CADDocument[]) {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(next));
  } catch {
    // ignore
  }
}

let docs: CADDocument[] = safeLoad();

function nextId() {
  return String(
    docs.reduce((max, d) => Math.max(max, Number(d.id) || 0), 0) + 1
  );
}

/* =========================
   READ
   ========================= */

export function loadDocs(): CADDocument[] {
  return [...docs];
}

// compatibilità col vecchio nome
export function loadDoc(): CADDocument[] {
  return loadDocs();
}

/* =========================
   CREATE
   ========================= */

export function saveDoc(doc: Omit<CADDocument, "id"> & { id?: string }): CADDocument {
  const newDoc: CADDocument = {
    ...doc,
    id: doc.id?.trim() || nextId(),
  };

  docs = [...docs, newDoc];
  persist(docs);
  return newDoc;
}

/* =========================
   UPDATE
   ========================= */

export function updateDoc(id: string, patch: Partial<CADDocument>): CADDocument | null {
  let updated: CADDocument | null = null;

  docs = docs.map((d) => {
    if (d.id !== id) return d;
    updated = { ...d, ...patch, id: d.id };
    return updated;
  });

  persist(docs);
  return updated;
}

/* =========================
   DELETE
   ========================= */

export function deleteDoc(id: string) {
  docs = docs.filter((d) => d.id !== id);
  persist(docs);
}

/* =========================
   RESET / REPLACE
   ========================= */

export function replaceDocs(next: CADDocument[]) {
  docs = Array.isArray(next) ? [...next] : [];
  persist(docs);
}

export function resetDocs() {
  docs = [...demoDocs];
  persist(docs);
}

import {
  listDocuments,
  initDocument,
  uploadFileDirect
} from "../api/files";


function webFileKind(file: File): "PDF" | "CAD" | "IMAGE" | "OTHER" {
  const name = String(file.name || "").toLowerCase();
  const mime = String(file.type || "").toLowerCase();

  if (name.endsWith(".pdf") || mime.includes("pdf")) return "PDF";
  if (name.endsWith(".dxf") || name.endsWith(".dwg")) return "CAD";
  if (mime.startsWith("image/") || /\.(png|jpe?g|gif|bmp|webp|svg)$/i.test(name)) {
    return "IMAGE";
  }
  return "OTHER";
}

export async function archiveWebFile(
  projectId: string,
  fileName: string,
  blob: Blob
): Promise<{ documentId: string; versioned: boolean } | null> {
  const pid = String(projectId || "").trim();
  const name = String(fileName || "").trim();

  if (!pid || !name || !blob) {
    console.warn("[Web:DMS] Projekt-ID, Dateiname oder Datei fehlt.");
    return null;
  }

  const file = new File(
    [blob],
    name,
    { type: blob.type || "application/octet-stream" }
  );

  const documents: any[] = await listDocuments(pid);
  const normalizedName = name.toLowerCase();

  const existing = (Array.isArray(documents) ? documents : []).find(
    (doc: any) =>
      !doc?.deletedAt &&
      String(doc?.name || "").trim().toLowerCase() === normalizedName
  );

  let documentId = String(existing?.id || "").trim();
  const versioned = Boolean(documentId);

  if (!documentId) {
    const created = await initDocument(pid, webFileKind(file) as any, name);
    documentId = String(created?.documentId || "").trim();

    if (!documentId) {
      throw new Error("Dokumenten-ID wurde nicht erzeugt.");
    }
  }

  await uploadFileDirect(documentId, file);

  console.log("[Web:DMS]", {
    projectId: pid,
    documentId,
    fileName: name,
    versioned
  });

  return { documentId, versioned };
}

export async function archiveWebPdf(
  projectId: string,
  fileName: string,
  blob: Blob
): Promise<{ documentId: string; versioned: boolean } | null> {
  const pid = String(projectId || "").trim();
  const name = String(fileName || "").trim();

  if (!pid || !name || !blob) {
    console.warn("[Web:DMS] Projekt-ID, Dateiname oder PDF fehlt.");
    return null;
  }

  const documents: any[] = await listDocuments(pid);

  const normalizedName = name.toLowerCase();

  const existing = (Array.isArray(documents) ? documents : []).find(
    (doc: any) =>
      !doc?.deletedAt &&
      String(doc?.name || "").trim().toLowerCase() === normalizedName
  );

  let documentId = String(existing?.id || "").trim();
  let versioned = Boolean(documentId);

  if (!documentId) {
    const created = await initDocument(
      pid,
      "PDF" as any,
      name
    );

    documentId = String(created?.documentId || "").trim();

    if (!documentId) {
      throw new Error("Dokumenten-ID wurde nicht erzeugt.");
    }

    versioned = false;
  }

  const file = new File(
    [blob],
    name,
    { type: "application/pdf" }
  );

  await uploadFileDirect(documentId, file);

  console.log("[Web:DMS]", {
    projectId: pid,
    documentId,
    fileName: name,
    versioned
  });

  return {
    documentId,
    versioned
  };
}

export async function archiveWebPdfFromUrl(
  projectId: string,
  fileName: string,
  url: string
) {
  const response = await fetch(url, {
    credentials: "include"
  });

  if (!response.ok) {
    throw new Error(
      `PDF konnte nicht für das DMS geladen werden (${response.status}).`
    );
  }

  const sourceBlob = await response.blob();

  const blob =
    sourceBlob.type === "application/pdf"
      ? sourceBlob
      : new Blob([sourceBlob], { type: "application/pdf" });

  return archiveWebPdf(
    projectId,
    fileName,
    blob
  );
}

// apps/web/src/lib/formulas.ts

/**
 * Sicuro: niente eval
 *
 * Supporta:
 * - numeri decimali
 * - + - * / ^ (% opzionale aggiunto)
 * - parentesi ()
 * - variabili: L, B, H, D, T, N, ecc.
 * - funzioni:
 *   round(x), ceil(x), floor(x),
 *   min(a,b,...), max(a,b,...), sum(a,b,...),
 *   abs(x), sqrt(x)
 * - prefisso opzionale "="
 * - unary minus / unary plus
 */

export type Vars = Record<string, number | undefined>;

type Token =
  | { t: "num"; v: number }
  | { t: "id"; v: string }
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "rp" }
  | { t: "comma" }
  | { t: "fn"; name: string; argc: number };

const isDigit = (c: string) => c >= "0" && c <= "9";

const isIdStart = (c: string) =>
  (c >= "a" && c <= "z") ||
  (c >= "A" && c <= "Z") ||
  c === "_" ||
  c === "$";

const isIdChar = (c: string) => isIdStart(c) || isDigit(c);

function isOpToken(tk?: Token): tk is Extract<Token, { t: "op" }> {
  return !!tk && tk.t === "op";
}

function isValueToken(tk?: Token): boolean {
  return !!tk && (tk.t === "num" || tk.t === "id" || tk.t === "rp" || tk.t === "fn");
}

/* =========================================================
   TOKENIZE
   ========================================================= */

export function tokenize(expr: string): Token[] {
  const s = expr.trim().replace(/^\s*=/, "");
  const out: Token[] = [];
  let i = 0;

  while (i < s.length) {
    const c = s[i];

    if (c === " " || c === "\t" || c === "\n" || c === "\r") {
      i++;
      continue;
    }

    if ("+-*/^%".includes(c)) {
      out.push({ t: "op", v: c });
      i++;
      continue;
    }

    if (c === "(") {
      out.push({ t: "lp" });
      i++;
      continue;
    }

    if (c === ")") {
      out.push({ t: "rp" });
      i++;
      continue;
    }

    if (c === ",") {
      out.push({ t: "comma" });
      i++;
      continue;
    }

    if (isDigit(c) || (c === "." && isDigit(s[i + 1] || ""))) {
      let j = i + 1;
      let dotCount = c === "." ? 1 : 0;

      while (j < s.length) {
        const ch = s[j];
        if (isDigit(ch)) {
          j++;
          continue;
        }
        if (ch === ".") {
          dotCount++;
          if (dotCount > 1) break;
          j++;
          continue;
        }
        break;
      }

      const raw = s.slice(i, j);
      const num = Number(raw);
      if (!Number.isFinite(num)) {
        throw new Error(`Ungültige Zahl: ${raw}`);
      }

      out.push({ t: "num", v: num });
      i = j;
      continue;
    }

    if (isIdStart(c)) {
      let j = i + 1;
      while (j < s.length && isIdChar(s[j])) j++;
      out.push({ t: "id", v: s.slice(i, j) });
      i = j;
      continue;
    }

    throw new Error(`Unerwartetes Zeichen: ${c}`);
  }

  return out;
}

/* =========================================================
   SHUNTING-YARD -> RPN
   ========================================================= */

const prec: Record<string, number> = {
  "+": 1,
  "-": 1,
  "*": 2,
  "/": 2,
  "%": 2,
  "^": 4,
  "u+": 5,
  "u-": 5,
};

const rightAssoc = new Set(["^", "u+", "u-"]);

type StackItem =
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "fnName"; name: string };

type FnFrame = {
  hasValue: boolean;
  commaCount: number;
};

export function toRPN(tokens: Token[]): Token[] {
  const out: Token[] = [];
  const st: StackItem[] = [];
  const fnFrames: FnFrame[] = [];

  let prev: Token | undefined;

  for (let i = 0; i < tokens.length; i++) {
    const tk = tokens[i];

    if (tk.t === "num") {
      out.push(tk);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = tk;
      continue;
    }

    if (tk.t === "id") {
      const next = tokens[i + 1];
      if (next?.t === "lp") {
        st.push({ t: "fnName", name: tk.v });
        prev = tk;
        continue;
      }

      out.push(tk);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = tk;
      continue;
    }

    if (tk.t === "lp") {
      const prevWasFnName = st.length > 0 && st[st.length - 1].t === "fnName";
      st.push({ t: "lp" });

      if (prevWasFnName) {
        fnFrames.push({
          hasValue: false,
          commaCount: 0,
        });
      }

      prev = tk;
      continue;
    }

    if (tk.t === "comma") {
      while (st.length && st[st.length - 1].t !== "lp") {
        const top = st.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!st.length) throw new Error("Unerwartetes Komma");

      if (!fnFrames.length) throw new Error("Komma außerhalb einer Funktion");

      fnFrames[fnFrames.length - 1].commaCount++;
      prev = tk;
      continue;
    }

    if (tk.t === "op") {
      let op = tk.v;

      const unary =
        !prev ||
        prev.t === "op" ||
        prev.t === "lp" ||
        prev.t === "comma";

      if (unary && (op === "+" || op === "-")) {
        op = op === "+" ? "u+" : "u-";
      }

      while (st.length) {
        const top = st[st.length - 1];
        if (top.t !== "op") break;

        const pTop = prec[top.v];
        const pCur = prec[op];
        const shouldPop = rightAssoc.has(op) ? pTop > pCur : pTop >= pCur;

        if (!shouldPop) break;
        out.push(st.pop() as Extract<StackItem, { t: "op" }>);
      }

      st.push({ t: "op", v: op });
      prev = { t: "op", v: op };
      continue;
    }

    if (tk.t === "rp") {
      while (st.length && st[st.length - 1].t !== "lp") {
        const top = st.pop()!;

if (!shouldPop) break;
        out.push(st.pop() as Extract<StackItem, { t: "op" }>);
      }

      st.push({ t: "op", v: op });
      prev = { t: "op", v: op };
      continue;
    }

    if (tk.t === "rp") {
      while (st.length && st[st.length - 1].t !== "lp") {
        const top = st.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!st.length) throw new Error("Klammern passen nicht");
      st.pop(); // remove lp

      if (st.length && st[st.length - 1].t === "fnName") {
        const fn = st.pop() as { t: "fnName"; name: string };
        const frame = fnFrames.pop();

        if (!frame) throw new Error("Funktionsfehler");

        const argc = frame.hasValue ? frame.commaCount + 1 : 0;
        out.push({ t: "fn", name: fn.name, argc });
        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      } else {
        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      }

      prev = tk;
      continue;
    }
  }

  while (st.length) {
    const top = st.pop()!;
    if (top.t === "lp" || top.t === "fnName") {
      throw new Error("Klammern passen nicht");
    }
    out.push(top);
  }

  return out;
}

/* =========================================================
   FUNCTIONS
   ========================================================= */

function callFn(name: string, args: number[]): number {
  switch (name.toLowerCase()) {
    case "round":
      return Math.round(args[0] ?? 0);
    case "ceil":
      return Math.ceil(args[0] ?? 0);
    case "floor":
      return Math.floor(args[0] ?? 0);
    case "abs":
      return Math.abs(args[0] ?? 0);
    case "sqrt":
      return Math.sqrt(args[0] ?? 0);
    case "min":
      return args.length ? Math.min(...args) : 0;
    case "max":
      return args.length ? Math.max(...args) : 0;
    case "sum":
      return args.reduce((a, b) => a + b, 0);
    default:
      throw new Error(`Unbekannte Funktion: ${name}`);
  }
}

/* =========================================================
   EVAL RPN
   ========================================================= */

export function evalRPN(rpn: Token[], vars: Vars): number {
  const st: number[] = [];

  for (const tk of rpn) {
    if (tk.t === "num") {
      st.push(tk.v);
      continue;
    }

    if (tk.t === "id") {
      const v = vars[tk.v];
      st.push(typeof v === "number" && Number.isFinite(v) ? v : 0);
      continue;
    }

    if (tk.t === "fn") {
      const args = tk.argc > 0 ? st.splice(-tk.argc, tk.argc) : [];
      st.push(callFn(tk.name, args));
      continue;
    }

    if (tk.t === "op") {
      if (tk.v === "u+") {
        const a = st.pop() ?? 0;
        st.push(+a);
        continue;
      }

      if (tk.v === "u-") {
        const a = st.pop() ?? 0;
        st.push(-a);
        continue;
      }

      const b = st.pop() ?? 0;
      const a = st.pop() ?? 0;

      switch (tk.v) {
        case "+":
          st.push(a + b);
          break;
        case "-":
          st.push(a - b);
          break;
        case "*":
          st.push(a * b);
          break;
        case "/":
          st.push(b === 0 ? 0 : a / b);
          break;
        case "%":
          st.push(b === 0 ? 0 : a % b);
          break;
        case "^":
          st.push(Math.pow(a, b));
          break;
        default:
          throw new Error(`Unbekannter Operator: ${tk.v}`);
      }
    }
  }

  const result = st.pop() ?? 0;
  return Number.isFinite(result) ? result : 0;
}

/* =========================================================
   PUBLIC API
   ========================================================= */

export function evaluateExpression(expr: string, vars: Vars): number {
  if (!expr || !expr.trim()) return 0;

  try {
    const rpn = toRPN(tokenize(expr));
    const val = evalRPN(rpn, vars);
    return Number.isFinite(val) ? val : 0;
  } catch {
    return 0;
  }
}

/* apps/web/src/lib/mengen/formulas.ts
   Mini parser sicuro con shunting-yard (niente eval).
   Supporta:
   - + - * / ^
   - parentesi ()
   - funzioni: SUM, AVG, MIN, MAX, ROUND(x,n), CEIL, FLOOR, ABS, SQRT
   - costanti: PI, E
   - variabili: { L: 2.5, W: 3, row_1: 12, ... }
   - unary minus / unary plus
*/

export type NumMap = Record<string, number>;

type Token =
  | { t: "num"; v: number }
  | { t: "id"; v: string }
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "rp" }
  | { t: "comma" }
  | { t: "fn"; name: string; argc: number };

const prec: Record<string, number> = {
  "+": 1,
  "-": 1,
  "*": 2,
  "/": 2,
  "^": 4,
  "u+": 5,
  "u-": 5,
};

const rightAssoc = new Set(["^", "u+", "u-"]);

const isDigit = (c: string) => c >= "0" && c <= "9";
const isAlpha = (c: string) => /[A-Za-z_]/.test(c);
const isAlphaNum = (c: string) => /[A-Za-z0-9_]/.test(c);

function tokenize(expr: string): Token[] {
  const s = expr.trim().replace(/^\s*=/, "");
  const out: Token[] = [];
  let i = 0;

  while (i < s.length) {
    const c = s[i];

    if (/\s/.test(c)) {
      i++;
      continue;
    }

    if ("+-*/^".includes(c)) {
      out.push({ t: "op", v: c });
      i++;
      continue;
    }

    if (c === "(") {
      out.push({ t: "lp" });
      i++;
      continue;
    }

    if (c === ")") {
      out.push({ t: "rp" });
      i++;
      continue;
    }

    if (c === ",") {
      out.push({ t: "comma" });
      i++;
      continue;
    }

    if (isDigit(c) || c === ".") {
      let j = i;
      let dotCount = 0;

      while (j < s.length) {
        const ch = s[j];
        if (isDigit(ch)) {
          j++;
          continue;
        }
        if (ch === ".") {
          dotCount++;
          if (dotCount > 1) break;
          j++;
          continue;
        }
        break;
      }

      const raw = s.slice(i, j);
      const v = Number(raw);
      if (!Number.isFinite(v)) {
        throw new Error(`Ungültige Zahl: ${raw}`);
      }

      out.push({ t: "num", v });
      i = j;
      continue;
    }

    if (isAlpha(c)) {
      let j = i + 1;
      while (j < s.length && isAlphaNum(s[j])) j++;
      out.push({ t: "id", v: s.slice(i, j).toUpperCase() });
      i = j;
      continue;
    }

    throw new Error(`Carattere non valido: '${c}'`);
  }

  return out;
}

type StackItem =
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "fnName"; name: string };

type FnFrame = {
  hasValue: boolean;
  commaCount: number;
};

function toRPN(tokens: Token[]): Token[] {
  const out: Token[] = [];
  const st: StackItem[] = [];
  const fnFrames: FnFrame[] = [];

  let prev: Token | undefined;

  for (let i = 0; i < tokens.length; i++) {
    const tk = tokens[i];

    if (tk.t === "num") {
      out.push(tk);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = tk;
      continue;
    }

    if (tk.t === "id") {
      const next = tokens[i + 1];
      if (next?.t === "lp") {
        st.push({ t: "fnName", name: tk.v });
        prev = tk;
        continue;
      }

      out.push(tk);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = tk;
      continue;
    }

    if (tk.t === "lp") {
      const prevWasFn = st.length > 0 && st[st.length - 1].t === "fnName";
      st.push({ t: "lp" });

      if (prevWasFn) {
        fnFrames.push({
          hasValue: false,
          commaCount: 0,
        });
      }

      prev = tk;
      continue;
    }

    if (tk.t === "comma") {
      while (st.length && st[st.length - 1].t !== "lp") {
        const top = st.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!st.length) throw new Error("Separatore ',' fuori posto");
      if (!fnFrames.length) throw new Error("Separatore ',' fuori funzione");

      fnFrames[fnFrames.length - 1].commaCount++;
      prev = tk;
      continue;
    }

    if (tk.t === "op") {
      let op = tk.v;
      const unary =
        !prev || prev.t === "op" || prev.t === "lp" || prev.t === "comma";

      if (unary && (op === "+" || op === "-")) {
        op = op === "+" ? "u+" : "u-";
      }

      while (st.length) {
        const top = st[st.length - 1];
        if (top.t !== "op") break;

        const pTop = prec[top.v];
        const pCur = prec[op];
        const shouldPop = rightAssoc.has(op) ? pTop > pCur : pTop >= pCur;

        if (!shouldPop) break;
        out.push(st.pop() as { t: "op"; v: string });
      }

      st.push({ t: "op", v: op });
      prev = { t: "op", v: op };
      continue;
    }

    if (tk.t === "rp") {
      while (st.length && st[st.length - 1].t !== "lp") {
        const top = st.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!st.length) throw new Error("Parentesi non bilanciate");
      st.pop();

      if (st.length && st[st.length - 1].t === "fnName") {
        const fn = st.pop() as { t: "fnName"; name: string };
        const frame = fnFrames.pop();
        if (!frame) throw new Error("Funktionsfehler");

        const argc = frame.hasValue ? frame.commaCount + 1 : 0;
        out.push({ t: "fn", name: fn.name, argc });

        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      } else {
        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      }

      prev = tk;
      continue;
    }
  }

  while (st.length) {
    const x = st.pop()!;
    if (x.t === "lp" || x.t === "fnName") throw new Error("Parentesi non bilanciate");

} else {
        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      }

      prev = tk;
      continue;
    }
  }

  while (st.length) {
    const x = st.pop()!;
    if (x.t === "lp" || x.t === "fnName") throw new Error("Parentesi non bilanciate");
    out.push(x);
  }

  return out;
}

function callFn(name: string, args: number[]): number {
  switch (name) {
    case "SUM":
      return args.reduce((a, b) => a + b, 0);

    case "AVG":
      return args.length ? args.reduce((a, b) => a + b, 0) / args.length : 0;

    case "MIN":
      return args.length ? Math.min(...args) : 0;

    case "MAX":
      return args.length ? Math.max(...args) : 0;

    case "ROUND": {
      const x = args[0] ?? 0;
      const n = Math.trunc(args[1] ?? 0);
      const m = Math.pow(10, n);
      return Math.round(x * m) / m;
    }

    case "CEIL":
      return Math.ceil(args[0] ?? 0);

    case "FLOOR":
      return Math.floor(args[0] ?? 0);

    case "ABS":
      return Math.abs(args[0] ?? 0);

    case "SQRT":
      return Math.sqrt(args[0] ?? 0);

    default:
      throw new Error(`Funzione non supportata: ${name}`);
  }
}

function evalRPN(rpn: Token[], vars: NumMap): number {
  const stack: number[] = [];
  const constants: NumMap = { PI: Math.PI, E: Math.E };

  for (const tk of rpn) {
    if (tk.t === "num") {
      stack.push(tk.v);
      continue;
    }

    if (tk.t === "id") {
      const key = tk.v.toUpperCase();
      if (key in vars) {
        stack.push(vars[key]);
      } else if (key in constants) {
        stack.push(constants[key]);
      } else {
        throw new Error(`Variabile sconosciuta: ${tk.v}`);
      }
      continue;
    }

    if (tk.t === "fn") {
      const args = tk.argc > 0 ? stack.splice(-tk.argc, tk.argc) : [];
      stack.push(callFn(tk.name, args));
      continue;
    }

    if (tk.t === "op") {
      if (tk.v === "u+") {
        const a = stack.pop();
        if (a == null) throw new Error("Argomento mancante");
        stack.push(+a);
        continue;
      }

      if (tk.v === "u-") {
        const a = stack.pop();
        if (a == null) throw new Error("Argomento mancante");
        stack.push(-a);
        continue;
      }

      const b = stack.pop();
      const a = stack.pop();
      if (a == null || b == null) throw new Error("Argomenti operatori insufficienti");

      switch (tk.v) {
        case "+":
          stack.push(a + b);
          break;
        case "-":
          stack.push(a - b);
          break;
        case "*":
          stack.push(a * b);
          break;
        case "/":
          stack.push(b === 0 ? NaN : a / b);
          break;
        case "^":
          stack.push(Math.pow(a, b));
          break;
        default:
          throw new Error(`Operatore sconosciuto: ${tk.v}`);
      }
    }
  }

  if (stack.length !== 1) throw new Error("Espressione non valida");
  return stack[0];
}

export function evaluateExpression(expr: string, vars: NumMap = {}): number {
  if (!expr || !expr.trim()) return 0;

  const normalizedVars: NumMap = Object.fromEntries(
    Object.entries(vars).map(([k, v]) => [k.toUpperCase(), Number(v)])
  );

  const tokens = tokenize(expr);
  const rpn = toRPN(tokens);
  const res = evalRPN(rpn, normalizedVars);

  return Number.isFinite(res) ? res : NaN;
}

import type { jsPDF } from "jspdf";
import { apiUrl } from "../apiBase";
import { archiveWebPdf } from "../dmsArchive";

export type CompanyPdfData = {
  id?: string;
  code: string;
  name: string;
  address: string;
  phone: string;
  email: string;
  logoDataUrl: string | null;
};

let cachedCompany: CompanyPdfData | null = null;
let pendingCompany: Promise<CompanyPdfData | null> | null = null;

function getToken(): string {
  try {
    return (
      localStorage.getItem("rlc_token") ||
      JSON.parse(localStorage.getItem("rlc_auth") || "{}")?.token ||
      ""
    );
  } catch {
    return "";
  }
}

function authHeaders(): Record<string, string> {
  const token = getToken();

  return {
    Accept: "application/json",
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function blobToPngDataUrl(blob: Blob): Promise<string | null> {
  return new Promise((resolve) => {
    const objectUrl = URL.createObjectURL(blob);
    const image = new Image();

    image.onload = () => {
      try {
        const canvas = document.createElement("canvas");

        canvas.width = Math.max(
          1,
          image.naturalWidth || image.width,
        );

        canvas.height = Math.max(
          1,
          image.naturalHeight || image.height,
        );

        const ctx = canvas.getContext("2d");

        if (!ctx) {
          URL.revokeObjectURL(objectUrl);
          resolve(null);
          return;
        }

        ctx.drawImage(image, 0, 0);

        const dataUrl = canvas.toDataURL("image/png");

        URL.revokeObjectURL(objectUrl);
        resolve(dataUrl);
      } catch {
        URL.revokeObjectURL(objectUrl);
        resolve(null);
      }
    };

    image.onerror = () => {
      URL.revokeObjectURL(objectUrl);
      resolve(null);
    };

    image.src = objectUrl;
  });
}

export async function loadCompanyPdfData(
  force = false,
): Promise<CompanyPdfData | null> {
  if (!force && cachedCompany) return cachedCompany;
  if (!force && pendingCompany) return pendingCompany;

  pendingCompany = (async () => {
    try {
      const headerResponse = await fetch(
        apiUrl("/api/company/header"),
        {
          method: "GET",
          credentials: "include",
          headers: authHeaders(),
        },
      );

      if (!headerResponse.ok) {
        throw new Error(
          `Firmendaten HTTP ${headerResponse.status}`,
        );
      }

      const payload = await headerResponse.json();
      const company = payload?.company;

      if (!company) return null;

      let logoDataUrl: string | null = null;

      if (company.logoPath || company.logoUrl) {
        const logoResponse = await fetch(
          apiUrl("/api/company/logo"),
          {
            method: "GET",
            credentials: "include",
            headers: authHeaders(),
          },
        );

        if (logoResponse.ok) {
          logoDataUrl = await blobToPngDataUrl(
            await logoResponse.blob(),
          );
        }
      }

      cachedCompany = {
        id: String(company.id || ""),
        code: String(company.code || ""),
        name: String(company.name || ""),
        address: String(company.address || ""),
        phone: String(company.phone || ""),
        email: String(company.email || ""),
        logoDataUrl,
      };

      return cachedCompany;
    } catch (error) {
      console.error(
        "Firmendaten für PDF konnten nicht geladen werden:",
        error,
      );

      return null;
    } finally {
      pendingCompany = null;
    }
  })();

  return pendingCompany;
}

export function clearCompanyPdfCache(): void {
  cachedCompany = null;
  pendingCompany = null;
}

export function drawCompanyPdfHeader(
  doc: jsPDF,
  company: CompanyPdfData | null,
  options?: {
    top?: number;
    left?: number;
    right?: number;
    height?: number;
    showCode?: boolean;
    drawLine?: boolean;
  },
): number {
  const top = options?.top ?? 8;
  const left = options?.left ?? 14;
  const right = options?.right ?? 14;
  const height = options?.height ?? 22;
  const showCode = options?.showCode ?? true;
  const drawLine = options?.drawLine ?? true;

  const pageWidth = doc.internal.pageSize.getWidth();
  const textRight = pageWidth - right;

  if (!company) {
    return top + height;
  }

  if (company.logoDataUrl) {
    try {
      const maxWidth = 34;
      const maxHeight = 16;

      doc.addImage(
        company.logoDataUrl,
        "PNG",
        left,
        top,
        maxWidth,
        maxHeight,
        undefined,
        "FAST",
      );
    } catch (error) {
      console.warn(
        "Firmenlogo konnte nicht in PDF eingefügt werden:",
        error,
      );
    }
  }

  doc.setTextColor(15, 23, 42);
  doc.setFont("helvetica", "bold");
  doc.setFontSize(10);

  doc.text(
    company.name || "Firma",
    textRight,
    top + 4,
    { align: "right" },
  );

  doc.setFont("helvetica", "normal");
  doc.setFontSize(7.5);
  doc.setTextColor(71, 85, 105);

  const lines = [
    company.address,
    [company.phone, company.email]
      .filter(Boolean)
      .join(" · "),
    showCode && company.code
      ? `Firmencode: ${company.code}`
      : "",
  ].filter(Boolean);

  lines.forEach((line, index) => {
    doc.text(
      line,
      textRight,
      top + 9 + index * 4,
      { align: "right" },
    );
  });

  if (drawLine) {
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.25);

    doc.line(
      left,

textRight,
      top + 9 + index * 4,
      { align: "right" },
    );
  });

  if (drawLine) {
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.25);

    doc.line(
      left,
      top + height,
      pageWidth - right,
      top + height,
    );
  }

  return top + height + 5;
}

export async function addCompanyPdfHeader(
  doc: jsPDF,
  options?: Parameters<typeof drawCompanyPdfHeader>[2],
): Promise<{
  company: CompanyPdfData | null;
  contentStartY: number;
}> {
  const company = await loadCompanyPdfData();

  const contentStartY = drawCompanyPdfHeader(
    doc,
    company,
    options,
  );

  return {
    company,
    contentStartY,
  };
}

const preparedDocuments = new WeakSet<jsPDF>();

/**
 * Disegna l'intestazione aziendale su tutte le pagine già create.
 * È il punto centrale obbligatorio per ogni PDF RLC.
 */
export async function applyCompanyPdfHeaderToAllPages(
  doc: jsPDF,
): Promise<void> {
  if (preparedDocuments.has(doc)) return;

  const company = await loadCompanyPdfData();

  const currentPage = Number((doc as any).getCurrentPageInfo?.()?.pageNumber || doc.getNumberOfPages());
  const pageCount = doc.getNumberOfPages();

  for (let page = 1; page <= pageCount; page += 1) {
    doc.setPage(page);

    const pageWidth = doc.internal.pageSize.getWidth();
    const unitScale = pageWidth > 400 ? 2.834645669 : 1;
    const left = 8 * unitScale;
    const right = 8 * unitScale;
    const top = 3 * unitScale;
    const headerHeight = 13 * unitScale;
    const pageHeight = doc.internal.pageSize.getHeight();
    const footerY = pageHeight - 6 * unitScale;

    if (company) {
      // Fondo uniforme: l'intestazione resta leggibile anche su PDF costruiti da canvas.
      doc.setFillColor(255, 255, 255);
      doc.rect(0, 0, pageWidth, headerHeight + 3 * unitScale, "F");

      if (company.logoDataUrl) {
        try {
          doc.addImage(
            company.logoDataUrl,
            "PNG",
            left,
            top,
            25 * unitScale,
            10 * unitScale,
            undefined,
            "FAST",
          );
        } catch (error) {
          console.warn("Firmenlogo konnte nicht in PDF eingefügt werden:", error);
        }
      }

      const textRight = pageWidth - right;

      doc.setTextColor(15, 23, 42);
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8.5 * unitScale);
      doc.text(company.name || "Firma", textRight, top + 3.5 * unitScale, {
        align: "right",
      });

      doc.setFont("helvetica", "normal");
      doc.setFontSize(6.2 * unitScale);
      doc.setTextColor(71, 85, 105);

      const contact = [company.phone, company.email].filter(Boolean).join(" · ");
      const lines = [company.address, contact].filter(Boolean);

      lines.forEach((line, index) => {
        doc.text(line, textRight, top + (7 + index * 3.2) * unitScale, {
          align: "right",
        });
      });

      doc.setDrawColor(203, 213, 225);
      doc.setLineWidth(0.2 * unitScale);
      doc.line(
        left,
        headerHeight + 2 * unitScale,
        pageWidth - right,
        headerHeight + 2 * unitScale,
      );
    }

    // Piè di pagina identico in tutti i moduli Web.
    doc.setFillColor(255, 255, 255);
    doc.rect(0, pageHeight - 10 * unitScale, pageWidth, 10 * unitScale, "F");
    doc.setDrawColor(203, 213, 225);
    doc.setLineWidth(0.2 * unitScale);
    doc.line(left, pageHeight - 9 * unitScale, pageWidth - right, pageHeight - 9 * unitScale);
    doc.setFont("helvetica", "normal");
    doc.setFontSize(6.2 * unitScale);
    doc.setTextColor(100, 116, 139);
    doc.text(
      company?.name || "RLC Bausoftware",
      left,
      footerY,
    );
    doc.text(
      `Seite ${page}/${pageCount}`,
      pageWidth - right,
      footerY,
      { align: "right" },
    );
  }

  doc.setPage(Math.min(currentPage, pageCount));
  preparedDocuments.add(doc);
}

export function savePdfWithCompanyHeader(
  doc: jsPDF,
  fileName: string,
  projectId?: string | null,
): void {
  const preview = reservePdfPreview(fileName);
  const dmsProjectId = String(projectId || "").trim();

  void applyCompanyPdfHeaderToAllPages(doc)
    .then(() => {
      const blob = doc.output("blob");

      // L'anteprima non aspetta mai il DMS e non viene bloccata da un errore DMS.
      openPdfBlobPreview(blob, fileName, preview);

      if (dmsProjectId) {
        void archiveWebPdf(dmsProjectId, fileName, blob).catch((error) => {
          console.error("[Web PDF:DMS] Archivierung fehlgeschlagen:", error);
        });
      }
    })
    .catch((error) => {
      console.error("PDF-Firmenkopf konnte nicht erzeugt werden:", error);
      openPdfBlobPreview(doc.output("blob"), fileName, preview);
    });
}

export async function outputPdfBlobWithCompanyHeader(
  doc: jsPDF,
): Promise<Blob> {
  await applyCompanyPdfHeaderToAllPages(doc);
  return doc.output("blob");
}

