import * as pdfjsLib from "pdfjs-dist";
import pdfjsWorker from "pdfjs-dist/build/pdf.worker.min.js?url";

pdfjsLib.GlobalWorkerOptions.workerSrc = pdfjsWorker;

/* =========================================================
   PDF TEXT READ
   ========================================================= */

type TextItem = {
  str?: string;
};

function isPdfFile(file: File) {
  return (
    file.type === "application/pdf" || file.name.toLowerCase().endsWith(".pdf")
  );
}

export async function readPdfText(file: File): Promise<string> {
  if (!file) {
    throw new Error("Keine PDF-Datei übergeben.");
  }

  if (!isPdfFile(file)) {
    throw new Error("Ungültige Datei. Bitte eine PDF-Datei auswählen.");
  }

  try {
    const buffer = await file.arrayBuffer();
    const array = new Uint8Array(buffer);

    const loadingTask = pdfjsLib.getDocument({
      data: array,
      useWorkerFetch: false,
      isEvalSupported: false,
    } as any);

    const doc = await loadingTask.promise;

    const pages: string[] = [];

    for (let p = 1; p <= doc.numPages; p++) {
      const page = await doc.getPage(p);
      const content = await page.getTextContent();

      const items = (content.items || []) as TextItem[];
      const line = items
        .map((it) => (typeof it?.str === "string" ? it.str : ""))
        .filter(Boolean)
        .join(" ");

      if (line.trim()) {
        pages.push(line.trim());
      }
    }

    const text = pages
      .join("\n")
      .replace(/[ \t]+/g, " ")
      .replace(/\n{2,}/g, "\n")
      .trim();

    return text;
  } catch (err: any) {
    throw new Error(
      err?.message || "PDF konnte nicht gelesen werden."
    );
  }
}

import { API_BASE } from "./apiBase";
// apps/web/src/lib/recipesApi.ts

function apiUrl(path: string): string {
  const p = path.startsWith("/") ? path : `/${path}`;
  return API_BASE ? `${API_BASE}${p}` : p;
}

function withQuery(
  path: string,
  params?: Record<string, string | number | boolean | null | undefined>
) {
  if (!params) return path;

  const qs = new URLSearchParams();
  for (const [key, value] of Object.entries(params)) {
    if (value === undefined || value === null) continue;
    qs.set(key, String(value));
  }

  const s = qs.toString();
  return s ? `${path}?${s}` : path;
}

async function http<T>(path: string, init: RequestInit = {}): Promise<T> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);

  try {
    const isFormData =
      typeof FormData !== "undefined" && init.body instanceof FormData;

    const res = await fetch(apiUrl(path), {
      credentials: "include",
      signal: controller.signal,
      ...init,
      headers: {
        ...(isFormData ? {} : { "Content-Type": "application/json" }),
        ...(init.headers || {}),
      },
    });

    const text = await res.text();

    let data: unknown = null;
    try {
      data = text ? JSON.parse(text) : null;
    } catch {
      data = text;
    }

    if (!res.ok) {
      const obj =
        typeof data === "object" && data !== null
          ? (data as Record<string, unknown>)
          : null;

      const msg =
        (obj?.error as string) ||
        (obj?.message as string) ||
        text ||
        `HTTP ${res.status} ${res.statusText}`;

      throw new Error(msg);
    }

    const obj =
      typeof data === "object" && data !== null
        ? (data as Record<string, unknown>)
        : null;

    if (obj?.ok === false) {
      throw new Error(
        (obj?.error as string) ||
          (obj?.message as string) ||
          "Backend Fehler"
      );
    }

    return data as T;
  } catch (err: any) {
    if (err?.name === "AbortError") {
      throw new Error("Timeout API");
    }
    throw err;
  } finally {
    clearTimeout(timeout);
  }
}

