type AuthUser = {
  id: string;
  email: string;
  appRole?: string | null;
  emailVerifiedAt?: string | null;
  companyId?: string | null;
  companyRole?: string | null;
};

type AuthResponse = {
  ok?: boolean;
  token?: string;
