function getRlcAuthToken() {
  const keys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc_auth_token"
  ];

  for (const storage of [localStorage, sessionStorage]) {
    for (const key of keys) {
      const value = storage.getItem(key);

      if (value && value.trim()) {
        return value.trim();
      }
    }
  }

  return "";
}

async function rlcFetch(
  input: RequestInfo | URL,
  init: RequestInit = {}
) {
  const headers = new Headers(init.headers || {});
  const token = getRlcAuthToken();

  if (token) {
    headers.set("Authorization", `Bearer ${token}`);
  }

  if (
    init.body &&
    !(init.body instanceof FormData) &&
    !headers.has("Content-Type")
  ) {
    headers.set("Content-Type", "application/json");
  }

  return window.fetch(input, {
    ...init,
    headers,
    credentials: "include"
  });
}

function apiUrl(path: string): string {
  const p = path.startsWith("/") ? path : `/${path}`;
  return API_BASE ? `${API_BASE}${p}` : p;
}

type AbschlagStatus = "Entwurf" | "Freigegeben" | "Gebucht";

type AbschlagRow = {
  lvPos: string;
  kurztext: string;
  einheit: string;
  qty: number;
  ep: number;
  total: number;
};

type AbschlagItem = {
  id: string;
  projectId: string;
  nr: number;
  date: string;
  title?: string;
  netto: number;
  mwst: number;
  brutto: number;
  status: AbschlagStatus;
  rows: AbschlagRow[];
};

const fmtEUR = (v: number) =>
new Intl.NumberFormat("de-DE", {
  style: "currency",
  currency: "EUR"
}).format(safeNum(v));

function safeTrim(v: unknown) {
  return String(v ?? "").trim();
}

function safeNum(x: unknown, fallback = 0) {
  if (x === null || x === undefined || x === "") return fallback;
  const normalized =
  typeof x === "string" ? x.replace(/\s/g, "").replace(",", ".") : x;
  const n = Number(normalized);
  return Number.isFinite(n) ? n : fallback;
}

async function apiJson<T>(path: string, init?: RequestInit): Promise<T> {
  const headers = {
    "Content-Type": "application/json",
    ...(init?.headers || {})
  };

  const res = await rlcFetch(apiUrl(path), {
    ...init,
    headers,
    credentials: "include"
  });

  if (!res.ok) {
    const txt = await res.text().catch(() => "");
    throw new Error(txt || `Server-Fehler (${res.status})`);
  }

  return (await res.json()) as T;
}

function recalc(a: AbschlagItem): AbschlagItem {
  const mwst = safeNum(a.mwst, 19);
  const rows = Array.isArray(a.rows) ? a.rows : [];

  const normalizedRows: AbschlagRow[] = rows.map((r) => {
    const qty = safeNum(r.qty);
    const ep = safeNum(r.ep);
    return {
      lvPos: safeTrim(r.lvPos),
      kurztext: safeTrim(r.kurztext),
      einheit: safeTrim(r.einheit) || "m",
      qty,
      ep,
      total: qty * ep
    };
  });

  const netto = normalizedRows.reduce((sum, r) => sum + safeNum(r.total), 0);
  const brutto = netto * (1 + mwst / 100);

  return {
    ...a,
    id: safeTrim(a.id),
    projectId: safeTrim(a.projectId),
    nr: safeNum(a.nr),
    date: safeTrim(a.date),
    title: safeTrim(a.title),
    mwst,
    rows: normalizedRows,
    netto,
    brutto
  };
}

