export default function Kassenbuch() {
  const [rows, setRows] = useState<any[]>([]);
  const [error, setError] = useState("");

  const [form, setForm] = useState({
    date: new Date().toISOString().slice(0,10),
    text: "",
    account: "1000",
    contraAccount: "1200",
    amount: 0
  });

  const load = async () => {
    try {
      setError("");
      const data = await accountingApi("/api/accounting/ledger");
      setRows(data.items || []);
    } catch (e:any) {
      setError(e?.message || "Fehler");
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const save = async () => {
    await accountingApi("/api/accounting/ledger", {
      method: "POST",
      body: JSON.stringify(form)
    });

    setForm({
      date: new Date().toISOString().slice(0,10),
      text: "",
      account: "1000",
      contraAccount: "1200",
