                </td>
              </tr>
            );
          })}

          {!rows.length && (
            <tr>
              <td colSpan={8}>Keine Buchungen vorhanden.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

import React, { useEffect, useMemo, useState } from "react";
import { useProject } from "../../store/useProject";
import { apiUrl } from "../../lib/apiBase";
import { accountingApi, euro, getAccountingProject } from "./accountingApi";
import "./styles.css";

const num = (value: unknown) => Number.isFinite(Number(value)) ? Number(value) : 0;
const clean = (value: unknown) => String(value ?? "").trim() || "OHNE-KOSTENSTELLE";

function authHeaders(): Record<string, string> {
  try {
    for (const key of ["rlc_token", "token", "authToken", "accessToken", "rlc_auth_token"]) {
      const value = localStorage.getItem(key) || sessionStorage.getItem(key);
      if (value) return { Authorization: `Bearer ${value}` };
    }
  } catch {}
  return {};
}

async function apiJson(path: string, init: RequestInit = {}) {
  const headers = new Headers(init.headers || {});
  headers.set("Accept", "application/json");
  headers.set("Content-Type", "application/json");
  for (const [key, value] of Object.entries(authHeaders())) headers.set(key, value);

  const response = await fetch(apiUrl(path), {
    ...init,
    credentials: "include",
    headers
  });
  const payload = await response.json().catch(() => null);
  if (!response.ok || payload?.ok === false) throw new Error(payload?.error || `HTTP ${response.status}`);
  return payload || {};
}

export default function Kostenstellen() {
  const { getSelectedProject } = useProject();
  const project = getSelectedProject?.();
  const projectId = String(project?.code || project?.id || getAccountingProject() || "").trim();

  const [masters, setMasters] = useState<any[]>([]);
  const [bills, setBills] = useState<any[]>([]);
  const [labor, setLabor] = useState<any[]>([]);
  const [machines, setMachines] = useState<any[]>([]);
  const [materialInfo, setMaterialInfo] = useState<any[]>([]);
  const [error, setError] = useState("");
  const [form, setForm] = useState({ id: "", code: "", description: "", mainArea: "Allgemein", budget: 0 });

  const load = async () => {
    try {
      setError("");
      const [masterData, billData, laborData, resourceData] = await Promise.all([
        projectId ? apiJson(`/api/cost-centers?projectId=${encodeURIComponent(projectId)}`) : Promise.resolve({}),
        accountingApi("/api/accounting/vendor-bills"),
        projectId ? apiJson(`/api/personal/labor-costs?projectId=${encodeURIComponent(projectId)}`) : Promise.resolve({}),
        projectId ? apiJson(`/api/resource-costs/summary?projectId=${encodeURIComponent(projectId)}`) : Promise.resolve({})
      ]);
      setMasters(masterData.items || []);
      setBills(billData.items || []);
      setLabor(laborData.items || []);
      setMachines(resourceData.machineItems || []);
      setMaterialInfo(resourceData.materialItems || []);
    } catch (e: any) { setError(e?.message || "Kostenstellen konnten nicht geladen werden."); }
  };

  useEffect(() => { void load(); }, [projectId]);

  const rows = useMemo(() => {
    const map = new Map<string, any>();

    for (const master of masters) {
      const code = clean(master.code);
      map.set(code, {
        id: master.id, code, description: master.description || "", mainArea: master.mainArea || "Allgemein",
        budget: num(master.budget), supplier: 0, labor: 0, machines: 0, materialInfo: 0
      });
    }

    const ensure = (raw: unknown) => {
      const code = clean(raw);
      if (!map.has(code)) map.set(code, {
        id: "", code, description: code === "OHNE-KOSTENSTELLE" ? "Noch nicht zugeordnet" : "Aus Ist-Kosten erkannt",
        mainArea: "Automatisch", budget: 0, supplier: 0, labor: 0, machines: 0, materialInfo: 0
      });
      return map.get(code);
    };

    for (const bill of bills) {
      const target = ensure(bill?.data?.costCenter);
      target.supplier += num(bill.grossAmount);
    }
    for (const item of labor) {
      const target = ensure(item.costCenter || item.kostenstelle);
      target.labor += num(item.personnelCost);
    }
    for (const item of machines) {
      const target = ensure(item.costCenter || item.kostenstelle);
      target.machines += num(item.amount);
    }
    for (const item of materialInfo) {
      const target = ensure(item.costCenter || item.kostenstelle);
      target.materialInfo += num(item.amount);
    }

    return Array.from(map.values()).map((row) => ({
      ...row,
      actual: row.supplier + row.labor + row.machines,
      variance: row.budget - (row.supplier + row.labor + row.machines)
    })).sort((a, b) => a.code.localeCompare(b.code));
  }, [masters, bills, labor, machines, materialInfo]);

  const totals = useMemo(() => rows.reduce((sum, row) => ({
    budget: sum.budget + row.budget, actual: sum.actual + row.actual,
    supplier: sum.supplier + row.supplier, labor: sum.labor + row.labor, machines: sum.machines + row.machines
  }), { budget: 0, actual: 0, supplier: 0, labor: 0, machines: 0 }), [rows]);

  const save = async () => {
    try {
      if (!projectId || !form.code.trim()) throw new Error("Projekt und Kostenstellen-Code sind erforderlich.");
      const body = { projectId, code: form.code.trim(), description: form.description.trim() || form.code.trim(), mainArea: form.mainArea, budget: num(form.budget) };
      if (form.id) await apiJson(`/api/cost-centers/${encodeURIComponent(form.id)}`, { method: "PUT", body: JSON.stringify(body) });
      else await apiJson("/api/cost-centers", { method: "POST", body: JSON.stringify(body) });

