  costCenter?: string; reportId?: string; workflowStatus?: string;
  rowsCount?: number; attachmentsCount?: number; pdfUrl?: string | null;
};

const clean = (value: unknown) => String(value ?? "").trim();

function serverFileUrl(value: string) {
  if (/^https?:\/\//i.test(value)) return value;
  const origin =
    (import.meta as any)?.env?.VITE_BACKEND_URL ||
    (import.meta as any)?.env?.VITE_API_ORIGIN ||
    "https://api.rlcbausoftware.com";
  return `${String(origin).replace(/\/$/, "")}/${String(value || "").replace(/^\//, "")}`;
}

export default function LieferscheineKosten() {
  const [items, setItems] = useState<DeliveryNote[]>([]);
  const [query, setQuery] = useState("");
  const [costCenter, setCostCenter] = useState("ALL");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const load = async () => {
    try {
      setLoading(true); setError("");
      const projectId = getAccountingProject();
      const result = await accountingApi(`/api/ls/accounting-list?projectId=${encodeURIComponent(projectId)}`);
      setItems(Array.isArray(result?.items) ? result.items : []);
    } catch (e: any) {
      setError(e?.message || "Lieferscheine konnten nicht geladen werden.");
    } finally { setLoading(false); }
  };

  useEffect(() => { void load(); }, []);

  const costCenters = useMemo(
    () => Array.from(new Set(items.map((item) => clean(item.costCenter)).filter(Boolean))).sort(),
    [items]
  );

  const filtered = useMemo(() => {
    const needle = query.trim().toLowerCase();
    return items.filter((item) => {
      const centerOk = costCenter === "ALL" || clean(item.costCenter) === costCenter;
      const values = [item.number, item.reportId, item.supplier, item.material, item.costCenter, item.date]
        .map(clean).join(" ").toLowerCase();
      return centerOk && (!needle || values.includes(needle));
    });
  }, [items, query, costCenter]);

  return (
    <div className="bh-page">
      <div className="bh-header-row">
        <div>
          <h2>Lieferscheine</h2>
          <div className="bh-note">Projekt: {getAccountingProject()} · Quelle: Mobile, Cloud und Baustelle</div>
        </div>
        <button className="bh-btn ghost" onClick={() => void load()}>{loading ? "Lädt…" : "Aktualisieren"}</button>
      </div>

      <div className="bh-note" style={{ marginBottom: 14 }}>
        Ein Lieferschein dokumentiert Lieferung und Menge. Der finanzielle Aufwand wird erst über die zugeordnete
        <b> Eingangsrechnung</b> gebucht.
      </div>

      <div className="bh-filters">
        <div>
          <label>Suche</label>
          <input value={query} onChange={(e) => setQuery(e.target.value)}
            placeholder="Nummer, Lieferant, Material oder Kostenstelle" />
        </div>
        <div>
          <label>Kostenstelle</label>
          <select value={costCenter} onChange={(e) => setCostCenter(e.target.value)}>
            <option value="ALL">Alle</option>
            {costCenters.map((value) => <option key={value} value={value}>{value}</option>)}
          </select>
        </div>
        <div className="bh-note" style={{ alignSelf: "end" }}>{filtered.length} von {items.length} Lieferscheinen</div>
      </div>

      {error ? <div className="bh-note">{error}</div> : null}

      <table className="bh-table">
        <thead>
          <tr>
            <th>Nr.</th><th>Datum</th><th>Lieferant</th><th>Material / Menge</th>
            <th>Kostenstelle</th><th>Status</th><th>Dokumente</th><th>Aktion</th>
          </tr>
        </thead>
        <tbody>
          {filtered.map((item) => (
            <tr key={item.key}>
              <td>{item.number || `LS-${item.reportId || "—"}`}</td>
              <td>{dateDe(item.date)}</td>
              <td>{item.supplier || "—"}</td>
              <td>
                {item.material || "—"}
                {item.quantity !== null && item.quantity !== undefined
                  ? <small className="bh-note" style={{ display: "block" }}>{item.quantity} {item.unit || ""}</small>
                  : null}
              </td>
              <td>{item.costCenter || "—"}</td>
              <td>{item.workflowStatus || "FREIGEGEBEN"}</td>
              <td>{item.pdfUrl ? "PDF" : "—"} · {item.attachmentsCount || 0} Anlage(n)</td>
              <td>
                <div style={{ display: "flex", gap: 6, flexWrap: "wrap" }}>
                  {item.pdfUrl ? <button className="bh-btn ghost"
                    onClick={() => window.open(serverFileUrl(item.pdfUrl || ""), "_blank", "noopener,noreferrer")}>PDF öffnen</button> : null}
                  <button className="bh-btn" onClick={() => {
                    window.location.assign(`/buchhaltung/eingang?deliveryNoteKey=${encodeURIComponent(item.key)}`);
                  }}>Eingangsrechnung erfassen</button>
                </div>
              </td>
            </tr>
          ))}
          {!filtered.length ? <tr><td colSpan={8}>
            {loading ? "Lieferscheine werden geladen…" : "Keine freigegebenen Lieferscheine im aktuellen Filter."}
          </td></tr> : null}
        </tbody>
      </table>
    </div>
  );
}

import React, { useEffect, useState } from "react";
import { accountingApi, dateDe, euro, getAccountingProject } from "./accountingApi";
import { renderRlcMahnPdf } from "./serverPdfCore";
import "./styles.css";

export default function Mahnwesen() {
  const [rows, setRows] = useState<any[]>([]);
  const [error, setError] = useState("");

  const createMahnPdf = async (row: any) => {
    if (Number(row.dunningLevel || 0) < 1) {
      setError("Bitte zuerst die Mahnstufe 1, 2 oder 3 auswählen.");
      return;
    }

    try {
      setError("");
      await renderRlcMahnPdf({
        projectId: getAccountingProject(),
        invoiceId: row.id,
        dunningLevel: Number(row.dunningLevel),
        fileName: `Mahnung_${row.number}.pdf`
      });
    } catch (e: any) {
      setError(e?.message || "Mahnung PDF konnte nicht erzeugt werden");
    }
  };

  const load = async () => {
    try {
      setError("");
      const data = await accountingApi("/api/accounting/mahnwesen");
      setRows(data.items || []);
    } catch (e:any) {
      setError(e?.message || "Fehler");
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const setLevel = async (row:any, level:number) => {
    await accountingApi(`/api/accounting/invoices/${row.id}/dunning`, {
      method: "POST",
      body: JSON.stringify({
        dunningLevel: level,
        lastDunningDate:
          level > 0
            ? new Date().toISOString()
            : null,
        dunningFee:
          level === 1 ? 5 :
          level === 2 ? 10 :
          level >= 3 ? 20 : 0,
        interestRate:
          level >= 2 ? 9 : 5
      })
    });

    await load();
  };

  return (
    <div className="bh-page">
      <div className="bh-header-row">
        <h2>Mahnwesen</h2>
        <button className="bh-btn ghost" onClick={load}>
          Aktualisieren
        </button>
      </div>

      {error && <div className="bh-note">{error}</div>}

      <table className="bh-table">
        <thead>
          <tr>
            <th>Rechnung</th>
            <th>Kunde</th>
            <th>Datum</th>
            <th>Brutto</th>
            <th>Bezahlt</th>
            <th>Offen</th>
            <th>Stufe</th>
            <th>Letzte Mahnung</th>
            <th>Gebühr</th>
            <th>Aktion</th>
          </tr>
        </thead>

        <tbody>
          {rows.map(row => (
            <tr key={row.id}>
              <td>{row.number}</td>
              <td>{row.customer?.name || "—"}</td>
              <td>{dateDe(row.date)}</td>
              <td>{euro(row.grossAmount)} €</td>
              <td>{euro(row.paidAmount)} €</td>
              <td>{euro(row.openAmount)} €</td>
              <td>{row.dunningLevel}</td>
              <td>{dateDe(row.lastDunningDate)}</td>
              <td>{euro(row.dunningFee)} €</td>
                <td>
                  <div style={{ display: "flex", gap: 7, alignItems: "center", flexWrap: "wrap" }}>
                    <select
                      aria-label="Mahnstufe"
                      value={row.dunningLevel}
                      onChange={e=>setLevel(row, Number(e.target.value))}
                    >
                      <option value={0}>0 · Keine</option>
                      <option value={1}>1 · 1. Mahnung</option>
                      <option value={2}>2 · 2. Mahnung</option>
                      <option value={3}>3 · Letzte Mahnung</option>
                    </select>
                    <button
                      className="bh-btn ghost"
                      onClick={() => window.location.assign(`/buchhaltung/zahlungen?invoiceId=${encodeURIComponent(row.id)}`)}
                    >
                      Zahlung erfassen
                    </button>
                    <button
                      className="bh-btn ghost"
                      onClick={() => window.location.assign("/buchhaltung/rechnungen")}
                    >
                      Rechnung öffnen
                    </button>
                      <button
                        className="bh-btn"
                        disabled={Number(row.dunningLevel || 0) < 1}
                        onClick={() => void createMahnPdf(row)}
                      >
                        Mahnung PDF
                      </button>
                  </div>
                </td>
            </tr>
          ))}

          {!rows.length && (
            <tr>
              <td colSpan={10}>Keine Forderungen vorhanden.</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}

