import { renderRlcServerPdf } from "./serverPdfCore";
import { getAccountingProject } from "./accountingApi";
type AufmassRow = {
  id: string;
  pos: string;
  text: string;
  unit: string;
  ep: number;
  soll: number;
  formula: string;
  ist: number;
  note?: string;
