function printableReportHTML(list: Rechnung[]) {
  const rows = list.
  map((r) => {
    const b = brutto(r);
    const of = offen(r);
    return `<tr>
      <td>${escapeHtml(r.nr)}</td>
      <td>${escapeHtml(r.datum)}</td>
      <td>${escapeHtml(r.kunde)}</td>
      <td>${escapeHtml(r.typ)}</td>
