type Tagesbericht = Record<string, any>;

function authHeaders(): Record<string, string> {
  for (const key of [
  "rlc_token",
  "token",
  "authToken",
  "accessToken",
  "rlc_auth_token"])
  {
    const token = localStorage.getItem(key) || sessionStorage.getItem(key);

    if (token?.trim()) {
      return { Authorization: `Bearer ${token.trim()}` };
    }
  }

  return {};
}

async function request(path: string, init?: RequestInit) {
  const response = await fetch(apiUrl(path), {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init?.body ? { "Content-Type": "application/json" } : {}),
      ...authHeaders(),
      ...(init?.headers || {})
    }
  });

  const payload = await response.json().catch(() => null);

  if (!response.ok || payload?.ok === false) {
    throw new Error(
      payload?.message || payload?.error || `HTTP ${response.status}`
    );
  }

  return payload;
}

function assetUrl(value?: string | null): string {
  const url = String(value || "").trim();

  if (!url) return "";
  if (/^(https?:|blob:|data:)/i.test(url)) return url;

  return apiUrl(url.startsWith("/") ? url : `/${url}`);
}

function itemsOf(payload: any): any[] {
  for (const value of [
  payload,
  payload?.items,
  payload?.reports,
  payload?.data,
  payload?.data?.items])
  {
    if (Array.isArray(value)) return value;
  }

  return [];
}

function normalizeReport(raw: any, projectKey: string): Tagesbericht {
  const wrapper = raw || {};
  const report =
  Array.isArray(wrapper.rows) && wrapper.rows.length ?
  wrapper.rows[0] :
  wrapper;

  const sourceDocId = String(
    wrapper.id ||
    wrapper.docId ||
    report.sourceDocId ||
    report.id ||
    ""
  ).trim();

  return {
    ...wrapper,
    ...report,
    id: String(report.id || sourceDocId).trim(),
    sourceDocId,
    projectId: String(
      report.projectId || wrapper.projectId || projectKey
    ).trim(),
    projectCode: String(
      report.projectCode ||
      wrapper.projectCode ||
      projectKey
    ).trim(),
    date: String(
      report.date ||
      report.datum ||
      wrapper.date ||
      wrapper.datum ||
      ""
    ).slice(0, 10),
    weather:
    report.weather ||
    report.wetter ||
    wrapper.weather ||
    wrapper.wetter ||
    "",
    temperature:
    report.temperature ||
    report.temperatur ||
    wrapper.temperature ||
    wrapper.temperatur ||
    "",
    workers:
    report.workers ||
    report.mitarbeiter ||
    wrapper.workers ||
    wrapper.mitarbeiter ||
    "",
    machines:
    report.machines ||
    report.maschinen ||
    wrapper.machines ||
    wrapper.maschinen ||
    "",
    materials:
    report.materials ||
    report.materialien ||
    report.material ||
    wrapper.materials ||
    wrapper.materialien ||
    wrapper.material ||
    "",
    workDone:
    report.workDone ||
    report.arbeiten ||
    report.taetigkeit ||
    report.comment ||
    wrapper.workDone ||
    wrapper.arbeiten ||
    wrapper.comment ||
    "",
    issues:
    report.issues ||
    report.vorkommnisse ||
    wrapper.issues ||
    wrapper.vorkommnisse ||
    "",
    notes:
    report.notes ||
    report.notizen ||
    wrapper.notes ||
    wrapper.notizen ||
    wrapper.note ||
    "",
    attachments: Array.isArray(report.attachments) ?
    report.attachments :
    Array.isArray(wrapper.attachments) ?
    wrapper.attachments :
    [],
    lines: Array.isArray(report.lines) ?
    report.lines :
    Array.isArray(report.rows) &&
    report.rows.every(
      (line: any) =>
      String(line?.reportType || "").toUpperCase() !==
      "TAGESBERICHT"
    ) ?
    report.rows :
    [],
    reportType: "BAUTAGEBUCH",
    workflowStatus:
    report.workflowStatus ||
    wrapper.workflowStatus ||
    wrapper.status ||
    "",
    inBautagebuch: Boolean(
      report.inBautagebuch || wrapper.inBautagebuch
    )
  };
}

function hoursOf(item: Tagesbericht): number {
  return (Array.isArray(item.lines) ? item.lines : []).reduce(
    (sum: number, line: any) =>
    sum + Number(line.stunden || line.hours || 0),
    0
  );
}

function groupByDate(
items: Tagesbericht[])
: Array<[string, Tagesbericht[]]> {
  const groups = new Map<string, Tagesbericht[]>();

  for (const item of items) {
    const date = String(
      item.date || item.datum || "Ohne Datum"
    ).slice(0, 10);

    const current = groups.get(date) || [];
    current.push(item);
    groups.set(date, current);
  }

  return Array.from(groups.entries()).sort(([a], [b]) =>
  b.localeCompare(a)
  );
}

