function authHeaders(): Record<string, string> {
  for (const key of [
  "rlc_token",
  "token",
  "authToken",
  "accessToken",
  "rlc_auth_token"])
  {
    const token = localStorage.getItem(key) || sessionStorage.getItem(key);
    if (token?.trim()) {
      return { Authorization: `Bearer ${token.trim()}` };
    }
  }
  return {};
}

async function request(path: string, init?: RequestInit) {
  const response = await fetch(apiUrl(path), {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init?.body ? { "Content-Type": "application/json" } : {}),
      ...authHeaders(),
      ...(init?.headers || {})
    }
  });

  const payload = await response.json().catch(() => null);

  if (!response.ok || payload?.ok === false) {
    throw new Error(
      payload?.message || payload?.error || `HTTP ${response.status}`
    );
  }

  return payload;
}

function assetUrl(value?: string | null): string {
  const url = String(value || "").trim();
  if (!url) return "";
  if (/^(https?:|blob:|data:)/i.test(url)) return url;
  return apiUrl(url.startsWith("/") ? url : `/${url}`);
}

function itemsOf(payload: any): any[] {
  for (const value of [
  payload,
  payload?.items,
  payload?.reports,
  payload?.data,
  payload?.data?.items])
  {
    if (Array.isArray(value)) return value;
  }
  return [];
}

function normalizeReport(raw: any, projectKey: string): Tagesbericht {
  const wrapper = raw || {};
  const firstRow =
  Array.isArray(wrapper.rows) && wrapper.rows.length ?
  wrapper.rows[0] :
  Array.isArray(wrapper.lines) &&
  wrapper.lines.length === 1 &&
  String(wrapper.lines[0]?.reportType || "").toUpperCase() ===
  "TAGESBERICHT" ?
  wrapper.lines[0] :
  wrapper;

