    try {
      const responses = await Promise.all([
        request(
          `/api/tagesbericht/inbox/list?projectId=${encodeURIComponent(projectKey)}`
        ).catch(() => ({ items: [] }))
      ]);

      const normalized = responses.
      flatMap(itemsOf).
