type Counter = {
  value: number;
  available: boolean;
};

type OverviewData = {
  regie: Counter;
  lieferscheine: Counter;
  fotos: Counter;
  tagesberichte: Counter;
  bautagebuch: Counter;
  documents: Counter;
  members: Counter;
};

const EMPTY: Counter = { value: 0, available: false };

function authHeaders(): Record<string, string> {
  const keys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc.auth.token",
    "rlc_mobile_token",
    "rlc_auth_token",
    "rlc_access_token",
  ];

  for (const key of keys) {
    const token =
      localStorage.getItem(key) || sessionStorage.getItem(key);

    if (token?.trim()) {
      return { Authorization: `Bearer ${token.trim()}` };
    }
  }

  try {
    const raw =
      localStorage.getItem("auth") ||
      localStorage.getItem("rlc_auth") ||
      localStorage.getItem("user");

    if (raw) {
      const parsed = JSON.parse(raw);
      const token =
        parsed?.token ||
        parsed?.accessToken ||
        parsed?.authToken ||
        parsed?.data?.token ||
        parsed?.data?.accessToken;

      if (typeof token === "string" && token.trim()) {
        return { Authorization: `Bearer ${token.trim()}` };
      }
    }
  } catch {
    // Kein verwertbares Auth-Objekt.
  }

  return {};
}

function extractItems(payload: any): any[] {
  if (Array.isArray(payload)) return payload;
  if (!payload || typeof payload !== "object") return [];

  const candidates = [
    payload.items,
    payload.rows,
    payload.reports,
    payload.documents,
    payload.results,
    payload.entries,
    payload.files,
    payload.list,
    payload.members,
    payload.data,
    payload.data?.items,
    payload.data?.rows,
    payload.data?.reports,
    payload.data?.documents,
    payload.data?.files,
    payload.data?.members,
  ];

  for (const candidate of candidates) {
    if (Array.isArray(candidate)) return candidate;
  }

  return [];
}

function countPayload(payload: any): number {
  if (typeof payload?.count === "number") return payload.count;
  if (typeof payload?.total === "number") return payload.total;
  if (typeof payload?.totalCount === "number") return payload.totalCount;
  return extractItems(payload).length;
}

async function request(path: string): Promise<any> {
  const response = await fetch(apiUrl(path), {
    method: "GET",
    credentials: "include",
    headers: {
      Accept: "application/json",
      ...authHeaders(),
    },
  });

  const text = await response.text();

  let payload: any = {};
  try {
    payload = text ? JSON.parse(text) : {};
  } catch {
    payload = {};
  }

  if (!response.ok) {
    throw new Error(
      payload?.error ||
        payload?.message ||
        `HTTP ${response.status}`
    );
  }

  return payload;
}

async function readCount(path: string): Promise<Counter> {
  try {
    const payload = await request(path);
    return {
      value: countPayload(payload),
      available: true,
    };
  } catch {
    return EMPTY;
  }
}

async function readReportCount(
  path: string,
  reportType: "REGIE" | "TAGESBERICHT" | "BAUTAGEBUCH"
): Promise<Counter> {
  try {
    const payload = await request(path);

    const rows = extractItems(payload).filter((item: any) => {
      const first =
        Array.isArray(item?.rows) && item.rows.length
          ? item.rows[0]
          : item;

      const actual = String(
        item?.reportType ||
        first?.reportType ||
        item?.type ||
        first?.type ||
        "REGIE"
      )
        .trim()
        .toUpperCase();

      return actual === reportType;
    });

    return {
      value: rows.length,
      available: true,
    };
  } catch {
    return EMPTY;
  }
}

