  const load = React.useCallback(async () => {
    if (!projectId) {
      setTasks([]);
      setSelectedId(null);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data =
        await request<LoadResponse>(
          "/api/buero/bauzeitenplan/load",
          {
            method: "POST",
            body: JSON.stringify({
              projectId
            })
          }
        );

      const rows =
        Array.isArray(data.tasks)
          ? data.tasks.map((task) => ({
              id: task.id,
              name:
                task.name ||
                "Neuer Vorgang",
              dauerTage:
                Number(
                  task.dauerTage || 0
                ),
              start:
                task.start || null,
              end:
                task.end || null,
              progress:
                clamp(
                  Number(
                    task.progress || 0
                  )
                ),
              notes:
                task.notes || "",
              assignee:
                task.assignee || "",
              milestone:
                Boolean(
                  task.milestone
                ),
              deps:
                Array.isArray(task.deps)
                  ? task.deps
                  : [],
              ressourcen:
                task.ressourcen &&
                typeof task.ressourcen ===

task.assignee || "",
              milestone:
                Boolean(
                  task.milestone
                ),
              deps:
                Array.isArray(task.deps)
                  ? task.deps
                  : [],
              ressourcen:
                task.ressourcen &&
                typeof task.ressourcen ===
                  "object"
                  ? task.ressourcen
                  : {}
            }))
          : [];

      setTasks(rows);
      setCapacity(
        data.capacity || {}
      );

      if (data.start) {
        setPlanStart(data.start);
      }

      setSelectedId((current) => {
        if (
          current &&
          rows.some(
            (task) =>
              task.id === current
          )
        ) {
          return current;
        }

        return rows[0]?.id || null;
      });

      setDirty(false);
    } catch (e: any) {
      setError(
        e?.message ||
        "Bauzeitenplan konnte nicht geladen werden."
      );
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  React.useEffect(() => {
    void load();
  }, [load]);

  function newTask() {
    const start =
      new Date();

    const end =
      addDays(start, 4);

    const task: PlanTask = {
      id: uuid(),
      name: "Neuer Vorgang",
      dauerTage: 5,
      start: start.toISOString(),
      end: end.toISOString(),
      progress: 0,
      notes: "",
      assignee: "",
      milestone: false,
      deps: [],
      ressourcen: {}
    };

    setTasks((current) => [
      ...current,
      task
    ]);

    setSelectedId(task.id);
    setDirty(true);
  }

  function updateSelected(
    patch: Partial<PlanTask>
  ) {
    if (!selectedId) return;

    setTasks((current) =>
      current.map((task) => {
        if (
          task.id !== selectedId
        ) {
          return task;
        }

        const next = {
          ...task,
          ...patch
        };

        if (
          next.start &&
          next.end
        ) {
          next.dauerTage =
            dayDiff(
              next.start,
              next.end
            );
        }

        return next;
      })
    );

    setDirty(true);
  }

