function Gantt({
  tasks,
  zoom,
  selectedId,
  onSelect
}: {
  tasks: PlanTask[];
  zoom: Zoom;
  selectedId: string | null;
  onSelect: (id: string) => void;
}) {
  const dated =
    tasks.filter(
      (task) =>
        task.start &&
        task.end
    );

  const today =
    new Date();

  const min =
    dated.length
      ? new Date(
          Math.min(
            ...dated.map(
              (task) =>
                new Date(
                  task.start!
                ).getTime()
            )
          )
        )
      : addDays(today, -7);

  const max =
    dated.length
      ? new Date(
          Math.max(
            ...dated.map(
              (task) =>
                new Date(
                  task.end!
                ).getTime()
            )
          )
        )
      : addDays(today, 21);

  const start =
    addDays(min, -5);

  const end =
    addDays(max, 7);

  const dayWidth =
    zoom === "day"
      ? 34
      : zoom === "week"
        ? 17
        : 8;

  const totalDays =
    Math.max(
      1,
      Math.ceil(
        (
          end.getTime() -
          start.getTime()
        ) /
        86400000
      )
    );

  const labelWidth = 150;

  const width =
    labelWidth +
    totalDays * dayWidth;

  const rowHeight = 42;

  const xFor = (
    value: string
  ) =>
    labelWidth +
    (
      (
        new Date(value).getTime() -
        start.getTime()
      ) /
      86400000
    ) *
      dayWidth;

  const marks: {
    x: number;
    label: string;
  }[] = [];

  const cursor =
    new Date(start);

  while (cursor <= end) {
    const x =
      labelWidth +
      (
        (
          cursor.getTime() -
          start.getTime()
        ) /
        86400000
      ) *
        dayWidth;

    let label = "";

    if (zoom === "day") {
      label =
        cursor.toLocaleDateString(
          "de-DE",
          {
            day: "2-digit",
            month: "2-digit"
          }
        );

      cursor.setDate(
        cursor.getDate() + 1
      );
    } else if (zoom === "week") {
      label =
        `KW ${weekNumber(cursor)}`;

      cursor.setDate(
        cursor.getDate() + 7
      );
    } else {
      label =
        cursor.toLocaleDateString(
          "de-DE",
          {
            month: "short",
            year: "2-digit"
          }
        );

      cursor.setMonth(
        cursor.getMonth() + 1,
        1
      );
    }

    marks.push({
      x,
      label
    });
  }

  const height =
    Math.max(
      518,
      38 +
      tasks.length *
        rowHeight
    );

  return (
    <svg
      width={width}
      height={height}
      style={{
        display: "block",
        minWidth: "100%"
      }}
    >
      <rect
        x={0}
        y={0}
        width={width}
        height={36}
        fill="#f8fafc"
      />

      <rect
        x={0}
        y={0}
        width={labelWidth}
        height={height}
        fill="#fff"
        stroke="#e2e8f0"
      />

      <text
        x={12}
        y={23}
        fontSize="12"
        fontWeight="700"
        fill="#334155"
      >
        Vorgang
      </text>

      {marks.map(
        (mark, index) => (
          <g key={index}>
            <line
              x1={mark.x}
              y1={0}
              x2={mark.x}
              y2={height}
              stroke="#e8eef5"
            />

            <text
              x={mark.x + 5}
              y={23}
              fontSize="10"
              fill="#64748b"
            >
              {mark.label}
            </text>
          </g>
        )
      )}

      {tasks.map(
        (task, index) => {
          const y =
            36 +
            index *
              rowHeight;

          const selected =
            task.id ===
            selectedId;

          return (
            <g
              key={task.id}
              onClick={() =>
                onSelect(task.id)
              }
              style={{
                cursor: "pointer"
              }}
            >
              <rect
                x={0}
                y={y}
                width={width}
                height={rowHeight}
                fill={
                  selected
                    ? "#f3f7ff"
                    : index % 2
                      ? "#fbfdff"
                      : "#fff"
                }
              />

              <line
                x1={0}
                y1={y + rowHeight}
                x2={width}
                y2={y + rowHeight}
                stroke="#edf2f7"
              />

              <text
                x={12}
                y={y + 25}
                fontSize="11"
                fontWeight={
                  selected
                    ? "700"
                    : "500"
                }
                fill="#0f172a"
              >
                {task.name.length > 20
                  ? task.name.slice(
                      0,
                      18
                    ) + "…"
                  : task.name}
              </text>

              {task.start &&
              task.end ? (
                task.milestone ? (
                  <Milestone
                    x={xFor(
                      task.start
                    )}
                    y={
                      y +
                      rowHeight / 2
                    }
                  />
                ) : (
                  <TaskBar

task.milestone ? (
                  <Milestone
                    x={xFor(
                      task.start
                    )}
                    y={
                      y +
                      rowHeight / 2
                    }
                  />
                ) : (
                  <TaskBar
                    task={task}
                    x={xFor(
                      task.start
                    )}
                    y={y + 10}
                    width={Math.max(
                      9,
                      (
                        (
                          new Date(
                            task.end
                          ).getTime() -
                          new Date(
                            task.start
                          ).getTime()
                        ) /
                        86400000 +
                        1
                      ) *
                        dayWidth
                    )}
                  />
                )
              ) : null}
            </g>
          );
        }
      )}

      {(() => {
        const x =
          labelWidth +
          (
            (
              today.getTime() -
              start.getTime()
            ) /
            86400000
          ) *
            dayWidth;

        return (
          <line
            x1={x}
            y1={0}
            x2={x}
            y2={height}
            stroke="#ef4444"
            strokeWidth="1.5"
            strokeDasharray="4 4"
          />
        );
      })()}
    </svg>
  );
}

function TaskBar({
  task,
  x,
  y,
  width
}: {
  task: PlanTask;
  x: number;
  y: number;
  width: number;
}) {
  const progressWidth =
    width *
    clamp(task.progress) /
    100;

  return (
    <g>
      <rect
        x={x}
        y={y}
        width={width}
        height={22}
        rx={5}
        fill="#dbeafe"
        stroke="#60a5fa"
      />

      <rect
        x={x}
        y={y}
        width={progressWidth}
        height={22}
        rx={5}
        fill="#60a5fa"
      />

      <text
        x={x + 6}
        y={y + 15}
        fontSize="10"
        fontWeight="600"
        fill="#0f3f82"
      >
        {task.progress}%
      </text>
    </g>
  );
}

function Milestone({
  x,
  y
}: {
  x: number;
  y: number;
}) {
  const size = 8;

  return (
    <polygon
      points={`
        ${x},${y - size}
        ${x + size},${y}
        ${x},${y + size}
        ${x - size},${y}
      `}
      fill="#2563eb"
    />
  );
}

function Field({
  label,
  children
}: {
  label: string;
  children: React.ReactElement<any>;
}) {
  return (
    <div
      style={{
        display: "grid",
        gap: 5
      }}
    >
      <label
        style={{
          fontSize: 12,
          fontWeight: 650,
          color: "#334155"
        }}
      >
        {label}
      </label>

      {React.cloneElement(
        children,
        {
          style: {
            width: "100%",
            boxSizing:
              "border-box",
            ...(children.props
              ?.style || {})
          }
        }
      )}
    </div>
  );
}

function Kpi({
