          items.some((row) => row.id === current)
        ) {
          return current;
        }

        return items[0]?.id || null;
      });
    } catch (e: any) {
      setError(
        e?.message ||
        "Kommunikation konnte nicht geladen werden."
      );
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  React.useEffect(() => {
    void load();
  }, [load]);

  React.useEffect(() => {
    if (!selected) {

);
    } finally {
