  async function createThread() {
    if (!projectId) return;

    setSaving(true);
    setError("");

    try {
      const data = await request<{
        ok: true;
        item: Thread;
      }>("/api/communication", {
        method: "POST",
        body: JSON.stringify({
          projectId,
          subject: "Neue Konversation",
          participants: []
        })
      });

      await load();
      setSelectedId(data.item.id);
    } catch (e: any) {
      setError(
        e?.message ||
        "Konversation konnte nicht erstellt werden."
      );
    } finally {
      setSaving(false);
    }
  }

  async function saveThread() {
    if (!selected) return;

    setSaving(true);
    setError("");

    try {
      await request(
        `/api/communication/${encodeURIComponent(selected.id)}`,
        {
          method: "PUT",
          body: JSON.stringify({
            subject: subjectDraft,
            participants:
              splitList(participantsDraft)
