  location?: string | null;
  unit?: string | null;
  stock: number;
  minStock: number;
  priceNet: number;
  supplier?: string | null;
  projectId?: string | null;
  costCenter?: string | null;
  moves?: MaterialMove[];
};

type OrderLine = {
  id: string;
  materialId?: string | null;
  code?: string | null;
  name: string;
  unit?: string | null;
  qty: number;
  priceNet: number;
};

type PurchaseOrder = {
  id: string;
