import React from "react";
import { useSearchParams } from "react-router-dom";
import { apiUrl } from "../../lib/apiBase";
import MaschinenCore from "./maschinenCore";
import Einsatzplanung from "./ressourcenplanung";
import MaschinenWartung from "./MaschinenWartung";
import MaschinenKosten from "./MaschinenKosten";

type Tab =
  | "overview"
  | "maschinen"
  | "wartung"
  | "einsatz"
  | "kosten";

type Machine = {
  id: string;
  name: string;
  type?: string | null;
  serial?: string | null;
  projectId?: string | null;
  location?: string | null;
  status?: string | null;
  hours?: number;
  hourlyRate?: number;
  lastService?: string | null;
  nextService?: string | null;
  serviceIntervalDays?: number;
};

function getAuthToken(): string {
  const keys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc_auth_token"
  ];

  for (const storage of [localStorage, sessionStorage]) {
    for (const key of keys) {
      const value = storage.getItem(key);
      if (value?.trim()) return value.trim();
    }
  }

  return "";
}

async function request(path: string) {
  const token = getAuthToken();

  const response = await fetch(apiUrl(path), {
    credentials: "include",
    headers: {
      Accept: "application/json",
      ...(token
        ? { Authorization: `Bearer ${token}` }
        : {})
    }
  });

  const data = await response.json().catch(() => null);

  if (!response.ok || data?.ok === false) {
    throw new Error(
      data?.error ||
      data?.message ||
      `HTTP ${response.status}`
    );
  }

  return data;
}

function daysLeft(value?: string | null) {
  if (!value) return null;

  return Math.ceil(
    (new Date(value).getTime() - Date.now()) /
      86400000
  );
}

export default function Maschinenverwaltung() {
  const [params, setParams] = useSearchParams();

  const area = String(
    params.get("bereich") || ""
  );

  const resolveTab = (): Tab => {
    if (area === "maschinen") return "maschinen";
    if (area === "wartung") return "wartung";
    if (area === "einsatz") return "einsatz";
    if (area === "kosten") return "kosten";
    return "overview";
  };

  const [tab, setTab] =
    React.useState<Tab>(resolveTab);

  const [machines, setMachines] =
    React.useState<Machine[]>([]);

  const [loading, setLoading] =
    React.useState(false);

  const [error, setError] =
    React.useState("");

  const load = React.useCallback(async () => {
    setLoading(true);
    setError("");

    try {
      const data = await request(
        "/api/resource-costs/machines"
      );

      setMachines(
        Array.isArray(data?.items)
          ? data.items
          : []
      );
    } catch (e: any) {
      setError(
        e?.message ||
        "Maschinendaten konnten nicht geladen werden."
      );
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    void load();
  }, [load]);

  React.useEffect(() => {
    setTab(resolveTab());
  }, [area]);

  const open = (next: Tab) => {
    setTab(next);

    const nextParams =
      new URLSearchParams(params);

    if (next === "overview") {
      nextParams.delete("bereich");
    } else {
      nextParams.set("bereich", next);
    }

    setParams(nextParams);
  };

  const dueMachines = machines.filter(
    (machine) => {
      const days = daysLeft(
        machine.nextService
      );

      return (
        machine.status === "Wartung" ||
        (days !== null && days <= 14)
      );
    }
  );

  const operating = machines.filter(
    (machine) =>
      machine.status !== "Außer Betrieb"
  ).length;

  const assignedProjects = new Set(
    machines
      .map((machine) => machine.projectId)
      .filter(Boolean)
  ).size;

  const hourlyCost = machines.reduce(
    (sum, machine) =>
      sum +
      Number(machine.hourlyRate || 0),
    0
  );

  const operatingValue = machines.reduce(
    (sum, machine) =>
      sum +
      Number(machine.hours || 0) *
        Number(machine.hourlyRate || 0),
    0
  );

  const cards = [
    {
      key: "maschinen" as Tab,
      title: "Maschinen",
      value: machines.length,
      text: `${operating} aktiv`
    },
    {
      key: "wartung" as Tab,
      title: "Wartung",
      value: dueMachines.length,
      text: "fällig oder innerhalb 14 Tagen"
    },
    {
      key: "einsatz" as Tab,
      title: "Einsatz",
      value: assignedProjects,
      text: "zugeordnete Projekte"
    },
    {
      key: "kosten" as Tab,
      title: "Kosten",
