function getToken() {
  const directKeys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc_auth_token",
    "rlc_access_token",
    "rlc.auth.token",
    "rlc_mobile_token"
  ];

  for (const key of directKeys) {
    for (const storage of [localStorage, sessionStorage]) {
      const value = storage.getItem(key);
      if (value?.trim()) return value.trim();
    }
  }

  for (const key of [
    "rlc_auth",
    "auth",
    "user",
    "session",
    "rlc_session"
  ]) {
    for (const storage of [localStorage, sessionStorage]) {
      const raw = storage.getItem(key);
      if (!raw) continue;

      try {
        const parsed = JSON.parse(raw);

        const token =
          parsed?.token ??
          parsed?.accessToken ??
          parsed?.authToken ??
          parsed?.jwt ??
          parsed?.data?.token ??
          parsed?.data?.accessToken;

        if (typeof token === "string" && token.trim()) {
          return token.trim();
        }
      } catch {}
    }
  }

  return "";
}

async function request<T>(
  path: string,
  init?: RequestInit
): Promise<T> {
  const token = getToken();

  const response = await fetch(`${API_BASE}${path}`, {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init?.body
        ? { "Content-Type": "application/json" }
        : {}),
      ...(token
        ? { Authorization: `Bearer ${token}` }
        : {}),
      ...(init?.headers || {})
    }
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok || data?.ok === false) {
    throw new Error(
      data?.error ||
      data?.message ||
      `HTTP ${response.status}`
    );
  }

  return data as T;
}

function pad(value: number) {
  return String(value).padStart(2, "0");
}

function localInput(value: Date) {
  return `${value.getFullYear()}-${pad(value.getMonth() + 1)}-${pad(
    value.getDate()
  )}T${pad(value.getHours())}:${pad(value.getMinutes())}`;
}

function startOfDay(value: Date) {
  const d = new Date(value);
  d.setHours(0, 0, 0, 0);
  return d;
}

function endOfDay(value: Date) {
  const d = new Date(value);
  d.setHours(23, 59, 59, 999);
  return d;
}

function addDays(value: Date, days: number) {
  const d = new Date(value);
  d.setDate(d.getDate() + days);
  return d;
}

function addMonths(value: Date, months: number) {
  const d = new Date(value);
  d.setMonth(d.getMonth() + months);
  return d;
}

function startOfWeek(value: Date) {
  const d = startOfDay(value);
  const day = d.getDay();
  const offset = day === 0 ? -6 : 1 - day;
  d.setDate(d.getDate() + offset);
  return d;
}

function startOfMonth(value: Date) {
  return new Date(
    value.getFullYear(),
    value.getMonth(),
    1
  );
}

function sameDay(a: Date, b: Date) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function splitList(value: string) {
  return value
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function newDraft(
  date: Date,
  projectId: string
): Draft {
  const start = new Date(date);
  start.setHours(9, 0, 0, 0);

  const end = new Date(start);
  end.setHours(10, 0, 0, 0);

  return {
    title: "",
    projectId,
    start: localInput(start),
    end: localInput(end),
    allDay: false,
    location: "",
    attendees: "",
    notes: "",
    category: "Projekt",
    busyStatus: "busy",
    reminderMinutes: "15",
    sourceType: "",
    sourceId: ""
  };
}

function eventDraft(event: CalendarEvent): Draft {
  return {
    title: event.title || "",
    projectId: event.projectId || "",
    start: localInput(new Date(event.start)),
    end: localInput(new Date(event.end)),
    allDay: Boolean(event.allDay),
    location: event.location || "",
    attendees: (event.attendees || []).join(", "),
    notes: event.notes || "",
    category: event.category || "",
    busyStatus: event.busyStatus || "busy",
    reminderMinutes:
      event.reminderMinutes === null ||
      event.reminderMinutes === undefined
        ? ""
        : String(event.reminderMinutes),
    sourceType: event.sourceType || "",
    sourceId: event.sourceId || ""
  };
}

function monthTitle(value: Date) {
  return value.toLocaleDateString("de-DE", {
    month: "long",

