function MonthView({
  cursor,
  events,
  onSelectEvent,
  onCreate
}: {
  cursor: Date;
  events: CalendarEvent[];
  onSelectEvent: (id: string) => void;
  onCreate: (date: Date) => void;
}) {
  const first =
    startOfWeek(startOfMonth(cursor));

  const days =
    Array.from(
      { length: 42 },
      (_, index) => addDays(first, index)
    );

  const weeks =
    Array.from(
      { length: 6 },
      (_, index) =>
        days.slice(index * 7, index * 7 + 7)
    );

  function isMultiDay(event: CalendarEvent) {
    return !sameDay(
      new Date(event.start),
      new Date(event.end)
    );
  }

  return (
    <div>
      <div
        style={{
          display: "grid",
          gridTemplateColumns:
            "repeat(7,minmax(0,1fr))",
          borderBottom: "1px solid #e2e8f0"
        }}
      >
        {WEEKDAYS.map((day) => (
          <div
            key={day}
            style={{
              padding: "9px 10px",
              fontSize: 12,
              fontWeight: 700,
              color: "#475569",
              textAlign: "center"
            }}
          >
            {day}
          </div>
        ))}
      </div>

      {weeks.map((week, weekIndex) => {
        const weekStart = startOfDay(week[0]);
        const weekEnd = endOfDay(week[6]);

        const multiEvents =
          events
            .filter((event) => {
              if (!isMultiDay(event)) {
                return false;
              }

              const eventStart =
                new Date(event.start);

              const eventEnd =
                new Date(event.end);

              return (
                eventStart <= weekEnd &&

if (!isMultiDay(event)) {
                return false;
              }

              const eventStart =
                new Date(event.start);

              const eventEnd =
                new Date(event.end);

              return (
                eventStart <= weekEnd &&
                eventEnd >= weekStart
              );
            })
            .sort(
              (a, b) =>
                new Date(a.start).getTime() -
                new Date(b.start).getTime()
            );

        const lanes: number[] = [];

        const segments =
          multiEvents.map((event) => {
            const eventStart =
              startOfDay(new Date(event.start));

            const eventEnd =
              startOfDay(new Date(event.end));

            const segmentStart =
              eventStart < weekStart
                ? weekStart
                : eventStart;

            const segmentEnd =
              eventEnd > weekEnd
                ? startOfDay(week[6])
                : eventEnd;

            const startCol = Math.max(
              0,
              Math.round(
                (
                  segmentStart.getTime() -
                  weekStart.getTime()
                ) /
                86400000
              )
            );

            const endCol = Math.min(
              6,
              Math.round(
                (
                  segmentEnd.getTime() -
                  weekStart.getTime()
                ) /
                86400000
              )
            );

            let lane = 0;

            while (
              lanes[lane] !== undefined &&
              lanes[lane] >= startCol
            ) {
              lane += 1;
            }

            lanes[lane] = endCol;

            return {
              event,
              startCol,
              endCol,
              lane
            };
          });

        const maxLane =
          segments.length
            ? Math.max(
                ...segments.map(
                  (segment) => segment.lane
                )
              )
            : -1;

        const rowHeight =
          Math.max(
            112,
            48 + (maxLane + 1) * 24
          );

        return (
          <div
            key={weekIndex}
            style={{
              position: "relative",
              display: "grid",
              gridTemplateColumns:
                "repeat(7,minmax(0,1fr))",
              minHeight: rowHeight
            }}
          >
            {week.map((day) => {
              const currentMonth =
                day.getMonth() ===
                cursor.getMonth();

              const today =
                sameDay(day, new Date());

              const dayEvents =
                events.filter((event) => {
                  if (isMultiDay(event)) {
                    return false;
                  }

                  return sameDay(
                    new Date(event.start),
                    day
                  );
                });

              return (
                <div
                  key={day.toISOString()}
                  onDoubleClick={() =>
                    onCreate(day)
                  }
                  style={{
                    minHeight: rowHeight,
                    padding: 6,
                    borderRight:
                      "1px solid #e2e8f0",
                    borderBottom:
                      "1px solid #e2e8f0",
                    background:
                      currentMonth
                        ? "#fff"
                        : "#f8fafc"
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      justifyContent:
                        "flex-end",
                      marginBottom:
                        maxLane >= 0
                          ? 28 + maxLane * 24
                          : 5
                    }}
                  >
                    <button
                      type="button"
                      onClick={() =>
                        onCreate(day)
                      }
                      style={{
                        width: 27,
                        height: 27,
                        borderRadius: 999,
                        border: 0,
                        background:
                          today
                            ? "#0b5bd3"
                            : "transparent",
                        color:
                          today
                            ? "#fff"
                            : currentMonth
                              ? "#0f172a"
                              : "#94a3b8",
                        cursor: "pointer"
                      }}
                    >
                      {day.getDate()}
                    </button>
                  </div>

                  <div
                    style={{
                      display: "grid",
                      gap: 3
                    }}
                  >
                    {dayEvents
                      .slice(0, 3)
                      .map((event) => (
                        <EventChip
                          key={event.id}
                          event={event}
                          onClick={() =>
                            onSelectEvent(
                              event.id
                            )
                          }
                        />

{dayEvents
                      .slice(0, 3)
                      .map((event) => (
                        <EventChip
                          key={event.id}
                          event={event}
                          onClick={() =>
                            onSelectEvent(
                              event.id
                            )
                          }
                        />
                      ))}
                  </div>
                </div>
              );
            })}

            <div
              style={{
                position: "absolute",
                inset: 0,
                display: "grid",
                gridTemplateColumns:
                  "repeat(7,minmax(0,1fr))",
                gridTemplateRows:
                  `38px repeat(${Math.max(1, maxLane + 1)},24px)`,
                pointerEvents: "none",
                zIndex: 5
              }}
            >
              {segments.map(
                ({
                  event,
                  startCol,
                  endCol,
                  lane
                }) => (
                  <button
                    key={`${event.id}-${weekIndex}`}
                    type="button"
                    onClick={() =>
                      onSelectEvent(event.id)
                    }
                    title={`${event.title} · ${dateTime(event.start)} – ${dateTime(event.end)}`}
                    style={{
                      gridColumn:
                        `${startCol + 1} / ${endCol + 2}`,
                      gridRow:
                        `${lane + 2}`,
                      alignSelf: "start",
                      height: 20,
                      margin: "0 4px",
                      overflow: "hidden",
                      whiteSpace: "nowrap",
                      textOverflow: "ellipsis",
                      border:
                        "1px solid #60a5fa",
                      borderLeft:
                        "4px solid #0b5bd3",
                      borderRadius: 5,
                      background: "#dbeafe",
                      color: "#0f3f82",
                      padding: "2px 7px",
                      fontSize: 11,
                      fontWeight: 650,
                      textAlign: "left",
                      cursor: "pointer",
                      pointerEvents: "auto"
                    }}
                  >
                    {event.title}
                  </button>
                )
              )}
            </div>
          </div>
        );
      })}
    </div>
  );
}

