function projectColor(key: string) {
  let hash = 0;

  for (let i = 0; i < key.length; i += 1) {
    hash = ((hash << 5) - hash + key.charCodeAt(i)) | 0;
  }

  return projectPalette[Math.abs(hash) % projectPalette.length];
}

