    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as Dokument[]) : [];
  } catch {
    return [];
  }
};

const save = (rows: Dokument[]) => {
  localStorage.setItem(KEY, JSON.stringify(rows));
};

export function toCSV(list: Dokument[]): string {
  const header = `"Titel";"Tags";"ProjektId";"LetzteDatei";"LetzteGroesse";"Geaendert"`;

  const lines = list.map((d) => {
    const v = d.versions?.[0];
    return [
      d.title,
      (d.tags ?? []).join(", "),
      d.projektId ?? "",
      v?.fileName ?? "",
      v?.size ?? 0,
      d.updatedAt,
    ]
      .map((c) => `"${String(c).replace(/"/g, '""')}"`)
      .join(";");
  });

  return [header, ...lines].join("\r\n");
}

export function fromCSV(csv: string): Dokument[] {
  const rows = csv.split(/\r?\n/).filter(Boolean).slice(1);
  const now = Date.now();

  return rows.map((line) => {
    const cols = splitCsvSemicolon(line).map((c) => unquoteCsv(c));
    const [title, tags, projektId] = cols;

    return {
      id: crypto.randomUUID(),
      title: title || "Importiertes Dokument",
      projektId: projektId || undefined,
      tags: (tags || "")
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean),
      versions: [],
      updatedAt: now,
    } as Dokument;
  });
}

export const DocsDB = {
  list(): Dokument[] {
    return load().sort((a, b) => (b.updatedAt ?? 0) - (a.updatedAt ?? 0));
  },

  byId(id: DocID) {
    return load().find((d) => d.id === id);
  },

  create(title = "Neues Dokument", projektId?: string): Dokument {
    const now = Date.now();
    const d: Dokument = {
      id: crypto.randomUUID(),
      title,
      projektId,
      tags: [],
      versions: [],
      updatedAt: now,
    };

    const all = load();
    all.unshift(d);
    save(all);
    return d;
  },

  upsert(doc: Dokument) {
    const all = load();
    const i = all.findIndex((x) => x.id === doc.id);

    const next: Dokument = {
      ...doc,
      tags: Array.isArray(doc.tags) ? doc.tags : [],
      versions: Array.isArray(doc.versions) ? doc.versions : [],
      updatedAt: Date.now(),
    };

    if (i >= 0) all[i] = next;
    else all.unshift(next);

    save(all);
  },

  remove(id: DocID) {
    save(load().filter((d) => d.id !== id));
  },

  async addVersion(id: DocID, file: File) {
    const dataURL = await fileToDataURL(file);

    const v: DocVersion = {
      id: crypto.randomUUID(),
      fileName: file.name,
      mime: file.type || "application/octet-stream",
      size: file.size,
      uploadedAt: Date.now(),
      dataURL,
    };

    const all = load();
    const i = all.findIndex((d) => d.id === id);
    if (i < 0) return;

    const current = all[i];
    all[i] = {
      ...current,
      versions: [v, ...(current.versions ?? [])],
      updatedAt: Date.now(),
    };

    save(all);
  },

  restoreVersion(id: DocID, versionId: DocID) {
    const all = load();
    const i = all.findIndex((d) => d.id === id);
    if (i < 0) return;

    const doc = all[i];
    const versions = doc.versions ?? [];
    const v = versions.find((x) => x.id === versionId);
    if (!v) return;

    all[i] = {
      ...doc,
      versions: [v, ...versions.filter((x) => x.id !== versionId)],
      updatedAt: Date.now(),
    };

    save(all);
  },

  exportCSV(list: Dokument[]) {
    return toCSV(list);
  },

  importCSV(csv: string): number {
    const add = fromCSV(csv);
    const all = [...add, ...load()];
    save(all);
    return add.length;
  },

  exportJSON(): string {
    return JSON.stringify(load(), null, 2);
  },

  importJSON(json: string): number {
    try {
      const arr = JSON.parse(json) as Dokument[];
      if (!Array.isArray(arr)) return 0;

      const cleaned = arr.map((doc) => ({
        ...doc,
        id: doc.id || crypto.randomUUID(),
        title: doc.title || "Importiertes Dokument",
        tags: Array.isArray(doc.tags) ? doc.tags : [],
        versions: Array.isArray(doc.versions) ? doc.versions : [],
        updatedAt: typeof doc.updatedAt === "number" ? doc.updatedAt : Date.now(),
      })) as Dokument[];

      save(cleaned);
      return cleaned.length;
    } catch {
      return 0;
    }
  },
};

function splitCsvSemicolon(line: string): string[] {
  const result: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"') {
      if (inQuotes && next === '"') {
        current += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (ch === ";" && !inQuotes) {
      result.push(current);
      current = "";
      continue;
    }

    current += ch;
  }

  result.push(current);
  return result;
}

function unquoteCsv(value: string): string {
  return value.replace(/^"|"$/g, "").replace(/""/g, '"');
}

async function fileToDataURL(file: File): Promise<string> {
  return new Promise((resolve, reject) => {
    const r = new FileReader();
    r.onload = () => resolve(String(r.result));
    r.onerror = () => reject(new Error("Datei konnte nicht gelesen werden."));
    r.readAsDataURL(file);
  });
}

import { GanttTask } from "./types";

const KEY = "rlc-gantt-db";

/* ================= LOAD / SAVE ================= */

const load = (): GanttTask[] => {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed;
  } catch {
    return [];
  }
};

const save = (rows: GanttTask[]) => {
  localStorage.setItem(KEY, JSON.stringify(rows));
};

/* ================= HELPERS ================= */

function esc(s: string) {
  return (s || "").replace(/;/g, ",").replace(/\n/g, " ");
}

function unesc(s: string) {
  return s || "";
}

function normalizeTask(t: GanttTask): GanttTask {
  return {
    id: t.id || crypto.randomUUID(),
    name: t.name || "Neuer Vorgang",
    projectId: t.projectId || undefined,
    start: t.start || new Date().toISOString(),
    end: t.end || new Date().toISOString(),
    progress: Number.isFinite(t.progress) ? t.progress : 0,
    dependsOn: Array.isArray(t.dependsOn) ? t.dependsOn : [],
    notes: t.notes || "",
  };
}

/* ================= DB ================= */

export const GanttDB = {
  list(): GanttTask[] {
    return load();
  },

  create(projectId?: string): GanttTask {
    const now = new Date();
    const end = new Date(now.getTime() + 3 * 86400000);

    const task: GanttTask = normalizeTask({
      id: crypto.randomUUID(),
      name: "Neuer Vorgang",
      projectId,
      start: now.toISOString(),
      end: end.toISOString(),
      progress: 0,
      dependsOn: [],
      notes: "",
    });

    const all = load();
    all.push(task);
    save(all);

    return task;
  },

  remove(id: string) {
    const all = load().filter((x) => x.id !== id);
    save(all);
  },

  upsert(task: GanttTask) {
    const t = normalizeTask(task);

    const all = load();
    const index = all.findIndex((x) => x.id === t.id);

    if (index >= 0) {
      all[index] = t;
    } else {
      all.push(t);
    }

    save(all);
    return t;
  },

  /* ================= CSV ================= */

  exportCSV(rows: GanttTask[]) {
    const header =
      "id;name;projectId;start;end;progress;dependsOn;notes";

    const body = rows
      .map((r) => {
        const t = normalizeTask(r);

        return [
          t.id,
          esc(t.name),
          t.projectId ?? "",
          t.start,
          t.end,
          t.progress ?? 0,
          (t.dependsOn ?? []).join("|"),
          esc(t.notes ?? ""),
        ].join(";");
      })
      .join("\n");

    return header + "\n" + body;
  },

  importCSV(txt: string) {
    if (!txt) return 0;

    const lines = txt.split(/\r?\n/).filter(Boolean);
    if (lines.length <= 1) return 0;

    const rows = lines.slice(1).map((l) => l.split(";"));
    const all = load();

    let count = 0;

    for (const r of rows) {
      try {
        const task: GanttTask = normalizeTask({
          id: r[0] || crypto.randomUUID(),
          name: unesc(r[1] || ""),
          projectId: r[2] || undefined,
          start: r[3] || new Date().toISOString(),
          end: r[4] || new Date().toISOString(),
          progress: Number(r[5] || 0),
          dependsOn: (r[6] || "").split("|").filter(Boolean),
          notes: unesc(r[7] || ""),
        });

        const index = all.findIndex((x) => x.id === task.id);

        if (index >= 0) {
          all[index] = task;
        } else {
          all.push(task);
        }

        count++;
      } catch {
        // skip row
      }
    }

    save(all);
    return count;
  },
};

import { KThread, KMessage, KAttachment } from "./types";

const KEY = "rlc-komms-db";

/* ================= LOAD / SAVE ================= */

function load(): KThread[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed;
  } catch {
    return [];
  }
}

function save(data: KThread[]) {
  localStorage.setItem(KEY, JSON.stringify(data));
}

/* ================= HELPERS ================= */

function normalizeThread(t: KThread): KThread {
  return {
    id: t.id || crypto.randomUUID(),
    subject: t.subject || "",
    projectId: (t as any).projectId || undefined, // future API ready
    participants: Array.isArray(t.participants) ? t.participants : [],
    messages: Array.isArray(t.messages) ? t.messages : [],
    attachments: Array.isArray(t.attachments) ? t.attachments : [],
    unreadCount: Number.isFinite(t.unreadCount) ? t.unreadCount : 0,
    updatedAt: t.updatedAt || Date.now(),
  };
}

/* ================= DB ================= */

export const KommsDB = {
  list(): KThread[] {
    return load()
      .map(normalizeThread)
      .sort((a, b) => b.updatedAt - a.updatedAt);
  },

  createThread(projectId?: string): KThread {
    const thread: KThread = normalizeThread({
      id: crypto.randomUUID(),
      subject: "",
      projectId,
      participants: [],
      messages: [],
      attachments: [],
      unreadCount: 0,
      updatedAt: Date.now(),
    } as any);

    const all = load();
    all.push(thread);
    save(all);

    return thread;
  },

  removeThread(id: string) {
    const all = load().filter((x) => x.id !== id);
    save(all);
  },

  upsertThread(thread: KThread) {
    const t = normalizeThread(thread);

    const all = load();
    const index = all.findIndex((x) => x.id === t.id);

    if (index >= 0) {
      all[index] = t;
    } else {
      all.push(t);
    }

    save(all);
    return t;
  },

  addMessage(threadId: string, msg: KMessage) {
    const all = load();
    const index = all.findIndex((x) => x.id === threadId);

    if (index === -1) return;

    const t = normalizeThread(all[index]);

    const message: KMessage = {
      ...msg,
      id: msg.id || crypto.randomUUID(),
      createdAt: (msg as any).createdAt || Date.now(),
    } as any;

    t.messages = [message, ...(t.messages ?? [])];
    t.unreadCount = 0;
    t.updatedAt = Date.now();

    all[index] = t;
    save(all);

    return message;
  },

  markAsRead(threadId: string) {
    const all = load();
    const index = all.findIndex((x) => x.id === threadId);
    if (index === -1) return;

    const t = normalizeThread(all[index]);
    t.unreadCount = 0;

    all[index] = t;
    save(all);
  },

  async attach(threadId: string, file: File): Promise<KAttachment | null> {
    const all = load();
    const index = all.findIndex((x) => x.id === threadId);
    if (index === -1) return null;

    const t = normalizeThread(all[index]);

    const buf = await file.arrayBuffer();
    const blob = new Blob([buf], { type: file.type });

    const dataURL = await new Promise<string>((res) => {
      const r = new FileReader();
      r.onload = () => res(r.result as string);
      r.readAsDataURL(blob);
    });

    const att: KAttachment = {
      id: crypto.randomUUID(),
      name: file.name,
      mime: file.type,
      size: file.size,
      dataURL,
    };

    t.attachments = [att, ...(t.attachments ?? [])];
    t.updatedAt = Date.now();

    all[index] = t;
    save(all);

    return att;
  },
};

import { StockItem, PurchaseOrder } from "./types";

const KEY_ITEMS = "rlc-lager-items";
const KEY_POS = "rlc-lager-pos";

/* ================= LOAD / SAVE ================= */

const loadItems = (): StockItem[] => {
  try {
    const raw = localStorage.getItem(KEY_ITEMS);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as StockItem[]) : [];
  } catch {
    return [];
  }
};

const saveItems = (rows: StockItem[]) => {
  localStorage.setItem(KEY_ITEMS, JSON.stringify(rows));
};

const loadPOs = (): PurchaseOrder[] => {
  try {
    const raw = localStorage.getItem(KEY_POS);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as PurchaseOrder[]) : [];
  } catch {
    return [];
  }
};

const savePOs = (rows: PurchaseOrder[]) => {
  localStorage.setItem(KEY_POS, JSON.stringify(rows));
};

/* ================= HELPERS ================= */

function esc(s: string) {
  return (s || "").replace(/;/g, ",").replace(/\n/g, " ");
}

function asString(v: unknown): string {
  return typeof v === "string" ? v : "";
}

function asOptionalString(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v : undefined;
}

function normalizeItem(it: StockItem): StockItem {
  const raw = it as StockItem & { projectId?: string };
  const normalized: StockItem & { projectId?: string } = {
    id: it.id || crypto.randomUUID(),
    name: it.name || "",
    sku: it.sku || "",
    location: it.location || "",
    price: Number.isFinite(it.price) ? it.price : 0,
    stock: Number.isFinite(it.stock) ? it.stock : 0,
    minStock: Number.isFinite(it.minStock) ? it.minStock : 0,
    updatedAt: it.updatedAt || Date.now(),
  };

  if (raw.projectId) {
    normalized.projectId = raw.projectId;
  }

  return normalized;
}

function normalizePO(po: PurchaseOrder): PurchaseOrder {
  const raw = po as PurchaseOrder & { projectId?: string };
  const normalized: PurchaseOrder & { projectId?: string } = {
    id: po.id || crypto.randomUUID(),
    number: po.number || `PO-${Date.now()}`,
    vendor: po.vendor || "",
    status: po.status || "Entwurf",
    deliveryDate: po.deliveryDate || "",
    lines: Array.isArray(po.lines) ? po.lines : [],
    updatedAt: po.updatedAt || Date.now(),
  };

  if (raw.projectId) {
    normalized.projectId = raw.projectId;
  }

  return normalized;
}

/* ================= DB ================= */

export const LagerDB = {
  /* ================= ITEMS ================= */

  listItems(): StockItem[] {
    return loadItems()
      .map(normalizeItem)
      .sort((a, b) => asString(a.name).localeCompare(asString(b.name)));
  },

  createItem(projectId?: string): StockItem {
    const base: StockItem & { projectId?: string } = {
      id: crypto.randomUUID(),
      name: "",
      sku: "",
      location: "",
      price: 0,
      stock: 0,
      minStock: 0,
      updatedAt: Date.now(),
    };

    const pid = asOptionalString(projectId);
    if (pid) base.projectId = pid;

    const item = normalizeItem(base);

    const all = loadItems();
    all.push(item);
    saveItems(all);

    return item;
  },

  upsertItem(item: StockItem) {
    const it = normalizeItem(item);

    const all = loadItems();
    const index = all.findIndex((x) => x.id === it.id);

    if (index >= 0) {
      all[index] = it;
    } else {
      all.push(it);
    }

    saveItems(all);
    return it;
  },

  removeItem(id: string) {
    const all = loadItems().filter((x) => x.id !== id);
    saveItems(all);
  },

  move(id: string, dir: "IN" | "OUT", qty: number) {
    if (!qty || qty <= 0) return;

    const all = loadItems();
    const index = all.findIndex((x) => x.id === id);
    if (index === -1) return;

    const it = normalizeItem(all[index]);

    const delta = dir === "IN" ? qty : -qty;
    it.stock = Math.max(0, (it.stock || 0) + delta);
    it.updatedAt = Date.now();

    all[index] = it;
    saveItems(all);

    return it;
  },

  exportCSV(rows: StockItem[]) {
    const header = "id;name;sku;location;price;stock;minStock";

    const body = rows
      .map((r) => {
        const it = normalizeItem(r);
        return [
          it.id,
          esc(asString(it.name)),
          esc(asString(it.sku)),
          esc(asString(it.location)),
          it.price ?? 0,
          it.stock ?? 0,
          it.minStock ?? 0,
        ].join(";");
      })
      .join("\n");

    return header + "\n" + body;
  },

  /* ================= PURCHASE ORDERS ================= */

  listPOs(): PurchaseOrder[] {
    return loadPOs()
      .map(normalizePO)
      .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  },

  createPO(projectId?: string): PurchaseOrder {
    const base: PurchaseOrder & { projectId?: string } = {
      id: crypto.randomUUID(),
      number: `PO-${Date.now()}`,
      vendor: "",
      status: "Entwurf",
      deliveryDate: "",
      lines: [],
      updatedAt: Date.now(),
    };

    const pid = asOptionalString(projectId);
    if (pid) base.projectId = pid;

    const po = normalizePO(base);

    const all = loadPOs();
    all.push(po);
    savePOs(all);

    return po;
  },

  upsertPO(po: PurchaseOrder) {
    const p = normalizePO(po);

    const all = loadPOs();
    const index = all.findIndex((x) => x.id === p.id);

    if (index >= 0) {
      all[index] = p;
    } else {
      all.push(p);
    }

    savePOs(all);
    return p;
  },

  removePO(id: string) {

if (index >= 0) {
      all[index] = p;
    } else {
      all.push(p);
    }

    savePOs(all);
    return p;
  },

  removePO(id: string) {
    const all = loadPOs().filter((x) => x.id !== id);
    savePOs(all);
  },
};

