import { Projekt, ID } from "./types";

const KEY = "rlc_buro_projekte_v1";

/* ================= LOAD / SAVE ================= */

function read(): Projekt[] {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return demo();
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.map(normalize) : demo();
  } catch {
    return demo();
  }
}

function write(list: Projekt[]) {
  localStorage.setItem(KEY, JSON.stringify(list));
}

/* ================= HELPERS ================= */

function nowISO() {
  return new Date().toISOString();
}

function normalize(p: Projekt): Projekt {
  const now = nowISO();

  return {
    id: p.id || crypto.randomUUID(),
    name: p.name || "Neues Projekt",
    baustellenNummer: p.baustellenNummer || "",
    bauleiter: p.bauleiter || "",
    ort: p.ort || "",
    status: p.status === "archiv" ? "archiv" : "aktiv",
    createdAt: p.createdAt || now,
    updatedAt: p.updatedAt || now,
  };
}

function demo(): Projekt[] {
  const now = nowISO();
  return [
    normalize({
      id: crypto.randomUUID(),
      name: "TW-Leitung BA III – Musterstadt",
      baustellenNummer: "2025-0123",
      bauleiter: "M. Huber",
      ort: "Musterstadt",
      status: "aktiv",
      createdAt: now,
      updatedAt: now,
    }),
    normalize({
      id: crypto.randomUUID(),
      name: "Parkplatz Sanierung Süd",
      baustellenNummer: "2025-0042",
      bauleiter: "A. König",
      ort: "Bergdorf",
      status: "archiv",
      createdAt: now,
      updatedAt: now,
    }),
  ];
}

/* ================= DB ================= */

export const ProjekteDB = {
  list(): Projekt[] {
    return read().sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
  },

  get(id: ID): Projekt | undefined {
    return read().find((p) => p.id === id);
  },

  upsert(project: Projekt) {
    const p = normalize(project);
    const all = read();

    const index = all.findIndex((x) => x.id === p.id);

    if (index >= 0) {
      all[index] = { ...p, updatedAt: nowISO() };
    } else {
      all.unshift({
        ...p,
        createdAt: nowISO(),
        updatedAt: nowISO(),
      });
    }

    write(all);
    return p;
  },

  create(partial?: Partial<Projekt>): Projekt {
    const now = nowISO();

    const p = normalize({
      id: crypto.randomUUID(),
      name: partial?.name ?? "Neues Projekt",
      baustellenNummer: partial?.baustellenNummer ?? "",
      bauleiter: partial?.bauleiter ?? "",
      ort: partial?.ort ?? "",
      status: partial?.status ?? "aktiv",
      createdAt: now,
      updatedAt: now,
    } as Projekt);

    const all = read();
    all.unshift(p);
    write(all);

    return p;
  },

  remove(id: ID) {
    const all = read().filter((p) => p.id !== id);
    write(all);
  },

  /* ================= CSV ================= */

  importCSV(csv: string) {
    if (!csv) return 0;

    const rows = csv.split(/\r?\n/).filter(Boolean).slice(1);
    const all = read();

    let count = 0;

    for (const line of rows) {
      try {
        const cols = line
          .split(";")
          .map((c) =>
            c.replace(/^"|"$/g, "").replace(/""/g, `"`)
          );

        const [name, nr, ort, bauleiter, status] = cols;

        const p = normalize({
          id: crypto.randomUUID(),
          name: name || "Importiertes Projekt",
          baustellenNummer: nr || "",
          ort: ort || "",
          bauleiter: bauleiter || "",
          status: status === "archiv" ? "archiv" : "aktiv",
          createdAt: nowISO(),
          updatedAt: nowISO(),
        } as Projekt);

        all.unshift(p);
        count++;
      } catch {
        // skip row
      }
    }

    write(all);
    return count;
  },

  exportCSV(list: Projekt[]) {
    const header =
      `"Name";"BaustellenNr";"Ort";"Bauleiter";"Status";"Erstellt";"Geändert"`;

    const lines = list.map((p) => {
      const pr = normalize(p);

      return [
        pr.name,
        pr.baustellenNummer ?? "",
        pr.ort ?? "",
        pr.bauleiter ?? "",
        pr.status,
        pr.createdAt,
        pr.updatedAt,
      ]
        .map((v) => `"${String(v).replace(/"/g, '""')}"`)
        .join(";");
    });

    return [header, ...lines].join("\r\n");
  },
};

import { HandoverDoc, HandoverAttachment } from "./types";

const KEY = "rlc-uebergabe-db";

/* ================= LOAD / SAVE ================= */

const load = (): HandoverDoc[] => {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
};

const save = (rows: HandoverDoc[]) => {
  localStorage.setItem(KEY, JSON.stringify(rows));
};

/* ================= HELPERS ================= */

function esc(s: string) {
  return (s || "").replace(/;/g, ",").replace(/\n/g, " ");
}

function normalize(d: HandoverDoc): HandoverDoc {
  return {
    id: d.id || crypto.randomUUID(),
    title: d.title || "Abnahme",
    projectId: d.projectId || undefined,
    client: d.client || "",
    address: d.address || "",
    date: d.date || new Date().toISOString(),
    status: d.status || "Entwurf",
    checklist: Array.isArray(d.checklist) ? d.checklist : [],
    signs: d.signs || {},
    attachments: Array.isArray(d.attachments) ? d.attachments : [],
    updatedAt: d.updatedAt || Date.now(),
  };
}

/* ================= DB ================= */

export const UebergabeDB = {
  list(): HandoverDoc[] {
    return load()
      .map(normalize)
      .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0));
  },

  create(projectId?: string): HandoverDoc {
    const doc = normalize({
      id: crypto.randomUUID(),
      title: "Abnahme",
      projectId,
      client: "",
      address: "",
      date: new Date().toISOString(),
      status: "Entwurf",
      checklist: [],
      signs: {},
      attachments: [],
      updatedAt: Date.now(),
    } as HandoverDoc);

    const all = load();
    all.push(doc);
    save(all);

    return doc;
  },

  upsert(doc: HandoverDoc) {
    const d = normalize(doc);

    const all = load();
    const index = all.findIndex((x) => x.id === d.id);

    if (index >= 0) {
      all[index] = d;
    } else {
      all.push(d);
    }

    save(all);
    return d;
  },

  remove(id: string) {
    const all = load().filter((x) => x.id !== id);
    save(all);
  },

  /* ================= ATTACHMENTS ================= */

  async attach(docId: string, file: File): Promise<HandoverAttachment | null> {
    const all = load();
    const index = all.findIndex((x) => x.id === docId);
    if (index === -1) return null;

    const d = normalize(all[index]);

    const dataURL = await new Promise<string>((res) => {
      const r = new FileReader();
      r.onload = () => res(String(r.result));
      r.readAsDataURL(file);
    });

    const attachment: HandoverAttachment = {
      id: crypto.randomUUID(),
      name: file.name,
      mime: file.type,
      size: file.size,
      dataURL,
    };

    d.attachments = [attachment, ...(d.attachments ?? [])];
    d.updatedAt = Date.now();

    all[index] = d;
    save(all);

    return attachment;
  },

  /* ================= CSV ================= */

  exportCSV(rows: HandoverDoc[]) {
    const header =
      "id;title;projectId;client;address;date;status;done/total";

    const body = rows
      .map((r) => {
        const d = normalize(r);

        const total = d.checklist?.length || 0;
        const done =
          d.checklist?.filter((i: any) => i.status === "ok").length || 0;

        return [
          d.id,
          esc(d.title || ""),
          d.projectId ?? "",
          esc(d.client || ""),
          esc(d.address || ""),
          d.date ?? "",
          d.status ?? "",
          `${done}/${total}`,
        ].join(";");
      })
      .join("\n");

    return header + "\n" + body;
  },

  /* ================= JSON ================= */

  exportJSON() {
    return JSON.stringify(load());
  },

  importJSON(txt: string) {
    try {
      const data: HandoverDoc[] = JSON.parse(txt || "[]");
      const normalized = data.map(normalize);
      save(normalized);
      return normalized.length;
    } catch {
      return 0;
    }
  },
};

import type { RlcUser } from "./types";

const KEY = "rlc-users-db";

/* ================= LOAD / SAVE ================= */

const load = (): RlcUser[] => {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? (parsed as RlcUser[]) : [];
  } catch {
    return [];
  }
};

const save = (rows: RlcUser[]) => {
  localStorage.setItem(KEY, JSON.stringify(rows));
};

/* ================= HELPERS ================= */

function asString(v: unknown): string {
  return typeof v === "string" ? v : "";
}

function asOptionalString(v: unknown): string | undefined {
  return typeof v === "string" && v.trim() ? v : undefined;
}

function normalize(u: RlcUser): RlcUser {
  const raw = u as RlcUser & { projectId?: string };

  const normalized: RlcUser & { projectId?: string } = {
    id: u.id || crypto.randomUUID(),
    name: u.name || "",
    email: u.email || "",
    role: u.role || "Mitarbeiter",
    active: typeof u.active === "boolean" ? u.active : true,
    rights: Array.isArray(u.rights) ? u.rights : [],
  };

  if (raw.projectId) {
    normalized.projectId = raw.projectId;
  }

  return normalized;
}

/* ================= DB ================= */

export const UserDB = {
  list(): RlcUser[] {
    return load()
      .map(normalize)
      .sort((a, b) => asString(a.name).localeCompare(asString(b.name)));
  },

  create(projectId?: string): RlcUser {
    const base: RlcUser & { projectId?: string } = {
      id: crypto.randomUUID(),
      name: "",
      email: "",
      role: "Mitarbeiter",
      active: true,
      rights: [],
    };

    const pid = asOptionalString(projectId);
    if (pid) base.projectId = pid;

    const user = normalize(base);

    const all = load();
    all.push(user);
    save(all);

    return user;
  },

  upsert(user: RlcUser) {
    const u = normalize(user);

    const all = load();
    const index = all.findIndex((x) => x.id === u.id);

    if (index >= 0) {
      all[index] = u;
    } else {
      all.push(u);
    }

    save(all);
    return u;
  },

  remove(id: string) {
    const all = load().filter((x) => x.id !== id);
    save(all);
  },
};

import React from "react";

import { API_BASE } from "../../lib/apiBase";
import { useProject } from "../../store/useProject";
import BuroWorkTabs from "./BuroWorkTabs";

type Task = {
  id: string;
  projectId: string;
  title: string;
  due?: string | null;
  done: boolean;
  assignee?: string | null;
  priority: string;
  tags: string[];
  createdAt: string;
  updatedAt: string;
};

function getToken() {
  const keys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc_auth_token",
    "rlc_access_token",
    "rlc.auth.token",
    "rlc_mobile_token"
  ];

  for (const key of keys) {
    for (const storage of [localStorage, sessionStorage]) {
      const value = storage.getItem(key);
      if (value?.trim()) return value.trim();
    }
  }

  for (const key of [
    "rlc_auth",
    "auth",
    "user",
    "session",
    "rlc_session"
  ]) {
    for (const storage of [localStorage, sessionStorage]) {
      const raw = storage.getItem(key);
      if (!raw) continue;

      try {
        const value = JSON.parse(raw);
        const token =
          value?.token ??
          value?.accessToken ??
          value?.authToken ??
          value?.jwt ??
          value?.data?.token ??
          value?.data?.accessToken;

        if (typeof token === "string" && token.trim()) {
          return token.trim();
        }
      } catch {}
    }
  }

  return "";
}

async function request<T>(
  path: string,
  init?: RequestInit
): Promise<T> {
  const token = getToken();

  const res = await fetch(`${API_BASE}${path}`, {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init?.body
        ? { "Content-Type": "application/json" }
        : {}),
      ...(token
        ? { Authorization: `Bearer ${token}` }
        : {}),
      ...(init?.headers || {})
    }
  });

  const data = await res.json().catch(() => ({}));

  if (!res.ok || data?.ok === false) {
    throw new Error(
      data?.error ||
      data?.message ||
      `HTTP ${res.status}`
    );
  }

  return data as T;
}

function dateOnly(value?: string | null) {
  if (!value) return "";
  return String(value).slice(0, 10);
}

export default function TasksPage() {
  const { getSelectedProject } = useProject();
  const project = getSelectedProject();

  const projectId = String(project?.id || "").trim();

  const projectLabel =
    [project?.code, project?.name]
      .filter(Boolean)
      .join(" · ") ||
    projectId ||
    "—";

  const [items, setItems] = React.useState<Task[]>([]);
  const [selectedId, setSelectedId] =
    React.useState<string | null>(null);

  const [query, setQuery] = React.useState("");
  const [openOnly, setOpenOnly] = React.useState(false);
  const [loading, setLoading] = React.useState(false);
  const [saving, setSaving] = React.useState(false);
  const [error, setError] = React.useState("");

  const selected =
    items.find((item) => item.id === selectedId) || null;

  const [form, setForm] = React.useState({
    title: "",
    due: "",
    assignee: "",
    priority: "med",
    tags: ""
  });

  const load = React.useCallback(async () => {
    if (!projectId) {
      setItems([]);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await request<{
        ok: true;
        items: Task[];
      }>(
        `/api/tasks?projectId=${encodeURIComponent(projectId)}`
      );

      setItems(data.items || []);

      setSelectedId((current) => {
        if (
          current &&
          data.items?.some((item) => item.id === current)
        ) {
          return current;
        }

        return data.items?.[0]?.id || null;
      });
    } catch (e: any) {
      setError(e?.message || "Aufgaben konnten nicht geladen werden.");
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  React.useEffect(() => {
    void load();
  }, [load]);

  React.useEffect(() => {
    if (!selected) {
      setForm({
        title: "",
        due: "",
        assignee: "",
        priority: "med",
        tags: ""
      });
      return;
    }

    setForm({
      title: selected.title || "",
      due: dateOnly(selected.due),
      assignee: selected.assignee || "",
      priority: selected.priority || "med",
      tags: (selected.tags || []).join(", ")
    });
  }, [selectedId, selected?.updatedAt]);

  async function createTask() {
    if (!projectId) return;

    setSaving(true);

    try {
      const data = await request<{
        ok: true;
        item: Task;
      }>("/api/tasks", {
        method: "POST",
        body: JSON.stringify({
          projectId,
          title: "Neue Aufgabe",
          priority: "med",
          tags: []
        })
      });

      await load();
      setSelectedId(data.item.id);
    } catch (e: any) {
      setError(e?.message || "Aufgabe konnte nicht erstellt werden.");
    } finally {
      setSaving(false);
    }
  }

  async function saveTask() {
    if (!selected) return;

    setSaving(true);

    try {
      await request(
        `/api/tasks/${encodeURIComponent(selected.id)}`,
        {
          method: "PUT",
          body: JSON.stringify({
            title: form.title,
            due: form.due || null,
            assignee: form.assignee || null,
            priority: form.priority,
            tags: form.tags
              .split(",")
              .map((x) => x.trim())
              .filter(Boolean)
          })
        }
      );

      await load();

due: form.due || null,
            assignee: form.assignee || null,
            priority: form.priority,
            tags: form.tags
              .split(",")
              .map((x) => x.trim())
              .filter(Boolean)
          })
        }
      );

      await load();
    } catch (e: any) {
      setError(e?.message || "Aufgabe konnte nicht gespeichert werden.");
    } finally {
      setSaving(false);
    }
  }

  async function toggleDone(task: Task) {
    await request(
      `/api/tasks/${encodeURIComponent(task.id)}`,
      {
        method: "PUT",
        body: JSON.stringify({
          done: !task.done
        })
      }
    );

    await load();
  }

  async function moveTaskToCalendar() {
    if (!selected) return;

    if (!selected.due) {
      window.alert("Bitte zuerst ein Fälligkeitsdatum festlegen.");
      return;
    }

    const start = new Date(selected.due);

    if (Number.isNaN(start.getTime())) {
      window.alert("Das Fälligkeitsdatum ist ungültig.");
      return;
    }

    start.setHours(9, 0, 0, 0);

    const end = new Date(start);
    end.setHours(10, 0, 0, 0);

    try {
      await request("/api/calendar", {
        method: "POST",
        body: JSON.stringify({
          projectId: selected.projectId,
          title: selected.title,
          start: start.toISOString(),
          end: end.toISOString(),
          allDay: false,
          attendees: [],
          notes: (selected as any).description || "",
          category: "Projekt",
          busyStatus: "busy",
          reminderMinutes: 15,
          sourceType: "task",
          sourceId: selected.id
        })
      });

      window.location.assign("/buro/outlook");
    } catch (e: any) {
      setError(
        e?.message ||
        "Termin konnte nicht erstellt werden."
      );
    }
  }

  async function removeTask() {
    if (!selected) return;

    if (!window.confirm(`Aufgabe "${selected.title}" löschen?`)) {
      return;
    }

    await request(
      `/api/tasks/${encodeURIComponent(selected.id)}`,
      { method: "DELETE" }
    );

    setSelectedId(null);
    await load();
  }

  const filtered = items.filter((item) => {
    const q = query.toLowerCase().trim();

    const text = [
      item.title,
      item.assignee || "",
      ...(item.tags || [])
    ].join(" ").toLowerCase();

    return (
      (!q || text.includes(q)) &&
      (!openOnly || !item.done)
    );
  });

  const openCount =
    items.filter((item) => !item.done).length;

  return (
    <div className="card">
      <header className="rlc-page-hero rlc-page-hero--split">
        <div>
          <div className="rlc-page-hero__eyebrow">
            Büro & Verwaltung
          </div>

          <h1>Aufgaben</h1>

          <p>
            Aufgaben, Zuständigkeiten und Termine zentral verwalten
            · Projekt {projectLabel}
          </p>
        </div>

        <div className="rlc-page-hero__actions">
          <button
            className="rlc-page-hero__button"
            onClick={() => void createTask()}
            disabled={!projectId || saving}
          >
            + Neue Aufgabe
          </button>
        </div>
      </header>

      <BuroWorkTabs active="aufgaben" />

      {error ? (
        <div className="card">{error}</div>
      ) : null}

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "repeat(3,minmax(0,1fr))",
          gap: 10,
          marginBottom: 12
        }}
      >
        <Kpi label="Gesamt" value={items.length} />
        <Kpi label="Offen" value={openCount} />
        <Kpi
          label="Erledigt"
          value={items.length - openCount}
        />
      </div>

      <div className="rlc-page-toolbar">
        <input
          className="rlc-page-toolbar__search"
          placeholder="Aufgabe, Zuständiger oder Tag suchen..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />

        <label>
          <input
            type="checkbox"
            checked={openOnly}
            onChange={(e) => setOpenOnly(e.target.checked)}
          />{" "}
          Nur offene
        </label>

        <button className="btn" onClick={() => void load()}>
          Aktualisieren
        </button>
      </div>

      <div
        className="rlc-page-workspace"
        style={{
          gridTemplateColumns: "360px minmax(0,1fr)",
          alignItems: "start"
        }}
      >
        <section className="rlc-page-list">
          <div className="rlc-page-section-head">
            <strong>Aufgaben</strong>
            <span>{filtered.length} Einträge</span>
          </div>

          <div className="rlc-page-document-list">
            {filtered.map((task) => (
              <button
                key={task.id}
                className={
                  selectedId === task.id
                    ? "rlc-page-document-row is-active"
                    : "rlc-page-document-row"
                }
                onClick={() => setSelectedId(task.id)}
              >
                <div className="rlc-page-document-icon">
                  {task.done ? "✓" : "A"}
                </div>

                <div className="rlc-page-document-copy">
                  <strong>{task.title}</strong>

                  <div className="rlc-page-document-meta">
                    <span>{task.assignee || "Nicht zugewiesen"}</span>
                    <span>{dateOnly(task.due) || "Kein Termin"}</span>

onClick={() => setSelectedId(task.id)}
              >
                <div className="rlc-page-document-icon">
                  {task.done ? "✓" : "A"}
                </div>

                <div className="rlc-page-document-copy">
                  <strong>{task.title}</strong>

                  <div className="rlc-page-document-meta">
                    <span>{task.assignee || "Nicht zugewiesen"}</span>
                    <span>{dateOnly(task.due) || "Kein Termin"}</span>
                    <span>Prio {task.priority}</span>
                  </div>
                </div>
              </button>
            ))}

            {!loading && filtered.length === 0 ? (
              <div className="rlc-page-empty">
                Keine Aufgaben vorhanden.
              </div>
            ) : null}
          </div>
        </section>

        <section className="rlc-page-detail">
          {!selected ? (
            <div className="rlc-page-empty">
              Aufgabe auswählen oder neu anlegen.
            </div>
          ) : (
            <>
              <div className="rlc-page-detail-head">
                <div className="rlc-page-detail-kicker">
                  Aufgabe
                </div>

                <h2>{selected.title}</h2>
              </div>

              <div className="rlc-page-detail-actions">
                <button
                  className="btn btn-primary"
                  onClick={() => void saveTask()}
                >
                  Speichern
                </button>

                <button
                  className="btn"
                  onClick={() => void toggleDone(selected)}
                >
                  {selected.done
                    ? "Wieder öffnen"
                    : "Abschließen"}
                </button>

                <button
                  className="btn"
                  onClick={() => void moveTaskToCalendar()}
                >
                  In Kalender übernehmen
                </button>

                <button
                  className="btn"
                  onClick={() => void removeTask()}
                >
                  Löschen
                </button>
              </div>

              <div
                style={{
                  padding: 18,
                  display: "grid",
