                  <input
                    value={form.title}
                    onChange={(e) =>
                      setForm({ ...form, title: e.target.value })
                    }
                  />
                </Field>

                <Field label="Fällig">
                  <input
                    type="date"
                    value={form.due}
                    onChange={(e) =>
                      setForm({ ...form, due: e.target.value })
                    }
                  />
                </Field>

                <Field label="Zuständig">
                  <input
                    value={form.assignee}
                    onChange={(e) =>
                      setForm({ ...form, assignee: e.target.value })
                    }
                  />
