import React from "react";

import { API_BASE } from "../../lib/apiBase";
import { useProject } from "../../store/useProject";
import {
  initDocument,
  uploadFileDirect
} from "../../api/files";

type ContractStatus =
  | "Entwurf"
  | "Aktiv"
  | "Läuft aus"
  | "Signiert"
  | "Beendet";

type ContractType =
  | "Bauvertrag"
  | "Nachunternehmervertrag"
  | "Liefervertrag"
  | "Mietvertrag"
  | "Wartungsvertrag"
  | "Arbeitsvertrag"
  | "Sonstige";

type ContractVersion = {
  id: string;
  version: number;
  createdAt?: string;
  uploadedBy?: string | null;
};

type ContractDocument = {
  id: string;
  name: string;
  kind?: string;
  currentVid?: string | null;
  updatedAt?: string;
  versions?: ContractVersion[];
};

type Contract = {
  id: string;
  companyId: string;
  projectId: string;
  documentId?: string | null;

  title: string;
  contractNumber?: string | null;
  partner?: string | null;
  contractType: ContractType;
  status: ContractStatus;

  valueNet: number;
  startDate?: string | null;
  endDate?: string | null;
  cancellationDays: number;

  notes?: string | null;
  tags: string[];

  createdAt?: string;
  updatedAt?: string;

  document?: ContractDocument | null;
};

function api(path: string) {
  return `${API_BASE}${path}`;
}

function getAuthToken(): string {
  try {
    const directKeys = [
      "rlc_token",
      "token",
      "authToken",
      "accessToken",
      "rlc_auth_token",
      "rlc_access_token",
      "rlc.auth.token",
      "rlc_mobile_token"
    ];

    for (const key of directKeys) {
      for (const storage of [localStorage, sessionStorage]) {
        const value = storage.getItem(key);
        if (value && value.trim()) return value.trim();
      }
    }

    const jsonKeys = [
      "rlc_auth",
      "auth",
      "user",
      "session",
      "rlc_session"
    ];

    for (const key of jsonKeys) {
      for (const storage of [localStorage, sessionStorage]) {
        const raw = storage.getItem(key);
        if (!raw) continue;

        try {
          const parsed = JSON.parse(raw);
          const token =
            parsed?.token ??
            parsed?.accessToken ??
            parsed?.authToken ??
            parsed?.jwt ??
            parsed?.data?.token ??
            parsed?.data?.accessToken;

          if (typeof token === "string" && token.trim()) {
            return token.trim();
          }
        } catch {}
      }
    }
  } catch {}

  return "";
}

async function request<T>(
  path: string,
  init?: RequestInit
): Promise<T> {
  const token = getAuthToken();

  const res = await fetch(api(path), {
    credentials: "include",
    ...init,
    headers: {
      Accept: "application/json",
      ...(init?.body
        ? { "Content-Type": "application/json" }
        : {}),
      ...(token
        ? { Authorization: `Bearer ${token}` }
        : {}),
      ...(init?.headers || {})
    }
  });

  const data = await res.json().catch(() => ({}));

  if (!res.ok) {
    throw new Error(
      data?.error ||
      `HTTP ${res.status}`
    );
  }

  return data as T;
}

function money(value: number) {
  return Number(value || 0).toLocaleString("de-DE", {
    style: "currency",
    currency: "EUR"
  });
}

function dateInput(value?: string | null) {
  if (!value) return "";

  const d = new Date(value);

  if (Number.isNaN(d.getTime())) {
    return "";
  }

  return d.toISOString().slice(0, 10);
}

function daysUntil(value?: string | null) {
  if (!value) return null;

  const end = new Date(value).getTime();

  if (!Number.isFinite(end)) {
    return null;
  }

  return Math.ceil(
    (end - Date.now()) /
    (1000 * 60 * 60 * 24)
  );
}

export default function Vertraege() {
  const { getSelectedProject } = useProject();
  const project = getSelectedProject();

  const projectId = String(project?.id || "").trim();
  const projectCode = String(project?.code || "").trim();

  const projectLabel =
    [projectCode, project?.name]
      .filter(Boolean)
      .join(" · ") ||
    projectId ||
    "—";

  const [all, setAll] = React.useState<Contract[]>([]);
  const [selectedId, setSelectedId] =
    React.useState<string | null>(null);

  const [search, setSearch] = React.useState("");
  const [statusFilter, setStatusFilter] =
    React.useState("ALL");
  const [typeFilter, setTypeFilter] =
    React.useState("ALL");

  const [loading, setLoading] =
    React.useState(false);
  const [saving, setSaving] =
    React.useState(false);
  const [error, setError] =
    React.useState("");

  const selected =
    all.find((row) => row.id === selectedId) ||
    null;

  const load = React.useCallback(async () => {
    if (!projectId) {
      setAll([]);
      setSelectedId(null);
      return;
    }

    setLoading(true);
    setError("");

    try {
      const data = await request<{
        ok: true;
        items: Contract[];
      }>(
        `/api/contracts?projectId=${encodeURIComponent(projectId)}`
      );

      const rows = Array.isArray(data.items)
        ? data.items
        : [];

      setAll(rows);

      setSelectedId((current) => {
        if (
          current &&
          rows.some((row) => row.id === current)
        ) {
          return current;
        }

        return rows[0]?.id || null;
      });
    } catch (e: any) {
      setError(
        e?.message ||
        "Verträge konnten nicht geladen werden."
      );
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  React.useEffect(() => {
    void load();

} catch (e: any) {
      setError(
        e?.message ||
        "Verträge konnten nicht geladen werden."
      );
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  React.useEffect(() => {
    void load();
  }, [load]);

  function localPatch(values: Partial<Contract>) {
    if (!selectedId) return;

    setAll((rows) =>
      rows.map((row) =>
        row.id === selectedId
          ? { ...row, ...values }
          : row
      )
    );
  }

  async function savePatch(
    id: string,
    values: Partial<Contract>
  ) {
    setSaving(true);
    setError("");

    try {
      await request(
        `/api/contracts/${encodeURIComponent(id)}`,
        {
          method: "PUT",
          body: JSON.stringify(values)
        }
      );

    } catch (e: any) {
      setError(
        e?.message ||
        "Vertrag konnte nicht gespeichert werden."
      );
    } finally {
      setSaving(false);
    }
  }

  async function saveContract() {
    if (!selected) return;

    await savePatch(selected.id, {
      title: selected.title,
      contractNumber: selected.contractNumber || "",
      partner: selected.partner || "",
      contractType: selected.contractType,
      status: selected.status,
      valueNet: Number(selected.valueNet || 0),
      startDate: selected.startDate || "",
      endDate: selected.endDate || "",
      cancellationDays: Number(selected.cancellationDays || 0),
      notes: selected.notes || "",
      tags: selected.tags || []
    });

    await load();
  }

  async function createContract() {
    if (!projectId) return;

    setSaving(true);
    setError("");

    try {
      const data = await request<{
        ok: true;
        item: Contract;
      }>("/api/contracts", {
        method: "POST",
        body: JSON.stringify({
          projectId,
          title: "Neuer Vertrag",
          contractType: "Bauvertrag",
