    }
  }

  async function deleteContract() {
    if (!selected) return;

    if (
      !window.confirm(
        `Vertrag "${selected.title}" wirklich löschen?`
      )
    ) {
      return;
    }

    setSaving(true);
    setError("");

    try {
      await request(
