function pickFile(
  onPick: (file: File) => void
) {
  const input =
    document.createElement("input");

  input.type = "file";
  input.accept =
    ".pdf,.doc,.docx,.xls,.xlsx,image/*";

  input.onchange = () => {
    const file =
      input.files?.[0];

    if (file) {
      onPick(file);
    }
  };

  input.click();
}

