    const viewportBounds: Bounds = {
      minX: viewBox.x - marginX,
      minY: -(viewBox.y + viewBox.height) - marginY,
      maxX: viewBox.x + viewBox.width + marginX,
      maxY: -viewBox.y + marginY,
