        if (res.ok && data?.ok !== false) {
          const payload = (data?.data || data?.document || data) as TakeoffPayload;
          const imported = normalizeFeatures(payload);
          if (imported.length) {
            replaceDrawing(imported, payload);
            setDirty(true);
            await persistCadDrawing(imported, {
