import { rlcClass } from "../../ui/rlcRuntimeStyle";import React from "react";
import L from "leaflet";
// @ts-ignore
import "leaflet.gridlayer.googlemutant";
import "leaflet/dist/leaflet.css";

export type LatLng = {lat: number;lng: number;};

export type GeoShape =
{type: "points";pts: LatLng[];} |
{type: "line";pts: LatLng[];} |
{type: "polygon";pts: LatLng[];};

type Props = {
  initialCenter?: LatLng;
  initialZoom?: number;
  shape?: GeoShape | null;
  autoFit?: boolean;
  onMapClick?: (p: LatLng) => void;
  height?: string | number;
};

export type CadGeoMapHandle = {
  fitToShape: () => void;
  clear: () => void;
  exportSnapshotPngDataUrl: () => Promise<string | null>;
  setShape: (s: GeoShape | null) => void;
};

function clampPts<T>(pts: T[] | undefined | null, max = 20000): T[] {
  if (!Array.isArray(pts)) return [];
  return pts.length > max ? pts.slice(0, max) : pts;
}

const cardStyle: React.CSSProperties = {
  padding: 0,
  overflow: "hidden",
  border: "1px solid #e5e7eb",
  borderRadius: 12,
  background: "#fff"
};

const hintStyle: React.CSSProperties = {
  padding: 10,
  fontSize: 12,
  opacity: 0.8
};

export const CadGeoMap = React.forwardRef<CadGeoMapHandle, Props>(
  function CadGeoMap(
  {
    initialCenter = { lat: 48.14, lng: 11.58 },
    initialZoom = 12,
    shape = null,
    autoFit = true,
    onMapClick,
    height = "75vh"
  },
  ref)
  {
    const containerRef = React.useRef<HTMLDivElement | null>(null);
    const mapRef = React.useRef<L.Map | null>(null);
    const geomLayerRef = React.useRef<L.LayerGroup | null>(null);

    const [localShape, setLocalShape] = React.useState<GeoShape | null>(
      shape ?? null
    );

    React.useEffect(() => {
      setLocalShape(shape ?? null);
    }, [shape]);

    React.useEffect(() => {
      const container = containerRef.current;
      if (!container || mapRef.current) return;

      const map = L.map(container, {
        zoomControl: true,
        preferCanvas: true,
        maxZoom: 22
      }).setView([initialCenter.lat, initialCenter.lng], initialZoom);

      const osm = L.tileLayer(
        "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png",
        {
          maxZoom: 19,
          attribution: "© OpenStreetMap",
          crossOrigin: true
        }
      ).addTo(map);

      const bayernLuftbild = (L as any).tileLayer.wms(
        "https://geoservices.bayern.de/od/wms/dop/v1/dop20?",
        {
          layers: "by_dop20c",
          format: "image/jpeg",
          transparent: false,
          version: "1.3.0",
          tiled: true,
          maxZoom: 21,
          attribution: "© Bayerische Vermessungsverwaltung",
          crossOrigin: true
        }
      );

      const baseLayers: Record<string, L.Layer> = {
        OSM: osm,
        "Bayern Luftbild (WMS)": bayernLuftbild
      };

      try {
        const key = (import.meta as any)?.env?.VITE_GOOGLE_MAPS_KEY;
        if (key && (L as any).gridLayer?.googleMutant) {
          baseLayers["Google Road"] = (L as any).gridLayer.googleMutant({
            type: "roadmap",
            maxZoom: 21,
            apiKey: key
          });
          baseLayers["Google Sat"] = (L as any).gridLayer.googleMutant({
            type: "satellite",
            maxZoom: 21,
            apiKey: key
          });
        }
      } catch (e) {
        console.warn("Google layers disabled:", e);
      }

      const overlayParzellen = (L as any).tileLayer.wms(
        "https://geoservices.bayern.de/od/wms/alkis/v1/parzellarkarte?",
        {
          layers: "by_alkis_parzellarkarte_umr_schwarz",
          format: "image/png",
          transparent: true,
          version: "1.3.0",
          tiled: true,
          maxZoom: 21,
          attribution: "© Bayerische Vermessungsverwaltung (ALKIS® OpenData)",
          crossOrigin: true
        }
      );

      const overlayGrenzen = (L as any).tileLayer.wms(
        "https://geoservices.bayern.de/od/wms/alkis/v1/verwaltungsgrenzen?",
        {
          layers: "by_alkis_gmd_grenze",
          format: "image/png",
          transparent: true,
          version: "1.3.0",
          tiled: true,
          maxZoom: 21,
          attribution: "© Bayerische Vermessungsverwaltung (ALKIS® OpenData)",
          crossOrigin: true
        }
      );

      const overlays: Record<string, L.Layer> = {
        "Flurkarte / Parzellen (WMS)": overlayParzellen,
        "Grenzen (WMS)": overlayGrenzen
      };

      L.control.layers(baseLayers, overlays).addTo(map);

      overlayParzellen.addTo(map);
      overlayGrenzen.addTo(map);

      geomLayerRef.current = L.layerGroup().addTo(map);

      map.on("click", (e: L.LeafletMouseEvent) => {
        onMapClick?.({ lat: e.latlng.lat, lng: e.latlng.lng });
      });

      mapRef.current = map;

      setTimeout(() => {
        map.invalidateSize();
      }, 200);

      return () => {
        map.off();
        map.remove();
        mapRef.current = null;
        geomLayerRef.current = null;
      };
    }, [initialCenter.lat, initialCenter.lng, initialZoom, onMapClick]);

    const clearGeom = React.useCallback(() => {
      geomLayerRef.current?.clearLayers();
    }, []);

    const drawGeom = React.useCallback(
      (s: GeoShape | null) => {
        const map = mapRef.current;
        const layer = geomLayerRef.current;
        if (!map || !layer) return;

        clearGeom();
        if (!s) return;

        const pts = clampPts(s.pts, 20000);
        if (!pts.length) return;

const drawGeom = React.useCallback(
      (s: GeoShape | null) => {
        const map = mapRef.current;
        const layer = geomLayerRef.current;
        if (!map || !layer) return;

        clearGeom();
        if (!s) return;

        const pts = clampPts(s.pts, 20000);
        if (!pts.length) return;

        if (s.type === "points") {
          pts.forEach((p) => {
            L.circleMarker([p.lat, p.lng], { radius: 4 }).addTo(layer);
          });
        } else if (s.type === "line") {
          pts.forEach((p) => {
            L.circleMarker([p.lat, p.lng], { radius: 3 }).addTo(layer);
          });
          if (pts.length >= 2) {
            L.polyline(
              pts.map((p) => [p.lat, p.lng]) as [number, number][],
              { weight: 3 }
            ).addTo(layer);
          }
        } else if (s.type === "polygon") {
          pts.forEach((p) => {
            L.circleMarker([p.lat, p.lng], { radius: 3 }).addTo(layer);
          });
          if (pts.length >= 3) {
            L.polygon(
              pts.map((p) => [p.lat, p.lng]) as [number, number][],
              { weight: 2, fillOpacity: 0.12 }
            ).addTo(layer);
          }
        }

        if (autoFit) {
          try {
            const bounds = L.latLngBounds(
              pts.map((p) => [p.lat, p.lng]) as [number, number][]
            );
            map.fitBounds(bounds, { padding: [30, 30] });
          } catch {

            // ignore
          }}
      },
      [autoFit, clearGeom]
    );

    React.useEffect(() => {
      drawGeom(localShape);
    }, [localShape, drawGeom]);

    const exportSnapshotPngDataUrl = React.useCallback(async (): Promise<string | null> => {
      const el = containerRef.current;
      const map = mapRef.current;
      if (!el || !map) return null;

      try {
        map.invalidateSize();
        await new Promise((r) => setTimeout(r, 250));

        const { default: html2canvas } = await import("html2canvas");
        const canvas = await html2canvas(el, {
          useCORS: true,
          allowTaint: false,
          backgroundColor: "#ffffff",
          scale: 2,
          logging: false
        });

        return canvas.toDataURL("image/png");
      } catch (e) {
        console.warn("Map snapshot failed:", e);
        return null;
      }
    }, []);

    React.useImperativeHandle(
      ref,
      () => ({
        fitToShape: () => {
          const map = mapRef.current;
          const pts = localShape?.pts;
          if (!map || !pts?.length) return;

          const bounds = L.latLngBounds(
            pts.map((p) => [p.lat, p.lng]) as [number, number][]
          );
          map.fitBounds(bounds, { padding: [30, 30] });
        },
        clear: () => setLocalShape(null),
        exportSnapshotPngDataUrl,
        setShape: (s) => setLocalShape(s)
      }),
      [localShape, exportSnapshotPngDataUrl]
    );

    return (
      <div className={rlcClass(null, cardStyle)}>
        <div
          ref={containerRef} className={rlcClass(null,
          {
            width: "100%",
            height
          })} />

        <div className={rlcClass(null, hintStyle)}>
          Hinweis: Bei aktivem Google-Layer kann der Snapshot leer oder schwarz
          sein (CORS). Für sichere Exporte besser OSM/WMS verwenden.
        </div>
      </div>);

  }
);

// apps/web/src/pages/cad/cadGeoTransform.ts

export type V2 = { x: number; y: number };
export type LatLng = { lat: number; lng: number };

export type Similarity = {
  // worldXY -> mercatorXY (meters)
  s: number;
  cos: number;
  sin: number;
  tx: number;
  ty: number;
};

const R = 6378137; // WebMercator sphere radius (meters)
const MAX_LAT = 85.05112878;

function clampLat(lat: number): number {
  return Math.max(-MAX_LAT, Math.min(MAX_LAT, lat));
}

export function isValidSimilarity(t: Similarity | null | undefined): t is Similarity {
  return !!t &&
    Number.isFinite(t.s) &&
    Number.isFinite(t.cos) &&
    Number.isFinite(t.sin) &&
    Number.isFinite(t.tx) &&
    Number.isFinite(t.ty) &&
    Math.abs(t.s) > 1e-12;
}

export function latLngToMercator(p: LatLng): V2 {
  const lat = clampLat(p.lat);
  const x = (p.lng * Math.PI) / 180;
  const y = (lat * Math.PI) / 180;

  return {
    x: R * x,
    y: R * Math.log(Math.tan(Math.PI / 4 + y / 2)),
  };
}

export function mercatorToLatLng(m: V2): LatLng {
  const lng = (m.x / R) * (180 / Math.PI);
  const lat =
    (2 * Math.atan(Math.exp(m.y / R)) - Math.PI / 2) * (180 / Math.PI);

  return {
    lat: clampLat(lat),
    lng,
  };
}

/**
 * Calibrazione con 2 punti:
 * world A,B (CAD) -> mercator A,B (map)
 * Risolve una trasformazione di similitudine: M = s * R(theta) * W + T
 */
export function solveSimilarity2Points(
  worldA: V2,
  worldB: V2,
  mapA: LatLng,
  mapB: LatLng
): Similarity | null {
  const mA = latLngToMercator(mapA);
  const mB = latLngToMercator(mapB);

  const vW = {
    x: worldB.x - worldA.x,
    y: worldB.y - worldA.y,
  };

  const vM = {
    x: mB.x - mA.x,
    y: mB.y - mA.y,
  };

  const lenW = Math.hypot(vW.x, vW.y);
  const lenM = Math.hypot(vM.x, vM.y);

  if (!Number.isFinite(lenW) || !Number.isFinite(lenM) || lenW < 1e-9 || lenM < 1e-9) {
    return null;
  }

  const s = lenM / lenW;

  let cos = (vW.x * vM.x + vW.y * vM.y) / (lenW * lenM);
  let sin = (vW.x * vM.y - vW.y * vM.x) / (lenW * lenM);

  // normalizzazione numerica
  const norm = Math.hypot(cos, sin) || 1;
  cos /= norm;
  sin /= norm;

  const rwA = {
    x: s * (cos * worldA.x - sin * worldA.y),
    y: s * (sin * worldA.x + cos * worldA.y),
  };

  return {
    s,
    cos,
    sin,
    tx: mA.x - rwA.x,
    ty: mA.y - rwA.y,
  };
}

export function worldToMercator(w: V2, t: Similarity): V2 {
  return {
    x: t.s * (t.cos * w.x - t.sin * w.y) + t.tx,
    y: t.s * (t.sin * w.x + t.cos * w.y) + t.ty,
  };
}

export function worldToLatLng(w: V2, t: Similarity): LatLng {
  return mercatorToLatLng(worldToMercator(w, t));
}

export function mercatorToWorld(m: V2, t: Similarity): V2 {
  const dx = m.x - t.tx;
  const dy = m.y - t.ty;

  // inversa di s * R
  return {
    x: (t.cos * dx + t.sin * dy) / t.s,
    y: (-t.sin * dx + t.cos * dy) / t.s,
  };
}

export function latLngToWorld(p: LatLng, t: Similarity): V2 {
  return mercatorToWorld(latLngToMercator(p), t);
}

