/*
 * RLC CAD Engine V1
 * Framework-independent geometry core used by the React editor.
 * BricsCAD is deliberately not referenced here.
 */

export type CadPoint = { x: number; y: number };

export type CadViewBox = {
  x: number;
  y: number;
  width: number;
  height: number;
};

export function rebaseCadPoint(
  point: CadPoint,
  origin: CadPoint
): CadPoint {
  return {
    x: point.x - origin.x,
    y: point.y - origin.y,
  };
}

export function restoreCadPoint(
  point: CadPoint,
  origin: CadPoint
): CadPoint {
  return {
    x: point.x + origin.x,
    y: point.y + origin.y,
  };
}

export function rebaseCadViewBox(
  viewBox: CadViewBox,
  origin: CadPoint
): CadViewBox {
  return {
    x: viewBox.x - origin.x,
    y: viewBox.y - origin.y,
    width: viewBox.width,
    height: viewBox.height,
  };
}

export function zoomCadViewBox(
  previous: CadViewBox,
  factor: number,
  anchorRatio: CadPoint
): CadViewBox {
  const safeFactor =
    Number.isFinite(factor) && factor > 0 ? factor : 1;
  const rx = Math.max(0, Math.min(1, Number(anchorRatio.x) || 0));
  const ry = Math.max(0, Math.min(1, Number(anchorRatio.y) || 0));
  const nextWidth = Math.max(
    0.001,
    Math.min(1e12, previous.width * safeFactor)
  );
  const nextHeight = Math.max(
    0.001,
    Math.min(1e12, previous.height * safeFactor)
  );
  const anchorX = previous.x + previous.width * rx;
  const anchorY = previous.y + previous.height * ry;
  return {
    x: anchorX - nextWidth * rx,
    y: anchorY - nextHeight * ry,
    width: nextWidth,
    height: nextHeight,
  };
}

export type CadFeatureKind =
  | "point"
  | "line"
  | "polyline"
  | "polygon"
  | "circle"
  | "text";

export type CadFeature = {
  id?: string;
