};

const EPSILON = 1e-9;

function finite(value: unknown, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? number : fallback;
}

function distance(a: CadPoint, b: CadPoint) {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function featureLength(points: CadPoint[], closed: boolean) {
  let total = 0;
  for (let index = 1; index < points.length; index += 1) {
    total += distance(points[index - 1], points[index]);
  }
  if (closed && points.length > 2) {
    total += distance(points[points.length - 1], points[0]);
  }
  return total;
}

function featureArea(points: CadPoint[]) {
  if (points.length < 3) return 0;
  let sum = 0;
  for (let index = 0; index < points.length; index += 1) {
    const current = points[index];
    const next = points[(index + 1) % points.length];
    sum += current.x * next.y - next.x * current.y;
  }
  return Math.abs(sum) / 2;
}

function normalizePoint(point: unknown): CadPoint | null {
  const candidate = point as Partial<CadPoint> | null | undefined;
  const x = Number(candidate?.x);
  const y = Number(candidate?.y);
  return Number.isFinite(x) && Number.isFinite(y) ? { x, y } : null;
}

export function createCadId(prefix = "CAD") {
  const random = Math.random().toString(36).slice(2, 8).toUpperCase();
  return `${prefix}_${Date.now().toString(36).toUpperCase()}_${random}`;
}

export function cloneCadFeatures(features: CadFeature[]) {
  return features.map((feature) => ({
    ...feature,
    pts: (feature.pts || []).map((point) => ({ ...point })),
    style: feature.style ? { ...feature.style } : undefined,
    meta: feature.meta ? { ...feature.meta } : undefined,
  }));
}

export function recalculateCadFeature(
  feature: CadFeature,
  fallbackIndex = 0
): CadFeature {
  const points = Array.isArray(feature.pts)
    ? feature.pts.map(normalizePoint).filter((point): point is CadPoint => Boolean(point))
    : [];
  const kind: CadFeatureKind =
    feature.kind ||
    (feature.closed ? "polygon" : points.length === 1 ? "point" : "polyline");
  const closed = Boolean(feature.closed || kind === "polygon");
  const radius = Math.max(0, finite(feature.radius));
  const suppliedLength = Math.max(0, finite(feature.length));
  const suppliedArea = Math.max(0, finite(feature.area));
  const length =
    kind === "circle"
      ? Math.PI * radius * 2
      : points.length > 1

: [];
  const kind: CadFeatureKind =
    feature.kind ||
    (feature.closed ? "polygon" : points.length === 1 ? "point" : "polyline");
  const closed = Boolean(feature.closed || kind === "polygon");
  const radius = Math.max(0, finite(feature.radius));
  const suppliedLength = Math.max(0, finite(feature.length));
  const suppliedArea = Math.max(0, finite(feature.area));
  const length =
    kind === "circle"
      ? Math.PI * radius * 2
      : points.length > 1
      ? featureLength(points, closed)
      : suppliedLength;
  const area =
    kind === "circle"
      ? Math.PI * radius * radius
      : closed && points.length > 2
      ? featureArea(points)
      : suppliedArea;

  return {
    ...feature,
    id: String(feature.id || createCadId(`F${fallbackIndex + 1}`)),
    kind,
    layer: String(feature.layer || "0"),
    pts: points,
    closed,
    radius: kind === "circle" ? radius : feature.radius,
    length,
    area,
  };
}

export function normalizeCadFeatures(payload: unknown): CadFeature[] {
  const source = payload as any;
  const candidates = Array.isArray(source?.features)
    ? source.features
    : Array.isArray(source?.normalized?.features)
    ? source.normalized.features
    : Array.isArray(source?.data?.features)
    ? source.data.features
    : Array.isArray(source?.data?.entities)
    ? source.data.entities
    : Array.isArray(source?.entities)
    ? source.entities
    : Array.isArray(source?.rows)
    ? source.rows
    : Array.isArray(source?.data?.rows)
    ? source.data.rows
    : Array.isArray(source?.takeoff)
    ? source.takeoff
    : [];

  return candidates.map((rawFeature: any, index: number) => {
    const rawPoints =
      rawFeature?.pts ||
      rawFeature?.points ||
      rawFeature?.vertices ||
      rawFeature?.geometry?.points ||
      rawFeature?.geometry?.coordinates ||
      [];
    const pts = Array.isArray(rawPoints)
      ? rawPoints
          .map((point: any) =>
            Array.isArray(point)
              ? normalizePoint({ x: point[0], y: point[1] })
              : normalizePoint(point)
          )
          .filter((point: CadPoint | null): point is CadPoint => Boolean(point))
      : [];
    const rawType = String(
      rawFeature?.kind ||
        rawFeature?.type ||
        rawFeature?.entityType ||
        rawFeature?.EntityType ||
        ""
    ).toLowerCase();
    const kind: CadFeatureKind =
      rawType.includes("circle") || rawType.includes("kreis")
        ? "circle"
        : rawType.includes("point") || rawType.includes("punkt")
        ? "point"
        : rawType.includes("text")
        ? "text"
        : rawType.includes("polygon") || Boolean(rawFeature?.closed)
        ? "polygon"
        : rawType.includes("line") && pts.length === 2
        ? "line"
        : "polyline";
    const lvPos =
      rawFeature?.meta?.lvPos ??
      rawFeature?.meta?.LvPos ??
      rawFeature?.lvPos ??
      rawFeature?.LvPos ??
      "";
    const lvText =
      rawFeature?.meta?.lvText ??
      rawFeature?.meta?.LvText ??
      rawFeature?.lvText ??
      rawFeature?.LvText ??
      "";

    return recalculateCadFeature(
      {
        ...rawFeature,
        id:
          rawFeature?.id ||
          rawFeature?.handle ||
          rawFeature?.Handle ||
          `F_${index + 1}`,
        kind,
        layer: rawFeature?.layer || rawFeature?.Layer || "0",
        name:
          rawFeature?.name ||
          rawFeature?.Name ||
          rawFeature?.label ||
          lvText ||
          undefined,
        pts,
        closed: Boolean(
          rawFeature?.closed ||
            rawFeature?.Closed ||
            kind === "polygon"
        ),
        radius:
          rawFeature?.radius ??
          rawFeature?.Radius ??
          rawFeature?.geometry?.radius,
        text: rawFeature?.text || rawFeature?.Text,
        length:
          rawFeature?.length ??
          rawFeature?.Length ??
          rawFeature?.laenge ??
          rawFeature?.Laenge,
        area:
          rawFeature?.area ??
          rawFeature?.Area ??
          rawFeature?.flaeche ??
          rawFeature?.Flaeche,
        meta: {
          ...(rawFeature?.meta || {}),
          ...(lvPos ? { lvPos: String(lvPos) } : {}),
          ...(lvText ? { lvText: String(lvText) } : {}),
          source: rawFeature?.meta?.source || "RLC Mengenermittlung",
        },
      },
      index
    );
  });
}

export function createCadDocument(
  projectId: string,
  features: CadFeature[],
  source?: CadDocument["source"]
): CadDocument {
  return {
    schema: "rlc-cad",
    schemaVersion: 1,
    projectId,
    updatedAt: new Date().toISOString(),
    source,
    features: cloneCadFeatures(features).map(recalculateCadFeature),
  };
}

export function translateCadFeatures(
  features: CadFeature[],
  selectedIds: string[],
  dx: number,
  dy: number
) {
  const selected = new Set(selectedIds);
  return features.map((feature, index) => {
    if (!selected.has(String(feature.id || ""))) return feature;
    return recalculateCadFeature(
      {
        ...feature,
        pts: (feature.pts || []).map((point) => ({
          x: point.x + dx,
          y: point.y + dy,
        })),
      },
      index
    );
  });
}

