export function duplicateCadFeatures(
  features: CadFeature[],
  selectedIds: string[],
  dx = 0,
  dy = 0
) {
  const selected = new Set(selectedIds);
  const copies: CadFeature[] = [];
  const copiedIds: string[] = [];

  features.forEach((feature, index) => {
    if (!selected.has(String(feature.id || ""))) return;
    const copiedId = createCadId("COPY");
    copiedIds.push(copiedId);
    copies.push(
      recalculateCadFeature(
        {
          ...feature,
          id: copiedId,
          pts: (feature.pts || []).map((point) => ({
            x: point.x + dx,
            y: point.y + dy,
          })),
          style: feature.style ? { ...feature.style } : undefined,
          meta: {
            ...(feature.meta || {}),
            copiedFrom: String(feature.id || ""),
          },
        },
        features.length + index
      )
    );
  });

  return {
    features: [...features, ...copies],
    copiedIds,
  };
}

export function rotateCadFeatures(
  features: CadFeature[],
  selectedIds: string[],
  center: CadPoint,
  angleDegrees: number
) {
  const selected = new Set(selectedIds);
  const angle = (angleDegrees * Math.PI) / 180;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);

  return features.map((feature, index) => {
    if (!selected.has(String(feature.id || ""))) return feature;
    return recalculateCadFeature(
      {
        ...feature,
        rotation: Number(feature.rotation || 0) + angleDegrees,
        pts: (feature.pts || []).map((point) => {
          const x = point.x - center.x;
          const y = point.y - center.y;
          return {
            x: center.x + x * cos - y * sin,
            y: center.y + x * sin + y * cos,
          };
        }),
      },
      index
    );
  });
}

export function scaleCadFeatures(
  features: CadFeature[],
  selectedIds: string[],
  center: CadPoint,
  factor: number
) {
  if (!Number.isFinite(factor) || Math.abs(factor) < EPSILON) return features;
  const selected = new Set(selectedIds);

  return features.map((feature, index) => {
    if (!selected.has(String(feature.id || ""))) return feature;
    const height = Number((feature.meta as any)?.height || 0);
    return recalculateCadFeature(
      {
        ...feature,
        radius:
          feature.kind === "circle"
            ? Math.abs(Number(feature.radius || 0) * factor)
            : feature.radius,
        pts: (feature.pts || []).map((point) => ({
          x: center.x + (point.x - center.x) * factor,
          y: center.y + (point.y - center.y) * factor,
        })),
        meta: {
          ...(feature.meta || {}),
          ...(height
            ? { height: Math.abs(height * factor) }
            : {}),
        },
      },
      index
    );
  });
}

function unitNormal(a: CadPoint, b: CadPoint) {
  const dx = b.x - a.x;
  const dy = b.y - a.y;
  const length = Math.hypot(dx, dy);
  if (length < EPSILON) return { x: 0, y: 0 };
  return { x: -dy / length, y: dx / length };
}

function offsetPolylinePoints(
  points: CadPoint[],
  closed: boolean,
  amount: number
) {
  if (points.length < 2 || Math.abs(amount) < EPSILON) {
    return points.map((point) => ({ ...point }));
  }

  const segmentCount = closed ? points.length : points.length - 1;
  const normals = Array.from({ length: segmentCount }, (_, index) =>
    unitNormal(points[index], points[(index + 1) % points.length])
  );

  return points.map((point, index) => {
    if (!closed && index === 0) {
      return {
        x: point.x + normals[0].x * amount,
        y: point.y + normals[0].y * amount,
      };
    }
    if (!closed && index === points.length - 1) {
      const normal = normals[normals.length - 1];
      return {
        x: point.x + normal.x * amount,
        y: point.y + normal.y * amount,
      };
    }

    const previous = normals[(index - 1 + normals.length) % normals.length];
    const next = normals[index % normals.length];
    const sum = { x: previous.x + next.x, y: previous.y + next.y };
    const sumLength = Math.hypot(sum.x, sum.y);
    if (sumLength < EPSILON) {
      return {
        x: point.x + next.x * amount,
        y: point.y + next.y * amount,
      };
    }
    const miter = { x: sum.x / sumLength, y: sum.y / sumLength };
    const denominator = Math.max(
      0.25,
      Math.abs(miter.x * next.x + miter.y * next.y)
    );
    const miterAmount = Math.min(Math.abs(amount) * 4, Math.abs(amount / denominator));
    const signedAmount = amount < 0 ? -miterAmount : miterAmount;
    return {
      x: point.x + miter.x * signedAmount,
      y: point.y + miter.y * signedAmount,
    };
  });
}

