function repeatedPoints(
  pairs: DxfPair[],
  xCode: number,
  yCode: number,
  scale: number
) {
  const points: CadPoint[] = [];
  let current: { x: number; y: number | null } | null = null;
  const flush = () => {
    if (current && current.y !== null) {
      points.push({ x: current.x, y: current.y });
    }
