      flush();
      current = { x: finite(pair.value) * scale, y: null };
    } else if (pair.code === yCode && current) {
      current.y = finite(pair.value) * scale;
    }
  }
  flush();
  return points;
}

function dxfUnitScale(pairs: DxfPair[]) {
  const unitScales: Record<number, number> = {
    0: 1,
    1: 0.0254,
    2: 0.3048,
    3: 1609.344,
    4: 0.001,
    5: 0.01,
    6: 1,
    7: 1000,
    8: 0.0000000254,
    9: 0.0000254,
    10: 0.9144,
    11: 0.0000001,
    12: 0.000000001,
    13: 0.000000000001,
    14: 0.1,
    15: 10,
    16: 100,
    17: 1000000000,
    18: 149597870700,
    19: 9460730472580800,
    20: 30856775814913670,
  };

  for (let index = 0; index < pairs.length - 1; index += 1) {
    if (pairs[index].code !== 9 || pairs[index].value !== "$INSUNITS") continue;
    for (let lookAhead = index + 1; lookAhead < Math.min(index + 6, pairs.length); lookAhead += 1) {
      if (pairs[lookAhead].code === 70) {
        const unitCode = Math.trunc(finite(pairs[lookAhead].value));
        return { unitCode, scale: unitScales[unitCode] ?? 1 };
      }
    }
  }
  return { unitCode: 0, scale: 1 };
}

function dxfAciColor(value: number) {
  const aci: Record<number, string> = {
    1: "#ff4d4f",
    2: "#ffd43b",
    3: "#51cf66",
    4: "#22d3ee",
    5: "#4dabf7",
    6: "#e649f5",
    7: "#e5e7eb",
    8: "#94a3b8",
    9: "#d1d5db",
  };
  return aci[Math.abs(Math.trunc(value))] || undefined;
}

function dxfTrueColor(value: number) {
  const color = Math.max(0, Math.trunc(value));
  if (!color) return undefined;
  return `#${(color & 0xffffff).toString(16).padStart(6, "0")}`;
}

function dxfLayerStyles(pairs: DxfPair[]) {
  const styles = new Map<string, DxfLayerStyle>();
  for (let index = 0; index < pairs.length; index += 1) {
    if (
      pairs[index].code !== 0 ||
      pairs[index].value.toUpperCase() !== "LAYER"
    ) {
      continue;
    }

    const entityPairs: DxfPair[] = [];
    index += 1;
    while (index < pairs.length && pairs[index].code !== 0) {
      entityPairs.push(pairs[index]);
      index += 1;
    }
    index -= 1;

    const name = firstValue(entityPairs, 2);
    if (!name) continue;
    const trueColor = numericValue(entityPairs, 420);
    const aciColor = numericValue(entityPairs, 62);
    styles.set(name, {
      color: dxfTrueColor(trueColor) || dxfAciColor(aciColor),
      lineType: firstValue(entityPairs, 6) || undefined,
      lineWeight: numericValue(entityPairs, 370) || undefined,
    });
  }
  return styles;
}

function extractEntityBlocks(pairs: DxfPair[]) {
  const entitiesMarker = pairs.findIndex(
    (pair, index) =>
      pair.code === 2 &&
      pair.value.toUpperCase() === "ENTITIES" &&
      pairs[index - 1]?.code === 0 &&
      pairs[index - 1]?.value.toUpperCase() === "SECTION"
  );
  if (entitiesMarker < 0) {
    throw new Error("DXF ENTITIES-Sektion nicht gefunden.");
  }

  const blocks: DxfEntityBlock[] = [];
  let index = entitiesMarker + 1;
  while (index < pairs.length) {
    const pair = pairs[index];
    if (pair.code === 0 && pair.value.toUpperCase() === "ENDSEC") break;
    if (pair.code !== 0) {
      index += 1;
      continue;
    }

    const type = pair.value.toUpperCase();
    const entityPairs: DxfPair[] = [];
    index += 1;
    while (index < pairs.length && pairs[index].code !== 0) {
      entityPairs.push(pairs[index]);
      index += 1;
    }
    blocks.push({ type, pairs: entityPairs });
  }
  return blocks;
}

function extractBlockDefinitions(
  pairs: DxfPair[],
  scale: number
): Map<string, DxfBlockDefinition> {
  const definitions = new Map<string, DxfBlockDefinition>();
  const blocksMarker = pairs.findIndex(
    (pair, index) =>
      pair.code === 2 &&
      pair.value.toUpperCase() === "BLOCKS" &&
      pairs[index - 1]?.code === 0 &&
      pairs[index - 1]?.value.toUpperCase() === "SECTION"
  );
  if (blocksMarker < 0) return definitions;

  let index = blocksMarker + 1;
  while (index < pairs.length) {
    const pair = pairs[index];
    if (pair.code === 0 && pair.value.toUpperCase() === "ENDSEC") break;
    if (pair.code !== 0 || pair.value.toUpperCase() !== "BLOCK") {
      index += 1;
      continue;
    }

    const header: DxfPair[] = [];
    index += 1;
    while (index < pairs.length && pairs[index].code !== 0) {
      header.push(pairs[index]);
      index += 1;
    }

    const name = firstValue(header, 2) || firstValue(header, 3);
    const basePoint =
      indexedPoint(header, 10, 20, scale) || { x: 0, y: 0 };
    const entities: DxfEntityBlock[] = [];

    while (index < pairs.length) {
      const marker = pairs[index];
      if (marker.code !== 0) {
        index += 1;
        continue;
      }
      const type = marker.value.toUpperCase();
      if (type === "ENDBLK") {
        index += 1;
        while (index < pairs.length && pairs[index].code !== 0) index += 1;
        break;
      }

      const entityPairs: DxfPair[] = [];
      index += 1;
      while (index < pairs.length && pairs[index].code !== 0) {
        entityPairs.push(pairs[index]);
        index += 1;
      }

if (type === "ENDBLK") {
        index += 1;
        while (index < pairs.length && pairs[index].code !== 0) index += 1;
        break;
      }

      const entityPairs: DxfPair[] = [];
      index += 1;
      while (index < pairs.length && pairs[index].code !== 0) {
        entityPairs.push(pairs[index]);
        index += 1;
      }
      entities.push({ type, pairs: entityPairs });
    }

    if (name) {
      definitions.set(name, { name, basePoint, entities });
    }
  }

  return definitions;
}

function baseDxfMeta(
  block: DxfEntityBlock,
  fileName: string,
  unitCode: number,
  layerStyle?: DxfLayerStyle
) {
  const layout = firstValue(block.pairs, 410);
  const paperSpace =
    Math.trunc(numericValue(block.pairs, 67)) === 1 ||
    Boolean(layout && layout.toLowerCase() !== "model");
  const entityTrueColor = numericValue(block.pairs, 420);
  const entityAciColor = numericValue(block.pairs, 62);
  return {
    source: "DXF",
    sourceFile: fileName,
    dxfType: block.type,
    dxfHandle: firstValue(block.pairs, 5),
    dxfUnitCode: unitCode,
    layout: layout || (paperSpace ? "Paper Space" : "Model"),
    paperSpace,
    color:
      dxfTrueColor(entityTrueColor) ||
      dxfAciColor(entityAciColor) ||
      layerStyle?.color,
    lineType: firstValue(block.pairs, 6) || layerStyle?.lineType,
    lineWeight:
      numericValue(block.pairs, 370) || layerStyle?.lineWeight || undefined,
  };
}

function arcPoints(
  center: CadPoint,
  radius: number,
  startDegrees: number,
  endDegrees: number
) {
  let sweep = endDegrees - startDegrees;
  while (sweep <= 0) sweep += 360;
  const segments = Math.max(8, Math.min(144, Math.ceil(sweep / 5)));
  const points: CadPoint[] = [];
  for (let index = 0; index <= segments; index += 1) {
    const degrees = startDegrees + (sweep * index) / segments;
    const radians = (degrees * Math.PI) / 180;
    points.push({
      x: center.x + Math.cos(radians) * radius,
      y: center.y + Math.sin(radians) * radius,
    });
  }
  return points;
}

function bulgeArcPoints(
  start: CadPoint,
  end: CadPoint,
  bulge: number
) {
  if (Math.abs(bulge) < EPSILON || distance(start, end) < EPSILON) {
    return [{ ...start }, { ...end }];
  }

  const chord = distance(start, end);
  const middle = {
    x: (start.x + end.x) / 2,
    y: (start.y + end.y) / 2,
  };
  const nx = -(end.y - start.y) / chord;
  const ny = (end.x - start.x) / chord;
  const centerDistance = (chord * (1 - bulge * bulge)) / (4 * bulge);
  const center = {
    x: middle.x + nx * centerDistance,
    y: middle.y + ny * centerDistance,
  };
  const startAngle = Math.atan2(start.y - center.y, start.x - center.x);
  const sweep = 4 * Math.atan(bulge);
  const segments = Math.max(
    4,
    Math.min(180, Math.ceil(Math.abs(sweep) / (Math.PI / 36)))
  );
  const radius = distance(center, start);
  const points: CadPoint[] = [];

  for (let index = 0; index <= segments; index += 1) {
    const angle = startAngle + (sweep * index) / segments;
    points.push({
      x: center.x + Math.cos(angle) * radius,
      y: center.y + Math.sin(angle) * radius,
    });
  }
  points[0] = { ...start };
  points[points.length - 1] = { ...end };
  return points;
}

function flattenBulgedPolyline(vertices: DxfVertex[], closed: boolean) {
  if (vertices.length < 2) return vertices.map((vertex) => vertex.point);
  const points: CadPoint[] = [{ ...vertices[0].point }];
  const segmentCount = closed ? vertices.length : vertices.length - 1;

  for (let index = 0; index < segmentCount; index += 1) {
    const start = vertices[index];
    const end = vertices[(index + 1) % vertices.length];
    const segment = bulgeArcPoints(start.point, end.point, start.bulge);
    points.push(...segment.slice(1));
  }

  if (
    closed &&
    points.length > 1 &&
    distance(points[0], points[points.length - 1]) < EPSILON
  ) {
    points.pop();
  }
  return points;
}

const IDENTITY_MATRIX: DxfMatrix = {
  a: 1,
  b: 0,
  c: 0,
  d: 1,
  e: 0,
  f: 0,
};

function applyDxfMatrix(matrix: DxfMatrix, point: CadPoint): CadPoint {
  return {
    x: matrix.a * point.x + matrix.c * point.y + matrix.e,
    y: matrix.b * point.x + matrix.d * point.y + matrix.f,
  };
}

function multiplyDxfMatrices(parent: DxfMatrix, local: DxfMatrix): DxfMatrix {
  return {
    a: parent.a * local.a + parent.c * local.b,
    b: parent.b * local.a + parent.d * local.b,
    c: parent.a * local.c + parent.c * local.d,
    d: parent.b * local.c + parent.d * local.d,
    e: parent.a * local.e + parent.c * local.f + parent.e,
    f: parent.b * local.e + parent.d * local.f + parent.f,
  };
}

function insertDxfMatrix(
  insertion: CadPoint,
  basePoint: CadPoint,
  scaleX: number,
  scaleY: number,
  rotationDegrees: number
): DxfMatrix {
  const angle = (rotationDegrees * Math.PI) / 180;
  const cos = Math.cos(angle);
  const sin = Math.sin(angle);
  const a = cos * scaleX;
  const b = sin * scaleX;
  const c = -sin * scaleY;
  const d = cos * scaleY;
  return {
    a,
    b,
    c,
    d,
    e: insertion.x - a * basePoint.x - c * basePoint.y,
    f: insertion.y - b * basePoint.x - d * basePoint.y,
  };
}

