            },
          });
        }
        index = Math.max(index, cursor - 1);
        continue;
      }

      if (block.type === "CIRCLE") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const radius = numericValue(block.pairs, 40) * scale;
        if (center && radius > EPSILON) {
          push({ kind: "circle", pts: [center], radius });
        }
        continue;
      }

      if (block.type === "ARC") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const radius = numericValue(block.pairs, 40) * scale;
        if (center && radius > EPSILON) {
          push({
            kind: "polyline",
            name: "Bogen",
            pts: arcPoints(
              center,
              radius,
              numericValue(block.pairs, 50),
              numericValue(block.pairs, 51)
            ),
          });
        }
        continue;
      }

      if (block.type === "ELLIPSE") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const majorAxis = indexedPoint(block.pairs, 11, 21, scale);
        if (center && majorAxis) {
          const startParameter = numericValue(block.pairs, 41, 0);
          const endParameter = numericValue(
            block.pairs,
            42,
            Math.PI * 2
          );
          const points = ellipsePoints(
            center,
            majorAxis,
            Math.abs(numericValue(block.pairs, 40, 1)),
            startParameter,
            endParameter
          );
          const closed =
            Math.abs(endParameter - startParameter) >= Math.PI * 2 - 1e-6;
          if (points.length) {
            if (
              closed &&
              distance(points[0], points[points.length - 1]) < EPSILON
            ) {
              points.pop();
            }
            push({
              kind: closed ? "polygon" : "polyline",
              name: "Ellipse",
              pts: points,
              closed,
            });
          }
        }
        continue;
      }

      if (block.type === "INSERT" || block.type === "DIMENSION") {
        const blockName = firstValue(block.pairs, 2);
        const definition = blockDefinitions.get(blockName);
        const insertion =
          indexedPoint(block.pairs, 10, 20, scale) || { x: 0, y: 0 };
        if (definition) {
          const scaleX = numericValue(block.pairs, 41, 1) || 1;
          const scaleY = numericValue(block.pairs, 42, 1) || 1;
          const rotation = numericValue(block.pairs, 50);
          const columns = Math.max(
            1,
            Math.trunc(numericValue(block.pairs, 70, 1))
          );
          const rows = Math.max(
            1,
            Math.trunc(numericValue(block.pairs, 71, 1))
          );
          const columnSpacing = numericValue(block.pairs, 44) * scale;
          const rowSpacing = numericValue(block.pairs, 45) * scale;
          const rotationRadians = (rotation * Math.PI) / 180;
          const rotationCos = Math.cos(rotationRadians);
          const rotationSin = Math.sin(rotationRadians);

          for (let row = 0; row < rows; row += 1) {
            for (let column = 0; column < columns; column += 1) {
              const localOffsetX = column * columnSpacing * scaleX;
              const localOffsetY = row * rowSpacing * scaleY;
              const instancePoint = {
                x:
                  insertion.x +
                  localOffsetX * rotationCos -
                  localOffsetY * rotationSin,
                y:
                  insertion.y +
                  localOffsetX * rotationSin +
                  localOffsetY * rotationCos,
              };
              const local = insertDxfMatrix(
                instancePoint,
                definition.basePoint,
                scaleX,
                scaleY,
                rotation
              );
              emitBlocks(
                definition.entities,
                layer,
                multiplyDxfMatrices(matrix, local),
                `${id}_${blockName}_${row}_${column}`,
                depth + 1,
                Boolean(meta.paperSpace),
                String(meta.layout || "Model")
              );
            }
          }
        } else {
          push({
            kind: "point",
            name: blockName || "Block",
            pts: [insertion],
            meta: { unresolvedBlock: blockName || true },
          });
        }
        continue;
      }

      if (block.type === "POINT") {
        const point = indexedPoint(block.pairs, 10, 20, scale);
        if (point) push({ kind: "point", name: "Punkt", pts: [point] });
        continue;
      }

      if (
        block.type === "TEXT" ||
        block.type === "MTEXT" ||
        block.type === "ATTRIB" ||
        block.type === "ATTDEF"
      ) {
        const horizontalJustification = Math.trunc(
          numericValue(block.pairs, 72)
        );
        const verticalJustification = Math.trunc(
          numericValue(block.pairs, 73)
        );
        const usesAlignmentPoint =
          block.type !== "MTEXT" &&
          (horizontalJustification !== 0 || verticalJustification !== 0);
        const insertionPoint = indexedPoint(block.pairs, 10, 20, scale);
        const alignmentPoint = indexedPoint(block.pairs, 11, 21, scale);
        const point = usesAlignmentPoint
          ? alignmentPoint || insertionPoint
          : insertionPoint || alignmentPoint;

);
        const verticalJustification = Math.trunc(
          numericValue(block.pairs, 73)
        );
        const usesAlignmentPoint =
          block.type !== "MTEXT" &&
          (horizontalJustification !== 0 || verticalJustification !== 0);
        const insertionPoint = indexedPoint(block.pairs, 10, 20, scale);
        const alignmentPoint = indexedPoint(block.pairs, 11, 21, scale);
        const point = usesAlignmentPoint
          ? alignmentPoint || insertionPoint
          : insertionPoint || alignmentPoint;
        const text = decodeDxfText(block.pairs);
        const attributeTag = firstValue(block.pairs, 2);
        const explicitRotation = block.pairs.some((pair) => pair.code === 50);
        const directionX = numericValue(block.pairs, 11);
        const directionY = numericValue(block.pairs, 21);
        const rotation =
          block.type === "MTEXT" &&
          !explicitRotation &&
          (Math.abs(directionX) > EPSILON ||
            Math.abs(directionY) > EPSILON)
            ? (Math.atan2(directionY, directionX) * 180) / Math.PI
            : numericValue(block.pairs, 50);
        if (point) {
          push({
            kind: "text",
            name: text || attributeTag || "Text",
            text: text || attributeTag,
            rotation,
            pts: [point],
            meta: {
              height: numericValue(block.pairs, 40) * scale,
              width: numericValue(block.pairs, 41) * scale,
              widthFactor:
                block.type === "MTEXT"
                  ? 1
                  : numericValue(block.pairs, 41, 1) || 1,
              textStyle: firstValue(block.pairs, 7),
              attachmentPoint: Math.trunc(
                numericValue(block.pairs, 71, 1)
              ),
              horizontalJustification,
              verticalJustification,
            },
          });
        }
        continue;
      }

      if (block.type === "SPLINE") {
        const points = splinePoints(block.pairs, scale);
        if (points.length > 1) {
          push({
            kind: "polyline",
            name: "Spline",
            pts: points,
            meta: { approximation: "de-boor" },
          });
        }
        continue;
      }

      if (block.type === "MLINE") {
        const points = repeatedPoints(block.pairs, 11, 21, scale);
        const fallbackPoints = repeatedPoints(block.pairs, 10, 20, scale);
        const centerLine = points.length > 1 ? points : fallbackPoints;
        if (centerLine.length > 1) {
          push({
            kind: "polyline",
            name: "Multilinie",
            pts: centerLine,
            meta: { approximation: "center-line" },
          });
        }
        continue;
      }

      if (block.type === "HATCH" || block.type === "LEADER") {
        const points = repeatedVertices(block.pairs, scale).map(
          (vertex) => vertex.point
        );
        if (points.length > 1) {
          const closed = block.type === "HATCH" && points.length > 2;
          push({
            kind: closed ? "polygon" : "polyline",
            name: block.type === "HATCH" ? "Schraffurgrenze" : "Führungslinie",
            pts: points,
            closed,
            meta: { approximation: "boundary-points" },
          });
        }
        continue;
      }

      if (
        block.type === "3DFACE" ||
        block.type === "SOLID" ||
        block.type === "TRACE"
      ) {
        const points = [10, 11, 12, 13]
          .map((xCode) =>
            indexedPoint(block.pairs, xCode, xCode + 10, scale)
          )
          .filter((point): point is CadPoint => Boolean(point));
        const unique = points.filter(
          (point, pointIndex) =>
            pointIndex === 0 ||
            distance(point, points[pointIndex - 1]) > EPSILON
        );
        if (unique.length >= 3) {
          push({
            kind: "polygon",
            pts: unique,
            closed: true,
            style: {
              ...style,
              fill: block.type === "SOLID" || block.type === "TRACE",
            },
          });
        }
        continue;
      }

      if (!["VERTEX", "SEQEND"].includes(block.type)) {
        unsupportedTypes.add(block.type);
      }
    }
  };

  emitBlocks(blocks);

  const normalized = features.map(recalculateCadFeature);
  if (!normalized.length) {
    throw new Error(
      "Die DXF-Datei enthält keine unterstützte 2D-Geometrie (LINE, POLYLINE, CIRCLE, ARC, ELLIPSE, INSERT, POINT, TEXT, SPLINE, MLINE)."
    );
  }

  return createCadDocument("", normalized, {
    fileName,
    format: "DXF",
    importedAt: new Date().toISOString(),
    unitCode,
    unitScale: scale,
    modelSpaceCount,
    paperSpaceCount,
    unsupportedTypes: Array.from(unsupportedTypes).sort(),
    blockDefinitionCount: blockDefinitions.size,
  });
}

// apps/web/src/lib/cad/store.ts
import { CadDoc, Entity, Layer, Vec2 } from "./types";

const KEY = "rlc.cad.doc";

function newid() {
  return Math.random().toString(36).slice(2, 10);
}

function createDefaultDoc(): CadDoc {
  return {
    id: "CAD-001",
    name: "Zeichnung 1",
    layers: [
      { id: "L1", name: "0", color: "#22c55e", visible: true, locked: false },
      { id: "L2", name: "Bestand", color: "#60a5fa", visible: true, locked: false },
    ],
    entities: [],
    view: { cx: 0, cy: 0, zoom: 1 },
    updatedAt: new Date().toISOString(),
  };
}

function normalizeDoc(input: unknown): CadDoc {
  const fallback = createDefaultDoc();

  if (!input || typeof input !== "object") return fallback;

  const raw = input as Partial<CadDoc>;

  const layers: Layer[] = Array.isArray(raw.layers) && raw.layers.length > 0
    ? raw.layers
        .filter((l): l is Layer => !!l && typeof l === "object")
        .map((l, idx) => ({
          id: String(l.id || `L${idx + 1}`),
          name: String(l.name || `Layer ${idx + 1}`),
          color: l.color || "#94a3b8",
          visible: l.visible !== false,
          locked: l.locked === true,
        }))
    : fallback.layers;

  const entities: Entity[] = Array.isArray(raw.entities)
    ? raw.entities.filter((e): e is Entity => !!e && typeof e === "object")
    : [];

  return {
    id: String(raw.id || fallback.id),
    name: String(raw.name || fallback.name),
    layers,
    entities,
    view: {
      cx: Number(raw.view?.cx ?? fallback.view.cx),
      cy: Number(raw.view?.cy ?? fallback.view.cy),
      zoom: Number(raw.view?.zoom ?? fallback.view.zoom),
    },
    updatedAt: String(raw.updatedAt || fallback.updatedAt),
    meta: raw.meta && typeof raw.meta === "object" ? raw.meta : undefined,
  };
}

export function loadDoc(): CadDoc {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return createDefaultDoc();
    return normalizeDoc(JSON.parse(raw));
  } catch {
    return createDefaultDoc();
  }
}

export function saveDoc(doc: CadDoc) {
  try {
    const normalized = normalizeDoc(doc);
    localStorage.setItem(
      KEY,
      JSON.stringify({
        ...normalized,
        updatedAt: new Date().toISOString(),
      })
    );
  } catch {
    // ignore localStorage write errors
  }
}

function distPointToSegment(p: Vec2, a: Vec2, b: Vec2) {
  const ab = { x: b.x - a.x, y: b.y - a.y };
  const ap = { x: p.x - a.x, y: p.y - a.y };
  const ab2 = ab.x * ab.x + ab.y * ab.y;
  const t =
    ab2 === 0
      ? 0
      : Math.max(0, Math.min(1, (ap.x * ab.x + ap.y * ab.y) / ab2));
  const proj = { x: a.x + t * ab.x, y: a.y + t * ab.y };
  return Math.hypot(p.x - proj.x, p.y - proj.y);
}

export const CadAPI = {
  newid,

  createDefaultDoc,

  getActiveLayerId(doc: CadDoc): string {
    const safeDoc = normalizeDoc(doc);
    const firstVisibleUnlocked = safeDoc.layers.find((l) => l.visible && !l.locked);
    return firstVisibleUnlocked?.id ?? safeDoc.layers[0]?.id ?? "L1";
  },

  addLayer(
    doc: CadDoc,
    name = `Layer ${doc.layers.length + 1}`,
    color = "#f59e0b"
  ) {
    const safeDoc = doc;
    safeDoc.layers.push({
      id: newid(),
      name,
      color,
      visible: true,
      locked: false,
    });
    safeDoc.updatedAt = new Date().toISOString();
  },

  removeLayer(doc: CadDoc, id: string) {
    if (doc.layers.length <= 1) return;

    doc.entities = doc.entities.filter((e) => e.layerId !== id);
    doc.layers = doc.layers.filter((l) => l.id !== id);

    if (doc.layers.length === 0) {
      doc.layers = createDefaultDoc().layers;
    }

    doc.updatedAt = new Date().toISOString();
  },

  addEntity(doc: CadDoc, e: Entity) {
    doc.entities.push(e);
    doc.updatedAt = new Date().toISOString();
  },

  removeEntity(doc: CadDoc, id: string) {
    doc.entities = doc.entities.filter((e) => e.id !== id);
    doc.updatedAt = new Date().toISOString();
  },

  hitTest(doc: CadDoc, p: Vec2, tol = 6): Entity | null {
    const t = tol;
    const near = (a: Vec2, b: Vec2) => Math.hypot(a.x - b.x, a.y - b.y) <= t;

    for (let i = doc.entities.length - 1; i >= 0; i--) {
      const e = doc.entities[i];
      const lay = doc.layers.find((l) => l.id === e.layerId);
      if (!lay?.visible) continue;

      if (e.type === "point") {
        if (near(e.p, p)) return e;
      } else if (e.type === "line") {
        const d = distPointToSegment(p, e.a, e.b);
        if (d <= t) return e;
      } else if (e.type === "polyline") {
        for (let j = 0; j < e.points.length - 1; j++) {
          const d = distPointToSegment(p, e.points[j], e.points[j + 1]);
          if (d <= t) return e;
        }

        if (e.closed && e.points.length > 2) {
          const d = distPointToSegment(
            p,
            e.points[e.points.length - 1],
            e.points[0]
          );
          if (d <= t) return e;
        }
      }
    }

    return null;
  },
};

// apps/web/src/lib/cad/types.ts

/* ===================== BASIC ===================== */

export type Vec2 = {
  x: number;
  y: number;
};

/* ===================== LAYERS ===================== */

export type Layer = {
  id: string;
  name: string;
  color?: string; // opzionale (import CAD può non averlo)
  visible: boolean;
  locked: boolean;
};

/* ===================== ENTITY TYPES ===================== */

export type EntityType = "point" | "line" | "polyline";

/* ===================== BASE ===================== */

export type BaseEntity = {
  id: string;
  layerId: string;
  type: EntityType;

  // 🔥 utile per KI / CAD Viewer / Takeoff
  meta?: Record<string, any>;
};

/* ===================== ENTITIES ===================== */

export type PointEntity = BaseEntity & {
  type: "point";
  p: Vec2;
};

export type LineEntity = BaseEntity & {
  type: "line";
  a: Vec2;
  b: Vec2;
};

export type PolylineEntity = BaseEntity & {
  type: "polyline";
  points: Vec2[];
  closed?: boolean; // opzionale → non sempre presente da CAD
};

/* ===================== UNION ===================== */

export type Entity = PointEntity | LineEntity | PolylineEntity;

/* ===================== VIEW ===================== */

export type CadView = {
  cx: number; // center x
  cy: number; // center y
  zoom: number;
};

/* ===================== DOCUMENT ===================== */

export type CadDoc = {
  id: string;
  name: string;

  layers: Layer[];
  entities: Entity[];

  view: CadView;

  updatedAt: string;

  // 🔥 estendibile per futuro (CAD import / versioning)
  meta?: Record<string, any>;
};

