    (position) => position?.calculationAvailable !== false
  ).length;
  const missingAffectedCostShare = confirmedPositions.filter(
    (position) => String(position?.impactStatus || "").toUpperCase() === "MISSING_AFFECTED_COST_SHARE"
  ).length;

