    const reader = new FileReader();

    reader.onload = () => {
      LV.importCSV(String(reader.result || ""));
      setRows(toManualRows(LV.list()));
      if (fileRef.current) fileRef.current.value = "";
    };

    reader.readAsText(file, "utf-8");
  }

