  async function saveUrkalkulation() {
    // Nach "Urkalkulation gesamtes LV" bedeutet Speichern: ALLE Positionen sichern.
    // Die aktuell markierte Position darf dabei weder verändert noch neu einsortiert werden.
    if (globalUrkDone) {
      if (!projectKey) {
        setInfo("Gesamte Urkalkulation lokal gespeichert. Kein Projekt ausgewählt.");
        return;
      }

      try {
        const token = getAuthToken();
        const allRows = LV.list();
        const response = await fetch(
          apiUrl(`/api/kalkulation/storage/urkalkulation/${encodeURIComponent(projectKey)}/save`),
          {
            method: "POST",
            credentials: "include",
            headers: {
              "Content-Type": "application/json",
              Accept: "application/json",
              ...(token ? { Authorization: `Bearer ${token}` } : {})
            },
            body: JSON.stringify({
              ok: true,
              version: "RLC_URKALKULATION_PROJECT_V2_ALL",
              source: "recipes-global",
              projectKey,
              projectCode: projectKey,
              projectTitle,
              savedAt: new Date().toISOString(),
              selectedId: selectedId || null,
              rows: allRows,
              context: ctx,
              recipeContext
            })
          }
        );
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        setLvRows(allRows);
        setInfo(`Gesamte Urkalkulation gespeichert: ${allRows.length} LV-Positionen. Auswahl bleibt unverändert.`);
      } catch (error: any) {
        console.error("[Recipes] globale Urkalkulation save failed", error);
        setInfo(`Globale Urkalkulation lokal vorhanden. Serverfehler: ${error?.message || "unbekannt"}`);
      }
      return;
    }

    const ok = saveForHandoff();
    if (!ok) return;

    if (!projectKey) {
      setInfo("Urkalkulation lokal gespeichert. Kein Projekt ausgewählt.");
      return;
    }

    const made = makeLvPayload();
    if (!made) return;

    const row = made.payload as LVPos & any;
    const ep = round2(n(row.preis || row.ep || summary.ep));
    const qty = Math.max(n(row.menge || row.qty, 1), 0.0001);
    const gp = round2(ep * qty);
    const savedAt = new Date().toISOString();

    const snapshot = {
      ok: true,
      version: "RLC_URKALKULATION_PROJECT_V1",
      source: "recipes",
      projectKey,
      projectCode: projectKey,
      projectTitle,
      savedAt,
      selectedId: row.id || selectedId || null,
      row: {
        ...row,
        preis: ep,
        ep,
        gp,
        qty,
        menge: qty,
        unit: row.einheit || row.unit || "m",
        einheit: row.einheit || row.unit || "m",
        recipeLines: lines,
        recipeSummary: summary,
        priceBreakdown: buildPriceBreakdown(lines, selectedRow),
        urkalkulationUnitPrice: ep,
        urkalkulationTotal: gp,
        calculationStatus: "recipes_ready",
        source: "recipes-urkalkulation-server-v1",
        updatedAt: savedAt
      },
      rows: LV.list(),
      context: ctx,
      recipeContext,
      summary
    };

    try {
      const token = getAuthToken();
      const response = await fetch(
        apiUrl(`/api/kalkulation/storage/urkalkulation/${encodeURIComponent(projectKey)}/save`),
        {
          method: "POST",
          credentials: "include",
          headers: {
            "Content-Type": "application/json",
            Accept: "application/json",
            ...(token ? { Authorization: `Bearer ${token}` } : {})
          },
          body: JSON.stringify(snapshot)
        }
      );

      const raw = await response.text();
      let result: any = null;
      try {
        result = raw ? JSON.parse(raw) : null;
      } catch {
        result = raw;
      }

      if (!response.ok) {
        throw new Error(
          result?.error || result?.message || `HTTP ${response.status}`
        );
      }

      setInfo("Urkalkulation lokal und auf dem Server gespeichert.");
    } catch (error: any) {
      console.error("[Recipes] Urkalkulation server save failed", error);
      setInfo(
        `Urkalkulation lokal gespeichert. Serverfehler: ${
        error?.message || "unbekannt"}`

      );
    }
  }

