          <div className={rlcClass(null, eyebrow)}>RLC Angebotsanalyse</div>
          <h1 className={rlcClass(null, title)}>Versionsvergleich / Angebotsanalyse</h1>
          <p className={rlcClass(null, subtitle)}>
