function getAuthToken(): string {
  try {
    const directKeys = [
    "token",
    "authToken",
    "accessToken",
    "rlc_token",
    "rlc_auth_token",
    "rlc_access_token"];


    for (const key of directKeys) {
      const value = localStorage.getItem(key);
      if (value && value.trim()) return value.trim();
    }

    const jsonKeys = ["auth", "user", "session", "rlc_auth", "rlc_session"];

    for (const key of jsonKeys) {
      const raw = localStorage.getItem(key);
      if (!raw) continue;

      try {
        const parsed = JSON.parse(raw);
        const token =
        parsed?.token ??
        parsed?.accessToken ??
        parsed?.authToken ??
        parsed?.jwt ??
        parsed?.data?.token ??
        parsed?.data?.accessToken;

        if (typeof token === "string" && token.trim()) return token.trim();
      } catch {


        //
      }}} catch {


    //
  }return "";
}

function authHeaders(extra?: Record<string, string>): HeadersInit {
  const token = getAuthToken();

  return {
    ...(extra || {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {})
  };
}

function extractKalkulationRows(payload: any): any[] {
  const candidates = [
    payload,
    payload?.rows,
    payload?.items,
    payload?.data,
    payload?.data?.rows,

...(extra || {}),
    ...(token ? { Authorization: `Bearer ${token}` } : {})
  };
}

function extractKalkulationRows(payload: any): any[] {
  const candidates = [
    payload,
    payload?.rows,
    payload?.items,
    payload?.data,
    payload?.data?.rows,
    payload?.data?.items,
    payload?.snapshot,
    payload?.snapshot?.rows,
    payload?.snapshot?.data,
    payload?.snapshot?.data?.rows,
    payload?.snapshot?.data?.items
  ];

  for (const candidate of candidates) {
    if (Array.isArray(candidate)) return candidate;
  }

  return [];
}

function kalkulationRowToLv(row: any, index: number): LVPos {
  const ep =
    n(
      row?.finalUnitPrice ??
      row?.rlcKiUnitPrice ??
      row?.suggestedUnitPrice ??
      row?.baseUnitPrice ??
      row?.unitPrice ??
      row?.preis ??
      row?.ep,
      0
    );

  return {
    ...row,
    id: String(row?.id || `server-kalk-${index + 1}`),
    posNr: String(
      row?.posNr ??
      row?.positionNumber ??
      row?.position ??
      row?.pos ??
      index + 1
    ),
    kurztext: String(
      row?.kurztext ??
      row?.shortText ??
      row?.text ??
      row?.beschreibung ??
      ""
    ),
    langtext: String(
      row?.langtext ??
      row?.longText ??
      row?.beschreibung ??
      row?.text ??
      ""
    ),
    einheit: String(
      row?.einheit ??
      row?.unit ??
      ""
    ),
    menge: n(
      row?.menge ??
      row?.quantity ??
      row?.qty,
      0
    ),
    preis: ep,
    source: row?.source || "server-kalkulation"
  } as LVPos;
}

async function loadKalkulationRowsFromServer(projectKey: string): Promise<LVPos[]> {
  if (!projectKey) return [];

  const paths = [
    `/api/kalkulation/storage/kalkulation-mit-ki/${encodeURIComponent(projectKey)}`,
    `/api/kalkulation/storage/ki/${encodeURIComponent(projectKey)}`,
    `/api/kalkulation/${encodeURIComponent(projectKey)}/ki`
  ];

  for (const path of paths) {
    try {
      const response = await fetch(apiUrl(path), {
        method: "GET",
        credentials: "include",
        headers: authHeaders({
          Accept: "application/json"
        })
      });

      if (!response.ok) continue;

      const payload = await response.json().catch(() => null);
      const rawRows = extractKalkulationRows(payload);

      if (!rawRows.length) continue;

      const rows = rawRows
        .map(kalkulationRowToLv)
        .filter((row) =>
          String(row.posNr || row.kurztext || row.langtext || "").trim()
        );

      if (rows.length) {
        console.log("[Angebot] Kalkulation vom Server geladen", {
          path,
          rows: rows.length
        });

        return rows;
      }
    } catch (error) {
      console.warn("[Angebot] Kalkulation-Adapter fehlgeschlagen", path, error);
    }
  }

  return [];
}


