// apps/web/src/pages/kalkulation/catalogStore.ts

export type CatalogGroup =
  | "Material"
  | "Arbeiter"
  | "Maschinen"
  | "Sonstiges"
  | string;

export type CatalogPos = {
  id: string;
  posNr: string;
  kurztext: string;
  einheit: string;
  ep: number;
  gruppe?: CatalogGroup;
  createdAt?: string;
  updatedAt?: string;
};

const KEY = "rlc_catalog_v2";
const LEGACY_KEY = "rlc_catalog_v1";
const CHUNK_SIZE = 500_000;

function nowIso(): string {
  return new Date().toISOString();
}

function safeUuid(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `cat-${Date.now()}-${Math.random().toString(36).slice(2)}`;
  }
}

function hasStorage(): boolean {
  try {
    return typeof localStorage !== "undefined";
  } catch {
    return false;
  }
}

function normalizeText(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizePosNr(value: unknown): string {
  return String(value ?? "")
    .trim()
    .replace(/\s+/g, "")
    .replace(/_/g, ".")
    .replace(/,+/g, ".")
    .replace(/\.+/g, ".")
    .replace(/^\./, "")
    .replace(/\.$/, "");
}

function normalizeGroup(value: unknown): CatalogGroup {
  const v = normalizeText(value);

  if (!v) return "Sonstiges";

  const l = v.toLowerCase();

  if (["material", "materialien", "stoff", "stoffe"].includes(l)) {
    return "Material";
  }

  if (["arbeiter", "lohn", "personal", "labor"].includes(l)) {
    return "Arbeiter";
  }

  if (["maschine", "maschinen", "gerät", "geraet", "machine"].includes(l)) {
    return "Maschinen";
  }

  return v;
}

function toNumber(value: unknown): number {
  if (value === null || value === undefined || value === "") return 0;

  const raw = String(value).trim();
  if (!raw) return 0;

  const normalized = raw
    .replace(/\s/g, "")
    .replace(/[€]/g, "")
    .replace(/\.(?=\d{3}(?:[.,]|$))/g, "")
    .replace(",", ".");

  const n = Number(normalized);
  return Number.isFinite(n) ? n : 0;
}

function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function csvEscape(value: unknown): string {
  const s = String(value ?? "");
  if (/[;"\n\r]/.test(s)) return `"${s.replace(/"/g, '""')}"`;
  return s;
}

function parseCsvLine(line: string, separator = ";"): string[] {
  const out: string[] = [];
  let current = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"') {
      if (inQuotes && next === '"') {
        current += '"';
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }

      continue;
    }

    if (ch === separator && !inQuotes) {
      out.push(current);
      current = "";
      continue;
    }

    current += ch;
  }

  out.push(current);
  return out;
}

function detectSeparator(firstLine: string): ";" | "," | "\t" {
  const semi = (firstLine.match(/;/g) || []).length;
  const comma = (firstLine.match(/,/g) || []).length;
  const tab = (firstLine.match(/\t/g) || []).length;

  if (tab > semi && tab > comma) return "\t";
  if (comma > semi) return ",";
  return ";";
}

function normalizeHeader(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "")
    .replace(/[_-]/g, "");
}

function findHeader(headers: string[], alternatives: string[]): number {
  return headers.findIndex((h) => alternatives.includes(h));
}

function makeRow(input: Partial<CatalogPos>): CatalogPos {
  const createdAt = normalizeText(input.createdAt) || nowIso();

  return {
    id: normalizeText(input.id) || safeUuid(),
    posNr: normalizePosNr(input.posNr),
    kurztext: normalizeText(input.kurztext),
    einheit: normalizeText(input.einheit),
    ep: round2(toNumber(input.ep)),
    gruppe: normalizeGroup(input.gruppe),
    createdAt,
    updatedAt: nowIso(),
  };
}

function sortRows(rows: CatalogPos[]): CatalogPos[] {
  return [...rows].sort((a, b) => {
    const g = String(a.gruppe || "").localeCompare(
      String(b.gruppe || ""),
      "de",
      {
        numeric: true,
        sensitivity: "base",
      }
    );

    if (g !== 0) return g;

    const p = String(a.posNr || "").localeCompare(
      String(b.posNr || ""),
      "de",
      {
        numeric: true,
        sensitivity: "base",
      }
    );

    if (p !== 0) return p;

    return String(a.kurztext || "").localeCompare(
      String(b.kurztext || ""),
      "de",
      {
        sensitivity: "base",
      }
    );
  });
}

function dedupeRows(rows: CatalogPos[]): CatalogPos[] {
  const byKey = new Map<string, CatalogPos>();

  for (const row of rows) {
    const clean = makeRow(row);
    const key = `${clean.gruppe || ""}:${clean.posNr || ""}:${
      clean.kurztext || ""
    }:${clean.einheit || ""}`;

    if (!clean.posNr && !clean.kurztext) continue;

    const existing = byKey.get(key);

    if (!existing) {
      byKey.set(key, clean);
      continue;
    }

    byKey.set(key, {
      ...existing,
      ...clean,
      id: existing.id,
      createdAt: existing.createdAt || clean.createdAt,
      updatedAt: nowIso(),
    });
  }

  return sortRows(Array.from(byKey.values()));
}

function clearChunks(baseKey: string) {
  if (!hasStorage()) return;

  Object.keys(localStorage).forEach((k) => {
    if (k === `${baseKey}_n` || k.startsWith(`${baseKey}_`)) {
      localStorage.removeItem(k);
    }
  });
}

function saveChunks(baseKey: string, json: string) {
  if (!hasStorage()) return;

if (!hasStorage()) return;

  Object.keys(localStorage).forEach((k) => {
    if (k === `${baseKey}_n` || k.startsWith(`${baseKey}_`)) {
      localStorage.removeItem(k);
    }
  });
}

function saveChunks(baseKey: string, json: string) {
  if (!hasStorage()) return;

  clearChunks(baseKey);

  const count = Math.ceil(json.length / CHUNK_SIZE);
  localStorage.setItem(`${baseKey}_n`, String(count));

  for (let i = 0; i < count; i += 1) {
    const start = i * CHUNK_SIZE;
    localStorage.setItem(
      `${baseKey}_${i}`,
      json.slice(start, start + CHUNK_SIZE)
    );
  }

  localStorage.setItem(`${baseKey}_updatedAt`, nowIso());
}

function loadChunks(baseKey: string): string | null {
  if (!hasStorage()) return null;

  const n = Number(localStorage.getItem(`${baseKey}_n`) || 0);
  if (!Number.isFinite(n) || n <= 0) return null;

  let json = "";

  for (let i = 0; i < n; i += 1) {
    json += localStorage.getItem(`${baseKey}_${i}`) || "";
  }

  return json || null;
}

function readRows(): CatalogPos[] {
  try {
    const raw = loadChunks(KEY) || loadChunks(LEGACY_KEY);
    if (!raw) return [];

    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];

    return sortRows(parsed.map(makeRow));
  } catch {
    return [];
  }
}

function writeRows(rows: CatalogPos[]) {
  const clean = dedupeRows(rows);
  saveChunks(KEY, JSON.stringify(clean));
}

function parseRowsFromCSV(text: string): CatalogPos[] {
  const content = String(text || "").replace(/^\uFEFF/, "").trim();
  if (!content) return [];

  const lines = content.split(/\r?\n/).filter((line) => line.trim().length > 0);
  if (!lines.length) return [];

  const sep = detectSeparator(lines[0]);
  const first = parseCsvLine(lines[0], sep).map(normalizeHeader);

  const hasHeader =
    first.includes("posnr") ||
    first.includes("positionsnummer") ||
    first.includes("kurztext") ||
    first.includes("einheit") ||
    first.includes("ep") ||
    first.includes("gruppe");

  let iPos = 0;
  let iKurz = 1;
  let iEinheit = 2;
  let iEp = 3;
  let iGruppe = 4;

  if (hasHeader) {
    iPos = findHeader(first, ["posnr", "positionsnummer", "pos", "position"]);
    iKurz = findHeader(first, [
      "kurztext",
      "text",
      "bezeichnung",
      "artikel",
      "leistung",
    ]);
    iEinheit = findHeader(first, ["einheit", "me", "eh", "unit"]);
    iEp = findHeader(first, [
      "ep",
      "preis",
      "einheitspreis",
      "einzelpreis",
      "nettopreis",
    ]);
    iGruppe = findHeader(first, [
      "gruppe",
      "typ",
      "art",
      "category",
      "kategorie",
    ]);
  }

  const body = hasHeader ? lines.slice(1) : lines;

  return body
    .map((line) => {
      const parts = parseCsvLine(line, sep);

      return makeRow({
        posNr: iPos >= 0 ? parts[iPos] : parts[0],
        kurztext: iKurz >= 0 ? parts[iKurz] : parts[1],
        einheit: iEinheit >= 0 ? parts[iEinheit] : parts[2],
        ep: toNumber(iEp >= 0 ? parts[iEp] : parts[3]),
        gruppe: iGruppe >= 0 ? parts[iGruppe] : parts[4],
      });
    })
    .filter((row) => row.posNr || row.kurztext);
}

export const Catalog = {
  list(): CatalogPos[] {
    return readRows();
  },

  count(): number {
    return readRows().length;
  },

  stats(): {
    total: number;
    material: number;
    arbeiter: number;
    maschinen: number;
    sonstiges: number;
    updatedAt: string;
  } {
    const rows = readRows();

    return {
      total: rows.length,
      material: rows.filter((r) => r.gruppe === "Material").length,
      arbeiter: rows.filter((r) => r.gruppe === "Arbeiter").length,
      maschinen: rows.filter((r) => r.gruppe === "Maschinen").length,
      sonstiges: rows.filter(
        (r) =>
          r.gruppe !== "Material" &&
          r.gruppe !== "Arbeiter" &&
          r.gruppe !== "Maschinen"
      ).length,
      updatedAt: hasStorage()
        ? localStorage.getItem(`${KEY}_updatedAt`) || ""
        : "",
    };
  },

  clear() {
    clearChunks(KEY);
    clearChunks(LEGACY_KEY);
  },

  setAll(rows: CatalogPos[]): number {
    const clean = dedupeRows(rows);
    writeRows(clean);
    return clean.length;
  },

  upsert(row: CatalogPos): CatalogPos {
    const all = readRows();
    const next = makeRow(row);

    const idx = all.findIndex((r) => r.id === next.id);

    if (idx >= 0) {
      next.createdAt = all[idx].createdAt || next.createdAt;
      all[idx] = next;
    } else {
      all.unshift(next);
    }

    writeRows(all);
    return next;
  },

  remove(id: string) {
    const next = readRows().filter((r) => r.id !== id);
    writeRows(next);
  },

  importCSV(text: string): number {
    const rows = parseRowsFromCSV(text);
    writeRows(rows);
    return rows.length;
  },

  appendCSV(text: string): number {
    const current = readRows();
    const incoming = parseRowsFromCSV(text);
    const merged = dedupeRows([...incoming, ...current]);

    writeRows(merged);
    return incoming.length;
  },

  exportCSV(rows?: CatalogPos[]): string {
    const data = rows ?? readRows();

    const header = ["PosNr", "Kurztext", "Einheit", "EP", "Gruppe"];

    const body = sortRows(data).map((row) =>
      [
        csvEscape(row.posNr),
        csvEscape(row.kurztext),
        csvEscape(row.einheit),
        csvEscape(row.ep),
        csvEscape(row.gruppe || "Sonstiges"),
      ].join(";")
    );

    return [header.join(";"), ...body].join("\n");
  },
};

// apps/web/src/pages/kalkulation/changeStore.ts

const KEY = "rlc_changes_v2";

export type ChangeStatus =
  | "Entwurf"
  | "Abgegeben"
  | "Beauftragt"
  | "Abgelehnt";

export type ChangeRow = {
  id: string;

  // LV Bezug
  posNr?: string;
  parentPosNr?: string;

  // Texte
  kurztext: string;
  langtext?: string;
  begruendung?: string;

  // Menge / Preis
  einheit?: string;
  mengeDelta: number;
  preis?: number;
  zeilenNetto?: number;

  // Workflow
  status?: ChangeStatus;

  // Server / Meta
  source?: "manual" | "regie" | "lv" | "ki" | "server" | "csv" | "unknown";
  serverId?: string;
  number?: string;
  createdAt?: string;
  updatedAt?: string;
};

type DB = Record<string, ChangeRow[]>;

function uid(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `chg-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function nowIso(): string {
  return new Date().toISOString();
}

function normalizeProjectId(projectId: unknown): string {
  const v = String(projectId ?? "").trim();
  return v || "_none_";
}

function toNumber(value: unknown, fallback = 0): number {
  if (value === null || value === undefined || value === "") return fallback;

  const raw = String(value)
    .trim()
    .replace(/\s/g, "")
    .replace(/\.(?=\d{3}(?:[.,]|$))/g, "")
    .replace(",", ".");

  const n = Number(raw);
  return Number.isFinite(n) ? n : fallback;
}

function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function cleanText(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizeStatus(value: unknown): ChangeStatus {
  const v = cleanText(value);

  if (
    v === "Entwurf" ||
    v === "Abgegeben" ||
    v === "Beauftragt" ||
    v === "Abgelehnt"
  ) {
    return v;
  }

  return "Entwurf";
}

function normalizeSource(value: unknown): ChangeRow["source"] {
  const v = cleanText(value).toLowerCase();

  if (
    v === "manual" ||
    v === "regie" ||
    v === "lv" ||
    v === "ki" ||
    v === "server" ||
    v === "csv" ||
    v === "unknown"
  ) {
    return v;
  }

  return "unknown";
}

function calcLine(row: Pick<ChangeRow, "mengeDelta" | "preis">): number {
  return round2(toNumber(row.mengeDelta) * toNumber(row.preis));
}

function makeRow(input: Partial<ChangeRow> & { id?: string }): ChangeRow {
  const mengeDelta = toNumber(input.mengeDelta);
  const preis =
    input.preis === undefined || input.preis === null
      ? undefined
      : toNumber(input.preis);

  const createdAt = cleanText(input.createdAt) || nowIso();

  const row: ChangeRow = {
    id: cleanText(input.id) || uid(),

    posNr: cleanText(input.posNr),
    parentPosNr: cleanText(input.parentPosNr),

    kurztext: cleanText(input.kurztext),
    langtext: cleanText(input.langtext),
    begruendung: cleanText(input.begruendung),

    einheit: cleanText(input.einheit) || "m",
    mengeDelta,
    preis,
    zeilenNetto: calcLine({ mengeDelta, preis }),

    status: normalizeStatus(input.status),

    source: normalizeSource(input.source),
    serverId: cleanText(input.serverId),
    number: cleanText(input.number),
    createdAt,
    updatedAt: nowIso(),
  };

  return row;
}

function load(): DB {
  try {
    const rawV2 = localStorage.getItem(KEY);
    if (rawV2) {
      const parsed = JSON.parse(rawV2);
      return parsed && typeof parsed === "object" ? parsed : {};
    }

    // Legacy fallback: vecchia chiave
    const legacy = localStorage.getItem("rlc_changes_v1");
    if (legacy) {
      const parsed = JSON.parse(legacy);
      return parsed && typeof parsed === "object" ? parsed : {};
    }

    return {};
  } catch {
    return {};
  }
}

function save(db: DB) {
  localStorage.setItem(KEY, JSON.stringify(db));
}

function sortRows(rows: ChangeRow[]): ChangeRow[] {
  return [...rows].sort((a, b) => {
    const au = cleanText(a.updatedAt || a.createdAt);
    const bu = cleanText(b.updatedAt || b.createdAt);

    if (au !== bu) return bu.localeCompare(au);

    return cleanText(a.posNr).localeCompare(cleanText(b.posNr), "de", {
      numeric: true,
      sensitivity: "base",
    });
  });
}

function dedupe(rows: ChangeRow[]): ChangeRow[] {
  const seen = new Set<string>();
  const out: ChangeRow[] = [];

  for (const row of rows) {
    const id = cleanText(row.id);
    if (!id || seen.has(id)) continue;
    seen.add(id);
    out.push(row);
  }

  return out;
}

function parseCsvLine(line: string, sep = ";"): string[] {
  const out: string[] = [];
  let cur = "";
  let inQuotes = false;

  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"') {
      if (inQuotes && next === '"') {
        cur += '"';
        i++;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }

    if (ch === sep && !inQuotes) {
      out.push(cur);
      cur = "";
      continue;
    }

    cur += ch;
  }

  out.push(cur);
  return out;
}

function csvEscape(value: unknown): string {
  const s = String(value ?? "");

  if (s.includes('"') || s.includes(";") || s.includes("\n") || s.includes("\r")) {
    return `"${s.replace(/"/g, '""')}"`;
  }

  return s;
}

function normalizeHeader(value: unknown): string {
  return String(value ?? "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, "")
    .replace(/[_-]/g, "");
}

function idx(headers: string[], names: string[]): number {
  return headers.findIndex((h) => names.includes(h));
}

