  };
}

function toFiniteNumber(value: unknown, fallback = 0): number {
  if (value === null || value === undefined || value === "") return fallback;

  const n =
  typeof value === "number" ?
  value :
  Number(String(value).replace(",", ".").trim());

  return Number.isFinite(n) ? n : fallback;
}

