    document.getElementById(`rlc-row-${id}`) ||
    document.getElementById(id);

    if (el) {
      el.scrollIntoView({ behavior: "smooth", block: "center" });

      if (el instanceof HTMLElement) {
        el.focus?.();
      }
    }
  } catch {


    // Scroll ist nur Komfortfunktion. Keine Kalkulation blockieren.
  }}
