    baseUnitPrice: n(result.baseUnitPrice) || serverEp,
    preis: serverEp,
    totalNet: serverEp > 0 ? round2(menge * serverEp) : 0
  } as any;

  const temp = normalizeEliteRow({
    ...oldRow,
