async function exportPdf(opts: {
  projectKey: string;
  projectTitle: string;
  rows: EliteRow[];
  chapterTotals: Record<string, any>;
  summary: any;
  offer: OfferData;
  client: ClientData;
  company: CompanyData;
  mwst: number;
  globalMarkup: number;
  delivery?: boolean;
}): Promise<any> {
  const {
    projectKey,
    projectTitle,
    rows,
    summary,
    offer,
    client,
    company,
    mwst,
    globalMarkup,
    delivery
  } = opts;

  const response = await fetch(apiUrl("/api/pdf/kalkulation-ki"), {
    method: "POST",
    credentials: "include",
    headers: authJsonHeaders(),
    body: JSON.stringify({
      projectKey,
      projectTitle,

      project: {
        id: projectKey,
        code: projectKey,
        name: projectTitle,
        client: client?.name || "",
        auftraggeber: client?.name || "",
        clientAddress: client?.address || ""
      },

      offerNo: offer?.number || "",
      angebotNr: offer?.number || "",

      offer: {
        number: offer?.number || "",
        place: offer?.place || "",
        notes: offer?.notes || ""
      },

      client: {
        name: client?.name || "",
        address: client?.address || ""
      },

      company,
      rows,
      summary,
      totals: summary,
      mwst,
      globalMarkup,

      options: {
        city: offer?.place || "",
        dateISO: new Date().toISOString()
      }
    })
  });

  if (!response.ok) {
    const detail = await response.text().catch(() => "");
    throw new Error(
      detail ||
      `RLC PDF Core Fehler: HTTP ${response.status}`
    );
  }

  const blob = await response.blob();

  if (!blob.size) {
    throw new Error("RLC PDF Core hat eine leere PDF-Datei geliefert.");
  }

  const filename =
  `KI_Angebot_${safeFileName(offer?.number || projectKey || "Projekt")}.pdf`;

  const bytes = new Uint8Array(await blob.arrayBuffer());
  let binary = "";
  const chunkSize = 0x8000;

  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(
      ...bytes.subarray(i, i + chunkSize)
    );
  }

  const result = {
    blob,
    name: filename,
    base64: btoa(binary)
  };

  if (!delivery) {
    downloadBlob(blob, filename);
  }

  return result;
}

