    const raw = json?.rows || json?.items || json?.data || null;

    if (!Array.isArray(raw)) {
      const fallback = this.list().slice(0, safeLimit);
      return {
        rows: fallback,
        total: fallback.length,
        limit: safeLimit,
        offset: safeOffset,
        hasNext: false,
        hasPrev: safeOffset > 0,
