    return {
      rows: clean,
      total,
      limit: responseLimit,
      offset: responseOffset,
      hasNext:
        typeof json?.hasNext === "boolean"
          ? json.hasNext
          : responseOffset + clean.length < total,
      hasPrev:
        typeof json?.hasPrev === "boolean" ? json.hasPrev : responseOffset > 0,
