    const json = await fetchJson<{
      ok?: boolean;
      rows?: any[];
      items?: any[];
      data?: any[];

    }>(`${API_PATH}/datenbank?${params.toString()}`, {
      method: "GET",
      headers: authJsonHeaders(),
