  return "m";

  if (
  text.includes("abfuhr") ||
  text.includes("entsorgung") ||
  text.includes("deponie"))
  return "t";

  if (
  text.includes("schacht") ||
  text.includes("bogen") ||
  text.includes("abzweig") ||
  text.includes("anschluss") ||
  text.includes("stück") ||
  text.includes("stk"))
  return "Stk";

  return "";
}

function kostenSum(k?: Partial<KalkulationsKosten>): number {
  return round2(
    n(k?.material) +
    n(k?.lohn) +
