    projectCtx?.currentProject ||
    projectCtx?.selectedProject ||
    projectCtx?.current ||
    projectCtx ||
    null);

}

function getProjectKey(projectCtx: any): string {
  const p = getCurrentProject(projectCtx);

  return String(
    p?.code ||
    p?.projectCode ||
    p?.number ||
    p?.projektnummer ||
    p?.id ||
    ""
  ).
  trim().
  toUpperCase();
}

function getProjectName(projectCtx: any): string {
  const p = getCurrentProject(projectCtx);
