  function exportCSV() {
    const csv = LV.exportCSV(rows);
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });

try {
      LV.importCSV(text);
      refreshRows();
      setInfo("CSV lokal importiert.");
