    headRow +
    body +
    foot +
    `</Table></Worksheet></Workbook>`;

    const fileName = `LV_${projectKey}.xls`;
    const blob = new Blob([xml], { type: "application/vnd.ms-excel" });
    downloadBlob(blob, fileName);

    const dmsProjectId = String(activeProject?.id || "").trim();
    if (dmsProjectId) {
