  function importCSV(text: string) {
    const parsed = parseCsv(text);

    if (!parsed.length) {
      setInfo("CSV Import: keine gültigen Zeilen gefunden.");
      return;
    }

    const next = [...parsed, ...rows];

    saveLocal(next);
    setInfo(`${parsed.length} Nachtragsposition(en) aus CSV importiert.`);
  }

