      preview = reservePdfPreview(pdfFileName);

      const projectPlace = String(
        currentProject?.place ||
        currentProject?.ort ||
        currentProject?.location ||
        ""
      ).trim();

      const payload = {
        title: "Nachträge",
        project: {
          id: currentProject?.id || "",
          code: projectCode,
          number: projectCode,
          name: projectName,
          location: projectPlace
        },
        options: {
          mwst,
          dateISO: new Date().toISOString().slice(0, 10),
