function keepRowsAndEnsureIds(rows: CatalogPos[]): CatalogPos[] {
  const used = new Set<string>();

  return rows.map((row) => {
    const normalized = normalizeRow(row);
    let id = getVisibleRowId(normalized);

    if (used.has(id)) id = `${id}-${safeId()}`;
    used.add(id);

    return {
      ...(normalized as any),
      id
    } as CatalogPos;
  });
}

