      setErr("Bitte Kurztext eintragen.");
      return;
    }

    const row = editorToCatalogRow(manual);
    const next = persistCatalog([row, ...cat]);

    setSelected({ [getVisibleRowId(row)]: true });
    setEditor(rowToEditor(row));
    setEditorRowId(getVisibleRowId(row));
    clearCheck();

    setManual({
      posNr: "",
      kurztext: "",
      langtext: "",
      einheit: "m",
