    const next = cat.filter((row) => !ids.has(getVisibleRowId(row)));
    persistCatalog(next);

    setSelected({});
    setEditor(null);
    setEditorRowId("");
    clearCheck();

    setStat(`${ids.size} ausgewählte Position(en) gelöscht.`);
  }

  function autoCorrectSelected() {
