// apps/web/src/lib/pricing.ts

export type PriceGroup =
  | "Material"
  | "Arbeit"
  | "Maschine"
  | "Fremdleistung"
  | "Entsorgung"
  | "Sonstiges";

export type PriceSource =
  | "demo"
  | "manual"
  | "csv"
  | "server"
  | "company"
  | "catalog"
  | "unknown";

export type PriceRow = {
  id: string;

  // Identifikation
  artikelNr: string;
  refKey?: string;

  // Beschreibung
  bezeichnung: string;
  kurztext?: string;
  langtext?: string;

  // Einheit / Preis
  einheit: string;
  ep: number; // Einzelpreis netto
  waehrung?: string;

  // Klassifikation
  gruppe?: PriceGroup | string;
  kategorie?: string;
  gewerk?: string;

  // Gültigkeit / Herkunft
  validFrom?: string;
  validTo?: string | null;
  source?: PriceSource;
  note?: string;

  // Meta
  createdAt?: string;
  updatedAt?: string;
};

const KEY = "rlc.kalkulation.preise";
const BACKUP_KEY = "rlc.kalkulation.preise.backup";
const VERSION_KEY = "rlc.kalkulation.preise.version";

const CURRENT_VERSION = "2";

function uid(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `price-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function nowIso(): string {
  return new Date().toISOString();
}

function normalizeText(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizeCurrency(value: unknown): string {
  const v = normalizeText(value).toUpperCase();
  return v || "EUR";
}

function parseNumber(value: unknown, fallback = 0): number {
  if (value === null || value === undefined || value === "") return fallback;

  if (typeof value === "number") {
    return Number.isFinite(value) ? value : fallback;
  }

  const raw = String(value).trim();
  if (!raw) return fallback;

  const normalized = raw
    .replace(/\s/g, "")
    .replace(/\.(?=\d{3}(?:[.,]|$))/g, "")
    .replace(",", ".");

  const n = Number(normalized);
  return Number.isFinite(n) ? n : fallback;
}

function roundPrice(value: unknown): number {
  return Math.round((parseNumber(value, 0) + Number.EPSILON) * 100) / 100;
}

function normalizeUnit(value: unknown): string {
  const v = normalizeText(value);
  const l = v.toLowerCase();

  if (l === "m2" || l === "qm" || l === "m^2") return "m²";
  if (l === "m3" || l === "cbm" || l === "m^3") return "m³";
  if (l === "stk" || l === "st" || l === "stück" || l === "stck") return "St";
  if (l === "std" || l === "stunden") return "h";
  if (l === "to" || l === "tonnen") return "t";
  if (l === "pauschal") return "PS";

  return v || "St";
}

function normalizeGroup(value: unknown): PriceGroup {
  const v = normalizeText(value).toLowerCase();

  if (["material", "materialien", "mat"].includes(v)) return "Material";
  if (["arbeit", "arbeiter", "lohn", "labor", "personal"].includes(v)) return "Arbeit";
  if (["maschine", "maschinen", "machine", "gerät", "geraet"].includes(v)) return "Maschine";
  if (["fremdleistung", "subunternehmer", "subcontractor"].includes(v)) return "Fremdleistung";
  if (["entsorgung", "deponie", "abfall"].includes(v)) return "Entsorgung";

  return "Sonstiges";
}

function sanitizeSource(value: unknown): PriceSource {
  const v = normalizeText(value).toLowerCase();

  if (
    v === "demo" ||
    v === "manual" ||
    v === "csv" ||
    v === "server" ||
    v === "company" ||
    v === "catalog" ||
    v === "unknown"
  ) {
    return v;
  }

  return "unknown";
}

function makeRefKey(row: Partial<PriceRow>): string {
  const existing = normalizeText(row.refKey);
  if (existing) return existing.toUpperCase();

  const artikelNr = normalizeText(row.artikelNr);
  const group = normalizeGroup(row.gruppe);

  if (!artikelNr) return "";

  if (group === "Arbeit") return `LABOR:${artikelNr}`.toUpperCase();
  if (group === "Maschine") return `MACHINE:${artikelNr}`.toUpperCase();
  if (group === "Material") return `MATERIAL:${artikelNr}`.toUpperCase();
  if (group === "Fremdleistung") return `SUB:${artikelNr}`.toUpperCase();
  if (group === "Entsorgung") return `DISPOSAL:${artikelNr}`.toUpperCase();

  return `OTHER:${artikelNr}`.toUpperCase();
}

export function normalizePriceRow(row: Partial<PriceRow>): PriceRow {
  const createdAt = normalizeText(row.createdAt) || nowIso();

  const next: PriceRow = {
    id: normalizeText(row.id) || uid(),

    artikelNr: normalizeText(row.artikelNr),
    refKey: makeRefKey(row),

    bezeichnung: normalizeText(row.bezeichnung || row.kurztext),
    kurztext: normalizeText(row.kurztext || row.bezeichnung),
    langtext: normalizeText(row.langtext),

    einheit: normalizeUnit(row.einheit),
    ep: roundPrice(row.ep),
    waehrung: normalizeCurrency(row.waehrung),

    gruppe: normalizeGroup(row.gruppe),
    kategorie: normalizeText(row.kategorie),
    gewerk: normalizeText(row.gewerk),

    validFrom: normalizeText(row.validFrom) || new Date().toISOString().slice(0, 10),
    validTo: row.validTo === undefined ? null : row.validTo,
    source: sanitizeSource(row.source),
    note: normalizeText(row.note),

    createdAt,
    updatedAt: nowIso(),
  };

  if (!next.bezeichnung && next.artikelNr) {
    next.bezeichnung = next.artikelNr;
  }

  if (!next.kurztext) {
    next.kurztext = next.bezeichnung;
  }

  return next;
}

function sortRows(rows: PriceRow[]): PriceRow[] {
  return [...rows].sort((a, b) => {
    const g = String(a.gruppe || "").localeCompare(String(b.gruppe || ""), "de", {
      numeric: true,
      sensitivity: "base",
    });
    if (g !== 0) return g;

return next;
}

function sortRows(rows: PriceRow[]): PriceRow[] {
  return [...rows].sort((a, b) => {
    const g = String(a.gruppe || "").localeCompare(String(b.gruppe || ""), "de", {
      numeric: true,
      sensitivity: "base",
    });
    if (g !== 0) return g;

    return String(a.artikelNr || "").localeCompare(String(b.artikelNr || ""), "de", {
      numeric: true,
      sensitivity: "base",
    });
  });
}

function dedupeRows(rows: PriceRow[]): PriceRow[] {
  const map = new Map<string, PriceRow>();

  for (const row of rows) {
    const normalized = normalizePriceRow(row);
    const key =
      normalized.refKey ||
      `${normalized.gruppe}:${normalized.artikelNr}`.toUpperCase() ||
      normalized.id;

    const existing = map.get(key);

    if (existing?.createdAt) {
      normalized.createdAt = existing.createdAt;
    }

    map.set(key, normalized);
  }

  return sortRows(Array.from(map.values()));
}

function safeParse(raw: string | null): PriceRow[] | null {
  if (!raw) return null;

  try {
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return null;
    return dedupeRows(parsed);
  } catch {
    return null;
  }
}

function writeRows(rows: PriceRow[]) {
  const normalized = dedupeRows(rows);

  try {
    const old = localStorage.getItem(KEY);
    if (old) localStorage.setItem(BACKUP_KEY, old);
  } catch {
    // ignore backup failure
  }

  localStorage.setItem(KEY, JSON.stringify(normalized));
  localStorage.setItem(VERSION_KEY, CURRENT_VERSION);
}

export function loadPreise(): PriceRow[] {
  try {
    const rows = safeParse(localStorage.getItem(KEY));

    if (rows && rows.length) {
      const version = localStorage.getItem(VERSION_KEY);

      if (version !== CURRENT_VERSION) {
        writeRows(rows);
      }

      return rows;
    }

    const initial = demo();
    writeRows(initial);
    return initial;
  } catch {
    return demo();
  }
}

export function savePreise(rows: PriceRow[]) {
  try {
    writeRows(rows);
  } catch {
    // localStorage quota or browser restriction
  }
}

export function clearPreise() {
  try {
    localStorage.removeItem(KEY);
    localStorage.removeItem(BACKUP_KEY);
    localStorage.removeItem(VERSION_KEY);
  } catch {
    // ignore
  }
}

export function upsertPreis(row: Partial<PriceRow>): PriceRow {
  const all = loadPreise();
  const next = normalizePriceRow(row);

  const idx = all.findIndex((x) => {
    if (next.refKey && x.refKey) return x.refKey === next.refKey;
    return x.id === next.id;
  });

  if (idx >= 0) {
    next.createdAt = all[idx].createdAt || next.createdAt;
    all[idx] = next;
  } else {
    all.unshift(next);
  }

  savePreise(all);
  return next;
}

export function removePreis(idOrRefKey: string) {
  const key = normalizeText(idOrRefKey).toUpperCase();

  const next = loadPreise().filter(
    (r) => r.id !== idOrRefKey && String(r.refKey || "").toUpperCase() !== key
  );

  savePreise(next);
}

export function findPreis(refKeyOrArtikelNr: string): PriceRow | null {
  const key = normalizeText(refKeyOrArtikelNr).toUpperCase();
  if (!key) return null;

  return (
    loadPreise().find((r) => {
      return (
        String(r.refKey || "").toUpperCase() === key ||
        String(r.artikelNr || "").toUpperCase() === key
      );
    }) || null
  );
}

export function searchPreise(query: string, group?: PriceGroup | "Alle"): PriceRow[] {
  const q = normalizeText(query).toLowerCase();

  return loadPreise().filter((r) => {
    const groupOk = !group || group === "Alle" ? true : r.gruppe === group;
    if (!groupOk) return false;

    if (!q) return true;

    const hay = [
      r.artikelNr,
      r.refKey,
      r.bezeichnung,
      r.kurztext,
      r.langtext,
      r.einheit,
      r.gruppe,
      r.kategorie,
      r.gewerk,
    ]
      .join(" ")
      .toLowerCase();

    return hay.includes(q);
  });
}

export function importPreiseCSV(text: string): number {
  const content = String(text || "").replace(/^\uFEFF/, "").trim();
  if (!content) return 0;

  const lines = content.split(/\r?\n/).filter((line) => line.trim());
  if (!lines.length) return 0;

  const sep = lines[0].includes(";") ? ";" : ",";

  const splitLine = (line: string) => {
    const out: string[] = [];
    let cur = "";
    let quoted = false;

    for (let i = 0; i < line.length; i += 1) {
      const ch = line[i];
      const next = line[i + 1];

      if (ch === '"') {
        if (quoted && next === '"') {
          cur += '"';
          i += 1;
        } else {
          quoted = !quoted;
        }
        continue;
      }

      if (ch === sep && !quoted) {
        out.push(cur);
        cur = "";
        continue;
      }

      cur += ch;
    }

    out.push(cur);
    return out;
  };

  const normalizeHeader = (v: string) =>
    v.trim().toLowerCase().replace(/\s+/g, "").replace(/[_-]/g, "");

  const first = splitLine(lines[0]).map(normalizeHeader);

  const hasHeader =
    first.includes("artikelnr") ||
    first.includes("refkey") ||
    first.includes("bezeichnung") ||
    first.includes("kurztext") ||
    first.includes("einheit") ||
    first.includes("ep") ||
    first.includes("gruppe");

  const idx = (names: string[]) => first.findIndex((h) => names.includes(h));

