// apps/web/src/pages/kalkulation/projectStore.ts

const KEY = "rlc_projects_v2";
const LEGACY_KEY = "rlc_projects_v1";

const CUR = "rlc_current_project_id";
const CUR_CODE = "rlc_current_project_code";

export type Project = {
  id: string;

  // Hauptdaten
  name: string; // Projektname
  number: string; // BaustellenNummer / BA-Code

  // Alias compatibili con altri moduli
  code: string;
  projectCode: string;

  client?: string; // Auftraggeber
  location?: string; // Ort
  place?: string;

  createdAt: number;
  updatedAt: number;

  // opzionali per compatibilitÃ  futura/server
  dbId?: string | number;
  companyId?: string;
};

type ProjectInput = Partial<Project> & {
  id?: string;
  code?: string;
  projectCode?: string;
  number?: string;
  name?: string;
  client?: string;
  location?: string;
  place?: string;
};

function uid(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `project-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function now(): number {
  return Date.now();
}

function clean(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizeProjectCode(value: unknown): string {
  return clean(value)
    .toUpperCase()
    .replace(/\s+/g, "-")
    .replace(/[^A-Z0-9_.-]/g, "");
}

function isProjectLike(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === "object";
}

function normalizeProject(raw: unknown): Project | null {
  if (!isProjectLike(raw)) return null;

  const id = clean(raw.id) || uid();

  const number = normalizeProjectCode(
    raw.number ?? raw.code ?? raw.projectCode ?? raw.projektnummer
  );

  const name = clean(raw.name ?? raw.projectName ?? raw.projektname);

  if (!number && !name) return null;

  const finalNumber = number || `BA-${new Date().getFullYear()}-${id.slice(0, 6).toUpperCase()}`;

  const createdAtRaw = Number(raw.createdAt);
  const updatedAtRaw = Number(raw.updatedAt);

  return {
    id,
    name,
    number: finalNumber,
    code: finalNumber,
    projectCode: finalNumber,

    client: clean(raw.client ?? raw.auftraggeber ?? raw.kunde),
    location: clean(raw.location ?? raw.place ?? raw.ort),
    place: clean(raw.place ?? raw.location ?? raw.ort),

    createdAt: Number.isFinite(createdAtRaw) && createdAtRaw > 0 ? createdAtRaw : now(),
    updatedAt: Number.isFinite(updatedAtRaw) && updatedAtRaw > 0 ? updatedAtRaw : now(),

    dbId: (raw.dbId as any) ?? undefined,
    companyId: clean(raw.companyId) || undefined,
  };
}

function sortProjects(rows: Project[]): Project[] {
  return [...rows].sort((a, b) => {
    const au = Number(a.updatedAt || a.createdAt || 0);
    const bu = Number(b.updatedAt || b.createdAt || 0);
    return bu - au;
  });
}

function dedupe(rows: Project[]): Project[] {
  const byId = new Map<string, Project>();
  const byCode = new Map<string, string>();

  for (const row of rows) {
    const normalized = normalizeProject(row);
    if (!normalized) continue;

    const codeKey = normalizeProjectCode(normalized.code || normalized.number);

    const existingIdByCode = codeKey ? byCode.get(codeKey) : "";
    if (existingIdByCode && byId.has(existingIdByCode)) {
      const old = byId.get(existingIdByCode)!;
      byId.set(existingIdByCode, {
        ...old,
        ...normalized,
        id: old.id,
        createdAt: old.createdAt || normalized.createdAt,
        updatedAt: Math.max(old.updatedAt || 0, normalized.updatedAt || 0),
      });
      continue;
    }

    byId.set(normalized.id, normalized);
    if (codeKey) byCode.set(codeKey, normalized.id);
  }

  return sortProjects(Array.from(byId.values()));
}

function readRaw(key: string): unknown[] {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function readAll(): Project[] {
  const current = readRaw(KEY);
  const legacy = readRaw(LEGACY_KEY);

  const safeLegacy: Project[] = Array.isArray(legacy) ? (legacy as Project[]) : [];
  const rows = dedupe([...(current as Project[]), ...safeLegacy]);

  // migrazione automatica da v1 a v2
  if (rows.length && current.length === 0) {
    writeAll(rows);
  }

  return rows;
}

function writeAll(rows: Project[]) {
  localStorage.setItem(KEY, JSON.stringify(dedupe(rows)));
}

function findProject(idOrCode: string): Project | null {
  const key = clean(idOrCode);
  const codeKey = normalizeProjectCode(key);

  return (
    readAll().find(
      (p) =>
        p.id === key ||
        normalizeProjectCode(p.number) === codeKey ||
        normalizeProjectCode(p.code) === codeKey ||
        normalizeProjectCode(p.projectCode) === codeKey
    ) || null
  );
}

export const Projects = {
  list(): Project[] {
    return readAll();
  },

  count(): number {
    return readAll().length;
  },

  get(idOrCode: string): Project | null {
    return findProject(idOrCode);
  },

  upsert(p: ProjectInput): Project {
    const all = readAll();

    const incoming = normalizeProject({
      ...p,
      id: p.id || uid(),
      number: p.number ?? p.code ?? p.projectCode,
      code: p.code ?? p.number ?? p.projectCode,
      projectCode: p.projectCode ?? p.code ?? p.number,
    });

    if (!incoming) {
      throw new Error("Projekt ungÃ¼ltig: BaustellenNummer oder Projektname fehlt.");
    }

    const idx = all.findIndex(
      (x) =>
        x.id === incoming.id ||

number: p.number ?? p.code ?? p.projectCode,
      code: p.code ?? p.number ?? p.projectCode,
      projectCode: p.projectCode ?? p.code ?? p.number,
    });

    if (!incoming) {
      throw new Error("Projekt ungÃ¼ltig: BaustellenNummer oder Projektname fehlt.");
    }

    const idx = all.findIndex(
      (x) =>
        x.id === incoming.id ||
        normalizeProjectCode(x.number) === normalizeProjectCode(incoming.number)
    );

    const createdAt = idx >= 0 ? all[idx].createdAt : incoming.createdAt;

    const item: Project = {
      ...incoming,
      createdAt,
      updatedAt: now(),
    };

    if (idx >= 0) all[idx] = item;
    else all.unshift(item);

    writeAll(all);
    return item;
  },

  remove(idOrCode: string) {
    const target = findProject(idOrCode);
    if (!target) return;

    const next = readAll().filter((p) => p.id !== target.id);
    writeAll(next);

    if (Projects.getCurrentId() === target.id) {
      localStorage.removeItem(CUR);
      localStorage.removeItem(CUR_CODE);
    }
  },

  clear() {
    localStorage.removeItem(KEY);
    localStorage.removeItem(LEGACY_KEY);
    localStorage.removeItem(CUR);
    localStorage.removeItem(CUR_CODE);
  },

  setCurrent(idOrCode: string) {
    const p = findProject(idOrCode);
    if (!p) return;

    localStorage.setItem(CUR, p.id);
    localStorage.setItem(CUR_CODE, p.code || p.number);
  },

  getCurrentId(): string | null {
    return localStorage.getItem(CUR);
  },

  getCurrentCode(): string | null {
    return localStorage.getItem(CUR_CODE);
  },

  getCurrent(): Project | null {
    const id = localStorage.getItem(CUR);
    const code = localStorage.getItem(CUR_CODE);

    if (id) {
      const byId = findProject(id);
      if (byId) return byId;
    }

    if (code) {
      const byCode = findProject(code);
      if (byCode) return byCode;
    }

    return null;
  },

  exportJSON(): string {
    return JSON.stringify(readAll(), null, 2);
  },

  importJSON(json: string): number {
    const parsed = JSON.parse(json);
    if (!Array.isArray(parsed)) throw new Error("Invalid JSON: Array erwartet.");

    const imported = dedupe(parsed.map(normalizeProject).filter(Boolean) as Project[]);
    writeAll(imported);

    return imported.length;
  },

  mergeImportJSON(json: string): number {
    const parsed = JSON.parse(json);
    if (!Array.isArray(parsed)) throw new Error("Invalid JSON: Array erwartet.");

    const imported = parsed.map(normalizeProject).filter(Boolean) as Project[];
    const merged = dedupe([...imported, ...readAll()]);
    writeAll(merged);

    return imported.length;
  },
};

// apps/web/src/pages/kalkulation/recipeLibrary.ts

export type RecipeLibraryGroup =
  | "Personal"
  | "Maschinen"
  | "LKW / Transport"
  | "Material"
  | "Entsorgung"
  | "Fremdleistung"
  | "Gemeinkosten"
  | "Risiko"
  | "Gewinn"
  | "Sonstiges";

export type RecipeLibraryItem = {
  id: string;
  code: string;
  title: string;
  unit: string;
  qty: number;
  unitPrice: number;
  minPrice: number;
  maxPrice: number;
  avgPrice: number;
  variants: number;
  group: RecipeLibraryGroup;
  keywords: string[];
  source: "base" | "csv-import" | "manual";
  createdAt: string;
  updatedAt: string;
};

export type RecipeLibraryImportResult = {
  imported: number;
  skipped: number;
  duplicatesMerged: number;
  total: number;
};

const STORE_KEY = "rlc_recipe_library_v1";

/* ================= BASIC HELPERS ================= */

function safeId(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `lib-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function n(value: unknown, fallback = 0): number {
  if (value === null || value === undefined || value === "") return fallback;

  const raw = String(value).trim();

  const normalized = raw.includes(",")
    ? raw.replace(/\./g, "").replace(",", ".")
    : raw.replace(/\s/g, "");

  const parsed = typeof value === "number" ? value : Number(normalized);
  return Number.isFinite(parsed) ? parsed : fallback;
}

function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function norm(value: unknown): string {
  return String(value ?? "")
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}

function compact(value: unknown): string {
  return norm(value).replace(/[^a-z0-9äöüß]+/gi, "");
}

function normalizeUnit(unit: unknown): string {
  const u = String(unit ?? "").trim();
  const l = u.toLowerCase();

  if (!u) return "St";
  if (["m2", "qm", "m²", "m^2"].includes(l)) return "m²";
  if (["m3", "cbm", "m³", "m^3"].includes(l)) return "m³";
  if (["stk", "st", "stück", "stueck"].includes(l)) return "St";
  if (["std", "h", "stunden"].includes(l)) return "h";
  if (["to", "tonne", "tonnen"].includes(l)) return "t";
  if (["psch", "pausch", "pauschale"].includes(l)) return "pauschal";

  return u;
}

function splitCsvLine(line: string): string[] {
  const out: string[] = [];
  let cur = "";
  let inside = false;

  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i];
    const next = line[i + 1];

    if (ch === '"' && inside && next === '"') {
      cur += '"';
      i += 1;
      continue;
    }

    if (ch === '"') {
      inside = !inside;
      continue;
    }

    if ((ch === ";" || ch === ",") && !inside) {
      out.push(cur.trim());
      cur = "";
      continue;
    }

    cur += ch;
  }

  out.push(cur.trim());
  return out;
}

function makeKeywords(title: string): string[] {
  return Array.from(
    new Set(
      norm(title)
        .split(/[^a-z0-9äöüß]+/i)
        .map((x) => x.trim())
        .filter((x) => x.length >= 3)
    )
  );
}

function classifyGroup(title: string): RecipeLibraryGroup {
  const t = norm(title);

  if (
    t.includes("lkw") ||
    t.includes("transport") ||
    t.includes("abfuhr") ||
    t.includes("anfuhr") ||
    t.includes("anliefer") ||
    t.includes("fahren") ||
    t.includes("tieflader")
  ) {
    return "LKW / Transport";
  }

  if (
    t.includes("bagger") ||
    t.includes("radlader") ||
    t.includes("walze") ||
    t.includes("rüttel") ||
    t.includes("ruettel") ||
    t.includes("ruttel") ||
    t.includes("verdichter") ||
    t.includes("maschine") ||
    t.includes("fugenschneider") ||
    t.includes("steinschneider") ||
    t.includes("pflasterknacker")
  ) {
    return "Maschinen";
  }

  if (
    t.includes("facharbeiter") ||
    t.includes("helfer") ||
    t.includes("polier") ||
    t.includes("arbeiter") ||
    t.includes("lohn") ||
    t.includes("kolonne") ||
    t.includes("bauleiter") ||
    t.includes("vermessung")
  ) {
    return "Personal";
  }

  if (
    t.includes("entsorgung") ||
    t.includes("deponie") ||
    t.includes("verwertung") ||
    t.includes("beseitigung") ||
    t.includes("aufbruch entsorgen")
  ) {
    return "Entsorgung";
  }

  if (
    t.includes("frostschutz") ||
    t.includes("kies") ||
    t.includes("schotter") ||
    t.includes("sand") ||
    t.includes("splitt") ||
    t.includes("pflaster") ||
    t.includes("bordstein") ||
    t.includes("rasengitter") ||
    t.includes("asphalt") ||
    t.includes("beton") ||
    t.includes("rohr") ||
    t.includes("leitung") ||
    t.includes("speedpipe") ||
    t.includes("material") ||
    t.includes("stein") ||
    t.includes("platte") ||
    t.includes("fugen")
  ) {
    return "Material";
  }

  if (t.includes("fremd") || t.includes("nachunternehmer")) {
    return "Fremdleistung";
  }

  if (t.includes("gemeinkosten") || t.includes("bgk")) return "Gemeinkosten";
  if (t.includes("risiko")) return "Risiko";
  if (t.includes("gewinn")) return "Gewinn";

  return "Sonstiges";
}

/**
 * Wichtig:
 * Nicht nur title+unit verwenden.
 * Sonst werden tausende reale Positionen zu wenigen Einträgen verschmolzen.
 */
function dedupeKey(item: Pick<RecipeLibraryItem, "code" | "title" | "unit" | "unitPrice" | "group">): string {
  const code = compact(item.code);
  const title = compact(item.title);
  const unit = compact(normalizeUnit(item.unit));

return "Sonstiges";
}

/**
 * Wichtig:
 * Nicht nur title+unit verwenden.
 * Sonst werden tausende reale Positionen zu wenigen Einträgen verschmolzen.
 */
function dedupeKey(item: Pick<RecipeLibraryItem, "code" | "title" | "unit" | "unitPrice" | "group">): string {
  const code = compact(item.code);
  const title = compact(item.title);
  const unit = compact(normalizeUnit(item.unit));
  const group = compact(item.group);
  const price = round2(n(item.unitPrice)).toFixed(2);

  if (code) {
    return `code:${code}|unit:${unit}|price:${price}|group:${group}`;
  }

  return `title:${title}|unit:${unit}|price:${price}|group:${group}`;
}

function normalizeItem(row: Partial<RecipeLibraryItem>): RecipeLibraryItem {
  const now = new Date().toISOString();

  const title = String(row.title || "").trim();
  const unit = normalizeUnit(row.unit);
  const unitPrice = round2(n(row.unitPrice ?? row.avgPrice));
  const minPrice = round2(n(row.minPrice, unitPrice));
  const maxPrice = round2(n(row.maxPrice, unitPrice));
  const avgPrice = round2(n(row.avgPrice, unitPrice));
  const group = row.group || classifyGroup(title);

  return {
    id: String(row.id || safeId()),
    code: String(row.code || "").trim(),
    title,
    unit,
    qty: n(row.qty, 1),
    unitPrice,
    minPrice,
    maxPrice,
    avgPrice,
    variants: Math.max(1, n(row.variants, 1)),
    group,
    keywords: Array.isArray(row.keywords) ? row.keywords : makeKeywords(title),
    source: row.source || "manual",
    createdAt: String(row.createdAt || now),
    updatedAt: String(row.updatedAt || now),
  };
}

/* ================= STORAGE ================= */

function readDb(): RecipeLibraryItem[] {
  try {
    const raw = localStorage.getItem(STORE_KEY);
    const parsed = JSON.parse(raw || "[]");

    if (!Array.isArray(parsed)) return [];

    return parsed
      .map(normalizeItem)
      .filter((x) => x.title.trim() && x.unitPrice >= 0);
  } catch {
    return [];
  }
}

function writeDb(rows: RecipeLibraryItem[]) {
  localStorage.setItem(STORE_KEY, JSON.stringify(rows.map(normalizeItem)));
}

function mergeItems(
  oldItem: RecipeLibraryItem,
  newItem: RecipeLibraryItem
): RecipeLibraryItem {
  const oldVariants = Math.max(1, n(oldItem.variants, 1));
  const newVariants = Math.max(1, n(newItem.variants, 1));
  const totalVariants = oldVariants + newVariants;

  const avgPrice = round2(
    (n(oldItem.avgPrice) * oldVariants + n(newItem.avgPrice) * newVariants) /
      totalVariants
  );

  return normalizeItem({
    ...oldItem,
    code: oldItem.code || newItem.code,
    title: oldItem.title || newItem.title,
    unit: oldItem.unit || newItem.unit,
    qty: round2((n(oldItem.qty) + n(newItem.qty)) / 2),
    unitPrice: avgPrice,
    avgPrice,
    minPrice: Math.min(n(oldItem.minPrice, avgPrice), n(newItem.minPrice, avgPrice)),
    maxPrice: Math.max(n(oldItem.maxPrice, avgPrice), n(newItem.maxPrice, avgPrice)),
    variants: totalVariants,
    keywords: Array.from(new Set([...oldItem.keywords, ...newItem.keywords])),
    source: oldItem.source === "base" ? "base" : newItem.source,
    updatedAt: new Date().toISOString(),
  });
}

/* ================= CSV IMPORT ================= */

function parseCsv(text: string): Record<string, string>[] {
  const lines = String(text || "")
    .replace(/\r/g, "")
    .split("\n")
    .map((x) => x.trim())
    .filter(Boolean);

  if (lines.length < 2) return [];

  const headers = splitCsvLine(lines[0]).map((h) =>
    norm(h).replace(/[^a-z0-9]+/g, "")
  );

  return lines.slice(1).map((line) => {
    const cells = splitCsvLine(line);
    const obj: Record<string, string> = {};

    headers.forEach((h, i) => {
      obj[h] = cells[i] ?? "";
    });

    return obj;
  });
}

function firstValue(obj: Record<string, string>, names: string[]): string {
  for (const name of names) {
    const key = norm(name).replace(/[^a-z0-9]+/g, "");
    const value = obj[key];
    if (value !== undefined && String(value).trim()) return value;
  }

  return "";
}

function csvObjToItem(obj: Record<string, string>): RecipeLibraryItem | null {
  const code = firstValue(obj, [
    "code",
    "nr",
    "nummer",
    "artikelnummer",
    "artnr",
    "posnr",
    "position",
    "positionsnummer",
    "oz",
  ]);

  const title = firstValue(obj, [
    "title",
    "titel",
    "kurztext",
    "text",
    "bezeichnung",
    "beschreibung",
    "name",
    "leistung",
  ]);

  const unit = firstValue(obj, ["unit", "einheit", "me", "mengeneinheit"]);
  const qty = firstValue(obj, ["qty", "menge", "quantity", "anzahl"]) || "1";

  const unitPrice = firstValue(obj, [
    "unitprice",
    "preis",
    "ep",
    "einheitspreis",
    "price",
    "avgprice",
    "durchschnittspreis",
  ]);

  const groupRaw = firstValue(obj, ["group", "gruppe", "category", "kategorie"]);
  const price = n(unitPrice);

  if (!String(title).trim()) return null;
  if (price < 0) return null;

  const group =
    groupRaw && isRecipeLibraryGroup(groupRaw)
      ? (groupRaw as RecipeLibraryGroup)
      : classifyGroup(title);

  return normalizeItem({
    id: safeId(),
    code,
    title,
    unit,
    qty: n(qty, 1),
    unitPrice: price,
    minPrice: price,
    maxPrice: price,
    avgPrice: price,
    variants: 1,
    group,
    keywords: makeKeywords(`${code} ${title} ${group}`),
    source: "csv-import",
  });
}

function isRecipeLibraryGroup(value: string): boolean {
  return [
    "Personal",
    "Maschinen",
    "LKW / Transport",

variants: 1,
    group,
    keywords: makeKeywords(`${code} ${title} ${group}`),
    source: "csv-import",
  });
}

function isRecipeLibraryGroup(value: string): boolean {
  return [
    "Personal",
    "Maschinen",
    "LKW / Transport",
    "Material",
    "Entsorgung",
    "Fremdleistung",
    "Gemeinkosten",
    "Risiko",
    "Gewinn",
    "Sonstiges",
  ].includes(value);
}

/* ================= SEARCH ================= */

function scoreItem(item: RecipeLibraryItem, query: string): number {
  const q = norm(query);
  if (!q) return 0;

  const title = norm(item.title);
  const code = norm(item.code);
  const group = norm(item.group);

  let score = 0;

  if (title === q) score += 100;
  if (title.includes(q)) score += 50;
  if (code && code.includes(q)) score += 45;
  if (group.includes(q)) score += 15;

  const qTokens = q.split(/[^a-z0-9äöüß]+/i).filter((x) => x.length >= 3);
  const itemTokens = new Set(item.keywords);

  for (const token of qTokens) {
    if (itemTokens.has(token)) score += 12;
    else if (title.includes(token)) score += 8;
    else if (code.includes(token)) score += 6;
  }

  if (item.variants > 1) score += Math.min(12, item.variants);

  return score;
}

/* ================= PUBLIC API ================= */

export const RecipeLibrary = {
  key: STORE_KEY,

  list(): RecipeLibraryItem[] {
    return readDb().sort((a, b) =>
      a.title.localeCompare(b.title, "de", {
        numeric: true,
        sensitivity: "base",
      })
    );
  },

  count(): number {
    return readDb().length;
  },

  clear() {
    localStorage.removeItem(STORE_KEY);
  },

  upsert(row: Partial<RecipeLibraryItem>): RecipeLibraryItem {
    const item = normalizeItem(row);
    const rows = readDb();

    const key = dedupeKey(item);
    const idx = rows.findIndex((x) => x.id === item.id || dedupeKey(x) === key);

    if (idx >= 0) {
      rows[idx] = mergeItems(rows[idx], item);
      writeDb(rows);
      return rows[idx];
    }

    rows.unshift(item);
    writeDb(rows);
    return item;
  },

  bulkUpsert(items: Partial<RecipeLibraryItem>[]): RecipeLibraryItem[] {
    const saved: RecipeLibraryItem[] = [];

    for (const item of items) {
      saved.push(this.upsert(item));
    }

    return saved;
  },

  search(query: string, limit = 50): RecipeLibraryItem[] {
    return readDb()
      .map((item) => ({ item, score: scoreItem(item, query) }))
      .filter((x) => x.score > 0)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit)
      .map((x) => x.item);
  },

  byGroup(group: RecipeLibraryGroup): RecipeLibraryItem[] {
    return this.list().filter((x) => x.group === group);
  },

  importCsvPriceLibrary(text: string): RecipeLibraryImportResult {
    const parsed = parseCsv(text);
    const rows = readDb();
    const map = new Map<string, RecipeLibraryItem>();

    for (const row of rows) {
      map.set(dedupeKey(row), row);
    }

    let imported = 0;
    let skipped = 0;
    let duplicatesMerged = 0;

    for (const obj of parsed) {
      const item = csvObjToItem(obj);

      if (!item) {
        skipped += 1;
        continue;
      }

      const key = dedupeKey(item);
      const existing = map.get(key);

      if (existing) {
        map.set(key, mergeItems(existing, item));
        duplicatesMerged += 1;
      } else {
        map.set(key, item);
        imported += 1;
      }
    }

    const next = Array.from(map.values()).sort((a, b) =>
      a.title.localeCompare(b.title, "de", {
        numeric: true,
        sensitivity: "base",
      })
    );

    writeDb(next);

    return {
      imported,
      skipped,
      duplicatesMerged,
      total: next.length,
    };
  },

  exportJson(): string {
    return JSON.stringify(readDb(), null, 2);
  },

  importJson(text: string): number {
    const parsed = JSON.parse(text || "[]");

    if (!Array.isArray(parsed)) return 0;

    const saved = this.bulkUpsert(parsed);
    return saved.length;
  },

  exportCsv(): string {
    const header = [
      "id",
      "code",
      "title",
      "unit",
      "qty",
      "unitPrice",
      "minPrice",
      "maxPrice",
      "avgPrice",
      "variants",
      "group",
      "keywords",
      "source",
    ];

    const body = readDb().map((r) =>
      [
        r.id,
        r.code,
        r.title,
        r.unit,
        r.qty,
        r.unitPrice,
        r.minPrice,
        r.maxPrice,
        r.avgPrice,
        r.variants,
        r.group,
        r.keywords.join(", "),
        r.source,
      ]
        .map((v) => `"${String(v ?? "").replace(/"/g, '""')}"`)
        .join(";")
    );

    return [header.join(";"), ...body].join("\n");
  },
};

// apps/web/src/pages/kalkulation/recipesHandoff.ts

export const KI_HANDOFF_KEY = "rlc_kalkulation_ki_handoff_v1";

export type KiHandoffRow = {
  posNr: string;
  kurztext: string;
  langtext?: string;
  einheit: string;
  menge: number;
  preis: number;
  gesamt?: number;
  confidence?: number;
};

export type KiHandoffPayload = {
  source: "rezepte";
  ts: number;

  projectId?: string; // UUID DB
  projectCode?: string; // BA-... FS key
  projectKey?: string; // fallback compatibile

  recipeKey?: string;
  variantId?: string;

  mwst?: number;
  pricingDate?: string;

  rows: KiHandoffRow[];
};

function toNumber(value: unknown, fallback = 0): number {
  const n =
    typeof value === "number"
      ? value
      : Number(String(value ?? "").replace(",", ".").trim());

  return Number.isFinite(n) ? n : fallback;
}

function toText(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizeRow(row: Partial<KiHandoffRow>): KiHandoffRow | null {
  const posNr = toText(row.posNr);
  const kurztext = toText(row.kurztext);
  const einheit = toText(row.einheit);
  const menge = toNumber(row.menge);
  const preis = toNumber(row.preis);
  const gesamt =
    row.gesamt !== undefined ? toNumber(row.gesamt) : Number((menge * preis).toFixed(2));

  if (!posNr && !kurztext) return null;

  return {
    posNr,
    kurztext,
    langtext: toText(row.langtext),
    einheit,
    menge,
    preis,
    gesamt,
    confidence:
      row.confidence !== undefined ? Math.max(0, Math.min(1, toNumber(row.confidence))) : undefined,
  };
}

export function normalizeKiHandoffPayload(
  payload: Partial<KiHandoffPayload>
): KiHandoffPayload | null {
  const rows = Array.isArray(payload.rows)
    ? payload.rows.map(normalizeRow).filter(Boolean) as KiHandoffRow[]
    : [];

  if (!rows.length) return null;

  return {
    source: "rezepte",
    ts: toNumber(payload.ts, Date.now()),

    projectId: toText(payload.projectId) || undefined,
    projectCode: toText(payload.projectCode) || undefined,
    projectKey:
      toText(payload.projectKey) ||
      toText(payload.projectCode) ||
      toText(payload.projectId) ||
      undefined,

    recipeKey: toText(payload.recipeKey) || undefined,
    variantId: toText(payload.variantId) || undefined,

    mwst: payload.mwst !== undefined ? toNumber(payload.mwst, 19) : undefined,
    pricingDate: toText(payload.pricingDate) || undefined,

    rows,
  };
}

export function saveKiHandoff(payload: Partial<KiHandoffPayload>): boolean {
  const normalized = normalizeKiHandoffPayload(payload);
  if (!normalized) return false;

  localStorage.setItem(KI_HANDOFF_KEY, JSON.stringify(normalized));
  return true;
}

export function loadKiHandoff(): KiHandoffPayload | null {
  try {
    const raw = localStorage.getItem(KI_HANDOFF_KEY);
    if (!raw) return null;

    return normalizeKiHandoffPayload(JSON.parse(raw));
  } catch {
    return null;
  }
}

export function clearKiHandoff() {
  localStorage.removeItem(KI_HANDOFF_KEY);
}

