  return out;
}

function readAll(): LVPos[] {
  try {
    const key = lvStorageKey();
    if (!key) return [];

    const raw = localStorage.getItem(key);
    if (!raw) return [];

    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];

    return sortRows(dedupeById(parsed.map(parseStoredRow)));
  } catch {
