/* ================= API ================= */

function getAuthToken(): string {
  try {
    const keys = [
      "rlc_token",
      "token",
      "authToken",
      "accessToken",
      "rlc.auth.token",
      "rlc_mobile_token",
      "rlc_auth_token",
      "rlc_access_token",
    ];

    for (const key of keys) {
      const value = localStorage.getItem(key);
      if (value && value.trim()) return value.trim();
    }

    const jsonKeys = [
      "rlc_auth",
      "auth",
      "user",
      "session",
      "rlc_session",
      "rlc.auth",
      "rlc.session",
    ];

    for (const key of jsonKeys) {
      const raw = localStorage.getItem(key);
      if (!raw) continue;

      try {
        const parsed = JSON.parse(raw);
        const token =
          parsed?.token ??
          parsed?.accessToken ??
          parsed?.authToken ??
          parsed?.jwt ??
          parsed?.data?.token ??
          parsed?.data?.accessToken ??
          parsed?.user?.token ??
          parsed?.user?.accessToken;

        if (typeof token === "string" && token.trim()) return token.trim();
      } catch {
        //
      }
    }
  } catch {
    //
  }

  return "";
}

function authJsonHeaders(): HeadersInit {
  const token = getAuthToken();

  return {
    "Content-Type": "application/json",
    ...(token ? { Authorization: `Bearer ${token}` } : {}),
  };
}

async function postJson(path: string, body: unknown): Promise<any | null> {
  try {
    const url = apiUrl(path);

    const res = await fetch(url, {
      method: "POST",
      credentials: "include",
      headers: authJsonHeaders(),
      body: JSON.stringify(body),
    });

    const json = await res.json().catch(() => null);

    if (!res.ok || !json?.ok) {
      console.warn("[RLC Kalkulation KI] Server/OpenAI call failed:", {
        url,
        status: res.status,
        response: json,
      });

      return null;
    }

    return json;
  } catch (error) {
    console.warn("[RLC Kalkulation KI] Server/OpenAI not reachable:", error);
    return null;
  }
}

async function postKiSuggestBatchChunked(
  projectCode: string,
  inputRows: EliteKalkulationInputRow[],
  options: Record<string, any>
): Promise<any | null> {
  /*
   * Professionelle KI-Strategie:
   * - Normal schnell in Chunks rechnen.
   * - Bei 504/Timeout nicht alles abbrechen.
   * - Fehlenden Chunk automatisch kleiner erneut rechnen.
   * - Erst wenn auch Einzelposition scheitert: lokaler Fallback nur für diese Position.
   */
  const forceRecalculate = options?.forceRecalculate === true;

  const completedRows = forceRecalculate
    ? []
    : inputRows.filter((r) => {
        const hasBreakdown =
          Array.isArray(r.priceBreakdown) && r.priceBreakdown.length > 0;

        const hasPrice =
          n(r.finalUnitPrice) > 0 ||
          n(r.suggestedUnitPrice) > 0 ||
          n(r.preis) > 0;

        const hasBasicData =
          cleanText(r.kurztext).length > 0 &&
          cleanText(r.einheit).length > 0 &&
          n(r.menge) > 0;

        return hasBreakdown && hasPrice && hasBasicData;
      });

  const completedIds = new Set(completedRows.map((r) => String(r.id || "")));

  const rowsNeedingKi = forceRecalculate
    ? inputRows.filter((r) => !isStructuralInputRow(r, projectCode))
    : inputRows.filter(
        (r) =>

cleanText(r.einheit).length > 0 &&
          n(r.menge) > 0;

        return hasBreakdown && hasPrice && hasBasicData;
      });

  const completedIds = new Set(completedRows.map((r) => String(r.id || "")));

  const rowsNeedingKi = forceRecalculate
    ? inputRows.filter((r) => !isStructuralInputRow(r, projectCode))
    : inputRows.filter(
        (r) =>
          !completedIds.has(String(r.id || "")) &&
          !isStructuralInputRow(r, projectCode)
      );

  if (!rowsNeedingKi.length) {
    const rows = inputRows.map(localEliteCalculateRow);

    return {
      ok: true,
      source: "local-rule-engine",
      rows,
      summary: {
        ...buildSummary(rows),
        checkedCount: inputRows.length,
        skippedCount: completedRows.length,
        serverRequestedCount: 0,
        serverReturnedCount: 0,
        localFallbackCount: 0,
        forceRecalculate,
      },
      error:
        "Prüfung abgeschlossen: Alle sichtbaren LV-Positionen haben EP, Menge, Einheit und Urkalkulation.",
    };
  }

  const serverRows: any[] = [];
  let localFallbackCount = 0;
  let retrySingleCount = 0;

  /*
   * SPEED FIX:
   * Vorher: sehr kleine Chunks + sequenzielles await.
   * Jetzt: größere Chunks + kontrollierte Parallelität.
   *
   * Ziel:
   * - 17 Positionen nicht mehr 8 Minuten.
   * - 500 Positionen nicht mehrere Stunden.
   * - Server/OpenAI wird trotzdem nicht unkontrolliert überlastet.
   */
  const primaryChunkSize = forceRecalculate ? 4 : 12;
  const maxParallelChunks = 1;

  const chunks: EliteKalkulationInputRow[][] = [];

  for (let i = 0; i < rowsNeedingKi.length; i += primaryChunkSize) {
    chunks.push(rowsNeedingKi.slice(i, i + primaryChunkSize));
  }

  function authHeaders(): Record<string, string> {
    try {
      const direct =
        localStorage.getItem("token") ||
        localStorage.getItem("authToken") ||
        localStorage.getItem("accessToken") ||
        localStorage.getItem("rlc_token");

      if (direct) {
        return { Authorization: `Bearer ${direct}` };
      }

      const authRaw =
        localStorage.getItem("auth") ||
        localStorage.getItem("rlc_auth") ||
        localStorage.getItem("user");

      if (authRaw) {
        const parsed = JSON.parse(authRaw);
        const token =
          parsed?.token ||
          parsed?.accessToken ||
          parsed?.authToken ||
          parsed?.data?.token ||
          parsed?.data?.accessToken;

        if (token) {
          return { Authorization: `Bearer ${token}` };
        }
      }
    } catch {
      // keine Auth-Daten gefunden
    }

    return {};
  }
  async function requestChunk(
    chunk: EliteKalkulationInputRow[]
  ): Promise<any[] | null> {
    try {
      const res = await fetch(apiUrl("/api/kalkulation/ki/suggest-batch"), {
        method: "POST",
        credentials: "include",
        headers: {
          "Content-Type": "application/json",
          ...authHeaders(),
        },
        body: JSON.stringify({
          projectCode,
          projectKey: projectCode,
          sourceLvHeaderId:
            String(
              options?.sourceLvHeaderId ||
              options?.lvHeaderId ||
              ""
            ).trim() || undefined,
          rows: chunk,
          options: {
            ...options,
            maxParallelRows: options?.maxParallelRows ?? (forceRecalculate ? 4 : 6),
            maxOpenAiRowsPerBatch:
              options?.maxOpenAiRowsPerBatch ?? (forceRecalculate ? 20 : 8),
            forceRecalculate,
          },
        }),
      });

      if (!res.ok) {
        console.warn("[useKiSuggest] suggest-batch chunk failed", {
          status: res.status,
          chunkSize: chunk.length,
        });
        return null;
      }

      const json = await res.json().catch(() => null);

      const rows =
        json?.rows ||
        json?.suggestions ||
        json?.data?.rows ||
        json?.data?.suggestions ||
        [];

      if (!Array.isArray(rows)) return null;

      return rows;
    } catch (e) {
      console.warn("[useKiSuggest] suggest-batch chunk error", e);
      return null;
    }
  }
  async function processChunk(chunk: EliteKalkulationInputRow[]) {
    const chunkResult = await requestChunk(chunk);

    if (chunkResult) {
      serverRows.push(...chunkResult);
      return;
    }

    /*
     * Adaptive Retry:
     * Nur wenn ein ganzer Chunk scheitert, werden die Positionen einzeln erneut versucht.
     */
    for (const singleRow of chunk) {
      retrySingleCount += 1;

      const singleResult = await requestChunk([singleRow]);

      if (singleResult) {
        serverRows.push(...singleResult);
      } else {
        localFallbackCount += 1;
        serverRows.push(localEliteCalculateRow(singleRow));
      }
    }
  }

  let nextChunkIndex = 0;

  async function worker() {
    while (nextChunkIndex < chunks.length) {
      const currentIndex = nextChunkIndex;
      nextChunkIndex += 1;

      const chunk = chunks[currentIndex];
      if (chunk?.length) {
        await processChunk(chunk);
      }
    }
  }

  await Promise.all(
    Array.from(
      { length: Math.min(maxParallelChunks, chunks.length) },
      () => worker()
    )
  );

  const completedNormalized = completedRows.map(localEliteCalculateRow);

  const resultByKey = new Map<string, any>();

  for (const r of [...completedNormalized, ...serverRows]) {
    const idKey = String(r?.id || "").trim();
    const posKey = String(r?.posNr || "").trim();

() => worker()
    )
  );

  const completedNormalized = completedRows.map(localEliteCalculateRow);

  const resultByKey = new Map<string, any>();

  for (const r of [...completedNormalized, ...serverRows]) {
    const idKey = String(r?.id || "").trim();
    const posKey = String(r?.posNr || "").trim();

    if (idKey) resultByKey.set(`id:${idKey}`, r);
    if (posKey) resultByKey.set(`pos:${posKey}`, r);
  }

  const allRows = inputRows
    .filter((r) => !isStructuralInputRow(r, projectCode))
    .map((inputRow) => {
      const idKey = String(inputRow.id || "").trim();
      const posKey = String(inputRow.posNr || "").trim();

      return (
        (idKey ? resultByKey.get(`id:${idKey}`) : null) ||
        (posKey ? resultByKey.get(`pos:${posKey}`) : null) ||
        localEliteCalculateRow(inputRow)
      );
    });

  return {
    ok: true,
    source: "server",
    engine: forceRecalculate
      ? "adaptive-force-openai-recalculate"
      : "adaptive-database-openai-rule-engine",
    rows: allRows,
    summary: {
      ...buildSummary(allRows),
      checkedCount: inputRows.length,
      skippedCount: completedRows.length,
      serverRequestedCount: rowsNeedingKi.length,
      serverReturnedCount: Math.max(0, serverRows.length - localFallbackCount),
      localFallbackCount,
      retrySingleCount,
      forceRecalculate,
      primaryChunkSize,
    },
  };
}

/* ================= HELPERS ================= */

function n(value: unknown, fallback = 0): number {
  if (value === null || value === undefined || value === "") return fallback;

  const raw = String(value).trim();
  const normalized = raw.includes(",")
    ? raw.replace(/\./g, "").replace(",", ".")
    : raw.replace(/\s/g, "");

  const x = typeof value === "number" ? value : Number(normalized);
  return Number.isFinite(x) ? x : fallback;
}

function cleanText(value: unknown): string {
  return String(value ?? "").trim();
}
function isStructuralInputRow(row: EliteKalkulationInputRow, projectCode = ""): boolean {
  const pos = cleanText(row.posNr);
  const kurz = cleanText(row.kurztext);
  const lang = cleanText(row.langtext);
  const gewerk = cleanText(row.gewerk).toLowerCase();
  const leistungsart = cleanText(row.leistungsart).toLowerCase();
  const text = `${kurz} ${lang}`.toLowerCase();
  const unit = cleanText(row.einheit).toLowerCase();
  const pc = cleanText(projectCode).toLowerCase();

  if (pc && pos.toLowerCase() === pc) return true;
  if (/^ba-\d{4}/i.test(pos)) return true;
  if (/^ba-\d{4}/i.test(kurz)) return true;

  if (/^titel\s*\d*$/i.test(kurz)) return true;
  if (/^abschnitt\s*\d*$/i.test(kurz)) return true;
  if (/^kapitel\s*\d*$/i.test(kurz)) return true;

  if (gewerk.includes("gliederung")) return true;
  if (leistungsart.includes("struktur")) return true;
  if (text.includes("keine kalkulatorische leistungsposition")) return true;

  if ((unit === "ps" || unit === "pauschal") && /^(\d{2}|\d{2}\.\d{2})$/.test(pos)) {
    return true;
  }

  return false;
}


function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function safeId(): string {
  try {
    return crypto.randomUUID();
  } catch {
    return `pb-${Date.now()}-${Math.random().toString(16).slice(2)}`;
  }
}

function hasExistingCalculationData(row: EliteKalkulationInputRow): boolean {
  const breakdown =
    Array.isArray(row.priceBreakdown) && row.priceBreakdown.length > 0;

  const costs =
    n(row.materialCost) > 0 ||
    n(row.laborCost) > 0 ||
    n(row.machineCost) > 0 ||
    n(row.subcontractorCost) > 0 ||
    n(row.disposalCost) > 0 ||
    n(row.overheadCost) > 0 ||
    n(row.riskCost) > 0 ||
    n(row.profitCost) > 0;

  const prices =
    n(row.baseUnitPrice) > 0 ||
    n(row.suggestedUnitPrice) > 0 ||
    n(row.finalUnitPrice) > 0 ||
    n(row.preis) > 0;

  return breakdown || costs || prices;
}

function normalizePriceBreakdown(lines: unknown): PriceBreakdownLine[] {
  if (!Array.isArray(lines)) return [];

  return lines
    .map((x: any) => ({
      id: String(x?.id || safeId()),
      group: String(x?.group || "Material") as PriceBreakdownLine["group"],
      name: cleanText(x?.name || "Kostenansatz"),
      unit: cleanText(x?.unit || "EH"),
      qty: n(x?.qty, 1),
      price: n(x?.price),
      total:
        x?.total !== undefined && x?.total !== null
          ? round2(n(x.total))
          : round2(n(x?.qty, 1) * n(x?.price)),
      note: cleanText(x?.note || ""),
    }))
    .filter((x) => x.total > 0);
}

function sumBreakdown(lines?: PriceBreakdownLine[]): number {
  if (!Array.isArray(lines)) return 0;
  return round2(lines.reduce((s, x) => s + n(x.total), 0));
}

function buildPriceBreakdownFromCosts(row: {
  einheit?: string;
  materialCost?: number;
  laborCost?: number;
  machineCost?: number;
  subcontractorCost?: number;
  disposalCost?: number;
  overheadCost?: number;
  riskCost?: number;
  profitCost?: number;
}): PriceBreakdownLine[] {
  const unit = cleanText(row.einheit) || "EH";
  const lines: PriceBreakdownLine[] = [];

  function add(
    group: PriceBreakdownLine["group"],
    name: string,
    value: unknown,
    note = ""
  ) {
    const total = round2(n(value));
    if (total <= 0) return;

    lines.push({
      id: safeId(),
      group,
      name,
      unit,
      qty: 1,
      price: total,
      total,
      note,
    });
  }

  add("Material", "Materialansatz", row.materialCost);
  add("Personal", "Lohn / Kolonne", row.laborCost);

group,
      name,
      unit,
      qty: 1,
      price: total,
      total,
      note,
    });
  }

  add("Material", "Materialansatz", row.materialCost);
  add("Personal", "Lohn / Kolonne", row.laborCost);
  add("Maschinen", "Maschinenansatz", row.machineCost);
  add("Fremdleistung", "Fremdleistung", row.subcontractorCost);
  add("Entsorgung", "Entsorgung / Deponie", row.disposalCost);
  add("Gemeinkosten", "Baustellengemeinkosten", row.overheadCost);
  add("Risiko", "Risikopuffer", row.riskCost);
  add("Gewinn", "Gewinnanteil", row.profitCost);

  return lines;
}

/* ================= DETECTION ================= */

function detectGewerk(text: string): string {
  const t = text.toLowerCase();

  if (
    t.includes("aushub") ||
    t.includes("erde") ||
    t.includes("boden") ||
    t.includes("verfüll") ||
    t.includes("kies") ||
    t.includes("graben")
  ) {
    return "Tiefbau / Erdarbeiten";
  }

  if (
    t.includes("rohr") ||
    t.includes("leitung") ||
    t.includes("kanal") ||
    t.includes("dn") ||
    t.includes("speedpipe") ||
    t.includes("kabelschutz")
  ) {
    return "Tiefbau / Leitungsbau";
  }

  if (
    t.includes("beton") ||
    t.includes("schalung") ||
    t.includes("bewehrung") ||
    t.includes("fundament")
  ) {
    return "Rohbau / Betonbau";
  }

  if (t.includes("asphalt") || t.includes("pflaster") || t.includes("decke")) {
    return "Straßenbau / Oberfläche";
  }

  return "Allgemein";
}

function detectLeistungsart(text: string): string {
  const t = text.toLowerCase();

  if (t.includes("liefern") && t.includes("verlegen")) {
    return "Liefern und Einbauen";
  }

  if (t.includes("liefern")) return "Lieferleistung";
  if (t.includes("verlegen") || t.includes("einbauen")) return "Einbauleistung";
  if (t.includes("aushub") || t.includes("abtrag")) return "Erdbewegung";
  if (t.includes("abfuhr") || t.includes("entsorgung")) {
    return "Transport / Entsorgung";
  }
  if (t.includes("schalung")) return "Schalarbeiten";
  if (t.includes("bewehrung")) return "Bewehrungsarbeiten";
  if (t.includes("beton")) return "Betonarbeiten";

  return "Sonstige Leistung";
}

function detectBauverfahren(text: string, unit: string): string {
  const t = text.toLowerCase();

  if (t.includes("aushub")) return "Baggeraushub mit Laden / ggf. Abtransport";
  if (t.includes("abfuhr")) return "LKW-Transport inklusive Lade-/Kippvorgang";
  if (t.includes("verfüll")) return "Einbau lagenweise mit Verdichtung";
  if (t.includes("speedpipe")) return "Rohr-/Speedpipe-Verlegung im Leitungsgraben";
  if (t.includes("kabelschutz")) return "Kabelschutzrohr liefern und verlegen";
  if (t.includes("schalung")) return "Schalung stellen, vorhalten und entfernen";
  if (t.includes("bewehrung")) return "Bewehrung schneiden, biegen, verlegen";
  if (t.includes("beton")) return "Beton liefern, einbauen und verdichten";

  if (unit === "m") return "Längenbezogene Ausführung";
  if (unit === "m²") return "Flächenbezogene Ausführung";
  if (unit === "m³") return "Volumenbezogene Ausführung";

  return "Standard-Ausführung";
}

function riskFromText(text: string, unit: string, menge: number): RiskLevel {
  const t = text.toLowerCase();

  const risky =
    t.includes("nach bedarf") ||
    t.includes("bauseits") ||
    t.includes("unbekannt") ||
    t.includes("entsorgung") ||
    t.includes("bodenklasse") ||
    t.includes("kontaminiert") ||
    t.includes("bestand") ||
    t.includes("anschluss") ||
    t.includes("provisorisch");

  if (!text || !unit || menge <= 0) return "high";
  if (risky) return "high";
  if (text.length < 12) return "medium";
  if (menge > 1000) return "medium";

  return "low";
}

function confidenceFrom(row: EliteKalkulationInputRow, risk: RiskLevel): number {
  let score = 0.88;

  const text = cleanText(row.kurztext);
  const unit = cleanText(row.einheit);
  const menge = n(row.menge);

  if (!text) score -= 0.35;
  if (text.length < 12) score -= 0.12;
  if (!unit) score -= 0.2;
  if (menge <= 0) score -= 0.18;
  if (risk === "medium") score -= 0.1;
  if (risk === "high") score -= 0.22;

  return Math.max(0.25, Math.min(0.98, round2(score)));
}

function normUnit(value: string): string {
  const u = cleanText(value).toLowerCase();
  if (u === "m2" || u === "m^2" || u === "qm") return "m²";
  if (u === "m3" || u === "m^3" || u === "cbm") return "m³";
  if (u === "stk" || u === "stck" || u === "stück" || u === "stueck") return "St";
  return value;
}

function getPlausibleUnitRange(text: string, unitRaw: string): {
  min: number;
  avg: number;
  max: number;
  label: string;
} {
  const t = text.toLowerCase();
  const unit = normUnit(unitRaw);

  if (unit === "m²") {
    if (
      t.includes("unterlage reinigen") ||
      t.includes("untergrund reinigen") ||
      t.includes("fläche reinigen") ||
      t.includes("flaeche reinigen")
    ) {
      return { min: 0.15, avg: 0.45, max: 2.5, label: "Unterlage reinigen" };
    }

    if (
      t.includes("schichtenverbund") ||
      t.includes("haftkleber") ||
      t.includes("bitumenemulsion")
    ) {
      return { min: 0.35, avg: 0.85, max: 2.5, label: "Schichtenverbund" };
    }

    if (
      t.includes("einfräsen") ||
      t.includes("einfraesen") ||
      t.includes("abfräsen") ||
      t.includes("abfraesen") ||
      t.includes("fräsen") ||
      t.includes("fraesen")
    ) {
      return { min: 2, avg: 4.5, max: 9, label: "Asphalt fräsen" };
    }

    if (
      t.includes("ac 11 ds") ||

t.includes("einfräsen") ||
      t.includes("einfraesen") ||
      t.includes("abfräsen") ||
      t.includes("abfraesen") ||
      t.includes("fräsen") ||
      t.includes("fraesen")
    ) {
      return { min: 2, avg: 4.5, max: 9, label: "Asphalt fräsen" };
    }

    if (
      t.includes("ac 11 ds") ||
      t.includes("ads aus ac 11") ||
      t.includes("asphaltdeckschicht") ||
      t.includes("deckschicht")
    ) {
      return { min: 10, avg: 18, max: 32, label: "Asphaltdeckschicht" };
    }

    if (
      t.includes("zulage") &&
      (t.includes("mehr") || t.includes("minder")) &&
      (t.includes("stärke") || t.includes("staerke"))
    ) {
      return { min: 1, avg: 4.5, max: 12, label: "Asphalt Mehr-/Minderstärke" };
    }

    if (t.includes("planie")) {
      return { min: 2, avg: 5, max: 10, label: "Planie" };
    }

    if (t.includes("pflaster")) {
      return { min: 25, avg: 39, max: 75, label: "Pflaster" };
    }

    if (t.includes("asphalt")) {
      return { min: 8, avg: 18, max: 35, label: "Asphalt Oberfläche" };
    }
  }

  return { min: 0, avg: 0, max: 0, label: "" };
}

function clampToPlausibleRange(price: number, text: string, unitRaw: string): number {
  const range = getPlausibleUnitRange(text, unitRaw);
  const p = n(price);

  if (p <= 0) return 0;
  if (range.min <= 0 || range.max <= 0 || range.avg <= 0) return round2(p);

  if (p < range.min || p > range.max) return round2(range.avg);
  return round2(p);
}

function unitBasePrice(text: string, unit: string): number {
  const t = text.toLowerCase();
  const u = normUnit(unit);

  const range = getPlausibleUnitRange(t, u);
  if (range.avg > 0) return range.avg;

  if (t.includes("aushub") && u === "m³") return 18.5;
  if (t.includes("abfuhr") && (u === "t" || u === "m³")) return 22;
  if (t.includes("verfüll") && u === "m³") return 26;
  if (t.includes("kies") && u === "m³") return 38;
  if (t.includes("speedpipe") && u === "m") return 7.8;
  if (t.includes("kabelschutzrohr") && u === "m") return 18.5;
  if (t.includes("rohr") && u === "m") return 24;
  if (t.includes("schalung") && u === "m²") return 42;
  if (t.includes("bewehrung") && u === "kg") return 2.15;
  if (t.includes("beton") && u === "m³") return 165;

  if (u === "m") return 12;
  if (u === "m²") return 8;
  if (u === "m³") return 35;
  if (u === "kg") return 2;
  if (u === "t") return 30;
  if (u === "St") return 65;

  return 25;
}

