  async function eliteCalculateRows(
    projectCode: string,
    rows: EliteKalkulationInputRow[] | LVPos[],
    optionsOverride: Record<string, any> = {}
  ): Promise<EliteKalkulationResponse> {
    setLoading(true);

    try {
      const inputRows: EliteKalkulationInputRow[] = Array.isArray(rows)
        ? rows.map((r: any) => ({
            id: r.id,
            posNr: r.posNr,
            kurztext: r.kurztext,
            langtext: r.langtext,
            einheit: r.einheit,
