function getAuthHeaders(): Record<string, string> {
  const keys = [
  "rlc_token",
  "token",
  "authToken",
  "accessToken",
  "rlc.auth.token",
  "rlc_mobile_token",
  "rlc_auth_token",
  "rlc_access_token"];


  for (const key of keys) {
    const token = localStorage.getItem(key) || sessionStorage.getItem(key);
    if (token?.trim()) return { Authorization: `Bearer ${token.trim()}` };
  }

  try {
    const raw =
    localStorage.getItem("auth") ||
    localStorage.getItem("rlc_auth") ||
    localStorage.getItem("user");

    if (raw) {
      const parsed = JSON.parse(raw);
      const token =
      parsed?.token ||
      parsed?.accessToken ||
      parsed?.authToken ||
      parsed?.jwt ||
      parsed?.data?.token ||
      parsed?.data?.accessToken ||
      parsed?.user?.token ||
      parsed?.user?.accessToken;

      if (typeof token === "string" && token.trim()) {
        return { Authorization: `Bearer ${token.trim()}` };
      }
    }
  } catch {


    // ignore
  }return {};
}


async function loadCompanyLogoForPdf(): Promise<string | null> {
  try {
    const tokenKeys = [
    "rlc_token",
    "token",
    "authToken",
    "accessToken",
    "rlc_access_token"];


    let token = "";

    for (const key of tokenKeys) {
      const value =
      localStorage.getItem(key) ||
      sessionStorage.getItem(key);

      if (value?.trim()) {
        token = value.trim();
        break;
      }
    }

    const headers: Record<string, string> = {};
    if (token) {
      headers.Authorization = `Bearer ${token}`;
    }

    const response = await fetch(apiUrl("/api/company/logo"), {
      method: "GET",
      headers,
      credentials: "include",
      cache: "no-store"
    });

    if (!response.ok) {
      return null;
    }

    const blob = await response.blob();

    if (!blob.type.startsWith("image/")) {
      return null;
    }

    return await new Promise<string>((resolve, reject) => {
      const reader = new FileReader();

      reader.onload = () => {
        if (typeof reader.result === "string") {
          resolve(reader.result);
        } else {
          reject(new Error("Firmenlogo konnte nicht gelesen werden."));
        }
      };

      reader.onerror = () =>
      reject(reader.error || new Error("Firmenlogo konnte nicht gelesen werden."));

      reader.readAsDataURL(blob);
    });
  } catch (error) {
    console.warn("Firmenlogo für PDF konnte nicht geladen werden:", error);
    return null;
  }
}

async function api<T>(url: string, init?: RequestInit): Promise<T> {
  const headers = new Headers(init?.headers || {});
  if (!headers.has("Content-Type") && init?.body) {
    headers.set("Content-Type", "application/json");
  }

  Object.entries(getAuthHeaders()).forEach(([key, value]) => {
    headers.set(key, value);
  });

  const response = await fetch(apiUrl(url), {
    ...init,
    credentials: "include",
    headers
  });

  const text = await response.text();
  if (!response.ok) throw new Error(text || `HTTP ${response.status}`);

  if (!text.trim()) return {} as T;

  try {
    return JSON.parse(text) as T;
  } catch {
    throw new Error(`Ungültige Serverantwort von ${url}`);
  }
}

