          measurement.comment || ""];

        }),
        styles: { fontSize: 8.5, cellPadding: 1.8 },
        headStyles: {
          fillColor: [235, 239, 245],
          textColor: [15, 23, 42]
        },
        margin: { left: margin, right: margin }
      });

      y = (doc as any).lastAutoTable?.finalY + 7 || y + 25;
    }

    const commentRows: string[][] = [];

    areas.forEach((area) => {
      const areaComment = String(area.comment || "").trim();
