function safeJson<T>(raw: string | null, fallback: T): T {
  if (!raw) return fallback;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

function apiUrl(path: string): string {
  const base = String(API_BASE || "").replace(/\/+$/, "");
  const cleanPath = path.startsWith("/") ? path : `/${path}`;

  if (!base) return cleanPath;

  if (base.endsWith("/api") && cleanPath.startsWith("/api/")) {
    return `${base}${cleanPath.slice(4)}`;
  }

  return `${base}${cleanPath}`;
}

async function loadServerAufmassCount(code: string): Promise<number> {
  if (!code) return 0;

  const response = await fetch(
    apiUrl(`/api/aufmass/aufmass/${encodeURIComponent(code)}`),
    {
      method: "GET",
      credentials: "include"
    }
  );

  const payload = await response.json().catch(() => null);

  if (!response.ok) {
    throw new Error(
      payload?.error || `Aufmaß konnte nicht geladen werden: HTTP ${response.status}`
    );
  }

  const rows = Array.isArray(payload?.rows) ?
  payload.rows :
  Array.isArray(payload?.items) ?
  payload.items :
  Array.isArray(payload) ?
  payload :
  [];

  return rows.filter((row: any) => {
    const raw =
    row?.ist ??
    row?.istMenge ??
    row?.measuredQuantity ??
    row?.quantityActual ??
    0;

    const value =
    typeof raw === "string" ?
    Number(raw.replace(/\./g, "").replace(",", ".")) :
    Number(raw);

    return Number.isFinite(value) && Math.abs(value) > 0;
  }).length;
}

