async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(apiUrl(path), {
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      ...getHistorieAuthHeaders(),
      ...(init?.headers || {})
    },
    ...init
  });

  const raw = await response.text();
  const data = raw ? JSON.parse(raw) : {};

  if (!response.ok) {
    throw new Error(data?.error || data?.message || `HTTP ${response.status}`);
  }

  return data as T;
}

function normalizeRows(input: unknown): Row[] {
  const source = Array.isArray(input) ?
  input :
  Array.isArray((input as any)?.rows) ?
  (input as any).rows :
  Array.isArray((input as any)?.items) ?
  (input as any).items :
  [];

  return source.map((value: any, index: number) => {
    const pos = String(
      value?.pos ??
      value?.posNr ??
      value?.position ??
      value?.nr ??
      value?.Positionsnummer ??
      ""
    ).trim();

    const text = String(
      value?.text ??
      value?.kurztext ??
      value?.Kurztext ??
      value?.langtext ??
      value?.Text ??
      ""
    ).trim();

    const qty = Number(
      value?.qty ??
      value?.menge ??
      value?.quantity ??
      value?.ist ??
      value?.Ist ??
      value?.soll ??
      value?.Soll ??
      0
    );

    const ep = Number(
      value?.ep ??
      value?.unitPrice ??
      value?.unitPriceNet ??
      value?.rlcKiUnitPrice ??
      0
    );

    const factor = Number(value?.factor ?? 1);

    return {
      id:
      String(value?.id ?? value?.rowId ?? value?.uuid ?? "").trim() ||
      `${pos || "row"}-${index}`,
      pos,
      text,
      qty: Number.isFinite(qty) ? qty : 0,
      unit: String(
        value?.unit ?? value?.einheit ?? value?.Einheit ?? value?.uom ?? ""
      ).trim(),
      ep: Number.isFinite(ep) ? ep : 0,
      factor: Number.isFinite(factor) && factor !== 0 ? factor : 1
    };
  });
}

