import React, { useRef, useState } from "react";

function apiUrl(path: string): string {
  const p = path.startsWith("/") ? path : `/${path}`;
  return API_BASE ? `${API_BASE}${p}` : p;
}

type Props = {
  onImported?: () => void;
};

export default function ImportProjectJson({ onImported }: Props) {
  const fileRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);

  const handleChoose = () => {
    fileRef.current?.click();
  };

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (!f) return;

    const isJsonName = /\.json$/i.test(f.name);
    const isJsonType =
    f.type === "application/json" || f.type === "text/json";

    if (!isJsonName && !isJsonType) {
      window.alert("Bitte eine gültige project.json auswählen.");
      e.target.value = "";
      return;
    }

    setBusy(true);

    try {
      const fd = new FormData();
      fd.append("file", f);

      const res = await fetch(apiUrl("/api/import/project-json"), {
        method: "POST",
        body: fd,
        credentials: "include"
      });

      const json = await res.json().catch(() => null);

      if (!res.ok || !json || json?.ok === false) {
        throw new Error(json?.error || `Import fehlgeschlagen (${res.status})`);
      }

      onImported?.();

      window.alert(
        `Import erfolgreich: ${
        json?.imported?.name || json?.project?.name || f.name}`

      );
    } catch (err: any) {
      console.error("Import error:", err);
      window.alert(`Fehler beim Import: ${err?.message || String(err)}`);
    } finally {
      setBusy(false);
      if (fileRef.current) {
        fileRef.current.value = "";
      }
    }
  };

  return (
    <div className="rlc-migrated-pages-start-importprojectjson-tsx-1560">
      <input
        ref={fileRef}
        type="file"
        accept=".json,application/json"

        onChange={handleFile} className="rlc-migrated-pages-start-importprojectjson-tsx-1561" />


      <button type="button" onClick={handleChoose} disabled={busy}>
        {busy ? "Importiere..." : "Import project.json"}
      </button>

      <small>
        Unterstützt: Datei <code>project.json</code>
      </small>
    </div>);

}

import { API_BASE } from "../../lib/apiBase";
import React, { useRef, useState } from "react";

type Props = {
  onImported?: () => void;
};

function apiUrl(path: string): string {
  const p = path.startsWith("/") ? path : `/${path}`;
  return API_BASE ? `${API_BASE}${p}` : p;
}

export default function ProjectImport({ onImported }: Props) {
  const inputRef = useRef<HTMLInputElement>(null);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);

  const openPicker = () => inputRef.current?.click();

  const onPick: React.ChangeEventHandler<HTMLInputElement> = async (e) => {
    const f = e.target.files?.[0];
    if (!f) return;

    setMsg(null);
    setBusy(true);

    try {
      const fd = new FormData();
      fd.append("file", f);

      const isJson = /\.json$/i.test(f.name);
      const isZip = /\.zip$/i.test(f.name);

      if (!isJson && !isZip) {
        throw new Error("Bitte eine .json oder .zip Datei auswählen.");
      }

      const endpoint = isJson ?
      apiUrl("/api/import/project-json") :
      apiUrl("/api/import/project-zip");

      const r = await fetch(endpoint, {
        method: "POST",
        body: fd,
        credentials: "include"
      });

      const j = await r.json().catch(() => null);

      if (!r.ok || !j || j.ok === false) {
        throw new Error(j?.error || "Import fehlgeschlagen");
      }

      setMsg(`✅ Import OK: ${j.project?.name || j.created || j.from || f.name}`);
      onImported?.();
    } catch (err: any) {
      console.error("Import error:", err);
      setMsg(`❌ ${err?.message || String(err)}`);
    } finally {
      setBusy(false);
      if (inputRef.current) inputRef.current.value = "";
    }
  };

  return (
    <div className="rlc-migrated-pages-start-projectimport-tsx-1562">
      <button
        type="button"
        onClick={openPicker}
        disabled={busy} className="rlc-migrated-pages-start-projectimport-tsx-1563">


        {busy ? "Importiere..." : "Import"}
      </button>

      <input
        ref={inputRef}
        type="file"
        accept=".json,.zip,application/json,application/zip"
        onChange={onPick} className="rlc-migrated-pages-start-projectimport-tsx-1564" />



      {busy && <span>⏳ Import läuft...</span>}
      {msg && <span>{msg}</span>}
    </div>);

}

