import type React from "react";

const UNITLESS = new Set([
  "animationIterationCount",
  "aspectRatio",
  "borderImageOutset",
  "borderImageSlice",
  "borderImageWidth",
  "columnCount",
  "columns",
  "flex",
  "flexGrow",
  "flexShrink",
  "fontWeight",
  "gridArea",
  "gridColumn",
  "gridColumnEnd",
  "gridColumnStart",
  "gridRow",
  "gridRowEnd",
  "gridRowStart",
  "lineClamp",
  "lineHeight",
  "opacity",
  "order",
  "orphans",
  "scale",
  "tabSize",
  "widows",
  "zIndex",
  "zoom",
  "fillOpacity",
  "strokeOpacity",
  "strokeWidth",
]);

export type RlcDynamicCssEntry = readonly [
  variableName: string,
  cssProperty: string,
  value: unknown
];

export type RlcStyleOperation =
  | readonly ["spread", React.CSSProperties | null | undefined | false]
  | readonly ["value", keyof React.CSSProperties | string, unknown];

const THEME_COLOR_ALIASES: Record<string, string> = {
  "#ffffff": "var(--rlc-surface)",
  "#fff": "var(--rlc-surface)",
  white: "var(--rlc-surface)",
  "#f7f9fc": "var(--rlc-bg)",
  "#f5f8ff": "var(--rlc-primary-faint)",
  "#eaf2ff": "var(--rlc-primary-soft)",
  "#dde5f0": "var(--rlc-border)",
  "#bed6ff": "var(--rlc-border-strong)",
  "#146ef5": "var(--rlc-primary)",
  "#0b5bd3": "var(--rlc-primary-hover)",
  "#172033": "var(--rlc-text)",
  "#6d7890": "var(--rlc-muted)",
};

const COLOR_PROPERTIES = new Set([
  "color",
  "background",
  "backgroundColor",
  "borderColor",
  "borderTopColor",
  "borderRightColor",
  "borderBottomColor",
  "borderLeftColor",
  "outlineColor",
  "textDecorationColor",
]);

function normalizeValue(property: string, value: unknown) {
  if (value === null || value === undefined || value === false) return undefined;
  if (typeof value === "number" && value !== 0 && !UNITLESS.has(property)) {
    return `${value}px`;
  }
  return String(value);
}

/**
 * Unico ponte ammesso tra valori React calcolati e il CSS RLC.
 * Le proprietà vere vivono in rlc-inline-theme.css; qui vengono valorizzate
 * soltanto le variabili necessarie a misure, coordinate e stati runtime.
 */
export function rlcDynamicStyle(
  entries: readonly RlcDynamicCssEntry[]
): React.CSSProperties {
  const variables: Record<string, string | undefined> = {};

  for (const [variableName, property, value] of entries) {
    variables[variableName] = normalizeValue(property, value);
  }

  return variables as React.CSSProperties;
}

function normalizeThemeValue(property: string, value: unknown) {
  if (!COLOR_PROPERTIES.has(property) || typeof value !== "string") return value;
  return THEME_COLOR_ALIASES[value.trim().toLowerCase()] || value;
}

/**
 * Tutti gli style prop Web passano da questa funzione. Mantiene l'ordine
 * degli spread React, ma applica i token centrali ai colori RLC conosciuti.
 */
export function rlcStyleOps(
  operations: readonly RlcStyleOperation[]
): React.CSSProperties {
  const result: Record<string, unknown> = {};

  for (const operation of operations) {
    if (operation[0] === "spread") {
      const source = operation[1];
      if (source && typeof source === "object") Object.assign(result, source);
      continue;
    }
    const property = String(operation[1]);
    result[property] = normalizeThemeValue(property, operation[2]);
  }

  for (const property of Object.keys(result)) {
    result[property] = normalizeThemeValue(property, result[property]);
  }

  return result as React.CSSProperties;
}

import type { CSSProperties } from "react";

const cache = new Map<string, string>();
let sheet: CSSStyleSheet | null = null;

function ensureSheet(): CSSStyleSheet | null {
  if (typeof document === "undefined") return null;
  if (sheet) return sheet;
  const node = document.createElement("style");
  node.dataset.rlcRuntimeTheme = "true";
  document.head.appendChild(node);
  sheet = node.sheet;
  return sheet;
}

function kebab(value: string): string {
  if (value.startsWith("--")) return value;
  return value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
}

function serialize(style: CSSProperties): string {
  return Object.entries(style)
    .filter(([, value]) => value !== null && value !== undefined && value !== false)
    .map(([property, value]) => {
      const unitless = /^(animationIterationCount|columnCount|fillOpacity|flex|flexGrow|flexShrink|fontWeight|lineHeight|opacity|order|orphans|scale|strokeOpacity|widows|zIndex|zoom)$/;
      const rendered =
        typeof value === "number" && value !== 0 && !unitless.test(property)
          ? `${value}px`
          : String(value);
      return `${kebab(property)}:${rendered}`;
    })
    .join(";");
}

function semanticClass(style: CSSProperties): string {
  const background = String(style.background || style.backgroundImage || "");
  return background.includes("gradient") ? "rlc-gradient-surface" : "";
}

export function rlcClass(
  current: string | null | undefined | false,
  style: CSSProperties | null | undefined | false
): string {
  if (!style) return current || "";
  const declaration = serialize(style);
  if (!declaration) return current || "";
  let generated = cache.get(declaration);
  if (!generated) {
    generated = `rlc-runtime-${cache.size + 1}`;
    cache.set(declaration, generated);
    ensureSheet()?.insertRule(`.${generated}{${declaration}}`);
  }
  return [current || "", semanticClass(style), generated].filter(Boolean).join(" ");
}

// apps/web/src/utils/cadImport.ts
// Bridge CAD → (Aufmaß/Kalkulation) via localStorage (queue-based)

export type CadExportPayload = {
  target: "aufmasseditor" | "kalkulation";
  kind: "AREA" | "LINE";
  layer: string;
  label?: string;
  area_m2?: number;
  length_m?: number;
  points?: { x: number; y: number }[];
  ts?: number;
};

const KEY = "rlc.cad.export.queue.v1";
const TTL = 2 * 60 * 1000; // 2 minuti

function safeParse(raw: string | null): CadExportPayload[] {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function validatePayload(p: CadExportPayload): boolean {
  if (!p.target || !p.kind || !p.layer) return false;

  if (p.kind === "AREA" && typeof p.area_m2 !== "number") return false;
  if (p.kind === "LINE" && typeof p.length_m !== "number") return false;

  return true;
}

/* =========================
   SAVE (queue)
   ========================= */

export function saveCadExport(payload: CadExportPayload) {
  const pack: CadExportPayload = {
    ...payload,
    ts: Date.now(),
  };

  if (!validatePayload(pack)) {
    console.warn("[CAD] invalid payload", pack);
    return;
  }

  try {
    const current = safeParse(localStorage.getItem(KEY));
    const next = [...current, pack];
    localStorage.setItem(KEY, JSON.stringify(next));
  } catch (e) {
    console.error("[CAD] save error", e);
  }
}

/* =========================
   CONSUME (per target)
   ========================= */

export function consumeCadExport(
  expectedTarget: "aufmasseditor" | "kalkulation"
): CadExportPayload[] {
  try {
    const current = safeParse(localStorage.getItem(KEY));

    if (!current.length) return [];

    const now = Date.now();

    const valid = current.filter(
      (p) =>
        p.target === expectedTarget &&
        typeof p.ts === "number" &&
        now - p.ts < TTL
    );

    const remaining = current.filter(
      (p) =>
        !p.ts ||
        now - p.ts >= TTL ||
        p.target !== expectedTarget
    );

    localStorage.setItem(KEY, JSON.stringify(remaining));

    return valid;
  } catch (e) {
    console.error("[CAD] consume error", e);
    return [];
  }
}

/* =========================
   CLEAR (manual debug)
   ========================= */

export function clearCadExport() {
  try {
    localStorage.removeItem(KEY);
  } catch {}
}

// ============================================================
// CAD → LV MAPPING ENGINE
// ============================================================

export type CadItem = {
  kind: "AREA" | "LINE" | "POINT" | "VOLUME";
  layer?: string;
  label?: string; // es. "Asphaltdeckschicht Pos1.00.14"
  area_m2?: number;
  length_m?: number;
  volume_m3?: number;
  count?: number;
};

export type LVUnit = "m" | "m2" | "m3" | "stk";

export type LVTarget = {
  pos: string;
  kurztext: string;
  einheit: LVUnit;
  ep?: number;
};

type CadRule = {
  match: {
    layer?: RegExp;
    text?: RegExp;
    kind?: CadItem["kind"];
  };
  target: LVTarget;
};

// ============================================================
// REGOLE BASE
// ============================================================

const RULES: CadRule[] = [
  {
    match: { layer: /asphalt/i, text: /asphaltdeckschicht/i, kind: "AREA" },
    target: {
      pos: "001.002",
      kurztext: "Asphaltdeckschicht wiederherstellen",
      einheit: "m2",
      ep: 39.9,
    },
  },
  {
    match: { layer: /(speedpipe|leitung|trasse|rohr)/i, kind: "LINE" },
    target: {
      pos: "001.001",
      kurztext: "Speedpipe Verlegung 1,20 m Tiefe",
      einheit: "m",
      ep: 24.5,
    },
  },
  {
    match: { layer: /(kabel|strom)/i, kind: "LINE" },
    target: {
      pos: "002.010",
      kurztext: "Stromkabel im Schutzrohr verlegen",
      einheit: "m",
      ep: 18.9,
    },
  },
  {
    match: { layer: /(pflaster|stein)/i, kind: "AREA" },
    target: {
      pos: "003.005",
      kurztext: "Pflasterfläche herstellen",
      einheit: "m2",
      ep: 42.5,
    },
  },
];

// ============================================================
// HELPERS
// ============================================================

function norm(v?: string): string {
  return (v || "").trim().toLowerCase();
}

function safeNumber(v: unknown): number {
  return typeof v === "number" && Number.isFinite(v) ? v : 0;
}

function unitTextFromEinheit(e: LVUnit): string {
  switch (e) {
    case "m2":
      return "m²";
    case "m3":
      return "m³";
    case "stk":
      return "Stk";
    default:
      return "m";
  }
}

function calcMenge(item: CadItem, einheit: LVUnit): number {
  switch (einheit) {
    case "m2":
      return safeNumber(item.area_m2);
    case "m3":
      return safeNumber(item.volume_m3);
    case "stk":
      return safeNumber(item.count) || 1;
    case "m":
    default:
      return safeNumber(item.length_m);
  }
}

function ruleScore(rule: CadRule, item: CadItem): number {
  let score = 0;

  if (rule.match.kind) {
    if (rule.match.kind !== item.kind) return -1;
    score += 3;
  }

  if (rule.match.layer) {
    if (!rule.match.layer.test(item.layer || "")) return -1;
    score += 2;
  }

  if (rule.match.text) {
    if (!rule.match.text.test(item.label || "")) return -1;
    score += 2;
  }

  return score;
}

// ============================================================
// Utility: "Pos1.00.14" -> "1.00.14"
// ============================================================

export function extractPosFromText(t?: string): string | null {
  if (!t) return null;
  const m = t.match(/pos\.?\s*([\d.]+)/i);
  return m?.[1] ?? null;
}

// ============================================================
// Euristica fallback
// ============================================================

function heuristic(item: CadItem): LVTarget | null {
  const text = `${norm(item.layer)} ${norm(item.label)}`;

  if (/(asphalt|deck|pflaster|fläche)/.test(text) && item.kind === "AREA") {
    return {
      pos: "001.002",
      kurztext: "Asphalt / Fläche",
      einheit: "m2",
    };
  }

  if (/(leitung|trasse|kanal|rohr|kabel|speedpipe)/.test(text) && item.kind === "LINE") {
    return {
      pos: "001.001",
      kurztext: "Leitungstrasse",
      einheit: "m",
    };
  }

  if (/(schacht|punkt|anschluss)/.test(text) && item.kind === "POINT") {
    return {
      pos: "009.001",
      kurztext: "Punkt / Anschluss",
      einheit: "stk",
    };
  }

  if (/(aushub|graben|boden)/.test(text) && item.kind === "VOLUME") {
    return {
      pos: "004.001",
      kurztext: "Aushub / Bodenbewegung",
      einheit: "m3",
    };
  }

  return null;
}

// ============================================================
// Resolver principale
// ============================================================

export function resolveCadToLV(
  item: CadItem
): (LVTarget & { menge: number; unitText: string }) | null {
  const bestRule = RULES
    .map((rule) => ({ rule, score: ruleScore(rule, item) }))
    .filter((x) => x.score >= 0)
    .sort((a, b) => b.score - a.score)[0]?.rule;

  let base: LVTarget | null = bestRule ? bestRule.target : heuristic(item);
  if (!base) return null;

  const posFromLabel = extractPosFromText(item.label);
  if (posFromLabel) {
    base = { ...base, pos: posFromLabel };
  }

  const menge = calcMenge(item, base.einheit);
  const unitText = unitTextFromEinheit(base.einheit);

  return {
    ...base,
    menge,
    unitText,
  };
}

// apps/web/src/utils/excel.ts
import * as XLSX from "xlsx";

export interface ExportColumn<T extends Record<string, unknown>> {
  key: keyof T;
  header: string;
}

function normalizeCell(value: unknown): string | number | boolean {
  if (value == null) return "";
  if (value instanceof Date) return value.toISOString();
  if (typeof value === "number") return Number.isFinite(value) ? value : "";
  if (typeof value === "boolean") return value;
  return String(value);
}

function buildColumnWidths<T extends Record<string, unknown>>(
  columns: ExportColumn<T>[],
  rows: T[]
): { wch: number }[] {
  return columns.map((col) => {
    const headerLen = String(col.header).length;
    const maxRowLen = rows.reduce((max, row) => {
      const value = normalizeCell(row[col.key]);
      return Math.max(max, String(value).length);
    }, 0);

    return { wch: Math.min(Math.max(headerLen, maxRowLen, 10), 40) };
  });
}

export function exportToXlsx<T extends Record<string, unknown>>(
  fileName: string,
  columns: ExportColumn<T>[],
  rows: T[],
  sheetName = "Aufmass"
) {
  const data: Array<Array<string | number | boolean>> = [
    columns.map((c) => c.header),
    ...rows.map((row) => columns.map((c) => normalizeCell(row[c.key]))),
  ];

  const wb = XLSX.utils.book_new();
  const ws = XLSX.utils.aoa_to_sheet(data);
  ws["!cols"] = buildColumnWidths(columns, rows);

  XLSX.utils.book_append_sheet(wb, ws, sheetName);

  const safeFileName = fileName.endsWith(".xlsx") ? fileName : `${fileName}.xlsx`;
  XLSX.writeFile(wb, safeFileName);
}

// apps/web/src/utils/formulas.ts
// Parser / valutatore leggero per espressioni di Aufmaß (tedesco-friendly)

export type EvalContext = Record<string, number>;

type Token =
  | { t: "num"; v: number }
  | { t: "id"; v: string }
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "rp" }
  | { t: "comma" }
  | { t: "fn"; name: string; argc: number };

const PRECEDENCE: Record<string, number> = {
  "+": 1,
  "-": 1,
  "*": 2,
  "/": 2,
  "^": 4,
  "u+": 5,
  "u-": 5,
};

const RIGHT_ASSOC = new Set(["^", "u+", "u-"]);

function normalizeNumericLiteral(raw: string): string {
  const s = raw.trim();

  const hasComma = s.includes(",");
  const hasDot = s.includes(".");

  if (hasComma && hasDot) {
    // es. 1.234,56 -> 1234.56
    if (s.lastIndexOf(",") > s.lastIndexOf(".")) {
      return s.replace(/\./g, "").replace(",", ".");
    }
    // es. 1,234.56 -> 1234.56
    return s.replace(/,/g, "");
  }

  if (hasComma) {
    return s.replace(",", ".");
  }

  return s;
}

function isDigit(c: string): boolean {
  return c >= "0" && c <= "9";
}

function isIdStart(c: string): boolean {
  return /[A-Za-z_]/.test(c);
}

function isIdChar(c: string): boolean {
  return /[A-Za-z0-9_]/.test(c);
}

function tokenize(expr: string): Token[] {
  const s = expr.trim().replace(/^\s*=/, "");
  const tokens: Token[] = [];
  let i = 0;

  while (i < s.length) {
    const ch = s[i];

    if (/\s/.test(ch)) {
      i++;
      continue;
    }

    if ("+-*/^".includes(ch)) {
      tokens.push({ t: "op", v: ch });
      i++;
      continue;
    }

    if (ch === "(") {
      tokens.push({ t: "lp" });
      i++;
      continue;
    }

    if (ch === ")") {
      tokens.push({ t: "rp" });
      i++;
      continue;
    }

    if (ch === ",") {
      tokens.push({ t: "comma" });
      i++;
      continue;
    }

    if (isDigit(ch) || ch === "." || ch === ",") {
      let j = i + 1;
      while (j < s.length && /[0-9.,]/.test(s[j])) j++;

      const raw = s.slice(i, j);
      const normalized = normalizeNumericLiteral(raw);
      const num = Number(normalized);

      if (!Number.isFinite(num)) {
        throw new Error(`Ungültige Zahl: ${raw}`);
      }

      tokens.push({ t: "num", v: num });
      i = j;
      continue;
    }

    if (isIdStart(ch)) {
      let j = i + 1;
      while (j < s.length && isIdChar(s[j])) j++;

      tokens.push({ t: "id", v: s.slice(i, j).toUpperCase() });
      i = j;
      continue;
    }

    throw new Error(`Ungültiges Zeichen: '${ch}'`);
  }

  return tokens;
}

type StackItem =
  | { t: "op"; v: string }
  | { t: "lp" }
  | { t: "fnName"; name: string };

type FnFrame = {
  hasValue: boolean;
  commaCount: number;
};

function toRpn(tokens: Token[]): Token[] {
  const out: Token[] = [];
  const ops: StackItem[] = [];
  const fnFrames: FnFrame[] = [];

  let prev: Token | undefined;

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];

    if (token.t === "num") {
      out.push(token);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = token;
      continue;
    }

    if (token.t === "id") {
      const next = tokens[i + 1];

      if (next?.t === "lp") {
        ops.push({ t: "fnName", name: token.v });
        prev = token;
        continue;
      }

      out.push(token);
      if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      prev = token;
      continue;
    }

    if (token.t === "lp") {
      const prevWasFn = ops.length > 0 && ops[ops.length - 1].t === "fnName";
      ops.push({ t: "lp" });

      if (prevWasFn) {
        fnFrames.push({
          hasValue: false,
          commaCount: 0,
        });
      }

      prev = token;
      continue;
    }

    if (token.t === "comma") {
      while (ops.length && ops[ops.length - 1].t !== "lp") {
        const top = ops.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!ops.length) throw new Error("Separator ',' an falscher Stelle");
      if (!fnFrames.length) throw new Error("Separator ',' außerhalb Funktion");

      fnFrames[fnFrames.length - 1].commaCount++;
      prev = token;
      continue;
    }

    if (token.t === "op") {
      let op = token.v;

      const unary =
        !prev || prev.t === "op" || prev.t === "lp" || prev.t === "comma";

      if (unary && (op === "+" || op === "-")) {
        op = op === "+" ? "u+" : "u-";
      }

      while (ops.length) {
        const top = ops[ops.length - 1];
        if (top.t !== "op") break;

        const pTop = PRECEDENCE[top.v];
        const pCur = PRECEDENCE[op];
        const shouldPop = RIGHT_ASSOC.has(op) ? pTop > pCur : pTop >= pCur;

        if (!shouldPop) break;
        out.push(ops.pop() as { t: "op"; v: string });
      }

      ops.push({ t: "op", v: op });
      prev = { t: "op", v: op };
      continue;
    }

    if (token.t === "rp") {
      while (ops.length && ops[ops.length - 1].t !== "lp") {
        const top = ops.pop()!;
        if (top.t === "op") out.push(top);
      }

      if (!ops.length) throw new Error("Klammerfehler");
      ops.pop(); // remove lp

      if (ops.length && ops[ops.length - 1].t === "fnName") {
        const fn = ops.pop() as { t: "fnName"; name: string };
        const frame = fnFrames.pop();

        if (!frame) throw new Error("Funktionsfehler");

        const argc = frame.hasValue ? frame.commaCount + 1 : 0;
        out.push({ t: "fn", name: fn.name, argc });

if (!ops.length) throw new Error("Klammerfehler");
      ops.pop(); // remove lp

      if (ops.length && ops[ops.length - 1].t === "fnName") {
        const fn = ops.pop() as { t: "fnName"; name: string };
        const frame = fnFrames.pop();

        if (!frame) throw new Error("Funktionsfehler");

        const argc = frame.hasValue ? frame.commaCount + 1 : 0;
        out.push({ t: "fn", name: fn.name, argc });

        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      } else {
        if (fnFrames.length) fnFrames[fnFrames.length - 1].hasValue = true;
      }

      prev = token;
      continue;
    }
  }

  while (ops.length) {
    const op = ops.pop()!;
    if (op.t === "lp" || op.t === "fnName") {
      throw new Error("Klammerfehler");
    }
    out.push(op);
  }

  return out;
}

function applyFunction(name: string, args: number[]): number {
  switch (name) {
    case "SUM":
      return args.reduce((a, b) => a + b, 0);

    case "MIN":
      return args.length ? Math.min(...args) : 0;

    case "MAX":
      return args.length ? Math.max(...args) : 0;

    case "AVG":
      return args.length ? args.reduce((a, b) => a + b, 0) / args.length : 0;

    case "ROUND": {
      const x = args[0] ?? 0;
      const n = Math.trunc(args[1] ?? 0);
      const factor = Math.pow(10, n);
      return Math.round(x * factor) / factor;
    }

    case "CEIL":
      return Math.ceil(args[0] ?? 0);

    case "FLOOR":
      return Math.floor(args[0] ?? 0);

    case "ABS":
      return Math.abs(args[0] ?? 0);

    default:
      throw new Error(`Unbekannte Funktion: ${name}`);
  }
}

function evalRpn(rpn: Token[], ctx: EvalContext): number {
  const stack: number[] = [];

  const readValue = (name: string): number => {
    const value = ctx[name];
    if (typeof value === "number" && Number.isFinite(value)) return value;
    throw new Error(`Variable unbekannt: ${name}`);
  };

  for (const token of rpn) {
    if (token.t === "num") {
      stack.push(token.v);
      continue;
    }

    if (token.t === "id") {
      stack.push(readValue(token.v));
      continue;
    }

    if (token.t === "fn") {
      const args = token.argc > 0 ? stack.splice(-token.argc, token.argc) : [];
      stack.push(applyFunction(token.name, args));
      continue;
    }

    if (token.t === "op") {
      if (token.v === "u+") {
        const a = stack.pop();
        if (a == null) throw new Error("Fehlender Operand");
        stack.push(+a);
        continue;
      }

      if (token.v === "u-") {
        const a = stack.pop();
        if (a == null) throw new Error("Fehlender Operand");
        stack.push(-a);
        continue;
      }

      const b = stack.pop();
      const a = stack.pop();

      if (a == null || b == null) {
        throw new Error("Fehlende Operanden");
      }

      switch (token.v) {
        case "+":
          stack.push(a + b);
          break;
        case "-":
          stack.push(a - b);
          break;
        case "*":
          stack.push(a * b);
          break;
        case "/":
          stack.push(b === 0 ? NaN : a / b);
          break;
        case "^":
          stack.push(Math.pow(a, b));
          break;
        default:
          throw new Error(`Unbekannter Operator: ${token.v}`);
      }
    }
  }

  if (stack.length !== 1) {
    throw new Error("Ausdruck nicht auswertbar");
  }

  return stack[0];
}

export function evaluate(expr: string, ctx: EvalContext = {}): number {
  if (!expr || !expr.trim()) return 0;

  const normalizedCtx: EvalContext = Object.fromEntries(
    Object.entries(ctx).map(([k, v]) => [k.toUpperCase(), Number(v)])
  );

  const rpn = toRpn(tokenize(expr));
  const result = evalRpn(rpn, normalizedCtx);

  return Number.isFinite(result) ? result : NaN;
}

import { savePdfWithCompanyHeader as saveRlcPdfWithCompanyHeader, outputPdfBlobWithCompanyHeader as outputRlcPdfBlobWithCompanyHeader } from "../../lib/pdf/companyPdfHeader";
// apps/web/src/utils/pdf/printPdf.ts
import { jsPDF } from "jspdf";

export async function printJsPdf(
  doc: jsPDF,
  fileName = "document.pdf"
): Promise<void> {
  const blob = await outputRlcPdfBlobWithCompanyHeader(doc);
  const url = URL.createObjectURL(blob);

  let timer: number | null = null;
  let revoked = false;

  const revokeLater = (delay = 10000) => {
    window.setTimeout(() => {
      if (!revoked) {
        URL.revokeObjectURL(url);
        revoked = true;
      }
    }, delay);
  };

  try {
    const win = window.open(url, "_blank");

    if (!win) {
      saveRlcPdfWithCompanyHeader(doc, fileName);
      revokeLater(2000);
      return;
    }

    timer = window.setInterval(() => {
      try {
        if (win.closed) {
          if (timer) window.clearInterval(timer);
          revokeLater(1000);
          return;
        }

        if (win.document?.readyState === "complete") {
          if (timer) window.clearInterval(timer);
          win.focus();
          win.print();
          revokeLater(10000);
        }
      } catch {
        // cross-window access può fallire su alcuni browser/viewer PDF
      }
    }, 250);

    // safety timeout
    window.setTimeout(() => {
      if (timer) {
        window.clearInterval(timer);
        timer = null;
      }
      revokeLater(15000);
    }, 20000);
  } catch {
    saveRlcPdfWithCompanyHeader(doc, fileName);
    revokeLater(2000);
  }
}

// apps/web/src/utils/project.ts

const KEY = "rlc.currentProjectId";

export function getCurrentProjectId(): number | null {
  try {
    const q = new URLSearchParams(window.location.search).get("projectId");

    if (q && !isNaN(Number(q))) {
      const id = Number(q);
      localStorage.setItem(KEY, String(id)); // sync
      return id;
    }

    const ls = localStorage.getItem(KEY);
    if (!ls) return null;

    const id = Number(ls);
    return Number.isFinite(id) ? id : null;
  } catch {
    return null;
  }
}

export function setCurrentProjectId(id: number | null) {
  try {
    if (id == null) {
      localStorage.removeItem(KEY);
      return;
    }

    localStorage.setItem(KEY, String(id));
  } catch {}
}

export function withProject(path: string): string {
  const id = getCurrentProjectId();
  if (!id) return path;

  try {
    const url = new URL(path, window.location.origin);
    url.searchParams.set("projectId", String(id));
    return url.pathname + url.search;
  } catch {
    // fallback per path relativi senza base valida
    const sep = path.includes("?") ? "&" : "?";
    return `${path}${sep}projectId=${id}`;
  }
}

/**
 * Utility: aggiorna URL corrente senza reload
 */
export function syncProjectToUrl(id: number) {
  try {
    const url = new URL(window.location.href);
    url.searchParams.set("projectId", String(id));
    window.history.replaceState({}, "", url.toString());
  } catch {}
}

