import { useEffect, useMemo, useState } from "react";

export function usePersistentState<T>(key: string, initial: T) {
  const initialValue = useMemo(() => initial, [initial]);

  function read(): T {
    try {
      if (typeof window === "undefined") return initialValue;

      const raw = window.localStorage.getItem(key);
      if (!raw) return initialValue;

      return JSON.parse(raw) as T;
    } catch {
      return initialValue;
    }
  }

  const [value, setValue] = useState<T>(() => read());

  // rileggi se cambia la chiave
  useEffect(() => {
    setValue(read());
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);

  // salva su localStorage
  useEffect(() => {
    try {
      if (typeof window === "undefined") return;
      window.localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // quota exceeded o serializzazione fallita
    }
  }, [key, value]);

  // sync tra tab/browser
  useEffect(() => {
    if (typeof window === "undefined") return;

    function onStorage(e: StorageEvent) {
      if (e.key !== key) return;

      try {
        if (e.newValue === null) {
          setValue(initialValue);
          return;
        }

        setValue(JSON.parse(e.newValue) as T);
      } catch {
        setValue(initialValue);
      }
    }

    window.addEventListener("storage", onStorage);
    return () => window.removeEventListener("storage", onStorage);
  }, [key, initialValue]);

  function reset() {
    setValue(initialValue);
    try {
      if (typeof window === "undefined") return;
      window.localStorage.removeItem(key);
    } catch {}
  }

  return [value, setValue, reset] as const;
}

export default usePersistentState;

import DxfParser from "dxf-parser";

self.onmessage = (event: MessageEvent<{ source: string }>) => {
  try {
    const parser = new DxfParser();
    const result = parser.parseSync(event.data.source);

    self.postMessage({
      ok: true,
      dxf: result,
    });
  } catch (error: any) {
    self.postMessage({
      ok: false,
      error: String(error?.message || error),
    });
  }
};

