function guessExtFromLogoPath(logoPath?: string | null): "png" | "jpg" | "jpeg" | "webp" {
  const s = String(logoPath || "").toLowerCase();
  if (s.includes(".webp")) return "webp";
  if (s.includes(".jpeg")) return "jpeg";
  if (s.includes(".jpg")) return "jpg";
  return "png";
}

