      });
    } catch {}

    const existing = payload?.rows?.length
      ? { ...(payload || {}), rows: payload.rows }
      : await this.getMobileKalkulation(projectKey);
    const rows = extractMobileKalkulationRows(existing);

    const sourceLvHeaderId =
      String(
        payload?.sourceLvHeaderId ||
        payload?.lvHeaderId ||
        (existing as any)?.sourceLvHeaderId ||
        (existing as any)?.lvHeaderId ||
        (existing as any)?.data?.sourceLvHeaderId ||
        (existing as any)?.data?.lvHeaderId ||
        (existing as any)?.snapshot?.data?.sourceLvHeaderId ||
        (existing as any)?.snapshot?.data?.lvHeaderId ||
        ""
      ).trim() || undefined;

