export async function hasToken(): Promise<boolean> {
  const t = await getToken();
  return !!normalizeToken(t);
}

export async function clearToken() {
  try {
    await SecureStore.deleteItemAsync(TOKEN_KEY);
  } catch {
    // ignore
  }
