/* ============================================================
 *  AUTH STATE (SCOPED PER MODE)
 * ============================================================ */

function normalizeEmail(v: any): string | undefined {
  const s = String(v ?? "").trim().toLowerCase();
  return s ? s : undefined;
}

/**
 * Legge lo stato auth per la mode corrente (se omessa, usa getAuthMode()).
 */
export async function getAuthState(mode?: AuthMode): Promise<AuthState | null> {
  const m = mode || (await getAuthMode());
  const key = authStateKeyForMode(m);

  try {
    const raw = await AsyncStorage.getItem(key);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as AuthState;
    return {
      ...parsed,
      mode: normalizeMode(parsed.mode || m),
      email: normalizeEmail(parsed.email),
    };
  } catch {
    return null;
  }
}

/**
 * Scrive lo stato auth per la mode indicata (se manca, usa next.mode o getAuthMode()).
 */
export async function setAuthState(next: AuthState, mode?: AuthMode): Promise<void> {
  const m = mode || normalizeMode(next?.mode) || (await getAuthMode());
  const key = authStateKeyForMode(m);

  try {
    const fixed: AuthState = {
      ...next,
      mode: m,
      email: normalizeEmail(next?.email),
    };
    await AsyncStorage.setItem(key, JSON.stringify(fixed));
    await setAuthMode(m); // mantiene coerenza
  } catch {
    // ignore
  }
}

/**
 * Patch dello stato per una mode (default: mode corrente).
 */
export async function patchAuthState(
  patch: Partial<AuthState>,
  mode?: AuthMode
): Promise<AuthState | null> {
  const m = mode || (await getAuthMode());
  const prev = (await getAuthState(m)) || {};
  const next: AuthState = {
    ...prev,
    ...patch,
    mode: m,
    email: patch.email !== undefined ? normalizeEmail(patch.email) : prev.email,
  };
  await setAuthState(next, m);
  return next;
}

export function isEmailVerified(state: AuthState | null, email: string): boolean {
  if (!state) return false;
  const e = String(email || "").trim().toLowerCase();
  const sEmail = String(state.email || "").trim().toLowerCase();
  const vAt = String(state.emailVerifiedAt || "").trim();
  return !!e && !!vAt && !!sEmail && sEmail === e;
}

/* ============================================================
 *  ADMIN LOGIN (DEV ONLY) -> SERVER_SYNC
 * ============================================================ */

export async function adminLoginDev(): Promise<
  { ok: true; token: string } | { ok: false; error: string }
> {
  const IS_DEV = typeof __DEV__ !== "undefined" ? __DEV__ : false;
  if (!IS_DEV) {
    return { ok: false, error: "ADMIN_LOGIN_DISABLED_IN_PROD" };
  }
  if (!ADMIN_EMAIL || !ADMIN_KEY) {
    return { ok: false, error: "ADMIN_LOGIN_NOT_CONFIGURED" };
  }

  try {
    const url = `${await apiBaseUrl()}/api/auth/admin-login`;

    const resp = await fetch(url, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "x-admin-key": ADMIN_KEY,
      },
      body: JSON.stringify({ email: ADMIN_EMAIL }),
    });

    const data = await resp.json().catch(() => null);

    if (!resp.ok || !data?.token) {
      return { ok: false, error: String(data?.error || `HTTP_${resp.status}`) };
    }

    await setToken(String(data.token));

    const nowIso = new Date().toISOString();
    await setAuthState(
      {
        email: ADMIN_EMAIL,
        name: "Roberto",
        role: "ADMIN",
        mode: "SERVER_SYNC",
        userId: "admin-bypass",
        emailVerifiedAt: nowIso,
      },
      "SERVER_SYNC"
    );

    return { ok: true, token: String(data.token) };
  } catch (e: any) {
    return { ok: false, error: e?.message || "ADMIN_LOGIN_FAILED" };
  }
}

/* ============================================================
 *  LOGOUT
 * ============================================================ */

/**
 * Logout per una mode specifica.
 * - SERVER_SYNC: cancella token + auth_state:SERVER_SYNC
 * - NUR_APP: cancella solo auth_state:NUR_APP
 *
 * Se non passi mode, usa la mode corrente.
 */
export async function logout(mode?: AuthMode): Promise<void> {
  const m = mode || (await getAuthMode());

  if (m === "SERVER_SYNC") {
    await clearToken();
  }

  try {
    await AsyncStorage.removeItem(authStateKeyForMode(m));
  } catch {
    // ignore
  }
}

/**
 * Pulisce TUTTO (entrambi i profili) — utile per "Reset totale".
 */
export async function logoutAll(): Promise<void> {
  await clearToken();
  try {
    await AsyncStorage.removeItem(authStateKeyForMode("SERVER_SYNC"));
    await AsyncStorage.removeItem(authStateKeyForMode("NUR_APP"));
    await AsyncStorage.removeItem(AUTH_MODE_KEY);
  } catch {
    // ignore
  }
}

// apps/mobile/src/lib/companyBundle.ts
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as SecureStore from "expo-secure-store";
import * as FileSystem from "expo-file-system/legacy";
import * as Crypto from "expo-crypto";

import { setCompanyBrandingOffline } from "./companyCache";

/**
 * Bundle format:
 * - .rlccompany file: JSON con header + logo(base64) + firma
 * - QR light: JSON con solo header + firma (no logo)
 */

const OFFLINE_LICENSE_KEY = "rlc_offline_license_key_v1"; // se esiste -> usata come secret
const FALLBACK_SECRET_KEY = "rlc_company_bundle_secret_v1"; // secret locale generata (stabile sul device admin)
const BUNDLE_EXT = ".rlccompany";

const BUNDLE_DIR = `${FileSystem.documentDirectory || ""}rlc_company_bundle/`;
const TMP_LOGO = `${BUNDLE_DIR}tmp_logo_import.png`;
const TMP_BUNDLE = `${BUNDLE_DIR}company_setup${BUNDLE_EXT}`;

export type CompanyHeader = {
  name: string;
  address?: string;
  phone?: string;
  email?: string;
};

export type CompanyBundleLight = {
  v: 1;
  kind: "RLC_COMPANY_LIGHT";
  ts: string; // ISO
  header: CompanyHeader;
  sig: string;
};

export type CompanyBundleFile = {
  v: 1;
  kind: "RLC_COMPANY_FILE";
  ts: string; // ISO
  header: CompanyHeader;
  logo?: {
    mime: string;
    base64: string; // raw base64, no data:
  };
  sig: string;
};

function normalizeHeader(input: any): CompanyHeader {
  const h = input || {};
  const name = String(h.name || "").trim();
  return {
    name,
    address: String(h.address || "").trim() || undefined,
    phone: String(h.phone || "").trim() || undefined,
    email: String(h.email || "").trim() || undefined,
  };
}

function stableStringify(obj: any): string {
  // stringify con ordine chiavi stabile (per firma deterministica)
  if (obj === null || obj === undefined) return "null";
  if (typeof obj !== "object") return JSON.stringify(obj);
  if (Array.isArray(obj)) return `[${obj.map(stableStringify).join(",")}]`;
  const keys = Object.keys(obj).sort();
  const entries = keys.map((k) => `${JSON.stringify(k)}:${stableStringify(obj[k])}`);
  return `{${entries.join(",")}}`;
}

async function ensureDir() {
  try {
    const info = await FileSystem.getInfoAsync(BUNDLE_DIR);
    if (!info.exists) {
      await FileSystem.makeDirectoryAsync(BUNDLE_DIR, { intermediates: true });
    }
  } catch {
    // ignore
  }
}

async function getBundleSecret(): Promise<string> {
  // 1) preferisci license offline se presente
  try {
    const s = await SecureStore.getItemAsync(OFFLINE_LICENSE_KEY);
    if (s && s.trim()) return s.trim();
  } catch {}
  try {
    const s = await AsyncStorage.getItem(OFFLINE_LICENSE_KEY);
    if (s && s.trim()) return s.trim();
  } catch {}

  // 2) fallback: secret locale stabile
  try {
    const s = await SecureStore.getItemAsync(FALLBACK_SECRET_KEY);
    if (s && s.trim()) return s.trim();
  } catch {}
  try {
    const s = await AsyncStorage.getItem(FALLBACK_SECRET_KEY);
    if (s && s.trim()) return s.trim();
  } catch {}

  // 3) genera e persisti
  const gen = Crypto.randomUUID();
  try {
    await SecureStore.setItemAsync(FALLBACK_SECRET_KEY, gen);
  } catch {
    try {
      await AsyncStorage.setItem(FALLBACK_SECRET_KEY, gen);
    } catch {}
  }
  return gen;
}

async function signPayload(payloadWithoutSig: any): Promise<string> {
  const secret = await getBundleSecret();
  const canonical = stableStringify(payloadWithoutSig);
  const toHash = `${secret}.${canonical}`;
  return await Crypto.digestStringAsync(Crypto.CryptoDigestAlgorithm.SHA256, toHash);
}

async function readFileAsBase64(uri: string): Promise<string> {
  return await FileSystem.readAsStringAsync(uri, {
    encoding: FileSystem.EncodingType.Base64,
  });
}

function guessMimeFromUri(uri: string): string {
  const u = String(uri || "").toLowerCase();
  if (u.endsWith(".jpg") || u.endsWith(".jpeg")) return "image/jpeg";
  if (u.endsWith(".webp")) return "image/webp";
  if (u.endsWith(".svg")) return "image/svg+xml";
  return "image/png";
}

/**
 * ✅ Crea bundle "LIGHT" (per QR): header + firma
 */
export async function createCompanyBundleLight(input: {
  header: CompanyHeader;
}): Promise<CompanyBundleLight> {
  const header = normalizeHeader(input.header);
  if (!header.name) throw new Error("header.name missing");

  const base = {
    v: 1 as const,
    kind: "RLC_COMPANY_LIGHT" as const,
    ts: new Date().toISOString(),
    header,
  };

  const sig = await signPayload(base);
  return { ...base, sig };
}

/**
 * ✅ Crea bundle "FILE": header + logo base64 + firma
 */
export async function createCompanyBundleFile(input: {
  header: CompanyHeader;
  logoUri?: string | null;
}): Promise<CompanyBundleFile> {
  const header = normalizeHeader(input.header);
  if (!header.name) throw new Error("header.name missing");

  let logo: CompanyBundleFile["logo"] | undefined = undefined;

  if (input.logoUri) {
    const mime = guessMimeFromUri(input.logoUri);
    const base64 = await readFileAsBase64(input.logoUri);
    logo = { mime, base64 };
  }

  const base = {
    v: 1 as const,
    kind: "RLC_COMPANY_FILE" as const,
    ts: new Date().toISOString(),
    header,
    ...(logo ? { logo } : {}),
  };

  const sig = await signPayload(base);
  return { ...base, sig };
}

/**
 * ✅ Verifica firma (LIGHT o FILE)
 */
export async function verifyCompanyBundle(
  bundle: any
): Promise<{ ok: true } | { ok: false; error: string }> {
  try {

const sig = await signPayload(base);
  return { ...base, sig };
}

/**
 * ✅ Verifica firma (LIGHT o FILE)
 */
export async function verifyCompanyBundle(
  bundle: any
): Promise<{ ok: true } | { ok: false; error: string }> {
  try {
    if (!bundle || bundle.v !== 1) return { ok: false, error: "BUNDLE_VERSION_INVALID" };
    if (!bundle.kind) return { ok: false, error: "BUNDLE_KIND_MISSING" };
    if (!bundle.sig) return { ok: false, error: "BUNDLE_SIG_MISSING" };

    const { sig, ...rest } = bundle;
    const expected = await signPayload(rest);
    if (String(sig) !== String(expected)) return { ok: false, error: "BUNDLE_SIG_INVALID" };

    const h = normalizeHeader(bundle.header);
    if (!h.name) return { ok: false, error: "HEADER_INVALID" };

    return { ok: true };
  } catch (e: any) {
    return { ok: false, error: e?.message || "BUNDLE_VERIFY_FAILED" };
  }
}

/**
 * ✅ Esporta bundle FILE su filesystem (share via WhatsApp ecc.)
 */
export async function exportCompanyBundleToFile(
  bundle: CompanyBundleFile
): Promise<string> {
  await ensureDir();
  const uri = TMP_BUNDLE;
  await FileSystem.writeAsStringAsync(uri, JSON.stringify(bundle, null, 2), {
    encoding: FileSystem.EncodingType.UTF8,
  });
  return uri;
}

/**
 * ✅ Import bundle da fileUri (.rlccompany)
 */
export async function importCompanyBundleFromFile(fileUri: string): Promise<any> {
  const raw = await FileSystem.readAsStringAsync(fileUri, {
    encoding: FileSystem.EncodingType.UTF8,
  });
  return JSON.parse(raw);
}

/**
 * ✅ Applica bundle (salva in cache/persistenza usata da Home/PDF)
 * - salva header
 * - se logo presente: scrive logo in tmp file e lo passa a companyCache (che lo copia in rlc_company/logo.*)
 */
export async function applyCompanyBundle(bundle: any): Promise<void> {
  const v = await verifyCompanyBundle(bundle);
  if (!v.ok) throw new Error(v.error);

  const header = normalizeHeader(bundle.header);

  let tmpLogoUri: string | null = null;
  if (bundle.kind === "RLC_COMPANY_FILE" && bundle.logo?.base64) {
    await ensureDir();

    // scegli estensione da mime
    const mime = String(bundle.logo?.mime || "image/png").toLowerCase();
    const ext =
      mime.includes("jpeg") || mime.includes("jpg")
        ? ".jpg"
        : mime.includes("webp")
        ? ".webp"
        : mime.includes("svg")
        ? ".svg"
        : ".png";

    const tmp = TMP_LOGO.replace(/\.png$/, ext);

    await FileSystem.writeAsStringAsync(tmp, String(bundle.logo.base64), {
      encoding: FileSystem.EncodingType.Base64,
    });

    tmpLogoUri = tmp;
  }

  await setCompanyBrandingOffline({
    header,
    logoUri: tmpLogoUri,
  });

  // cleanup tmp logo (best effort)
  if (tmpLogoUri) {
    try {
      await FileSystem.deleteAsync(tmpLogoUri, { idempotent: true });
    } catch {}
  }
}

// apps/mobile/src/lib/companyCache.ts
import AsyncStorage from "@react-native-async-storage/async-storage";
import * as FileSystem from "expo-file-system/legacy";
import { Buffer } from "buffer";
import { api, request } from "./api";

const KEY_HEADER = "rlc_company_header_v1";
const KEY_LOGO_URI = "rlc_company_logo_uri_v1";

// persistente
const DIR = `${FileSystem.documentDirectory || ""}rlc_company/`;
const LOGO_FILE_BASE = "logo"; // estensione aggiunta dopo (logo.png / logo.jpg / ...)

function safeJsonParse<T>(s: string | null): T | null {
  if (!s) return null;
  try {
    return JSON.parse(s) as T;
  } catch {
    return null;
  }
}

async function ensureDir() {
  if (!DIR) return;
  try {
    const info = await FileSystem.getInfoAsync(DIR);
    if (!info.exists) {
      await FileSystem.makeDirectoryAsync(DIR, { intermediates: true });
    }
  } catch {
    // ignore
  }
}

function guessExtFromHeaders(contentType?: string) {
  const ct = String(contentType || "").toLowerCase();
  if (ct.includes("png")) return ".png";
  if (ct.includes("jpeg") || ct.includes("jpg")) return ".jpg";
  if (ct.includes("webp")) return ".webp";
  if (ct.includes("svg")) return ".svg"; // se mai
  return ".png";
}

function guessExtFromUri(uri?: string) {
  const u = String(uri || "").toLowerCase();
  const m = u.match(/\.([a-z0-9]{2,5})(\?.*)?$/i);
  const ext = m?.[1] ? `.${m[1]}` : "";
  if (!ext) return ".png";
  if (ext === ".jpeg") return ".jpg";
  if ([".png", ".jpg", ".webp", ".svg"].includes(ext)) return ext;
  return ".png";
}

async function cleanupOldLogoFiles() {
  try {
    await ensureDir();
    const listing = await FileSystem.readDirectoryAsync(DIR);
    const prefix = `${LOGO_FILE_BASE}.`;
    const hits = listing.filter((n) => n.toLowerCase().startsWith(prefix));
    for (const n of hits) {
      try {
        await FileSystem.deleteAsync(`${DIR}${n}`, { idempotent: true });
      } catch {}
    }
  } catch {
    // ignore
  }
}

/**
 * Scarica il logo dal server autenticato.
 * Endpoint server: GET /api/company/logo (auth required)
 */
async function downloadLogoToPersistentFile(): Promise<string | null> {
  try {
    await ensureDir();

    const url = await api.absUrlAsync("/api/company/logo");

    // fetch diretto -> prendiamo token con import dinamico per evitare cicli
    const token = await (async () => {
      try {
        const mod = await import("./auth");
        return await mod.getToken();
      } catch {
        return "";
      }
    })();

    const res = await fetch(url, {
      method: "GET",
      headers: {
        Accept: "image/*",
        ...(token ? { Authorization: `Bearer ${token}` } : {}),
      },
    });

    if (!res.ok) return null;

    const ct = res.headers.get("content-type") || "";
    const ext = guessExtFromHeaders(ct);

    // elimina eventuali vecchi logo.* (evita che resti in cache quello sbagliato)
    await cleanupOldLogoFiles();

    const buf = await res.arrayBuffer();
    const base64 = Buffer.from(buf).toString("base64");

    const target = `${DIR}${LOGO_FILE_BASE}${ext}`;

    await FileSystem.writeAsStringAsync(target, base64, {
      encoding: FileSystem.EncodingType.Base64,
    });

    await AsyncStorage.setItem(KEY_LOGO_URI, target);
    return target;
  } catch {
    return null;
  }
}

/**
 * ✅ NUR_APP / offline: salva header in cache
 */
export async function setCompanyHeaderCached(header: any | null): Promise<void> {
  try {
    if (!header) {
      await AsyncStorage.removeItem(KEY_HEADER);
      return;
    }
    await AsyncStorage.setItem(KEY_HEADER, JSON.stringify(header));
  } catch {
    // ignore
  }
}

/**
 * ✅ NUR_APP / offline: copia logo in cartella persistente e salva uri
 * sourceUri può essere file:// (ImagePicker) o content:// (Android)
 */
export async function saveCompanyLogoToPersistentFile(
  sourceUri: string
): Promise<string | null> {
  try {
    if (!sourceUri) return null;
    await ensureDir();

    // pulisci vecchi logo.*
    await cleanupOldLogoFiles();

    const ext = guessExtFromUri(sourceUri);
    const target = `${DIR}${LOGO_FILE_BASE}${ext}`;

    // Android content:// -> copia in cache temporanea e poi copia
    if (sourceUri.startsWith("content://")) {
      const tmp = `${FileSystem.cacheDirectory || DIR}tmp_logo${ext}`;
      await FileSystem.copyAsync({ from: sourceUri, to: tmp });
      await FileSystem.copyAsync({ from: tmp, to: target });
      try {
        await FileSystem.deleteAsync(tmp, { idempotent: true });
      } catch {}
    } else {
      await FileSystem.copyAsync({ from: sourceUri, to: target });
    }

    await AsyncStorage.setItem(KEY_LOGO_URI, target);
    return target;
  } catch {
    return null;
  }
}

/**
 * ✅ NUR_APP helper: salva header + logo (se presente) in un colpo
 */
export async function setCompanyBrandingOffline(opts: {
  header: any;
  logoUri?: string | null;
}): Promise<{ header: any; logoUri: string | null }> {
  const header = opts?.header ?? null;
  await setCompanyHeaderCached(header);

  let persisted: string | null = null;
  if (opts?.logoUri) {
    persisted = await saveCompanyLogoToPersistentFile(opts.logoUri);
  } else {
    // se non passa logoUri, non tocchiamo quello esistente
    persisted = (await getCompanyLogoUriCached()) || null;
  }

  return { header, logoUri: persisted };
}

/**
 * ✅ Sync header + logo (non crasha mai, torna sempre qualcosa se presente in cache)
 */
export async function syncCompanyHeaderAndLogo(): Promise<{

} else {
    // se non passa logoUri, non tocchiamo quello esistente
    persisted = (await getCompanyLogoUriCached()) || null;
  }

  return { header, logoUri: persisted };
}

/**
 * ✅ Sync header + logo (non crasha mai, torna sempre qualcosa se presente in cache)
 */
export async function syncCompanyHeaderAndLogo(): Promise<{
  header: any | null;
  logoUri: string | null;
}> {
  // 1) prova fetch header
  let header: any | null = null;

  try {
    const j = await request<any>("/api/company/header", { method: "GET" } as any);
    // accetta vari shape
    header = j?.company || j?.data?.company || j?.header || null;
    if (header) {
      await AsyncStorage.setItem(KEY_HEADER, JSON.stringify(header));
    }
  } catch {
    // ignore -> fallback cache
  }

  // 2) fallback header cache
  if (!header) {
    header = safeJsonParse<any>(await AsyncStorage.getItem(KEY_HEADER)) || null;
  }

  // 3) logo: se già c’è uri locale valido -> ok, altrimenti scarica
  let logoUri: string | null = null;

  try {
    const cachedLogo = (await AsyncStorage.getItem(KEY_LOGO_URI)) || "";
    if (cachedLogo) {
      const info = await FileSystem.getInfoAsync(cachedLogo);
      if (info.exists) logoUri = cachedLogo;
    }
  } catch {
    // ignore
  }

  if (!logoUri) {
    const dl = await downloadLogoToPersistentFile();
    if (dl) logoUri = dl;
  }

  return { header, logoUri };
}

/**
 * Solo lettura cache (offline)
 */
export async function getCompanyHeaderCached(): Promise<any | null> {
  return safeJsonParse<any>(await AsyncStorage.getItem(KEY_HEADER));
}

export async function getCompanyLogoUriCached(): Promise<string | null> {
  const u = (await AsyncStorage.getItem(KEY_LOGO_URI)) || "";
  if (!u) return null;
  try {
    const info = await FileSystem.getInfoAsync(u);
    return info.exists ? u : null;
  } catch {
    return null;
  }
}

/**
 * Force refresh logo (utile dopo upload admin/logo)
 */
export async function refreshCompanyLogo(): Promise<string | null> {
  const dl = await downloadLogoToPersistentFile();
  return dl || null;
}

/**
 * Clear cache (debug)
 */
export async function clearCompanyCache(): Promise<void> {
  try {
    await AsyncStorage.removeItem(KEY_HEADER);

    const u = (await AsyncStorage.getItem(KEY_LOGO_URI)) || "";
    await AsyncStorage.removeItem(KEY_LOGO_URI);

    // pulizia file locali
    if (u) {
      try {
        await FileSystem.deleteAsync(u, { idempotent: true });
      } catch {}
    }

    // pulisci eventuali altri logo.* rimasti
    await cleanupOldLogoFiles();
  } catch {}
}

// apps/mobile/src/lib/docSubmit.ts
import { Alert } from "react-native";
import { queueAdd } from "./offlineQueue";

/**
 * Tipo documento (coerente con la tua queue)
 */
export type DocType = "REGIE" | "LIEFERSCHEIN" | "PHOTOS";

export type SubmitResult = {
  ok: boolean;
  queued?: boolean;
  processed?: boolean;
  message?: string;
  error?: string;
};

/**
 * submitDraftUnified
 * - garantisce: prima esiste un draft offline, poi queue
 * - il processing reale avviene tramite Inbox/Sync (executor separato)
 */
export async function submitDraftUnified(opts: {
  docType: DocType;

  // Chiave cartella progetto (FS-key) e metadati
  projectFsKey: string; // BA-... o local-...
  projectTitle?: string;

  // Payload completo del documento (row/draft) come già salvi offline
  row: any;

  // Funzione di salvataggio offline del draft
  ensureSavedOffline: () => Promise<any>;

  // opzionale: se vuoi auto-alert
  silent?: boolean;
}): Promise<SubmitResult> {
  try {
    // 1) assicura draft salvato offline
    const savedRow = await opts.ensureSavedOffline();

    // 2) queue payload corretto per tipo documento
    if (opts.docType === "REGIE") {
      await queueAdd({
        kind: "REGIE",
        projectId: opts.projectFsKey,
        payload: {
          date: String(savedRow?.date || ""),
          text: String(
            savedRow?.text ||
              savedRow?.leistung ||
              savedRow?.bemerkungen ||
              savedRow?.note ||
              ""
          ),
          hours:
            savedRow?.hours == null || savedRow?.hours === ""
              ? undefined
              : Number(savedRow.hours),
          note: String(savedRow?.note || savedRow?.bemerkungen || ""),
          row: savedRow,
        },
      });
    } else if (opts.docType === "LIEFERSCHEIN") {
      await queueAdd({
        kind: "LIEFERSCHEIN",
        projectId: opts.projectFsKey,
        payload: {
          date: String(savedRow?.date || ""),
          lieferscheinNummer: String(
            savedRow?.lieferscheinNummer || savedRow?.lieferscheinNr || ""
          ),
          supplier: String(savedRow?.lieferant || savedRow?.supplier || ""),
          site: String(savedRow?.baustelle || savedRow?.site || ""),
          driver: String(savedRow?.fahrer || savedRow?.driver || ""),
          material: String(savedRow?.material || ""),
          quantity:
            savedRow?.quantity == null || savedRow?.quantity === ""
              ? undefined
              : Number(savedRow.quantity),
          unit: String(savedRow?.unit || savedRow?.einheit || ""),
          kostenstelle: String(savedRow?.kostenstelle || ""),
          lvItemPos:
            savedRow?.lvItemPos == null || savedRow?.lvItemPos === ""
              ? null
              : String(savedRow.lvItemPos),
          comment: String(
            savedRow?.comment || savedRow?.bemerkungen || savedRow?.note || ""
          ),
          bemerkungen: String(savedRow?.bemerkungen || ""),
          files: Array.isArray(savedRow?.attachments)
            ? savedRow.attachments
            : Array.isArray(savedRow?.files)
            ? savedRow.files
            : [],
          row: savedRow,
        },
      });
    } else {
      await queueAdd({
        kind: "FOTOS_NOTIZEN",
        projectId: opts.projectFsKey,
        payload: {
          createdAt: String(savedRow?.createdAt || new Date().toISOString()),
          note: String(savedRow?.note || savedRow?.bemerkungen || savedRow?.text || ""),
          imageUri: savedRow?.imageUri || null,
          imageMeta: savedRow?.imageMeta || null,
          extras: Array.isArray(savedRow?.extras) ? savedRow.extras : [],
          boxes: Array.isArray(savedRow?.boxes) ? savedRow.boxes : [],
          docId: savedRow?.docId ? String(savedRow.docId) : undefined,
          date: savedRow?.date ? String(savedRow.date) : undefined,
          kostenstelle: savedRow?.kostenstelle
            ? String(savedRow.kostenstelle)
            : undefined,
          lvItemPos:
            savedRow?.lvItemPos == null || savedRow?.lvItemPos === ""
              ? null
              : String(savedRow.lvItemPos),
          comment: savedRow?.comment ? String(savedRow.comment) : undefined,
          bemerkungen: savedRow?.bemerkungen
            ? String(savedRow.bemerkungen)
            : undefined,
          files: Array.isArray(savedRow?.files)
            ? savedRow.files
            : Array.isArray(savedRow?.attachments)
            ? savedRow.attachments
            : [],
        },
      });
    }

    if (!opts.silent) {
      Alert.alert("Eingereicht", "In Inbox/Queue übernommen.");
    }

    return {
      ok: true,
      queued: true,
      processed: false,
      message: "Queued",
    };
  } catch (e: any) {
    const msg = String(e?.message || e || "Unknown error");
    if (!opts.silent) Alert.alert("Fehler beim Einreichen", msg);
    return { ok: false, error: msg };
  }
}

// apps/mobile/src/lib/exportStorage.ts
import * as FileSystem from "expo-file-system/legacy";

function safeProjectKey(k: string) {
  return String(k || "")
    .trim()
    .replace(/[^\w.\-]+/g, "_")
    .slice(0, 80);
}

function safeFilename(name: string) {
  return String(name || "file")
    .trim()
    .replace(/[^\w.\-]+/g, "_")
    .slice(0, 160);
}

function baseDir() {
  const root = String(FileSystem.documentDirectory || "").trim();
  if (!root) throw new Error("FileSystem.documentDirectory fehlt");
  return root.endsWith("/") ? root : `${root}/`;
}

async function ensureDir(dirUri: string) {
  try {
    const info = await FileSystem.getInfoAsync(dirUri);
    if (info.exists && info.isDirectory) return;
    if (info.exists && !info.isDirectory) {
      await FileSystem.deleteAsync(dirUri, { idempotent: true });
    }
  } catch {}
  await FileSystem.makeDirectoryAsync(dirUri, { intermediates: true });
}

export type ExportKind = "regie" | "lieferschein" | "photos";
export type ExportFileType = "pdf" | "csv";

export type ExportMetaItem = {
  kind: ExportKind;
  fileType: ExportFileType;
  name: string;     // filename
  uri: string;      // local uri
  size?: number;
  mtime?: string;
};

function exportDir(projectFsKey: string, kind: ExportKind) {
  const k = safeProjectKey(projectFsKey);
  return `${baseDir()}rlc_exports/${k}/${kind}/`;
}

function exportFileUri(projectFsKey: string, kind: ExportKind, filename: string) {
  return `${exportDir(projectFsKey, kind)}${safeFilename(filename)}`;
}

export async function writeExportTextFile(opts: {
  projectFsKey: string;
  kind: ExportKind;
  filename: string; // should include .csv
  content: string;
}): Promise<{ uri: string; name: string }> {
  const dir = exportDir(opts.projectFsKey, opts.kind);
  await ensureDir(dir);

  const uri = exportFileUri(opts.projectFsKey, opts.kind, opts.filename);
  await FileSystem.writeAsStringAsync(uri, opts.content, {
    encoding: FileSystem.EncodingType.UTF8,
  });

  return { uri, name: safeFilename(opts.filename) };
}

export async function moveExportFile(opts: {
  projectFsKey: string;
  kind: ExportKind;
  filename: string; // should include .pdf
  fromUri: string;  // temp file uri
}): Promise<{ uri: string; name: string }> {
  const dir = exportDir(opts.projectFsKey, opts.kind);
  await ensureDir(dir);

  const uri = exportFileUri(opts.projectFsKey, opts.kind, opts.filename);

  // idempotent overwrite
  try {
    await FileSystem.deleteAsync(uri, { idempotent: true });
  } catch {}

  await FileSystem.copyAsync({ from: opts.fromUri, to: uri });

  // cleanup temp (best effort)
  try {
    await FileSystem.deleteAsync(opts.fromUri, { idempotent: true });
  } catch {}

  return { uri, name: safeFilename(opts.filename) };
}

export async function listExportFiles(projectFsKey: string, kind?: ExportKind): Promise<ExportMetaItem[]> {
  const kinds: ExportKind[] = kind ? [kind] : ["regie", "lieferschein", "photos"];
  const out: ExportMetaItem[] = [];

  for (const k of kinds) {
    const dir = exportDir(projectFsKey, k);

    try {
      const dirInfo = await FileSystem.getInfoAsync(dir);
      if (!dirInfo.exists || !dirInfo.isDirectory) continue;
    } catch {
      continue;
    }

    let names: string[] = [];
    try {
      names = await FileSystem.readDirectoryAsync(dir);
    } catch {
      continue;
    }

    for (const raw of names) {
      const name = String(raw || "").trim();
      if (!name) continue;
      const uri = `${dir}${name}`;

      try {
        const info: any = await FileSystem.getInfoAsync(uri);
        if (!info?.exists || info?.isDirectory) continue;

        const mt =
          typeof info?.modificationTime === "number"
            ? new Date(info.modificationTime * 1000).toISOString()
            : undefined;

        const lower = name.toLowerCase();
        const fileType: ExportFileType =
          lower.endsWith(".csv") ? "csv" : "pdf";

        out.push({
          kind: k,
          fileType,
          name,
          uri,
          size: typeof info?.size === "number" ? info.size : undefined,
          mtime: mt,
        });
      } catch {}
    }
  }

  out.sort((a, b) => {
    const ta = a.mtime ? Date.parse(a.mtime) : 0;
    const tb = b.mtime ? Date.parse(b.mtime) : 0;
    if (tb !== ta) return tb - ta;
    return String(a.name).localeCompare(String(b.name));
  });

  return out;
}

