function ymdNow() {
  return new Date().toISOString().slice(0, 10);
}

function esc(v: any) {
  return String(v ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function nl2br(v: any) {
  return esc(v).replace(/\n/g, "<br/>");
}

function formatDateDe(v?: string) {
  const s = String(v || "").trim();
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return s || "—";
  const [y, m, d] = s.split("-");
  return `${d}.${m}.${y}`;
}

function fileNameSafe(v: string) {
  return String(v || "")
    .trim()
    .replace(/[\/\\?%*:|"<>]/g, "-")
    .replace(/\s+/g, "_")
    .slice(0, 120);
}

function sortRows(rows: BautagebuchRow[]) {
  return [...rows].sort((a, b) => {
    const ad = String(a?.date || "");
    const bd = String(b?.date || "");
    if (ad < bd) return -1;
    if (ad > bd) return 1;
    return Number(a?.createdAt || 0) - Number(b?.createdAt || 0);
  });
}

async function logoUriToDataUri(uri?: string | null): Promise<string> {
  const src = String(uri || "").trim();
  if (!src) return "";

  try {
    if (src.startsWith("data:")) return src;

    const b64 = await FileSystem.readAsStringAsync(src, {
      encoding: FileSystem.EncodingType.Base64,
    });

    const lower = src.toLowerCase();
    const mime = lower.endsWith(".png")
      ? "image/png"
      : lower.endsWith(".webp")
      ? "image/webp"
      : "image/jpeg";

    return `data:${mime};base64,${b64}`;
  } catch {
    return "";
  }
}

