export async function buildBautagebuchPdf(
  input: BuildBautagebuchPdfInput
): Promise<BuildBautagebuchPdfResult> {
  const rows = sortRows(Array.isArray(input.rows) ? input.rows : []);

  if (!rows.length) {
    throw new Error(
      "Keine Tagesberichte für den PDF-Export gefunden."
    );
  }

  const date = ymdNow();

  const projectTitle =
    String(
      input.projectTitle ||
      input.projectFsKey ||
      "Projekt"
    ).trim() || "Projekt";

  const pdfRows: PdfRow[] = [];

  rows.forEach((row, index) => {
    const dateLabel = formatDateDe(row.date);

    pdfRows.push({
      pos: String(index + 1),
      text: `Tagesbericht ${dateLabel}`,
      unit: "",
      qty: 0,
      ep: 0,
      gp: 0,
      formula: "",
    });

    const details = [
      ["Wetter", row.weather],
      ["Temperatur", row.temperature],
      ["Mitarbeiter", row.workers],
      ["Maschinen", row.machines],
      ["Ausgeführte Arbeiten", row.workDone],
      ["Besondere Vorkommnisse", row.issues],
      ["Zusätzliche Notizen", row.notes],
    ].filter((entry) =>
      String(entry[1] || "").trim()
    );

    details.forEach(([label, value]) => {
      pdfRows.push({
        pos: "",
        text: `${label}: ${String(value || "").trim()}`,
        unit: "",
        qty: 0,
        ep: 0,
        gp: 0,
        formula: "",
      });
    });

    const attachmentCount =
      Array.isArray(row.attachments)
        ? row.attachments.length
        : 0;

    if (attachmentCount > 0) {
      pdfRows.push({
        pos: "",
        text: `Fotos / Anhänge: ${attachmentCount}`,
        unit: "",
        qty: 0,
        ep: 0,
        gp: 0,
        formula: "",
      });
    }
  });

  const fileName =
    fileNameSafe(
      input.filenameHint ||
      `Bautagebuch_${input.projectFsKey}_${
        input.monthLabel || date
      }`
    ) + ".pdf";

  const result = await buildDocumentPdf({
    type: "BAUTAGEBUCH",
    projectCode: String(
      input.projectFsKey || ""
    ).trim(),
    fileName,
    title: "Bautagebuch",
    subTitle: input.monthLabel ? `Zeitraum: ${String(input.monthLabel)}` : "",
    date,
    customer: {
      name: projectTitle,
    },
    rows: pdfRows,
    note: `${rows.length} Tagesbericht(e)`,
    shareAfterCreate: false,
  });

  return {
    pdfUri: result.pdfUri,
    fileName,
    date,
  };
}

export async function openBautagebuchPdf(result: any) {
  const uri = String(result?.pdfUri || result?.uri || result || "").trim();

  if (!uri) {
    throw new Error("PDF konnte nicht geöffnet werden: URI fehlt.");
  }

  await Linking.openURL(uri);
}

