          font-family: ${RLC_PDF_FONT_STACK};
          color: #111;
          margin: 0;
          padding: 0;
        }

        .page { width: 100%; }
        .page-break { page-break-after: always; }

        .rlc-global-footer {
          position: fixed;
          left: 0;
          right: 0;
          bottom: -11mm;
          display: flex;
          justify-content: space-between;
          align-items: center;
          border-top: 0.3mm solid #d8e1ea;
          padding-top: 2mm;
          color: #64748b;
          font-size: 8px;
        }

        .rlc-page-number::after { content: counter(page); }

        .company-header {
          display: flex;
          align-items: flex-start;
          justify-content: space-between;
          gap: 6mm;
          border: 0.3mm solid #111;
          padding: 3mm 4mm;
          margin-bottom: 3mm;
          min-height: 22mm;
          box-sizing: border-box;
        }

        .company-header-left {
          width: 36mm;
          display: flex;
          align-items: center;
          justify-content: flex-start;
        }

        .company-header-right {
          flex: 1;
          font-size: 10px;
          line-height: 1.45;
          display: flex;
          flex-direction: column;
          justify-content: center;
          text-align: left;
        }

        .company-logo {
          width: 30mm;
          max-height: 18mm;
          object-fit: contain;
          display: block;
        }

        .company-logo-placeholder {
          width: 30mm;
          height: 18mm;
          border: 0.3mm solid #999;
          background: #f8f8f8;
          border-radius: 2mm;
        }

        .company-line {
          margin-bottom: 1mm;
        }

        .doc-banner {
          width: 100%;
          box-sizing: border-box;
          border: 0.3mm solid #111;
          padding: 2.5mm 4mm;
          margin-bottom: 3mm;
          font-size: 14px;
          font-weight: 900;
          letter-spacing: 0.8px;
          text-align: center;
          background: #f3f3f3;
        }

        .doc-banner.fotos { background: #f5f7fa; }
        .doc-banner.ls {
          background: #eaeaea;
          border-left: 4mm solid #111;
          text-align: left;
          padding-left: 5mm;
        }
        .doc-banner.regie { background: #f3f3f3; }

        .head {
          display: flex;
          border: 0.3mm solid #111;
          height: 30mm;
        }

        .head-left {
          width: 55mm;
          border-right: 0.3mm solid #111;
          padding: 3mm 4mm;
          box-sizing: border-box;
        }

        .type-row {
          display:flex;
          align-items:center;
          justify-content: space-between;
          margin: 2mm 0;
          font-size: 10px;
        }

        .cb {
          width: 6mm;
          height: 6mm;
          border: 0.3mm solid #111;
          display:grid;
          place-items:center;
          font-weight:700;
        }

        .left-title {
          height: 100%;
          display: flex;
          align-items: center;
          justify-content: center;
          font-size: 14px;
          font-weight: 800;
          letter-spacing: 0.2px;
        }

        .head-mid {
          flex: 1;
          border-right: 0.3mm solid #111;
          padding: 3mm 4mm;
          box-sizing: border-box;
        }

        .head-mid .line {
          display:flex;
          gap: 2mm;
          font-size: 10px;
          margin: 2mm 0;
        }

        .head-mid .lab {
          width: 34mm;
          color:#111;
        }

        .head-mid .val {
          flex: 1;
          border-bottom: 0.3mm solid #111;
          padding-bottom: 1mm;
        }

        .head-right {
          width: 55mm;
          display:flex;
          flex-direction: column;
        }

        .rf {
          flex: 1;
          border-bottom: 0.3mm solid #111;
          display:flex;
          flex-direction: column;
          justify-content: space-between;
          padding: 2mm 2mm;

width: 55mm;
          display:flex;
          flex-direction: column;
        }

        .rf {
          flex: 1;
          border-bottom: 0.3mm solid #111;
          display:flex;
          flex-direction: column;
          justify-content: space-between;
          padding: 2mm 2mm;
          box-sizing: border-box;
        }

        .rf:last-child { border-bottom: none; }
        .rf .lab { font-size: 10px; text-align:center; }
        .rf .val { font-size: 10px; text-align:center; font-weight:600; }

        .days {
          margin-top: 2mm;
          border: 0.3mm solid #111;
        }

        .days .row { display:flex; }

        .days .cell {
          flex: 1;
          border-right: 0.3mm solid #111;
          padding: 1.5mm 0;
          text-align:center;
          font-size: 10px;
        }

        .days .cell:last-child { border-right: none; }
        .days .days-row .day { font-weight: 700; }
        .days .zeit-lab .zeit { background: #f3f3f3; }
        .days .zeit-val .v { height: 7mm; }

        .ls-info {
          display: flex;
          justify-content: space-between;
          gap: 4mm;
          margin-top: 2mm;
          padding: 2mm 2.5mm;
          border: 0.3mm solid #111;
          background: #fafafa;
          font-size: 10px;
        }

        table.main {
          width: 100%;
          border-collapse: collapse;
          margin-top: 2mm;
          border: 0.3mm solid #111;
        }

        table.main th,
        table.main td {
          border: 0.3mm solid #111;
          padding: 1.8mm 1.4mm;
          font-size: 10px;
          vertical-align: top;
        }

        table.main td { height: 10mm; }

        table.main th {
          background: #f3f3f3;
          text-align: center;
          font-weight: 700;
        }

        th.kosten, td.kosten { width: 18mm; }
        th.geraet, td.geraet { width: 33mm; }
        th.mitarb, td.mitarb { width: 26mm; }
        th.std, td.std { width: 12mm; text-align: center; }
        th.bes, td.bes { width: 62mm; }
        th.mat, td.mat { width: 36mm; }

        .badges {
          margin-bottom: 1mm;
          display:flex;
          flex-wrap:wrap;
          gap: 1mm;
        }

        .tag {
          font-size: 9px;
          padding: 0.3mm 1.3mm;
          border-radius: 2mm;
          display:inline-block;
          font-weight: 800;
          background: #111;
          color: #fff;
          border: none;
        }

        .desc {
          margin-top: 3mm;
          border: 0.3mm solid #111;
          min-height: 13mm;
        }

        .desc-title {
          background: #f3f3f3;
          padding: 1.5mm 2mm;
          font-weight: 700;
          font-size: 10px;
          border-bottom: 0.3mm solid #111;
        }

        .desc-body {
          padding: 2mm;
          font-size: 10px;
          min-height: 6mm;
          white-space: pre-wrap;
        }

        .bottom {
          margin-top: 3mm;
          display:flex;
          gap: 4mm;
          align-items: stretch;
        }

        .box {
          border: 0.3mm solid #111;
          min-height: 52mm;
          position: relative;
          display: flex;
          flex-direction: column;
        }

        .foto-big { flex: 2; }
        .bemerk-small { flex: 1; }

        .box-title {
          background: #f3f3f3;
          padding: 1.5mm 2mm;
          font-weight: 700;
          font-size: 10px;
          border-bottom: 0.3mm solid #111;
        }

        .photo {
          width: 100%;
          flex: 1;
          object-fit: cover;
          display: block;
          background: #fafafa;
        }

        .ph-muted {
          padding: 10mm 2mm;
          text-align:center;
          color:#666;
          font-size: 10px;
        }

        .bem-text {
          padding: 2mm;
          font-size: 10px;
          white-space: pre-wrap;
          flex: 1;
        }

        .sign {
          margin-top: 3mm;
          display:flex;
          gap: 4mm;
        }

        .sign-col {
          flex:1;
          border: 0.3mm solid #111;
        }

        .sign-title {
          background:#f3f3f3;
          padding: 1.5mm 2mm;
          font-weight:700;
          font-size:10px;
          border-bottom: 0.3mm solid #111;
        }

        .sign-line {
          display:flex;
          gap: 2mm;
          padding: 3mm 2mm;
          align-items:flex-end;
        }

        .sign-line .lab {
          width: 18mm;
          font-size: 10px;
        }

        .sign-line .line {
          flex:1;
          border-bottom: 0.3mm solid #111;
          height: 0;
        }
        /* RLC_OFFLINE_BLUE_HEADER_V1: same visual identity as PDF Core */
        .company-header {
          background: #0b4f78 !important;
          border: 0 !important;
          border-radius: 10px !important;
          padding: 14px 16px !important;
          margin-bottom: 18px !important;
          color: #ffffff !important;
        }
        .company-header-right,
        .company-header-right *,
        .company-line,
        .company-line:first-child {
          color: #ffffff !important;
        }
        .company-logo,
        .company-logo-placeholder {
          background: #ffffff !important;
          border-color: rgba(255,255,255,0.7) !important;
        }

