          <td class="mitarb">${escapeHtml(text(r.worker || ""))}</td>
          <td class="std"></td>
          <td class="bes">${badges.length ? `<div class="badges">${badges.join("")}</div>` : ""}${escapeHtml(text(r.comment || ""))}</td>
          <td class="mat">${escapeHtml(text(r.material || ""))}</td>
        </tr>
      `;
    })
    .join("");

  const content = `
