/**
 * ✅ Migrazione best-effort:
 * - normalizza projectId
 * - imposta tries/nextTryAt se mancanti
 * - dedupeKey se mancante
 */
export async function queueNormalizeExisting(): Promise<{ changed: number }> {
  const list = await queueList();
  let changed = 0;

  const next = list.map((x) => {
    let y: any = { ...x };

    const norm = normalizeProjectKey(y.projectId);
    if (norm !== y.projectId) {
      y.projectId = norm;
      changed++;
    }

    if (typeof y.tries !== "number") {
      y.tries = 0;
      changed++;
    }
    if (typeof y.lastTryAt === "undefined") {
      y.lastTryAt = null;
      changed++;
    }
    if (typeof y.nextTryAt === "undefined") {
      y.nextTryAt = null;
      changed++;
    }
    if (!y.dedupeKey) {
      y.dedupeKey = computeDedupeKey({
        kind: y.kind,
        projectId: y.projectId,
        payload: y.payload,
      });
      changed++;
    }

    return y as QueueItem;
  });

  if (changed > 0) await setJson(KEY, next);
  return { changed };
}

/** ============================================================
 * Processor
 * ============================================================ */

export type QueueExecutor = (item: QueueItem) => Promise<any>;

export type QueueFlushOptions = {
  /** max items per flush */
  maxItems?: number;

  /** se true: si ferma al primo errore */
  stopOnError?: boolean;

  /** limiti retry */
  maxTries?: number;

  /** processa anche ERROR se nextTryAt scaduto */
  includeErrors?: boolean;

  /** se true: ordina FIFO (oldest first). default true */
  fifo?: boolean;
};

/**
 * ✅ queueFlush:
 * - prende PENDING (e opzionalmente ERROR) pronti
 * - esegue executor(item)
 * - DONE se ok
 * - OFFLINE/TIMEOUT: resta PENDING, non incrementa tries, interrompe il flush
 * - altri errori: ERROR con backoff (tries++)
 */
export async function queueFlush(
  executor: QueueExecutor,
  options?: QueueFlushOptions
): Promise<{ processed: number; done: number; errored: number; skipped: number }> {
  const maxItems = options?.maxItems ?? 20;
  const stopOnError = options?.stopOnError ?? false;
  const maxTries = options?.maxTries ?? 8;
  const includeErrors = options?.includeErrors ?? true;
  const fifo = options?.fifo ?? true;

  return withLock(async () => {
    await queueNormalizeExisting();

    const list = await queueList();
    const t = nowMs();

    let processed = 0;
    let done = 0;
    let errored = 0;
    let skipped = 0;

    // FIFO logico: più vecchi prima
    const ordered = fifo ? [...list].sort((a, b) => a.ts - b.ts) : [...list];

    for (const item of ordered) {
      if (processed >= maxItems) break;

      const isPending = item.status === "PENDING";
      const isError = item.status === "ERROR";

      if (!isPending && !(includeErrors && isError)) {
        skipped++;
        continue;
      }

      if (item.tries >= maxTries) {
        if (item.status !== "ERROR") {
          await queueUpdate(item.id, {
            status: "ERROR",
            error: `maxTries reached (${maxTries})`,
            nextTryAt: null,
          });
        }
        skipped++;
        continue;
      }

      if (item.nextTryAt && item.nextTryAt > t) {
        skipped++;
        continue;
      }

      processed++;

      const triesNow = (item.tries || 0) + 1;

      try {
        // set "in progress" attempt (for debugging)
        await queueUpdate(item.id, {
          lastTryAt: t,
          tries: triesNow, // tentativo in corso
          status: "PENDING",
          error: undefined,
        });

        const res = await executor(item);

        await queueUpdate(item.id, {
          status: "DONE",
          error: undefined,
          nextTryAt: null,
          result: res ?? null,
        });

        done++;
      } catch (e: any) {
        const rawMsg = String(e?.message || "sync error");
        const msg = rawMsg.toLowerCase();

        // ✅ OFFLINE/TIMEOUT -> NON è errore del dato: resta PENDING, non incrementare tries
        if (isOfflineLikeMessage(msg)) {
          await queueUpdate(item.id, {
            status: "PENDING",
            error: undefined,
            lastTryAt: t,
            tries: item.tries || 0, // rollback tries
            nextTryAt: null,
          });

          // Se non c'è rete, ha poco senso continuare con altri
          skipped++;
          break;
        }

        // ❗ errori reali (server/validation ecc.) -> ERROR con backoff
        const nextTryAt = computeNextTryAt(triesNow);

tries: item.tries || 0, // rollback tries
            nextTryAt: null,
          });

          // Se non c'è rete, ha poco senso continuare con altri
          skipped++;
          break;
        }

        // ❗ errori reali (server/validation ecc.) -> ERROR con backoff
        const nextTryAt = computeNextTryAt(triesNow);

        await queueUpdate(item.id, {
          status: "ERROR",
          error: rawMsg,
          lastTryAt: t,
          tries: triesNow,
          nextTryAt,
        });

        errored++;

        if (stopOnError) break;
      }
    }

    return { processed, done, errored, skipped };
  });
}

/**
 * ✅ Helper: flush per progetto (utile in UI “Sync Projekt”)
 */
export async function queueFlushProject(
  projectId: string,
  executor: QueueExecutor,
  options?: Omit<QueueFlushOptions, "fifo"> & { fifo?: boolean }
) {
  const key = normalizeProjectKey(projectId);
  return queueFlush(async (item) => {
    if (item.projectId !== key) return null;
    return executor(item);
  }, options);
}

/**
 * ✅ Helper: check lock (per evitare doppio tap)
 */
export async function queueIsLocked(): Promise<boolean> {
  const lock = await getJson<{ at: number; id: string } | null>(LOCK_KEY, null);
  if (!lock) return false;
  return nowMs() - lock.at < 60000;
}

/**
 * ✅ COMPAT EXPORT (vecchio nome usato dagli screen)
 * queueProcessPending(executor, options) == queueFlush(executor, options)
 */
export async function queueProcessPending(
  executor: QueueExecutor,
  options?: QueueFlushOptions
) {
  return queueFlush(executor, options);
}

// apps/mobile/src/lib/openPdf.ts
import { Alert, Linking, Platform } from "react-native";
import * as IntentLauncher from "expo-intent-launcher";
import * as FileSystem from "expo-file-system"; // ONLY for Android contentUri bridge (no dirs)

function isHttp(u: string) {
  return /^https?:\/\//i.test(u);
}
function isFile(u: string) {
  return /^file:\/\//i.test(u);
}
function isContent(u: string) {
  return /^content:\/\//i.test(u);
}

export async function openPdfUri(rawUri: string) {
  const uri = String(rawUri || "").trim();
  if (!uri) throw new Error("openPdfUri: uri fehlt");

  // iOS: Linking.openURL(file:// or https://) works (Files/iCloud will hand back a readable URL)
  if (Platform.OS === "ios") {
    const ok = await Linking.canOpenURL(uri);
    if (!ok) throw new Error(`Kann PDF nicht öffnen (iOS canOpenURL=false): ${uri}`);
    await Linking.openURL(uri);
    return;
  }

  // Android
  if (Platform.OS === "android") {
    // If it's already a content:// uri -> open via Intent
    if (isContent(uri)) {
      await IntentLauncher.startActivityAsync("android.intent.action.VIEW", {
        data: uri,
        flags: 1, // FLAG_GRANT_READ_URI_PERMISSION
        type: "application/pdf",
      });
      return;
    }

    // If it's file:// uri -> convert to content:// using FileSystem.getContentUriAsync
    if (isFile(uri)) {
      const contentUri = await FileSystem.getContentUriAsync(uri);
      await IntentLauncher.startActivityAsync("android.intent.action.VIEW", {
        data: contentUri,
        flags: 1,
        type: "application/pdf",
      });
      return;
    }

    // If it's https:// -> just open link (system will route)
    if (isHttp(uri)) {
      const ok = await Linking.canOpenURL(uri);
      if (!ok) throw new Error(`Kann URL nicht öffnen: ${uri}`);
      await Linking.openURL(uri);
      return;
    }

    // fallback try
    const ok = await Linking.canOpenURL(uri);
    if (!ok) throw new Error(`Kann URI nicht öffnen: ${uri}`);
    await Linking.openURL(uri);
    return;
  }

  // Other platforms: best-effort
  const ok = await Linking.canOpenURL(uri);
  if (!ok) throw new Error(`Kann URI nicht öffnen: ${uri}`);
  await Linking.openURL(uri);
}

// small wrapper for UI
export async function openPdfOrAlert(uri: string) {
  try {
    await openPdfUri(uri);
  } catch (e: any) {
    Alert.alert("PDF öffnen", e?.message || String(e));
  }
}

// apps/mobile/src/lib/pdfStorage.ts

/**
 * Offline PDF storage (ROBUST for Expo SDK 54+)
 *
 * ✅ Uses legacy async API (getInfoAsync/copyAsync/readDirectoryAsync…)
 * ✅ But resolves base directories via BOTH:
 *   - legacy constants (documentDirectory/cacheDirectory) if present
 *   - new API: Directory.documentDirectory.uri / Directory.cacheDirectory.uri
 *
 * Exposed API:
 * - downloadPdf(projectFsKey, name, absUrl)                  // http/https ONLY
 * - importLocalPdf(projectFsKey, name, localUri)             // file:// or content://
 * - getLocalUri(projectFsKey, name)
 * - isDownloaded(projectFsKey, name)
 * - deletePdf(projectFsKey, name)
 * - listDownloadedPdfs(projectFsKey)
 */

import * as LegacyFS from "expo-file-system/legacy";
import * as FS from "expo-file-system";

/* ============================================================
 * Helpers
 * ============================================================ */

function safeProjectKey(k: string) {
  return String(k || "")
    .trim()
    .replace(/[^\w.\-]+/g, "_")
    .slice(0, 80);
}

function safeFilename(name: string) {
  const n = String(name || "file.pdf").trim();
  const base = n.replace(/[^\w.\-]+/g, "_").slice(0, 160);
  return base.toLowerCase().endsWith(".pdf") ? base : `${base}.pdf`;
}

function ensureTrailingSlash(v: string) {
  return v.endsWith("/") ? v : `${v}/`;
}

/**
 * Base directory robusto:
 * - preferisce documentDirectory
 * - fallback su cacheDirectory
 * - supporta anche SDK 54+ new API
 */
function baseDir(): string {
  const legacyDoc = String((LegacyFS as any).documentDirectory || "");
  const legacyCache = String((LegacyFS as any).cacheDirectory || "");

  const fsDoc = String((FS as any).documentDirectory || "");
  const fsCache = String((FS as any).cacheDirectory || "");

  const dirDoc =
    String((FS as any)?.Directory?.documentDirectory?.uri || "") ||
    String((FS as any)?.Directory?.documentDirectory || "");

  const dirCache =
    String((FS as any)?.Directory?.cacheDirectory?.uri || "") ||
    String((FS as any)?.Directory?.cacheDirectory || "");

  const root =
    legacyDoc.trim() ||
    fsDoc.trim() ||
    dirDoc.trim() ||
    legacyCache.trim() ||
    fsCache.trim() ||
    dirCache.trim();

  if (!root) {
    const keysLegacy = Object.keys(LegacyFS as any).slice(0, 30).join(",");
    const keysFS = Object.keys(FS as any).slice(0, 30).join(",");

    throw new Error(
      `FileSystem directory fehlt (document/cache). ` +
        `legacy.documentDirectory=${String((LegacyFS as any).documentDirectory)} ` +
        `legacy.cacheDirectory=${String((LegacyFS as any).cacheDirectory)} ` +
        `fs.documentDirectory=${String((FS as any).documentDirectory)} ` +
        `fs.cacheDirectory=${String((FS as any).cacheDirectory)} ` +
        `Directory.documentDirectory.uri=${String((FS as any)?.Directory?.documentDirectory?.uri)} ` +
        `Directory.cacheDirectory.uri=${String((FS as any)?.Directory?.cacheDirectory?.uri)} ` +
        `keysLegacy=[${keysLegacy}] keysFS=[${keysFS}]`
    );
  }

  return ensureTrailingSlash(root);
}

async function ensureDir(dirUri: string) {
  try {
    const info: any = await LegacyFS.getInfoAsync(dirUri);
    if (info.exists && info.isDirectory) return;
    if (info.exists && !info.isDirectory) {
      await LegacyFS.deleteAsync(dirUri, { idempotent: true });
    }
  } catch {}
  await LegacyFS.makeDirectoryAsync(dirUri, { intermediates: true });
}

function projectDirPreferred(projectFsKey: string) {
  const k = safeProjectKey(projectFsKey);
  return `${baseDir()}rlc/projects/${k}/pdf/`;
}

function projectDirLegacy(projectFsKey: string) {
  const k = safeProjectKey(projectFsKey);
  return `${baseDir()}rlc_pdfs/${k}/`;
}

function projectDir(projectFsKey: string) {
  return projectDirPreferred(projectFsKey);
}

function fileUriInDir(dir: string, name: string) {
  return `${dir}${safeFilename(name)}`;
}

function isHttpUrl(u: string) {
  return /^https?:\/\//i.test(u);
}
function isFileUrl(u: string) {
  return /^file:\/\//i.test(u);
}
function isContentUrl(u: string) {
  return /^content:\/\//i.test(u);
}

/* ============================================================
 * Types
 * ============================================================ */

export type PdfMetaItem = {
  name: string;
  uri: string;
  size?: number;
  mtime?: string;
};

/* ============================================================
 * Internal helpers
 * ============================================================ */

async function ensureProjectDirs(projectFsKey: string) {
  const d1 = projectDirPreferred(projectFsKey);
  const d2 = projectDirLegacy(projectFsKey);

  await ensureDir(d1);
  await ensureDir(d2);

  try {
    const root = baseDir();
    await ensureDir(`${root}rlc/`);
    await ensureDir(`${root}rlc/projects/`);
    await ensureDir(`${root}rlc/projects/${safeProjectKey(projectFsKey)}/`);
    await ensureDir(`${root}rlc/projects/${safeProjectKey(projectFsKey)}/pdf/`);
    await ensureDir(`${root}rlc_pdfs/`);
  } catch {}
}

async function infoIfFile(uri: string) {
  try {
    const info: any = await LegacyFS.getInfoAsync(uri);
    if (!info?.exists || info?.isDirectory) return null;
    return info;
  } catch {
    return null;
  }
}

async function findExistingLocal(
  projectFsKey: string,
  name: string
): Promise<string | null> {
  const safeName = safeFilename(name);

  const preferred = fileUriInDir(projectDirPreferred(projectFsKey), safeName);

} catch {
    return null;
  }
}

async function findExistingLocal(
  projectFsKey: string,
  name: string
): Promise<string | null> {
  const safeName = safeFilename(name);

  const preferred = fileUriInDir(projectDirPreferred(projectFsKey), safeName);
  const legacy = fileUriInDir(projectDirLegacy(projectFsKey), safeName);

  const i1 = await infoIfFile(preferred);
  if (i1) return preferred;

  const i2 = await infoIfFile(legacy);
  if (i2) return legacy;

  return null;
}

/* ============================================================
 * API
 * ============================================================ */

export async function listDownloadedPdfs(
  projectFsKey: string
): Promise<PdfMetaItem[]> {
  await ensureProjectDirs(projectFsKey);

  const preferredDir = projectDirPreferred(projectFsKey);
  const legacyDir = projectDirLegacy(projectFsKey);

  const allNames = new Set<string>();

  try {
    const pInfo: any = await LegacyFS.getInfoAsync(preferredDir);
    if (pInfo.exists && pInfo.isDirectory) {
      const pn = await LegacyFS.readDirectoryAsync(preferredDir);
      pn.forEach((x) => allNames.add(String(x || "").trim()));
    }
  } catch {}

  try {
    const lInfo: any = await LegacyFS.getInfoAsync(legacyDir);
    if (lInfo.exists && lInfo.isDirectory) {
      const ln = await LegacyFS.readDirectoryAsync(legacyDir);
      ln.forEach((x) => allNames.add(String(x || "").trim()));
    }
  } catch {}

  const out: PdfMetaItem[] = [];

  for (const raw of Array.from(allNames)) {
    const name = String(raw || "").trim();
    if (!name) continue;

    const uriPreferred = `${preferredDir}${name}`;
    const uriLegacy = `${legacyDir}${name}`;

    const infoP = await infoIfFile(uriPreferred);
    const info = infoP || (await infoIfFile(uriLegacy));
    if (!info) continue;

    const mt =
      typeof info?.modificationTime === "number"
        ? new Date(info.modificationTime * 1000).toISOString()
        : undefined;

    out.push({
      name,
      uri: infoP ? uriPreferred : uriLegacy,
      size: typeof info?.size === "number" ? info.size : undefined,
      mtime: mt,
    });
  }

  out.sort((a, b) => {
    const ta = a.mtime ? Date.parse(a.mtime) : 0;
    const tb = b.mtime ? Date.parse(b.mtime) : 0;
    if (tb !== ta) return tb - ta;
    return String(a.name).localeCompare(String(b.name));
  });

  return out;
}

export async function getLocalUri(
  projectFsKey: string,
  name: string
): Promise<string | null> {
  const uri = await findExistingLocal(projectFsKey, name);
  return uri || null;
}

export async function isDownloaded(
  projectFsKey: string,
  name: string
): Promise<boolean> {
  const uri = await findExistingLocal(projectFsKey, name);
  return !!uri;
}

export async function deletePdf(
  projectFsKey: string,
  name: string
): Promise<void> {
  const safeName = safeFilename(name);

  const preferred = fileUriInDir(projectDirPreferred(projectFsKey), safeName);
  const legacy = fileUriInDir(projectDirLegacy(projectFsKey), safeName);

  try {
    await LegacyFS.deleteAsync(preferred, { idempotent: true });
  } catch {}
  try {
    await LegacyFS.deleteAsync(legacy, { idempotent: true });
  } catch {}
}

export async function downloadPdf(
  projectFsKey: string,
  name: string,
  absUrl: string
): Promise<string> {
  const url = String(absUrl || "").trim();
  if (!isHttpUrl(url)) {
    throw new Error("downloadPdf: URL muss http/https sein");
  }

  await ensureProjectDirs(projectFsKey);

  const dir = projectDirPreferred(projectFsKey);
  const target = fileUriInDir(dir, name);

  try {
    await LegacyFS.deleteAsync(target, { idempotent: true });
  } catch {}

  const dl = LegacyFS.createDownloadResumable(url, target, {});
  const res = await dl.downloadAsync();

  const savedUri = String((res as any)?.uri || target);
  const info = await infoIfFile(savedUri);
  if (!info) throw new Error("Download fehlgeschlagen (Datei nicht vorhanden)");

  return savedUri;
}

export async function importLocalPdf(
  projectFsKey: string,
  name: string,
  localUri: string
): Promise<{ uri: string; name: string }> {
  const src = String(localUri || "").trim();
  if (!src) throw new Error("importLocalPdf: localUri fehlt");

  await ensureProjectDirs(projectFsKey);

  const safeName = safeFilename(name);
  const dir = projectDirPreferred(projectFsKey);
  const target = fileUriInDir(dir, safeName);

  try {
    await deletePdf(projectFsKey, safeName);
  } catch {}

  try {
    await LegacyFS.copyAsync({ from: src, to: target });
  } catch (e1: any) {
    const Enc = (LegacyFS as any).EncodingType || (FS as any).EncodingType;

    try {
      const b64 = await LegacyFS.readAsStringAsync(src, {
        encoding: Enc.Base64,
      });
      await LegacyFS.writeAsStringAsync(target, b64, {
        encoding: Enc.Base64,
      });
    } catch (e2: any) {
      throw new Error(
        `PDF Import fehlgeschlagen: ${
          e2?.message || e1?.message || String(e2 || e1)
        }`
      );
    }
  }

  const info = await infoIfFile(target);
  if (!info) throw new Error("PDF Import: Datei wurde nicht gespeichert");

  return {
    uri: target,
    name: safeName,
  };
}

// apps/mobile/src/lib/queueExecutor.ts
import type { QueueItem } from "./offlineQueue";
import { api } from "./api";

/**
 * Executor unico per queueProcessPending / queueFlush
 * IMPORTANTE:
 * - usa payload.row quando presente (è il record completo)
 * - altrimenti usa payload come “row”
 */
export async function rlcQueueExecutor(item: QueueItem) {
  const row = (item as any)?.payload?.row ?? (item as any)?.payload ?? {};

  switch (item.kind) {
    case "REGIE":
      return api.pushRegieToServer(item.projectId, row);

    case "LIEFERSCHEIN":
      return api.pushLieferscheinToServer(item.projectId, row);

    case "PHOTO_NOTE":
    case "FOTOS_NOTIZEN":
      return api.pushPhotosToServer(item.projectId, row);

    default:
      throw new Error(`Unknown queue kind: ${(item as any).kind}`);
  }
}

export type RlcRegieParsed = {
  datum?: string;
  baustelle?: string;
  wetter?: string;
  taetigkeit?: string;
  mitarbeiter?: { name: string; hours: string }[];
  geraete?: { name: string; hours: string }[];
  material?: { name: string; quantity: string; unit: string }[];
  bemerkung?: string;
  warnings?: string[];
};

export type RlcLieferscheinParsed = {
