function normalizeRowPositions(rows: RlcSmartRow[]) {
  const seen = new Set<string>();
  let hasDuplicate = false;

  for (const r of rows) {
    const p = clean(r.pos);
    if (p && seen.has(p)) {
      hasDuplicate = true;
      break;
    }
    if (p) seen.add(p);
  }

  if (!hasDuplicate) return rows;

  return rows.map((r, i) => ({
    ...r,
    pos: String(i + 1),
  }));
}

function parseQtyUnit(v: string) {
  const s = clean(v);
  const m = s.match(/([\d.,]+)\s*(m²|m2|m³|m3|m|stk|st|stück|stueck|psch|h|std|to|t|kg|lfm)?/i);
  return {
    qty: m?.[1] ? normNum(m[1]) : "",
    unit: m?.[2] ? normalizeUnit(m[2]) : "",
  };
}

function parseMoneyLabel(line: string) {
  const m = line.match(/(?:ep|einzelpreis|e-preis|preis|gp|gesamtpreis|gesamt|betrag)\s*[:=\-]?\s*([\d.,]+)\s*€?/i);
  return m?.[1] ? normNum(m[1]) : "";
}

function looksLikeOnlyPos(line: string) {
  return /^(?:pos\.?\s*)?\d+[\w.]*$/i.test(clean(line));
}

function parseOnlyPos(line: string) {
  return clean(line).replace(/^pos\.?\s*/i, "");
}

function isFieldLineForOcr(line: string) {
  return /^(menge|einheit|ep|einzelpreis|e-preis|gp|gesamtpreis|gesamt|betrag|text|kurztext|leistung|beschreibung)\s*[:=\-]?/i.test(clean(line));
}

function parseOcrBlockRows(input: string): RlcSmartRow[] {
  const rawLines = input
    .split(/\r?\n/)
    .map((x) => x.trim())
    .filter(Boolean);

  const rows: RlcSmartRow[] = [];

  let cur: any = null;

  function ensure() {
    if (!cur) cur = { pos: "", textParts: [], qty: "", unit: "", ep: "", gp: "" };
    return cur;
  }

  function flush() {
    if (!cur) return;

    const text = clean((cur.textParts || []).join(" "));
    const row = makeRow(
      cur.pos || String(rows.length + 1),
      text,
      cur.qty,
      cur.unit,
      cur.ep,
      cur.gp
    );

    if (row && (row.text || row.qty || row.ep || row.gp)) {
      rows.push(row);
    }

    cur = null;
  }

  for (const lineRaw of rawLines) {
    const line = clean(lineRaw.replace(/\s+/g, " "));
    if (!line) continue;

    // normale Formularfelder überspringen
    if (/^\s*(kunde|auftraggeber|firma|adresse|anschrift|email|e-mail|mail|telefon|tel|baustelle|projekt|bauvorhaben|titel|angebot|rechnung|betreff|datum|leistungszeitraum)\s*[:=]/i.test(line)) {
      continue;
    }

    // nuova posizione: "001" oppure "Pos 001"
    if (looksLikeOnlyPos(line)) {
      if (cur && (cur.textParts?.length || cur.qty || cur.ep || cur.gp)) flush();
      cur = { pos: parseOnlyPos(line), textParts: [], qty: "", unit: "", ep: "", gp: "" };
      continue;
    }

    // Text / Kurztext / Leistung
    let m = line.match(/^(?:text|kurztext|leistung|beschreibung)\s*[:=\-]\s*(.+)$/i);
    if (m) {
      ensure().textParts.push(clean(m[1]));
      continue;
    }

    // Menge: 25 m oppure Menge 25,00
    m = line.match(/^menge\s*[:=\-]?\s*(.+)$/i);
    if (m) {
      const q = parseQtyUnit(m[1]);
      ensure().qty = q.qty || ensure().qty;
      ensure().unit = q.unit || ensure().unit;
      continue;
    }

    // Einheit: m
    m = line.match(/^einheit\s*[:=\-]?\s*(.+)$/i);
    if (m) {
      const u = clean(m[1]).split(/\s+/)[0];
      if (isUnit(u)) ensure().unit = normalizeUnit(u);
      continue;
    }

    // EP / Einzelpreis
    m = line.match(/^(?:ep|einzelpreis|e-preis|preis)\s*[:=\-]?\s*(.+)$/i);
    if (m) {
      ensure().ep = normNum(m[1]);
      continue;
    }

    // GP / Gesamtpreis / Betrag
    m = line.match(/^(?:gp|gesamtpreis|gesamt|betrag)\s*[:=\-]?\s*(.+)$/i);
    if (m) {
      ensure().gp = normNum(m[1]);
      continue;
    }

    // fallback: se siamo dentro una posizione OCR, riga libera = testo
    if (cur && !isFieldLineForOcr(line)) {
      cur.textParts.push(line);
      continue;
    }
  }

  flush();

  return rows;
}

function mergeRows(primary: RlcSmartRow[], secondary: RlcSmartRow[]) {
  const out: RlcSmartRow[] = [];

  function key(r: RlcSmartRow) {
    return [
      clean(r.pos),
      clean(r.text).toLowerCase(),
      clean(r.qty),
      clean(r.unit).toLowerCase(),
      clean(r.ep),
      clean(r.gp || ""),
    ].join("|");
  }

  const seen = new Set<string>();

  for (const r of [...primary, ...secondary]) {
    const k = key(r);
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(r);
  }

  return out;
}

function sortRowsByPos(rows: RlcSmartRow[]) {
  const allHaveNumericPos = rows.every((r) => /^\d+([.,]\d+)?$/i.test(clean(r.pos)));
  if (!allHaveNumericPos) return rows;

  return [...rows].sort((a, b) => {
    const na = Number(String(a.pos).replace(",", "."));

out.push(r);
  }

  return out;
}

function sortRowsByPos(rows: RlcSmartRow[]) {
  const allHaveNumericPos = rows.every((r) => /^\d+([.,]\d+)?$/i.test(clean(r.pos)));
  if (!allHaveNumericPos) return rows;

  return [...rows].sort((a, b) => {
    const na = Number(String(a.pos).replace(",", "."));
    const nb = Number(String(b.pos).replace(",", "."));
    if (!Number.isFinite(na) || !Number.isFinite(nb)) return 0;
    return na - nb;
  });
}

function parseRows(input: string): RlcSmartRow[] {
  const lines = input
    .split(/\r?\n/)
    .map((x) => x.trim())
    .filter(Boolean);

  const rows: RlcSmartRow[] = [];

  for (const line of lines) {
    // Skip field lines
    if (/^\s*(kunde|auftraggeber|firma|adresse|anschrift|email|e-mail|mail|telefon|tel|baustelle|projekt|bauvorhaben|titel|angebot|rechnung|betreff|datum|leistungszeitraum)\s*[:=]/i.test(line)) {
      continue;
    }

    const row = parseLine(line, rows.length + 1);
    if (row) rows.push(row);
  }

  const ocrRows = parseOcrBlockRows(input);
  return normalizeRowPositions(sortRowsByPos(mergeRows(rows, ocrRows)));
}

function validateSmartDoc(doc: RlcSmartDoc) {
  const warnings: string[] = [];

  if (!doc.customerName) warnings.push("Kunde/Auftraggeber fehlt.");
  if (!doc.baustelle && !doc.title) warnings.push("Baustelle/Titel fehlt.");
  if (!doc.rows.length) warnings.push("Keine Positionen erkannt.");

  doc.rows.forEach((r, i) => {
    const label = r.pos || String(i + 1);
    if (!r.text) warnings.push(`Position ${label}: Text fehlt.`);
    if (!r.qty) warnings.push(`Position ${label}: Menge fehlt.`);
    if (!r.unit) warnings.push(`Position ${label}: Einheit fehlt.`);
    if (!r.ep) warnings.push(`Position ${label}: EP fehlt.`);
  });

  return warnings;
}

export function parseRlcKiSmartDoc(inputRaw: any): RlcSmartDoc {
  const input = clean(inputRaw);

  const doc: RlcSmartDoc = {
    title: pickField(input, ["titel", "angebot", "rechnung", "betreff"]),
    customerName: pickField(input, ["kunde", "auftraggeber", "firma", "name"]),
    address: pickField(input, ["adresse", "anschrift"]),
    email: pickField(input, ["email", "e-mail", "mail"]),
    phone: pickField(input, ["telefon", "tel", "phone"]),
    baustelle: pickField(input, ["baustelle", "projekt", "bauvorhaben"]),
    datum: parseDate(input),
    leistungszeitraum: parsePeriod(input),
    rechnungNr: pickField(input, ["rechnungsnummer", "rechnungnr", "rechnung-nr", "rechnung nr"]),
    angebotNr: pickField(input, ["angebotsnummer", "angebotnr", "angebot-nr", "angebot nr"]),
    note: input,
    rows: parseRows(input),
  };

  doc.warnings = validateSmartDoc(doc);
  return doc;
}

import AsyncStorage from "@react-native-async-storage/async-storage";
import { logout } from "./auth";

const SERVER_PROFILE_KEY = "rlc_verified_server_profile_v1";

export type RlcServerProfile = {
  serverId: string;
  serverName: string;
  companyCode?: string;
  apiUrl: string;
  aiMode?: "HYBRID" | "LOCAL" | "OPENAI";
  capabilities?: string[];
  verifiedAt: string;
  source: "qr" | "cloud";
};

type PairingQr = {
  type: "RLC_SERVER_PAIRING";
  version: 1;
  apiUrl: string;
  token: string;
};

function clean(value: unknown): string {
  return String(value ?? "").trim();
}

function normalizeApiUrl(input: string): string {
  const value = clean(input).replace(/\/$/, "");
  if (!/^https?:\/\//i.test(value)) {
    throw new Error("Die Server-URL ist ungültig.");
  }

  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error("Die Server-URL ist ungültig.");
  }

  const local = ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
  const isDev = typeof __DEV__ !== "undefined" ? __DEV__ : false;
  if (parsed.protocol !== "https:" && !local && !isDev) {
    throw new Error("Private Server müssen über HTTPS erreichbar sein.");
  }

  return parsed.toString().replace(/\/$/, "");
}

function parsePairingQr(rawValue: string): PairingQr {
  let value: any;
  try {
    value = JSON.parse(clean(rawValue));
  } catch {
    throw new Error("Dieser QR-Code gehört nicht zu RLC Bausoftware.");
  }

  if (
    value?.type !== "RLC_SERVER_PAIRING" ||
    Number(value?.version) !== 1 ||
    !clean(value?.token)
  ) {
    throw new Error("RLC Server-QR ungültig oder nicht unterstützt.");
  }

  return {
    type: "RLC_SERVER_PAIRING",
    version: 1,
    apiUrl: normalizeApiUrl(value.apiUrl),
    token: clean(value.token),
  };
}

async function fetchJsonWithTimeout(
  url: string,
  init: RequestInit = {},
  timeoutMs = 20_000
) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(url, { ...init, signal: controller.signal });
    const data = await response.json().catch(() => null);
    if (!response.ok) {
      throw new Error(clean(data?.error || data?.message) || `HTTP ${response.status}`);
    }
    return data;
  } finally {
    clearTimeout(timer);
  }
}

function profileFromServer(value: any, source: "qr" | "cloud"): RlcServerProfile {
  const serverId = clean(value?.serverId);
  const serverName = clean(value?.serverName) || "RLC Server";
  const apiUrl = normalizeApiUrl(value?.apiUrl);
  if (!serverId) throw new Error("Der Server hat keine gültige RLC Server-ID.");

  const aiMode = clean(value?.aiMode).toUpperCase();
  return {
    serverId,
    serverName,
    companyCode: clean(value?.companyCode) || undefined,
    apiUrl,
    aiMode:
      aiMode === "LOCAL" || aiMode === "OPENAI" || aiMode === "HYBRID"
        ? (aiMode as RlcServerProfile["aiMode"])
        : undefined,
    capabilities: Array.isArray(value?.capabilities)
      ? value.capabilities.map(clean).filter(Boolean)
      : [],
    verifiedAt: clean(value?.verifiedAt) || new Date().toISOString(),
    source,
  };
}

async function persistVerifiedProfile(profile: RlcServerProfile) {
  const previous = await getServerProfile();
  const changed =
    !!previous &&
    (previous.serverId !== profile.serverId || previous.apiUrl !== profile.apiUrl);

  if (changed) {
    // A JWT from server A must never be sent to server B.
    await logout("SERVER_SYNC");
  }

  await AsyncStorage.setItem(SERVER_PROFILE_KEY, JSON.stringify(profile));
  return profile;
}

export async function getServerProfile(): Promise<RlcServerProfile | null> {
  try {
    const raw = await AsyncStorage.getItem(SERVER_PROFILE_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    return profileFromServer(parsed, parsed?.source === "cloud" ? "cloud" : "qr");
  } catch {
    return null;
  }
}

export async function getVerifiedServerApiUrl(): Promise<string | null> {
  const profile = await getServerProfile();
  return profile?.apiUrl || null;
}

export async function verifyAndSavePairingQr(
  qrValue: string
): Promise<RlcServerProfile> {
  const qr = parsePairingQr(qrValue);
  const result = await fetchJsonWithTimeout(`${qr.apiUrl}/api/enterprise/pairing/verify`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Accept: "application/json" },
    body: JSON.stringify({ token: qr.token }),
  });

  if (result?.ok !== true || result?.verified !== true) {
    throw new Error("Der RLC Server konnte den QR-Code nicht bestätigen.");
  }

  const profile = profileFromServer(result.profile, "qr");
  if (profile.apiUrl !== qr.apiUrl) {
    throw new Error("Server-URL und QR-Code stimmen nicht überein.");
  }
  return persistVerifiedProfile(profile);
}

export async function verifyAndSaveCloudServer(
  cloudApiUrl: string
): Promise<RlcServerProfile> {
  const apiUrl = normalizeApiUrl(cloudApiUrl);
  const result = await fetchJsonWithTimeout(`${apiUrl}/api/enterprise/identity`, {
    headers: { Accept: "application/json" },
  });
  if (result?.ok !== true || result?.type !== "RLC_SERVER_IDENTITY") {
    throw new Error("Die RLC Cloud konnte nicht verifiziert werden.");
  }
  const profile = profileFromServer(result, "cloud");
  if (profile.apiUrl !== apiUrl) {
    throw new Error("Die RLC Cloud meldet eine andere Server-URL.");
  }
  return persistVerifiedProfile(profile);
}

