import AsyncStorage from "@react-native-async-storage/async-storage";
import { Platform } from "react-native";
import * as FileSystem from "expo-file-system/legacy";
import * as ImageManipulator from "expo-image-manipulator";
import { getApiUrl } from "./api";

/** ============================================================
 * JSON storage (unchanged)
 * ============================================================ */

export async function getJson<T>(key: string, fallback: T): Promise<T> {
  const raw = await AsyncStorage.getItem(key);
  if (!raw) return fallback;
  try {
    return JSON.parse(raw) as T;
  } catch {
    return fallback;
  }
}

export async function setJson<T>(key: string, value: T) {
  await AsyncStorage.setItem(key, JSON.stringify(value));
}

export function uid(prefix = "id") {
  return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

export function todayISO() {
  const d = new Date();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${d.getFullYear()}-${mm}-${dd}`;
}

/** ============================================================
 * File persistence helpers (NEW)
 * Goal: never store content:// or ph:// in JSON/queue -> always file://
 * ============================================================ */

function normDir(d: string) {
  return d.endsWith("/") ? d : d + "/";
}

export function safeName(name: string) {
  return String(name || "file")
    .replace(/[^\w.\-() ]+/g, "_")
    .replace(/\s+/g, "_")
    .slice(0, 180);
}

function isFileUri(u?: string) {
  return typeof u === "string" && u.startsWith("file://");
}
function isContentUri(u?: string) {
  return typeof u === "string" && u.startsWith("content://");
}
function isIosAssetUri(u?: string) {
  return (
    typeof u === "string" &&
    (u.startsWith("ph://") || u.startsWith("assets-library://"))
  );
}
function isHttpUrl(u?: string) {
  return typeof u === "string" && /^https?:\/\//i.test(u);
}
function isProjectsPath(u?: string) {
  return typeof u === "string" && u.startsWith("/projects/");
}

function extFromNameOrType(name?: string, type?: string, uri?: string) {
  const n = String(name || "").toLowerCase();
  const t = String(type || "").toLowerCase();
  const u = String(uri || "").toLowerCase();

  if (t.includes("pdf") || n.endsWith(".pdf") || u.endsWith(".pdf")) return "pdf";
  if (t.includes("png") || n.endsWith(".png") || u.endsWith(".png")) return "png";
  if (t.includes("webp") || n.endsWith(".webp") || u.endsWith(".webp")) return "webp";
  if (t.includes("heic") || n.endsWith(".heic") || u.endsWith(".heic")) return "heic";
  if (t.includes("heif") || n.endsWith(".heif") || u.endsWith(".heif")) return "heif";
  if (t.includes("jpeg") || n.endsWith(".jpeg") || u.endsWith(".jpeg")) return "jpeg";
  if (t.includes("jpg") || n.endsWith(".jpg") || u.endsWith(".jpg")) return "jpg";

  // default
  return "jpg";
}

function mimeFromExt(ext: string) {
  const e = String(ext || "").toLowerCase();
  if (e === "png") return "image/png";
  if (e === "webp") return "image/webp";
  if (e === "heic" || e === "heif") return "image/heic";
  if (e === "pdf") return "application/pdf";
  return "image/jpeg";
}

export async function ensureDir(dir: string) {
  const d = normDir(dir);
  const info = await FileSystem.getInfoAsync(d);
  if (!info.exists) {
    await FileSystem.makeDirectoryAsync(d, { intermediates: true });
  }
}

export function getBaseDirOrThrow(): string {
  if (Platform.OS === "web") {
    throw new Error("FS not available on web");
  }
  const base = FileSystem.documentDirectory || FileSystem.cacheDirectory;
  if (!base) throw new Error("No FileSystem base dir");
  return normDir(base);
}

async function getApiBaseUrlFromStorage(): Promise<string> {
  return getApiUrl();
}

/**
 * ✅ Persist ANY uri into a stable file:// in cache tmp/
 * Handles:
 * - content:// (Android)
 * - ph:// / assets-library:// (iOS Photos)
 * - HEIC/HEIF conversion to JPEG (best effort)
 * - http(s) or /projects/... download to cache
 */
export async function persistUriToCache(params: {
  uri: string;
  nameHint?: string;
  typeHint?: string;
}): Promise<{ uri: string; name?: string; type?: string }> {
  const input = String(params.uri || "").trim();
  if (!input) return { uri: "" };

  // already stable
  if (isFileUri(input)) {
    const ext0 = extFromNameOrType(params.nameHint, params.typeHint, input);
    return {
      uri: input,
      name: params.nameHint || `file.${ext0}`,
      type: params.typeHint || mimeFromExt(ext0),
    };
  }

  const base = getBaseDirOrThrow();
  const tmpDir = `${base}tmp/`;
  await ensureDir(tmpDir);

  // 1) remote URL or server /projects/... -> download
  if (isHttpUrl(input) || isProjectsPath(input)) {
    const apiBase = await getApiBaseUrlFromStorage();
    const abs = isHttpUrl(input) ? input : `${apiBase}${input}`;

    const ext = extFromNameOrType(params.nameHint, params.typeHint, abs);
    const target = `${tmpDir}${Date.now()}_${Math.floor(Math.random() * 1e9)}.${ext}`;

    try {
      const dl = await FileSystem.downloadAsync(abs, target);
      const finalUri = dl?.uri || target;
      return {
        uri: finalUri,
        name: params.nameHint || safeName(`download.${ext}`),
        type: params.typeHint || mimeFromExt(ext),
      };
    } catch (e: any) {
      // fallback: keep abs (might fail later but don’t crash here)
      return {
        uri: abs,

try {
      const dl = await FileSystem.downloadAsync(abs, target);
      const finalUri = dl?.uri || target;
      return {
        uri: finalUri,
        name: params.nameHint || safeName(`download.${ext}`),
        type: params.typeHint || mimeFromExt(ext),
      };
    } catch (e: any) {
      // fallback: keep abs (might fail later but don’t crash here)
      return {
        uri: abs,
        name: params.nameHint,
        type: params.typeHint,
      };
    }
  }

  // 2) content:// -> copy to tmp
  if (isContentUri(input)) {
    const ext = extFromNameOrType(params.nameHint, params.typeHint, input);
    const target = `${tmpDir}${Date.now()}_${Math.floor(Math.random() * 1e9)}.${ext}`;
    await FileSystem.copyAsync({ from: input, to: target });
    return {
      uri: target.startsWith("file://") ? target : `file://${target}`,
      name: params.nameHint || safeName(`file.${ext}`),
      type: params.typeHint || mimeFromExt(ext),
    };
  }

  // 3) iOS Photos (ph://) or HEIC/HEIF -> convert to JPEG in tmp
  const low = input.toLowerCase();
  const looksHeic =
    low.endsWith(".heic") ||
    low.endsWith(".heif") ||
    String(params.typeHint || "").toLowerCase().includes("heic") ||
    String(params.nameHint || "").toLowerCase().endsWith(".heic") ||
    String(params.nameHint || "").toLowerCase().endsWith(".heif");

  if (isIosAssetUri(input) || looksHeic) {
    const outName = `${Date.now()}_${Math.floor(Math.random() * 1e9)}.jpg`;
    const outPath = `${tmpDir}${outName}`;

    // ImageManipulator returns a file:// uri (usually inside cache already)
    // We still copy to our tmp path to make it predictable.
    const tries = [
      { width: 1400, compress: 0.9 },
      { width: 1000, compress: 0.85 },
    ];

    for (const t of tries) {
      try {
        const res = await ImageManipulator.manipulateAsync(
          input,
          [{ resize: { width: t.width } }],
          { compress: t.compress, format: ImageManipulator.SaveFormat.JPEG }
        );

        // res.uri is file://... -> copy to our outPath
        if (res?.uri) {
          await FileSystem.copyAsync({ from: res.uri, to: outPath });
          return {
            uri: outPath,
            name: params.nameHint || safeName("image.jpg"),
            type: "image/jpeg",
          };
        }
      } catch {
        // try next
      }
    }

    // total failure -> keep original (caller can decide)
    return {
      uri: input,
      name: params.nameHint,
      type: params.typeHint,
    };
  }

  // 4) unknown scheme -> keep as-is
  const ext = extFromNameOrType(params.nameHint, params.typeHint, input);
  return {
    uri: input,
    name: params.nameHint || `file.${ext}`,
    type: params.typeHint || mimeFromExt(ext),
  };
}

/**
 * ✅ Persist a uri into a STABLE project folder:
 * projects/<projectFsKey>/<relativeDir>/
 * Returns a file:// uri suitable for JSON/queue.
 */
export async function persistUriToProject(params: {
  projectFsKey: string;          // BA-...
  relativeDir: string;           // e.g. "inbox/fotos/<docId>/files"
  uri: string;
  nameHint?: string;
  typeHint?: string;
}): Promise<{ uri: string; name: string; type: string }> {
  const projectFsKey = String(params.projectFsKey || "").trim();
  if (!projectFsKey) throw new Error("persistUriToProject: projectFsKey missing");

  const base = getBaseDirOrThrow();
  const rel = String(params.relativeDir || "").replace(/^\/+/, "").replace(/\/+$/, "");
  const dir = `${base}projects/${projectFsKey}/${rel}/`;
  await ensureDir(dir);

  // 1) ensure local cache first (so we never copy content:// / ph:// directly into project)
  const cached = await persistUriToCache({
    uri: params.uri,
    nameHint: params.nameHint,
    typeHint: params.typeHint,
  });

  const src = String(cached.uri || "").trim();
  if (!src) throw new Error("persistUriToProject: source uri empty");

  // If still not file://, we cannot guarantee persistence (remote kept) -> fail hard
  if (!isFileUri(src) && !src.startsWith(getBaseDirOrThrow())) {
    throw new Error(`persistUriToProject: non-local uri not supported: ${src}`);
  }

  const ext = extFromNameOrType(cached.name, cached.type, src);
  const finalName = safeName(cached.name || `file.${ext}`);
  const target = `${dir}${finalName}`;

  // overwrite safe
  const info = await FileSystem.getInfoAsync(target);
  if (info.exists) {
    try {
      await FileSystem.deleteAsync(target, { idempotent: true });
    } catch {}
  }

  await FileSystem.copyAsync({ from: src, to: target });

  return {
    uri: target.startsWith("file://") ? target : `file://${target}`,
    name: finalName,
    type: cached.type || mimeFromExt(ext),
  };
}

import AsyncStorage from "@react-native-async-storage/async-storage";

import { queueAdd } from "./offlineQueue";
import { syncAll } from "./sync";

export type EingangDocType =
  | "REGIE"
  | "LIEFERSCHEIN"
  | "FOTO"
  | "TAGESBERICHT"
  | "BAUTAGEBUCH"
  | "ANGEBOT"
  | "RECHNUNG"
  | "MENGENERMITTLUNG"
  | "ABSCHLAGSRECHNUNG"
  | "KALKULATION";

export type EingangStatus =
  | "DRAFT"
  | "EINGEREICHT"
  | "IN_PRUEFUNG"
  | "FREIGEGEBEN"
  | "ABGELEHNT"
  | "ARCHIVIERT";

function keyFor(type: EingangDocType, projectKey: string) {
  const k = String(projectKey || "unknown").trim();

  switch (type) {
    case "REGIE":
      return `rlc_mobile_inbox_regie:${k}`;
    case "LIEFERSCHEIN":
      return `rlc_mobile_inbox_lieferschein:${k}`;
    case "FOTO":
      return `rlc_mobile_inbox_fotos:${k}`;
    case "TAGESBERICHT":
      return `rlc_mobile_inbox_tagesbericht:${k}`;
    case "BAUTAGEBUCH":
      return `rlc_mobile_inbox_bautagebuch:${k}`;
    case "ANGEBOT":
      return `rlc_mobile_inbox_angebot:${k}`;
    case "RECHNUNG":
      return `rlc_mobile_inbox_rechnung:${k}`;
    case "MENGENERMITTLUNG":
      return `rlc_mobile_inbox_mengen:${k}`;
    case "ABSCHLAGSRECHNUNG":
      return `rlc_mobile_inbox_abschlag:${k}`;
    case "KALKULATION":
      return `rlc_mobile_inbox_kalkulation:${k}`;
    default:
      return `rlc_mobile_inbox_misc:${k}`;
  }
}

async function readArray(key: string): Promise<any[]> {
  try {
    const raw = await AsyncStorage.getItem(key);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

async function writeArray(key: string, arr: any[]) {
  await AsyncStorage.setItem(key, JSON.stringify(arr || []));
}

function upsertById(list: any[], row: any) {
  const id = String(row?.id || row?.docId || "").trim();
  if (!id) return [row, ...list];

  const idx = list.findIndex((x) => String(x?.id || x?.docId || "") === id);
  if (idx >= 0) {
    const next = [...list];
    next[idx] = { ...next[idx], ...row };
    return next;
  }

  return [row, ...list];
}

export async function submitToEingangPruefung(params: {
  type: EingangDocType;
  projectKey: string;
  projectId?: string;
  projectCode?: string;
  title?: string;
  doc?: any;
  pdfUri?: string | null;
  status?: EingangStatus;
  sourceScreen?: string;
}) {
  const now = Date.now();
  const type = params.type;
  const projectKey = String(params.projectKey || params.projectCode || params.projectId || "unknown").trim();
  const doc = params.doc || {};

  const row = {
    ...doc,
    id: String(doc?.id || doc?.docId || `${type.toLowerCase()}_${now}`),
    docId: String(doc?.docId || doc?.id || `${type.toLowerCase()}_${now}`),
    docType: type,
    type,
    kind: String(type).toLowerCase(),
    projectId: String(params.projectId || doc?.projectId || projectKey),
    projectCode: String(params.projectCode || doc?.projectCode || projectKey),
    title: String(params.title || doc?.title || doc?.angebotTitle || doc?.rechnungNr || type),
    pdfUri: params.pdfUri ?? doc?.pdfUri ?? null,
    workflowStatus: params.status || doc?.workflowStatus || "EINGEREICHT",
    submittedAt: Number(doc?.submittedAt || now),
    createdAt: Number(doc?.createdAt || now),
    updatedAt: now,
    sourceScreen: params.sourceScreen || doc?.sourceScreen || type,
  };

  const modeRaw =
    (await AsyncStorage.getItem("rlc_mobile_mode")) ||
    (await AsyncStorage.getItem("rlc_app_mode_v1")) ||
    "SERVER_SYNC";

  if (modeRaw !== "NUR_APP") {
    const kind = type === "FOTO" ? "PHOTO_NOTE" : type;
    await queueAdd({
      kind: kind as any,
      projectId: projectKey,
      payload: { row },
    } as any);

    // Best effort: senza rete il documento rimane PENDING nella coda.
    try {
      await syncAll({ projectCode: projectKey });
    } catch {}
    return row;
  }

  const primaryKey = keyFor(type, projectKey);
  const allKey = `rlc_mobile_inbox_all:${projectKey}`;

  const primary = await readArray(primaryKey);
  await writeArray(primaryKey, upsertById(primary, row));

  const all = await readArray(allKey);
  await writeArray(allKey, upsertById(all, row));

  return row;
}

// apps/mobile/src/lib/submitUnified.ts
import { Alert } from "react-native";
import { queueAdd, queueProcessPending, type QueueItem } from "./offlineQueue";

export async function submitDraftUnified(opts: {
  docType: "REGIE" | "LIEFERSCHEIN" | "FOTOS_NOTIZEN" | "PHOTOS" | "PHOTO_NOTE";
  projectFsKey: string; // BA-...
  projectTitle?: string;
  row: any;
  ensureSavedOffline: () => Promise<any>;
  silent?: boolean;
}) {
  const pk = String(opts.projectFsKey || "").trim();

  // 1) assicurati che esista un draft offline (ritorna LocalRow)
  const savedRow = await opts.ensureSavedOffline();

  // 2) metti in queue nel formato che usa già la tua offlineQueue (kind + payload)
  await queueAdd({
    projectId: pk,
    kind: opts.docType === "PHOTOS" ? "PHOTO_NOTE" : opts.docType, // normalizza se serve
    payload: {
      projectId: pk,
      projectCode: pk,
      // mettiamo dentro la row già salvata offline
      row: savedRow,
    },
  } as any);

  // 3) prova a processare subito (best-effort) — stessa infra degli altri screen
  try {
    await queueProcessPending(
      async (item: QueueItem) => {
        // qui NON facciamo upload diretto: la tua screen già gestisce upload/submitOne
        // quindi lasciamo che il tuo executor di screen faccia il lavoro vero.
        // Questo submitUnified serve solo a garantire: saved offline + queued.
        return;
      },
      { maxTries: 1, stopOnError: false }
    );
  } catch {
    // offline: ok
  }

  if (!opts.silent) Alert.alert("Einreichen", "In Inbox/Queue übernommen.");
  return { ok: true };
}

// apps/mobile/src/lib/sync.ts
import AsyncStorage from "@react-native-async-storage/async-storage";
import { api } from "./api";
import { queueList, queueUpdate, QueueItem, DateiMeta } from "./offlineQueue";

/**
 * ✅ POLICY:
 * - Il server FS vuole projectKey = project.code (es. BA-2025-DEMO)
 * - La queue può contenere UUID o code
 * - syncAll deve poter sincronizzare SOLO il progetto corrente
 *
 * ⚠️ BUG FIX CRITICO:
 * - Non bisogna usare opts.projectCode per mappare ogni item,
 *   altrimenti tutti gli item risultano dello stesso progetto.
 *
 * ✅ PHOTO_NOTE FIX (CRITICO):
 * - Foto/Notizen devono andare in: projects/<BA>/inbox/fotos/<docId>/...
 * - Endpoint corretto server: POST /api/fotos/inbox/upload
 * - multipart fields:
 *   - main (1)   -> doc root
 *   - files (N)  -> doc/files
 *
 * ✅ MODE SEPARATION:
 * - SERVER_SYNC sends documents only to the server-side Eingang / Prüfung.
 * - NUR_APP uses the offline Inbox via AsyncStorage.
 * - sync.ts must never mirror SERVER_SYNC documents into the offline Inbox.
 */

let _projectMap: Map<string, string> | null = null;

async function loadProjectMap(): Promise<Map<string, string>> {
  if (_projectMap) return _projectMap;

  const map = new Map<string, string>();
  try {
    const projects = await api.projects();
    for (const p of projects) {
      const id = String((p as any).id || "").trim();
      const code = String((p as any).code || "").trim();

      if (id && code) map.set(id, code);
      if (code) map.set(code, code);
    }
  } catch {
    // best effort
  }

  _projectMap = map;
  return map;
}

type SyncOptions = {
  /** projectId può essere UUID oppure già code */
  projectId?: string;
  /** se disponibile, vince per definire il progetto target */
  projectCode?: string;
};

function looksLikeProjectCode(s: string) {
  // tu usi BA-2025-... / BA-2025_...
  return /^BA-\d{4}[-_]/i.test(s);
}

/** ✅ Key per ITEM: mai forzare con opts.projectCode */
async function projectKeyForItem(rawProjectId: string): Promise<string> {
  const pid = String(rawProjectId || "").trim();
  if (!pid) return pid;

  if (looksLikeProjectCode(pid)) return pid;

  const map = await loadProjectMap();
  return map.get(pid) || pid; // fallback = pid
}

/** ✅ Key per TARGET: qui sì che projectCode vince */
async function projectKeyForTarget(opts?: SyncOptions): Promise<string> {
  const forced = String(opts?.projectCode || "").trim();
  if (forced) return forced;

  const pid = String(opts?.projectId || "").trim();
  if (!pid) return "";

  if (looksLikeProjectCode(pid)) return pid;

  const map = await loadProjectMap();
  return map.get(pid) || pid;
}

/**
 * ✅ syncAll può sincronizzare:
 * - tutto (se opts non dato)
 * - SOLO un progetto (se opts.projectId o opts.projectCode dato)
 */
export async function syncAll(
  opts?: SyncOptions
): Promise<{ ok: number; fail: number }> {
  const list = await queueList();
  let ok = 0,
    fail = 0;

  // preload map (best effort)
  await loadProjectMap();

  const targetPk = await projectKeyForTarget(opts);

  for (const item of list) {
    if (item.status === "DONE") continue;

    // ✅ filtro per progetto (se richiesto)
    if (targetPk) {
      const itemPk = await projectKeyForItem(item.projectId);
      if (itemPk !== targetPk) continue;
    }

    try {
      await syncOne(item);
      await queueUpdate(item.id, { status: "DONE", error: undefined });
      ok++;
    } catch (e: any) {
      await queueUpdate(item.id, {
        status: "ERROR",
        error: e?.message || "sync failed",
      });
      fail++;
    }
  }
  return { ok, fail };
}

function normalizeLsUploadItems(
  up: any
): Array<{ name: string; type: string; publicUrl: string }> {
  const items = Array.isArray(up?.items) ? up.items : [];
  return items
    .map((x: any) => ({
      name: String(x?.name || "upload"),
      type: String(x?.type || "application/octet-stream"),
      publicUrl: String(x?.publicUrl || ""),
    }))
    .filter((x: any) => !!x.publicUrl);
}

/** =========================
 * PHOTO_NOTE: helpers
 * ========================= */

function inferImageMetaFromUri(uri: string) {
  const u = String(uri || "").toLowerCase();
  if (u.endsWith(".heic") || u.includes("heic"))
    return { ext: "heic", mime: "image/heic" };
  if (u.endsWith(".heif") || u.includes("heif"))
    return { ext: "heif", mime: "image/heif" };
  if (u.endsWith(".png")) return { ext: "png", mime: "image/png" };
  if (u.endsWith(".webp")) return { ext: "webp", mime: "image/webp" };
  return { ext: "jpg", mime: "image/jpeg" };
}

function uid(prefix = "ph") {
  return `${prefix}_${Date.now()}_${Math.floor(Math.random() * 1e9)}`;
}

/** token + base url like in screens (hard, no guessing) */
async function serverRequest<T>(
  path: string,
  init: RequestInit = {}
): Promise<T> {
  const token = await AsyncStorage.getItem("auth_token");
  const headers: Record<string, any> = { ...(init.headers as any) };

  // JSON only (NOT for FormData)
  if (!headers["Content-Type"] && !(init.body instanceof FormData)) {
    headers["Content-Type"] = "application/json";
  }
  if (token) headers.Authorization = `Bearer ${token}`;

  let base = "";
  try {
    base = String(
      (api as any)?.getApiUrl
        ? await (api as any).getApiUrl()
        : (api as any)?.apiUrl || ""
    ).replace(/\/$/, "");
  } catch {
    base = String((api as any)?.apiUrl || "").replace(/\/$/, "");
  }

  const res = await fetch(`${base}${path}`, { ...init, headers });

let base = "";
  try {
    base = String(
      (api as any)?.getApiUrl
        ? await (api as any).getApiUrl()
        : (api as any)?.apiUrl || ""
    ).replace(/\/$/, "");
  } catch {
    base = String((api as any)?.apiUrl || "").replace(/\/$/, "");
  }

  const res = await fetch(`${base}${path}`, { ...init, headers });
  const text = await res.text().catch(() => "");
  if (!res.ok) throw new Error(text || `HTTP ${res.status}`);
  return (text ? JSON.parse(text) : null) as T;
}

/** ✅ FINAL: upload Foto/Notiz in Server INBOX */
async function uploadPhotoNoteInbox(pk: string, p: any) {
  if (!looksLikeProjectCode(pk))
    throw new Error("PHOTO_NOTE: projectKey is not BA-...");

  const docId = String(p?.docId || p?.id || "").trim() || uid("ph");
  const date =
    String(p?.date || "").slice(0, 10) ||
    new Date().toISOString().slice(0, 10);

  const filesArr: DateiMeta[] = Array.isArray(p?.files)
    ? p.files
    : Array.isArray(p?.attachments)
    ? p.attachments
    : [];

  // pick main: prefer imageUri, else first attachment
  const mainUri =
    String(p?.imageUri || "").trim() ||
    String(filesArr?.[0]?.uri || "").trim();
  const remaining =
    mainUri && !String(p?.imageUri || "").trim() ? filesArr.slice(1) : filesArr;

  const fd = new FormData();
  fd.append("projectId", pk);
  fd.append("docId", docId);
  fd.append("date", date);
  fd.append("workflowStatus", String(p?.workflowStatus || "EINGEREICHT"));
  fd.append("comment", String(p?.comment ?? p?.note ?? ""));
  fd.append("bemerkungen", String(p?.bemerkungen ?? ""));
  fd.append("kostenstelle", String(p?.kostenstelle ?? ""));
  fd.append("lvItemPos", p?.lvItemPos ?? "");

  if (p?.extras) fd.append("extras", JSON.stringify(p.extras));
  if (p?.boxes) fd.append("boxes", JSON.stringify(p.boxes));

  // ✅ main as field "main"
  if (mainUri) {
    const meta = inferImageMetaFromUri(mainUri);
    fd.append(
      "main",
      { uri: mainUri, name: `main_${docId}.${meta.ext}`, type: meta.mime } as any
    );
  }

  // ✅ attachments as field "files"
  for (const f of remaining) {
    const uri = String(f?.uri || "").trim();
    if (!uri) continue;

    const meta = inferImageMetaFromUri(uri);
    const name = String(f?.name || `file_${docId}.${meta.ext}`).trim();
    const type = String(f?.type || meta.mime).trim();

    fd.append("files", { uri, name, type } as any);
  }

  // ✅ endpoint CORRETTO del tuo server (routes/fotos.ts)
  return serverRequest("/api/fotos/inbox/upload", {
    method: "POST",
    body: fd as any,
  });
}

async function syncOne(item: QueueItem) {
  // ✅ pk basato sull'item stesso (mai forzato)
  const pk = await projectKeyForItem(item.projectId);

  // =========================
  // REGIE
  // =========================
  if (item.kind === "REGIE") {
    const payload = {
      ...(item.payload || {}),
      projectId: pk, // server FS-key
    };
    return (api as any).pushRegieToServer(pk, payload);
  }

  // Tagesbericht e Bautagebuch condividono il workflow Regie sul server.
  if (item.kind === "TAGESBERICHT" || item.kind === "BAUTAGEBUCH") {
    const p: any = item.payload || {};
    const row = p?.row ?? p;
    return serverRequest("/api/regie", {
      method: "POST",
      body: JSON.stringify({
        ...row,
        projectId: pk,
        projectCode: pk,
        date: String(row?.date || new Date().toISOString().slice(0, 10)),
        reportType: item.kind,
        workflowStatus: "EINGEREICHT",
      }),
    });
  }

  // =========================
  // LIEFERSCHEIN (Upload + Commit)
  // =========================
  if (item.kind === "LIEFERSCHEIN") {
    const p: any = item.payload || {};

    const uploads: Array<{ name: string; type: string; publicUrl: string }> = [];
    const files: DateiMeta[] = Array.isArray(p.files) ? p.files : [];

    // a) Multi-files (preferito): UNA chiamata a /api/ls/upload
    if (files.length > 0) {
      const batch = files
        .map((f) => ({
          uri: f?.uri,
          name: f?.name,
          type: f?.type,
        }))
        .filter((f) => !!f.uri) as Array<{ uri: string; name?: string; type?: string }>;

      if (batch.length) {
        // deve esistere in api.ts:
        // uploadLieferscheinFiles(projectKey, batch, note?)
        const up = await (api as any).uploadLieferscheinFiles(
          pk,
          batch,
          p.note || p.comment
        );
        uploads.push(...normalizeLsUploadItems(up));
      }
    } else {
      // b) fallback vecchio: singolo imageUri
      const img = p.imageUri as string | undefined;
      if (img) {
        const up = await (api as any).uploadLieferscheinFiles(pk, [
  {
  uri: typeof img === "string" ? img : String((img as any)?.uri || ""),
  name:
    typeof img === "string"
      ? img.split("/").pop() || "file"
      : String((img as any)?.name || "file"),
  type:
    typeof img === "string"
      ? "application/octet-stream"
      : String((img as any)?.type || "application/octet-stream"),
},
]);
        uploads.push(...normalizeLsUploadItems(up));
      }
    }

    const rowFromPayload = {
      projectId: pk,
      date: p.date,
      lieferscheinNummer: p.lieferscheinNummer,
      supplier: p.supplier,
      site: p.site,
      driver: p.driver,
      material: p.material,
      quantity: p.quantity,
      unit: p.unit,
      kostenstelle: p.kostenstelle,
      lvItemPos: p.lvItemPos ?? null,
      comment: p.comment ?? p.note ?? "",
