      })),
    };

    const existingRows =
      (Array.isArray(p.rows) && p.rows) ||
      (Array.isArray(p?.items?.lieferscheine) && p.items.lieferscheine) ||
      null;

    const rowsRaw =
      existingRows && existingRows.length ? existingRows : [rowFromPayload];
    const rows = rowsRaw.map((r: any) => ({ ...r, projectId: pk }));

    const commitPayload = {
