          navigation.reset({
            index: 0,
            routes: [{ name: "ServerSetup" as any }]
          });
          return;
        }
        navigation.reset({
          index: 0,
          routes: [{
            name: "Login",
            params: {
              mode: m as any
            }
          }]
        });
        return;
      }
      if (alive) setLoading(false);
    })();
    return () => {
