  return Number(String(v ?? "").replace(",", ".") || 0);
}
function calcTotal(rows: any[]) {
  if (!Array.isArray(rows)) return 0;
  return rows.reduce((sum, r) => {
    const qty = num(r?.qty);
    const ep = num(r?.ep);
    return sum + qty * ep;
  }, 0);
}
