    case "ANGEBOT":
      return {
        bg: COLORS.accentSoft,
        border: COLORS.border,
        text: COLORS.accent
      };
    default:
      return {
        bg: COLORS.card2,
        border: COLORS.border,
        text: COLORS.text
      };
  }
}
function normalizeItem(input: any) {
  return {
    id: String(input?.id || ""),
