}
function perms(role?: SessionRole) {
  const isBauleiter = role === "BAULEITER";
  const isBuero = role === "BUERO";
  const isKalkulator = role === "KALKULATOR";
  const isPolier = role === "POLIER";
  const isFahrer = role === "FAHRER";
  const isMitarbeiter = role === "MITARBEITER";

  // Vollzugriff: Bauleiter, Büro, Kalkulator
  const full = isBauleiter || isBuero || isKalkulator;
