  if (lower.includes("unexpected token") && lower.includes("<")) {
    return "Antwort ist keine JSON-API (HTML/Text). Prüfe EXPO_PUBLIC_API_URL und ob das Backend erreichbar ist.";
  }
  if (msg.length > 600) return msg.slice(0, 600) + "…";
