  const regieAll = [...(Array.isArray(regieStore) ? regieStore : []), ...(Array.isArray(regieInbox) ? regieInbox : [])];
  const lsAll = [...(Array.isArray(lsStore) ? lsStore : []), ...(Array.isArray(lsInbox) ? lsInbox : [])];
  return {
