        updatedAt: now
      };
      const inboxIdx = inboxList.findIndex(x => String(x.id) === String(inboxRow.id));
      let nextInbox: TagesberichtRow[] = [];
      if (inboxIdx >= 0) {
        nextInbox = [...inboxList];
        nextInbox[inboxIdx] = {
          ...nextInbox[inboxIdx],
          ...inboxRow
        };
      } else {
        nextInbox = [inboxRow, ...inboxList];
      }
      nextInbox.sort((a, b) => {
        const aTime = Number(a.submittedAt || a.updatedAt || a.createdAt || 0);
