type Props = NativeStackScreenProps<RootStackParamList, "TagesberichtList">;
const KEY = "rlc_tagesbericht_list:";
type TagesberichtLine = {
  id: string;
  von?: string;
  bis?: string;
  pauseMin?: number;
  stunden?: number;
  mitarbeiter?: string;
  maschine?: string;
  ort?: string;
  taetigkeit?: string;
  notiz?: string;
};
type TagesberichtRow = {
  id: string;
  projectId: string;
  projectCode: string;
  date: string;
  weather?: string;
  temperature?: string;
  workers?: string;
  machines?: string;
  workDone?: string;
  issues?: string;
