function requestId() {
  return (req: any, res: any, next: any) => {
    const id =
      globalThis.crypto && "randomUUID" in globalThis.crypto
        ? (globalThis.crypto as any).randomUUID()
        : `${Date.now()}-${Math.random().toString(16).slice(2)}`;

    req.id = id;
    res.setHeader("X-Request-Id", id);
    next();
  };
}

