      const rows = await prisma.project.findMany({
        where,
        orderBy: { createdAt: "desc" },
        take: 500,
        select: {
          id: true,
          code: true,
          name: true,
          number: true,
          client: true,
          place: true,
          createdAt: true,
        },
      });

      if (!rows || rows.length === 0) {
        if (fsProjects.length > 0) {
          return res.json({ ok: true, source: "FS", projects: fsProjects });
        }
        return res.json({ ok: true, source: "DB", projects: [] });
      }

      return res.json({
        ok: true,
        source: "DB",
        projects: rows.map((p) => ({
          id: p.id,
          code: p.code,
          name: p.name,
          number: p.number ?? null,
          ort: p.place || "",
          kunde: p.client || "",
        })),
      });
    } catch {
      return res.json({ ok: true, source: "FS", projects: fsProjects });
    }
  }
);

/**
 * âœ… Mobile: lista PDF presenti in data/projects/<fsKey>/...
 * GET /api/projects/:fsKey/pdfs
 */
app.get(
  "/api/projects/:fsKey/pdfs",
  requireAuth,
  requireCompany,
  requireActiveSubscription,
  async (req, res) => {
    try {
      const fsKey = String(req.params.fsKey || "").trim();
      if (!fsKey || !isSafeFsKey(fsKey)) {
        return res.status(400).json({ ok: false, error: "invalid fsKey" });
      }

      const rootAbs = path.join(PROJECTS_ROOT, fsKey);
      if (!fs.existsSync(rootAbs)) {
        return res.json({ ok: true, items: [] });
      }

      const files = collectPdfFiles(rootAbs);

      const items = files.map((f) => ({
        name: f.name,
        folder: f.folder || undefined,
        mtime: f.mtime,
        url: `/projects/${encodeURIComponent(fsKey)}/${f.rel
          .split("/")
          .map((p) => encodeURIComponent(p))
          .join("/")}`,
      }));

      return res.json({ ok: true, items });
    } catch (e: any) {
      console.error("GET /api/projects/:fsKey/pdfs failed:", e);
      return res.status(500).json({
        ok: false,
        error: e?.message || "pdf list failed",
      });
    }
  }
);

app.post(
  "/api/projects/:fsKey/pdfs/upload",
  requireAuth,
  requireCompany,
  requireActiveSubscription,
  pdfUpload.single("file"),
  async (req, res) => {
    try {
      const fsKey = String(req.params.fsKey || "").trim();
      if (!fsKey || !isSafeFsKey(fsKey)) {
        return res.status(400).json({ ok: false, error: "invalid fsKey" });
      }

      const file = (req as any).file;
      if (!file?.buffer) {
        return res.status(400).json({ ok: false, error: "missing file" });
      }

      const original = String(file.originalname || "document.pdf").trim();
      const safeName = original.replace(/[^A-Za-z0-9._-]/g, "_");
      const finalName = safeName.toLowerCase().endsWith(".pdf")
        ? safeName
        : `${safeName}.pdf`;

      const dirAbs = path.join(PROJECTS_ROOT, fsKey, "pdfs");
      fs.mkdirSync(dirAbs, { recursive: true });

      const outAbs = path.join(dirAbs, finalName);
      fs.writeFileSync(outAbs, file.buffer);

      const auth = (req as any).auth || {};
      void archiveProjectBufferVersion({
        projectIdOrCode: fsKey,
        filename: finalName,
        kind: "PDF",
        buffer: file.buffer,
        uploadedBy: String(auth.email || auth.userId || auth.sub || "").trim() || null,
        meta: { module: "PROJEKTE", source: "index.projects.pdf.upload", folder: "pdfs" }
      }).catch((error) => console.error("[index:projects-pdf-upload:dms]", error));

      return res.json({
        ok: true,
        name: finalName,
        url: `/projects/${encodeURIComponent(fsKey)}/pdfs/${encodeURIComponent(finalName)}`,
      });
    } catch (e: any) {
      console.error("POST /api/projects/:fsKey/pdfs/upload failed:", e);
      return res.status(500).json({
        ok: false,
        error: e?.message || "pdf upload failed",
      });
    }
  }
);
