import { prisma } from "../../lib/prisma";
import { filterUsableRlcPriceSources } from "../quality/priceSourceQualityGate";

const db = prisma as any;

type CostGroup =
  | "MATERIAL"
  | "LABOR"
  | "MACHINE"
  | "TRANSPORT"
  | "SUBCONTRACTOR"
  | "DISPOSAL";

function n(value: unknown, fallback = 0): number {
  const result = Number(value);
  return Number.isFinite(result) ? result : fallback;
}

function round2(value: number): number {
  return Math.round((value + Number.EPSILON) * 100) / 100;
}

function norm(value: unknown): string {
  return String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function uniqueTerms(values: unknown[]): string[] {
  return [
    ...new Set(
      values
        .flatMap((value) => norm(value).split(" "))
        .filter((value) => value.length >= 3)
    ),
  ];
}

function includesTerm(text: string, term: string): boolean {
  return text.includes(norm(term));
}

function isRoadAsphaltEvent(event: any): boolean {
  const text = norm([
    event?.title,
    ...(event?.marketImpact?.materials || []),
    ...(event?.marketImpact?.trades || []),
    ...(event?.marketImpact?.lvTerms || []),
  ].join(" "));

  return /asphalt|bitumen|strassenbau|strasse|fahrbahn/.test(text);
}

function isPipeCoatingContext(entry: any): boolean {
  const text = norm([
    entry?.shortText,
    entry?.longText,
    entry?.trade,
    entry?.serviceType,
  ].join(" "));

  const pipeTerms =
    /ggg rohr|kanalrohr|rohre|rohrleitung|gusseisen|duktil|steckmuffe|dn [0-9]+/;

  const coatingTerms =
    /bitumendeckbeschichtung|bitumenbeschichtung|beschichtung/;

  return pipeTerms.test(text) && coatingTerms.test(text);
}

function hasPrimaryAsphaltContext(entry: any): boolean {
  const shortText = norm(entry?.shortText);
  const longText = norm(entry?.longText);
  const trade = norm(entry?.trade);

  const strongTerms =
    /asphalt|asphalttrag|asphaltbinder|asphaltdeck|schichtenverbund|anspruh|bindemittel|fahrbahn|strassenbau|strassenaufbruch|frase|fugenband/;

  return (
    strongTerms.test(shortText) ||
    strongTerms.test(trade) ||
    strongTerms.test(longText)
  );
}

function detectCostGroup(event: any): CostGroup {
  const text = norm(
    [
      event?.title,
      ...(event?.marketImpact?.materials || []),
      ...(event?.marketImpact?.trades || []),
      ...(event?.marketImpact?.lvTerms || []),
    ].join(" ")
  );

  if (
    /lohn|loehne|tarif|personal|arbeitslohn|stundenlohn|mindestlohn/.test(text)
  ) {
    return "LABOR";
  }

  if (
    /diesel|kraftstoff|transport|fracht|logistik|lieferkosten/.test(text)
  ) {
    return "TRANSPORT";
  }

  if (
    /maschine|geraet|bagger|lkw|radlader|energiepreis|strompreis/.test(text)
  ) {
    return "MACHINE";
  }

  if (/nachunternehmer|fremdleistung|subunternehmer/.test(text)) {
    return "SUBCONTRACTOR";
  }

  if (/entsorgung|deponie|abfall|recycling/.test(text)) {
    return "DISPOSAL";
  }

  return "MATERIAL";
}

function resolveChangePct(event: any): {
  minPct: number | null;
  maxPct: number | null;
  appliedPct: number | null;
  direction: string;
} {
  const impact = event?.marketImpact || {};
  const min = Number.isFinite(Number(impact.estimatedChangeMinPct))
    ? Number(impact.estimatedChangeMinPct)
    : null;
  const max = Number.isFinite(Number(impact.estimatedChangeMaxPct))
    ? Number(impact.estimatedChangeMaxPct)
    : null;

  let appliedPct: number | null = null;

  if (min != null && max != null) {
    appliedPct = (min + max) / 2;
  } else if (max != null) {
    appliedPct = max;
  } else if (min != null) {
    appliedPct = min;
  }

  const direction = String(impact.direction || "UNKNOWN").toUpperCase();

  if (appliedPct != null) {
    appliedPct = Math.abs(appliedPct);

    if (direction === "DOWN") {
      appliedPct *= -1;
    }
  }

  return {
    minPct: min,
    maxPct: max,
    appliedPct,
    direction,
  };
}

function costForGroup(entry: any, group: CostGroup): number {
  switch (group) {
    case "LABOR":
      return n(entry.laborCost);
    case "MACHINE":
      return n(entry.machineCost);
    case "TRANSPORT":
      return n(entry.transportCost);
    case "SUBCONTRACTOR":
      return n(entry.subcontractorCost);
    case "DISPOSAL":
      return n(entry.disposalCost);
    default:
      return n(entry.materialCost);
  }
}

function calculateMatchScore(entry: any, event: any): {
  score: number;
  reasons: string[];
  matchedTerms: string[];
} {
  const positionText = norm(
    [
      entry.positionNumber,
      entry.shortText,
      entry.longText,
      entry.trade,
      entry.serviceType,
      entry.constructionMethod,
      entry.soilClass,
      JSON.stringify(entry.tags || []),
      JSON.stringify(entry.resources || []),
      JSON.stringify(entry.parameters || {}),
    ].join(" ")
  );

  /*
   * Bitumen kann auch nur eine Rohrbeschichtung sein.
   * Solche Positionen dürfen bei Asphalt-/Straßenbauereignissen
   * nicht als Preiswirkung erkannt werden.
   */
  if (
    isRoadAsphaltEvent(event) &&
    isPipeCoatingContext(entry)
  ) {
    return {
      score: 0,
      reasons: ["Bitumen nur als Rohrbeschichtung erkannt"],
      matchedTerms: [],
    };
  }

  const materials = event?.marketImpact?.materials || [];
  const trades = event?.marketImpact?.trades || [];
  const lvTerms = event?.marketImpact?.lvTerms || [];

) {
    return {
      score: 0,
      reasons: ["Bitumen nur als Rohrbeschichtung erkannt"],
      matchedTerms: [],
    };
  }

  const materials = event?.marketImpact?.materials || [];
  const trades = event?.marketImpact?.trades || [];
  const lvTerms = event?.marketImpact?.lvTerms || [];

  const materialTerms = uniqueTerms(materials);
  const tradeTerms = uniqueTerms(trades);
  const technicalTerms = uniqueTerms(lvTerms);

  const matchedMaterials = materialTerms.filter((term) =>
    includesTerm(positionText, term)
  );
  const matchedTrades = tradeTerms.filter((term) =>
    includesTerm(positionText, term)
  );
  const matchedTechnical = technicalTerms.filter((term) =>
    includesTerm(positionText, term)
  );

  let score = 0;
  const reasons: string[] = [];

  if (
    isRoadAsphaltEvent(event) &&
    !hasPrimaryAsphaltContext(entry)
  ) {
    return {
      score: 0,
      reasons: ["Kein primärer Asphalt- oder Straßenbaukontext"],
      matchedTerms: [],
    };
  }

  if (materialTerms.length) {
    const ratio = matchedMaterials.length / materialTerms.length;
    score += ratio * 0.55;

    if (matchedMaterials.length) {
      reasons.push(`Material: ${matchedMaterials.join(", ")}`);
    }
  }

  if (tradeTerms.length) {
    const ratio = matchedTrades.length / tradeTerms.length;
    score += ratio * 0.25;

    if (matchedTrades.length) {
      reasons.push(`Gewerk: ${matchedTrades.join(", ")}`);
    }
  }

  if (technicalTerms.length) {
    const ratio = matchedTechnical.length / technicalTerms.length;
    score += ratio * 0.2;

    if (matchedTechnical.length) {
      reasons.push(`LV-Begriff: ${matchedTechnical.join(", ")}`);
    }
  }

  /*
   * Bei reinen Lohnereignissen darf das Gewerk den Hauptbezug liefern,
   * weil kein konkretes Material vorhanden sein muss.
   */
  const costGroup = detectCostGroup(event);

  if (
    costGroup === "LABOR" &&
    matchedTrades.length > 0 &&
    n(entry.laborCost) > 0
  ) {
    score = Math.max(score, 0.72);
    reasons.push("Lohnkosten in der Urkalkulation vorhanden");
  }

  /*
   * Positionen ohne Kostenaufschlüsselung bleiben sichtbar.
   * Sie dürfen jedoch nicht automatisch neu kalkuliert werden.
   */
  if (costForGroup(entry, costGroup) <= 0 && score > 0) {
    reasons.push("Betroffener Kostenanteil fehlt in der Urkalkulation");
  }

  return {
    score: Math.min(round2(score), 1),
    reasons,
    matchedTerms: [
      ...matchedMaterials,
      ...matchedTrades,
      ...matchedTechnical,
    ],
  };
}

function buildPositionImpact(
  entry: any,
  event: any,
  appliedPct: number,
  costGroup: CostGroup,
  match: ReturnType<typeof calculateMatchScore>
) {
  const currentUnitPrice = n(entry.unitPriceNet);
  const affectedCost = costForGroup(entry, costGroup);
  const quantity = n(entry.quantity);

  const calculationAvailable = affectedCost > 0;

  const affectedCostDelta = calculationAvailable
    ? round2(affectedCost * (appliedPct / 100))
    : 0;

  const suggestedUnitPrice = calculationAvailable
    ? round2(Math.max(0, currentUnitPrice + affectedCostDelta))
    : currentUnitPrice;

  const unitPriceDelta = round2(suggestedUnitPrice - currentUnitPrice);
  const totalDelta = round2(unitPriceDelta * quantity);

  return {
    id: entry.id,
    projectId: entry.projectId || null,
    projectCode: entry.projectCode || null,
    projectName: entry.projectName || null,
    positionNumber: entry.positionNumber || null,
    shortText: entry.shortText,
    unit: entry.unit || null,
    quantity,

    matchScore: match.score,
    matchReasons: match.reasons,
    matchedTerms: match.matchedTerms,

    impactStatus: calculationAvailable
      ? "CALCULATED"
      : "COST_BREAKDOWN_MISSING",
    calculationAvailable,
    affectedCostGroup: costGroup,
    affectedCost,
    affectedSharePct:
      currentUnitPrice > 0
        ? round2((affectedCost / currentUnitPrice) * 100)
        : 0,

    currentCosts: {
      materialCost: round2(n(entry.materialCost)),
      laborCost: round2(n(entry.laborCost)),
      machineCost: round2(n(entry.machineCost)),
      transportCost: round2(n(entry.transportCost)),
      subcontractorCost: round2(n(entry.subcontractorCost)),
      disposalCost: round2(n(entry.disposalCost)),
      overheadCost: round2(n(entry.overheadCost)),
      riskCost: round2(n(entry.riskCost)),
      profitCost: round2(n(entry.profitCost)),
    },

    currentUnitPrice: round2(currentUnitPrice),
    marketChangePct: round2(appliedPct),
    affectedCostDelta,
    suggestedUnitPrice,
    unitPriceDelta,
    unitPriceDeltaPct:
      currentUnitPrice > 0
        ? round2((unitPriceDelta / currentUnitPrice) * 100)
        : 0,
    currentTotal: round2(currentUnitPrice * quantity),
    suggestedTotal: round2(suggestedUnitPrice * quantity),
    totalDelta,
  };
}

export async function analyzeMarketCandidateImpact(
  candidateId: string,
  companyId: string
) {
  if (!candidateId) {
    throw new Error("MARKET_CANDIDATE_ID_REQUIRED");
  }

  if (!companyId) {
    throw new Error("COMPANY_ID_REQUIRED");
  }

  const candidate = await db.marketIntelligenceCandidate.findUnique({
    where: { id: candidateId },
    include: { event: true },
  });

  if (!candidate) {
    throw new Error("MARKET_CANDIDATE_NOT_FOUND");
  }

  if (candidate.type !== "PRICE_SUGGESTION") {
    throw new Error("MARKET_CANDIDATE_NOT_PRICE_SUGGESTION");
  }

  const event = candidate.event;
  const change = resolveChangePct(event);

if (!candidate) {
    throw new Error("MARKET_CANDIDATE_NOT_FOUND");
  }

  if (candidate.type !== "PRICE_SUGGESTION") {
    throw new Error("MARKET_CANDIDATE_NOT_PRICE_SUGGESTION");
  }

  const event = candidate.event;
  const change = resolveChangePct(event);

  if (change.appliedPct == null || change.appliedPct === 0) {
    const result = {
      version: "1.0",
      status: "NO_QUANTIFIED_CHANGE",
      analyzedAt: new Date().toISOString(),
      candidateId,
      companyId,
      direction: change.direction,
      minChangePct: change.minPct,
      maxChangePct: change.maxPct,
      appliedChangePct: null,
      affectedCostGroup: detectCostGroup(event),
      affectedPositions: [],
      summary: {
        positions: 0,
        projects: 0,
        currentTotal: 0,
        suggestedTotal: 0,
        estimatedDelta: 0,
        averageIncreasePct: 0,
      },
      note:
        "Das Marktereignis enthält noch keine belastbare prozentuale Preisänderung. Es wurden keine Preise geschätzt oder geändert.",
    };

    const oldData =
      candidate.proposedData &&
      typeof candidate.proposedData === "object" &&
      !Array.isArray(candidate.proposedData)
        ? candidate.proposedData
        : {};

    await db.marketIntelligenceCandidate.update({
      where: { id: candidateId },
      data: {
        proposedData: {
          ...oldData,
          impactAnalysis: result,
        },
      },
    });

    return result;
  }

  const entriesRaw = await db.kalkulationsDbEntry.findMany({
    where: {
      companyId,
      unitPriceNet: { gt: 0 },
    },
    orderBy: {
      updatedAt: "desc",
    },
    take: 10000,
  });

  const entries = filterUsableRlcPriceSources(entriesRaw);

  const costGroup = detectCostGroup(event);

  const affectedPositions = entries
    .map((entry: any) => ({
      entry,
      match: calculateMatchScore(entry, event),
    }))
    .filter(({ match }: any) => match.score >= 0.45)
    .map(({ entry, match }: any) =>
      buildPositionImpact(
        entry,
        event,
        change.appliedPct as number,
        costGroup,
        match
      )
    )
    .sort(
      (left: any, right: any) =>
        right.matchScore - left.matchScore ||
        Math.abs(right.totalDelta) - Math.abs(left.totalDelta)
    )
    .slice(0, 500);

  const currentTotal = round2(
    affectedPositions.reduce(
      (sum: number, position: any) => sum + position.currentTotal,
      0
    )
  );

  const suggestedTotal = round2(
    affectedPositions.reduce(
      (sum: number, position: any) => sum + position.suggestedTotal,
      0
    )
  );

  const estimatedDelta = round2(suggestedTotal - currentTotal);

  const projectIds = new Set(
    affectedPositions
      .map((position: any) => position.projectId)
      .filter(Boolean)
  );

  const result = {
    version: "1.0",
    status: affectedPositions.length ? "ANALYZED" : "NO_MATCHES",
    analyzedAt: new Date().toISOString(),
    candidateId,
    companyId,

    event: {
      id: event.id,
      title: event.title,
      sourceName: event.sourceName,
      publishedAt: event.publishedAt,
      materials: event.marketImpact?.materials || [],
      trades: event.marketImpact?.trades || [],
      lvTerms: event.marketImpact?.lvTerms || [],
    },

    direction: change.direction,
    minChangePct: change.minPct,
    maxChangePct: change.maxPct,
    appliedChangePct: round2(change.appliedPct),
    affectedCostGroup: costGroup,

    affectedPositions,

    summary: {
      positions: affectedPositions.length,
      calculablePositions: affectedPositions.filter(
        (position: any) => position.calculationAvailable
      ).length,
      missingCostBreakdown: affectedPositions.filter(
        (position: any) => !position.calculationAvailable
      ).length,
      projects: projectIds.size,
      currentTotal,
      suggestedTotal,
      estimatedDelta,
      averageIncreasePct:
        currentTotal > 0
          ? round2((estimatedDelta / currentTotal) * 100)
          : 0,
    },

    safety: {
      databasePricesChanged: false,
      recipesChanged: false,
      automaticApplication: false,
      approvalRequired: true,
    },
  };

  const oldData =
    candidate.proposedData &&
    typeof candidate.proposedData === "object" &&
    !Array.isArray(candidate.proposedData)
      ? candidate.proposedData
      : {};

  await db.marketIntelligenceCandidate.update({
    where: { id: candidateId },
    data: {
      proposedData: {
        ...oldData,
        impactAnalysis: result,
      },
    },
  });

  await db.marketIntelligenceReview.create({
    data: {
      candidateId,
      action: "IMPACT_ANALYSIS",
      note: `${affectedPositions.length} betroffene Positionen analysiert; keine Preise geändert.`,
      userId: null,
    },
  });

  return result;
}

import { prisma } from "../../lib/prisma";
import { filterUsableRlcPriceSources } from "../quality/priceSourceQualityGate";
import {
  getInternetIntelligenceEvents,
  getInternetIntelligenceStatus,
  getInternetMarketTrends,
  InternetEvent,
} from "./internetIntelligenceAgent";

type CandidateType =
  | "DATABASE_POSITION"
  | "KNOWLEDGE"
  | "PRICE_SUGGESTION"
  | "REGULATION_ALERT"
  | "TECHNOLOGY_ALERT";

type ReviewStatus =
  | "NEW"
  | "REVIEW"
  | "APPROVED"
  | "REJECTED"
  | "APPLIED";

const db = prisma as any;

const norm = (value: unknown) =>
  String(value || "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9äöüß]+/g, " ")
    .trim();

const tokens = (value: unknown) =>
  [...new Set(norm(value).split(/\s+/).filter((token) => token.length >= 3))];

const overlap = (left: string[], right: string[]) =>
  left.length
    ? left.filter((token) => right.includes(token)).length / left.length
    : 0;

const MARKET_ONLY_PATTERN =
  /preisindex|erzeugerpreis|einfuhrpreis|statistik|newsticker|meldung|bericht|marktbericht|konjunktur|inflation|tarifverhandlung|lohnerhöhung|lohnentwicklung/;

const TECHNICAL_POSITION_PATTERN =
  /liefern|einbauen|herstellen|verlegen|montieren|ausbauen|abbrechen|entsorgen|aushub|verdichten|pflastern|asphaltieren|betonieren|rohr|leitung|schacht|bordstein|pflaster|asphalttragschicht|asphaltbinder|asphaltdeckschicht/;

function isKnownDirection(event: InternetEvent) {
  return (
    event.marketImpact.direction === "UP" ||
    event.marketImpact.direction === "DOWN"
  );
}

function hasQuantifiedImpact(event: InternetEvent) {
  return (
    event.marketImpact.estimatedChangeMinPct != null ||
    event.marketImpact.estimatedChangeMaxPct != null
  );
}

function isRelevantPriceEvent(event: InternetEvent) {
  const hasTarget =
    event.marketImpact.materials.length > 0 ||
    event.marketImpact.trades.length > 0 ||
    event.marketImpact.lvTerms.length > 0;

  return (
    hasTarget &&
    (isKnownDirection(event) || hasQuantifiedImpact(event)) &&
    event.marketImpact.confidence >= 60 &&
    event.totalScore >= 60
  );
}

function isTechnicalDatabasePosition(event: InternetEvent) {
  const text = norm(
    `${event.title} ${event.marketImpact.materials.join(" ")} ` +
    `${event.marketImpact.trades.join(" ")} ${event.marketImpact.lvTerms.join(" ")}`
  );

  const hasMaterial = event.marketImpact.materials.length > 0;
  const hasTrade = event.marketImpact.trades.length > 0;
  const hasLvTerms = event.marketImpact.lvTerms.length >= 2;
  const isMarketOnly = MARKET_ONLY_PATTERN.test(text);
  const hasTechnicalLanguage = TECHNICAL_POSITION_PATTERN.test(text);

  return (
    hasMaterial &&
    hasTrade &&
    hasLvTerms &&
    hasTechnicalLanguage &&
    !isMarketOnly &&
    event.totalScore >= 85 &&
    event.marketImpact.confidence >= 80
  );
}

function classifyExclusiveAlert(
  event: InternetEvent
): "REGULATION_ALERT" | "TECHNOLOGY_ALERT" | null {
  const text = norm(
    `${event.title} ${event.matchedSignals.join(" ")} ` +
    `${event.marketImpact.lvTerms.join(" ")}`
  );

  if (
    /\bdin\b|\bnorm\b|gesetz|verordnung|richtlinie|regelwerk|vob|reb/.test(text)
  ) {
    return "REGULATION_ALERT";
  }

  if (
    /technologie|innovation|digitalisierung|gnss|machine control|maschine|verfahren|robotik|automatisierung/.test(
      text
    )
  ) {
    return "TECHNOLOGY_ALERT";
  }

  return null;
}

function proposedTechnicalPosition(event: InternetEvent) {
  const material = event.marketImpact.materials[0] || null;
  const trade = event.marketImpact.trades[0] || null;
  const lvTerms = event.marketImpact.lvTerms.slice(0, 8);

  const shortText = [
    material,
    trade && trade !== material ? trade : null,
  ]
    .filter(Boolean)
    .join(" – ")
    .slice(0, 180);

  return {
    shortText,
    longText: [
      `Technischer Marktkandidat: ${shortText}`,
      `Quelle: ${event.label}`,
      `Auslöser: ${event.title}`,
      lvTerms.length ? `LV-Bezug: ${lvTerms.join(", ")}` : null,
      `Bewertung: ${event.totalScore}/100`,
    ]
      .filter(Boolean)
      .join("\n"),
    unit: null,
    trade,
    material,
    tags: [
      ...event.marketImpact.materials,
      ...event.marketImpact.trades,
      ...event.marketImpact.lvTerms,
    ],
  };
}

async function findDatabaseMatches(event: InternetEvent) {
  const searchTokens = tokens(
    `${event.marketImpact.materials.join(" ")} ` +
    `${event.marketImpact.trades.join(" ")} ` +
    `${event.marketImpact.lvTerms.join(" ")} ${event.title}`
  );

  if (searchTokens.length < 2) return [];

  const rowsRaw = await db.kalkulationsDbEntry.findMany({
    take: 500,
    orderBy: { updatedAt: "desc" },
    select: {
      id: true,
      shortText: true,
      longText: true,
      unit: true,
      trade: true,
      unitPriceNet: true,
    },
  });

  const rows = filterUsableRlcPriceSources(rowsRaw);

  return rows
    .map((row: any) => ({
      ...row,
      score: overlap(
        searchTokens,
        tokens(`${row.shortText} ${row.longText} ${row.trade}`)
      ),
    }))
    .filter((row: any) => row.score >= 0.7)
    .sort((a: any, b: any) => b.score - a.score)
    .slice(0, 5);
}

async function findKnowledgeMatches(event: InternetEvent) {
  const searchTokens = tokens(
    `${event.title} ${event.marketImpact.materials.join(" ")} ` +
    `${event.marketImpact.trades.join(" ")} ` +
    `${event.marketImpact.lvTerms.join(" ")}`
  );

.filter((row: any) => row.score >= 0.7)
    .sort((a: any, b: any) => b.score - a.score)
    .slice(0, 5);
}

async function findKnowledgeMatches(event: InternetEvent) {
  const searchTokens = tokens(
    `${event.title} ${event.marketImpact.materials.join(" ")} ` +
    `${event.marketImpact.trades.join(" ")} ` +
    `${event.marketImpact.lvTerms.join(" ")}`
  );

  if (searchTokens.length < 2) return [];

  const rows = await db.rlcGlobalKnowledgeAggregated.findMany({
    take: 500,
    orderBy: { updatedAt: "desc" },
    select: {
      id: true,
      shortText: true,
      longText: true,
      unit: true,
      gewerk: true,
      category: true,
      confidence: true,
    },
  });

  return rows
    .map((row: any) => ({
      ...row,
      score: overlap(
        searchTokens,
        tokens(
          `${row.shortText} ${row.longText} ${row.gewerk} ${row.category}`
        )
      ),
    }))
    .filter((row: any) => row.score >= 0.72)
    .sort((a: any, b: any) => b.score - a.score)
    .slice(0, 5);
}

async function createCandidateIfMissing(
  eventId: string,
  type: CandidateType,
  data: Record<string, unknown>
) {
  const title = String(data.title || "");
  const fingerprint = norm(
    title
      .replace(/^Knowledge-Kandidat:\s*/i, "")
      .replace(/^Technische Datenbankposition prüfen:\s*/i, "")
      .replace(/^Neue Datenbankposition prüfen:\s*/i, "")
  )
    .replace(/statistisches bundesamt/g, "")
    .replace(/www genesis destatis de/g, "")
    .replace(/genesis destatis de/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 140);

  const sameEventType = await db.marketIntelligenceCandidate.findFirst({
    where: { eventId, type },
    select: { id: true },
  });

  if (sameEventType) return false;

  const recentSameType = await db.marketIntelligenceCandidate.findMany({
    where: {
      type,
      status: { in: ["NEW", "REVIEW", "APPROVED", "APPLIED"] },
    },
    take: 200,
    orderBy: { createdAt: "desc" },
    select: { id: true, title: true },
  });

  const duplicate = recentSameType.some((candidate: any) => {
    const candidateFingerprint = norm(
      String(candidate.title || "")
        .replace(/^Knowledge-Kandidat:\s*/i, "")
        .replace(/^Technische Datenbankposition prüfen:\s*/i, "")
        .replace(/^Neue Datenbankposition prüfen:\s*/i, "")
    )
      .replace(/statistisches bundesamt/g, "")
      .replace(/www genesis destatis de/g, "")
      .replace(/genesis destatis de/g, "")
      .replace(/\s+/g, " ")
      .trim()
      .slice(0, 140);

    if (!fingerprint || !candidateFingerprint) return false;

    const left = tokens(fingerprint);
    const right = tokens(candidateFingerprint);

    return (
      fingerprint === candidateFingerprint ||
      overlap(left, right) >= 0.82 ||
      overlap(right, left) >= 0.82
    );
  });

  if (duplicate) return false;

  await db.marketIntelligenceCandidate.create({
    data: {
      eventId,
      type,
      status: "NEW",
      ...data,
    },
  });

  return true;
}

export async function synchronizeMarketIntelligence(limit = 500) {
  const events = await getInternetIntelligenceEvents(limit);

  let imported = 0;
  let candidates = 0;

  for (const event of events) {
    const stored = await db.marketIntelligenceEvent.upsert({
      where: { externalId: event.id },
      update: {
        title: event.title,
        url: event.link,
        sourceId: event.sourceId,
        sourceName: event.label,
        publishedAt: new Date(event.publishedAt),
        priority: event.priority,
        relevanceScore: event.relevanceScore,
        trustScore: event.trustScore,
        totalScore: event.totalScore,
        verification: event.verification,
        matchedSignals: event.matchedSignals,
        priceHints: event.priceHints,
        marketImpact: event.marketImpact,
      },
      create: {
        externalId: event.id,
        title: event.title,
        url: event.link,
        sourceId: event.sourceId,
        sourceName: event.label,
        publishedAt: new Date(event.publishedAt),
        priority: event.priority,
        relevanceScore: event.relevanceScore,
        trustScore: event.trustScore,
        totalScore: event.totalScore,
        verification: event.verification,
        matchedSignals: event.matchedSignals,
        priceHints: event.priceHints,
        marketImpact: event.marketImpact,
      },
    });

    imported += 1;

    const alertType = classifyExclusiveAlert(event);

    if (alertType) {
      const created = await createCandidateIfMissing(stored.id, alertType, {
        confidence: event.marketImpact.confidence / 100,
        title: event.title,
        rationale:
          event.marketImpact.cause ||
          `Automatisch aus ${event.label} erkannt.`,
        proposedData: {
          marketImpact: event.marketImpact,
          source: {
            title: event.title,
            label: event.label,
            link: event.link,
          },
        },
      });

      if (created) candidates += 1;
      continue;
    }

    const databaseMatches = await findDatabaseMatches(event);
    const knowledgeMatches = await findKnowledgeMatches(event);

    if (isRelevantPriceEvent(event)) {
      const created = await createCandidateIfMissing(
        stored.id,
        "PRICE_SUGGESTION",
        {
          confidence: event.marketImpact.confidence / 100,
          title: event.title,
          rationale:
            event.marketImpact.cause ||

const databaseMatches = await findDatabaseMatches(event);
    const knowledgeMatches = await findKnowledgeMatches(event);

    if (isRelevantPriceEvent(event)) {
      const created = await createCandidateIfMissing(
        stored.id,
        "PRICE_SUGGESTION",
        {
          confidence: event.marketImpact.confidence / 100,
          title: event.title,
          rationale:
            event.marketImpact.cause ||
            `Preisrelevanter Markthinweis aus ${event.label}.`,
          proposedData: {
            marketImpact: event.marketImpact,
            databaseMatches,
            source: {
              title: event.title,
              label: event.label,
              link: event.link,
            },
          },
        }
      );

      if (created) candidates += 1;
    }

    if (
      !isRelevantPriceEvent(event) &&
      knowledgeMatches.length === 0 &&
      event.totalScore >= 65 &&
      event.marketImpact.confidence >= 50
    ) {
      const created = await createCandidateIfMissing(
        stored.id,
        "KNOWLEDGE",
        {
          confidence: event.totalScore / 100,
          title: `Knowledge-Kandidat: ${event.title}`,
          rationale:
            "Keine ausreichend ähnliche Information in Global Knowledge gefunden.",
          proposedData: {
            shortText: event.title.slice(0, 180),
            longText: [
              `Markthinweis: ${event.title}`,
              `Quelle: ${event.label}`,
              `Bewertung: ${event.totalScore}/100`,
              event.marketImpact.materials.length
                ? `Materialien: ${event.marketImpact.materials.join(", ")}`
                : null,
              event.marketImpact.trades.length
                ? `Gewerke: ${event.marketImpact.trades.join(", ")}`
                : null,
            ]
              .filter(Boolean)
              .join("\n"),
            unit: null,
            gewerk: event.marketImpact.trades[0] || null,
            category: "Market Intelligence",
          },
        }
      );

      if (created) candidates += 1;
    }

    if (
      databaseMatches.length === 0 &&
      isTechnicalDatabasePosition(event)
    ) {
      const position = proposedTechnicalPosition(event);

      if (position.shortText) {
        const created = await createCandidateIfMissing(
          stored.id,
          "DATABASE_POSITION",
          {
            confidence: event.totalScore / 100,
            title: `Technische Datenbankposition prüfen: ${position.shortText}`,
            rationale:
              "Technische Leistung erkannt, aber keine ausreichend ähnliche Position gefunden.",
            proposedData: position,
          }
        );

        if (created) candidates += 1;
      }
    }
  }

  return {
    imported,
    candidates,
    processedEvents: events.length,
  };
}

