      tags: data.tags || [], aiNote: `Freigegebener Market-Intelligence-Kandidat ${candidate.id}`,
      confidence: candidate.confidence, unitPriceNet: 0,
    }});
  } else if (candidate.type === "KNOWLEDGE") {
    const normalizedKey = norm(`${data.shortText}|${data.unit || ""}|${data.gewerk || ""}`).replace(/\s+/g, "-").slice(0, 180);
    result = await db.rlcGlobalKnowledgeAggregated.upsert({ where: { normalizedKey }, update: {
      longText: data.longText || null, confidence: Math.max(candidate.confidence, 0.5), needsReview: false,
      sources: [{ type: "MARKET_INTELLIGENCE", eventId: candidate.eventId, url: candidate.event.link }],
    }, create: {
      normalizedKey, shortText: data.shortText, longText: data.longText || null, unit: data.unit || null,
      gewerk: data.gewerk || null, category: data.category || "Market Intelligence", confidence: Math.max(candidate.confidence, 0.5),
      sampleCount: 1, needsReview: false, sources: [{ type: "MARKET_INTELLIGENCE", eventId: candidate.eventId, url: candidate.event.link }],
    }});
  } else {
    result = { recorded: true, message: "Hinweis freigegeben; keine Datenbankänderung erforderlich." };
  }
  await db.marketIntelligenceCandidate.update({ where: { id }, data: { status: "APPLIED", appliedAt: new Date(), appliedBy: userId || null, appliedResult: result } });
  await db.marketIntelligenceReview.create({ data: { candidateId: id, action: "APPLY", note: "Explizit angewendet", userId: userId || null } });
  return result;
}

import type { RlcAutonomousCalcInput, RlcAutonomousProjectContext, RlcRiskLevel } from "./types";
import { getBaupreisIndexFactor } from "../priceIndex/baupreisIndexService";
import {
  detectRlcConstructionFamilies,
  detectPrimaryRlcConstructionFamily,
} from "../domain/constructionFamilyRegistry";

function s(v: unknown): string {
  return String(v ?? "").toLowerCase();
}

function includesAny(text: string, words: string[]): boolean {
  return words.some((w) => text.includes(w));
}

function risk(high: boolean, medium: boolean): RlcRiskLevel {
  if (high) return "high";
  if (medium) return "medium";
  return "low";
}

export function analyzeRlcProjectContext(rows: RlcAutonomousCalcInput[] = [], projectCode?: string): RlcAutonomousProjectContext {
  const joined = rows.map((r) => `${r.kurztext ?? ""} ${r.langtext ?? ""}`).join(" ").toLowerCase();

  const detectedFamilies = detectRlcConstructionFamilies(joined);
  const primaryFamily = detectPrimaryRlcConstructionFamily(joined);

  const hasTraffic = includesAny(joined, [
    "verkehr",
    "straße",
    "fahrbahn",
    "asphalt",
    "sperrung",
    "ampel",
    "verkehrssicherung",
  ]);

  const hasDifficultLogistics = includesAny(joined, [
    "enge",
    "bestand",
    "kreuzung",
    "erschwernis",
    "zufahrt",
    "hang",
    "steigung",
    "innerorts",
  ]);

  const hasLongDuration = includesAny(joined, [
    "vorhaltung",
    "bauzeit",
    "winter",
    "monate",
    "2022 / 2023",
    "2 jahre",
  ]);

  const hasSpecialRisk = includesAny(joined, [
    "wasserhaltung",
    "verbau",
    "kontaminiert",
    "deponie",
    "kampfmittel",
    "altlast",
    "fels",
    "bodenklasse 7",
  ]);

  const logisticsRisk = risk(hasDifficultLogistics || hasSpecialRisk, hasTraffic);
  const trafficRisk = risk(false, hasTraffic);
  const durationRisk = risk(hasLongDuration, false);

  const difficulty: RlcRiskLevel =
    hasSpecialRisk || logisticsRisk === "high"
      ? "high"
      : hasTraffic || hasDifficultLogistics
        ? "medium"
        : "low";

  const warnings: string[] = [];
  if (hasTraffic) warnings.push("Verkehrsführung/Verkehrssicherung technisch und preislich prüfen.");
  if (hasDifficultLogistics) warnings.push("Logistik, Zufahrt und Arbeiten im Bestand erhöhen Kalkulationsrisiko.");
  if (hasLongDuration) warnings.push("Vorhaltung/Bauzeit beeinflusst Baustellengemeinkosten und Geräteansätze.");
  if (hasSpecialRisk) warnings.push("Sonderrisiken wie Verbau, Wasserhaltung, Fels, Deponie oder Altlasten prüfen.");

  const marketIndex = getBaupreisIndexFactor({
    sourceDate: "2024-02-01",
    targetDate: new Date(),
    text: joined,
  });

  const marketFactor =
    marketIndex.reliable
      ? marketIndex.factor
      : 1;

  return {
    projectCode,
    projectType:
      detectedFamilies.length > 1
        ? detectedFamilies.map((f) => f.label).join(" / ")
        : primaryFamily.label,
    trade: primaryFamily.trade,
    difficulty,
    logisticsRisk,
    trafficRisk,
    durationRisk,
    marketFactor,
    distanceFactor: 1.0,
    confidence: rows.length > 0 ? 0.7 : 0.45,
    warnings,
  };
}

import { resolveRlcResourceProfile } from "./familyResourceResolver";
import type { RlcAutonomousCalcInput } from "./types";

export type RlcRecipeCompatibilityResult = {
  compatible: boolean;
  inputFamily?: string;
  recipeFamily?: string;
  reason: string;
};

export function validateRecipeFamilyCompatibility(
  row: RlcAutonomousCalcInput,
  recipe: Record<string, any> | null | undefined
): RlcRecipeCompatibilityResult {
  if (!recipe) {
    return {
      compatible: false,
      reason: "Kein Recipe-Kandidat vorhanden.",
    };
  }

  const inputProfile = resolveRlcResourceProfile(row);

  const recipeProfile = resolveRlcResourceProfile({
    kurztext: [
      recipe.gewerk,
      recipe.leistungsart,
      recipe.bauverfahren,
    ]
      .filter(Boolean)
      .join(" "),
    langtext: "",
  });

  // Kann die Eingangsposition keiner Familie sicher zugeordnet werden,
  // entscheidet dieser Guard nicht gegen bestehende Legacy-Rezepte.
  if (!inputProfile) {
    return {
      compatible: true,
      recipeFamily: recipeProfile?.family,
      reason: "Eingangsfamilie nicht eindeutig; Legacy-Rezept bleibt zulässig.",
    };
  }

  // Für eine erkannte Eingangsfamilie muss auch das Recipe
  // fachlich einer Familie zugeordnet werden können.
  if (!recipeProfile) {
    return {
      compatible: false,
      inputFamily: inputProfile.family,
      reason: "Recipe-Kandidat besitzt keine kompatibel erkennbare Baufamilie.",
    };
  }

  const compatible = inputProfile.family === recipeProfile.family;

  return {
    compatible,
    inputFamily: inputProfile.family,
    recipeFamily: recipeProfile.family,
    reason: compatible
      ? "Eingangsposition und Recipe gehören zur gleichen Baufamilie."
      : `Familienkonflikt: ${inputProfile.family} != ${recipeProfile.family}.`,
  };
}

import { runKalkulationAgents } from "../agents/orchestrator";
import type { KalkulationAgentsResult } from "../agents/types";
import { calculateAutonomousUrkalkulation } from "./autonomousUrkalkulationEngine";
import { analyzeRlcProjectContext } from "./projectContextAnalyzer";
import type {
  RlcAutonomousCalcInput,
  RlcAutonomousCalcResult,
  RlcAutonomousProjectContext,
} from "./types";

export type RlcAutonomousResolveResult = {
  context: RlcAutonomousProjectContext;
  agents: KalkulationAgentsResult;
  result: RlcAutonomousCalcResult | null;
};

export function resolveRlcAutonomousCalculation(
  row: RlcAutonomousCalcInput,
  allRows: RlcAutonomousCalcInput[] = [],
  projectCode?: string
): RlcAutonomousResolveResult {
  const context = analyzeRlcProjectContext(
    allRows.length > 0 ? allRows : [row],
    projectCode
  );

  const agents = runKalkulationAgents({
    row,
    allRows: allRows.length > 0 ? allRows : [row],
    projectContext: context,
  });

  const engineResult = calculateAutonomousUrkalkulation(
    row,
    context,
    allRows.length > 0 ? allRows : [row]
  );

  const result = engineResult
    ? {
        ...engineResult,
        confidence: Math.min(engineResult.confidence, agents.confidence),
        riskLevel:
          agents.summary.riskLevel === "high"
            ? "high"
            : engineResult.riskLevel,
        calculationStatus: agents.summary.reviewRequired
          ? "needs_review"
          : engineResult.calculationStatus,
        warnings: Array.from(
          new Set([...engineResult.warnings, ...agents.warnings])
        ),
        aiReason:
          `${engineResult.aiReason} ` +
          `Agentenanalyse: ${agents.summary.trade}, ` +
          `${agents.summary.bauverfahren}, Risiko ${agents.summary.riskLevel}.`,
      }
    : null;

  return {
    context,
    agents,
    result,
  };
}

export function mapAutonomousResultToKiRow(
  row: RlcAutonomousCalcInput,
  resolved: RlcAutonomousResolveResult
): any | null {
  const r = resolved.result;
  if (!r) return null;

  return {
    ...row,
    finalUnitPrice: r.unitPrice,
    suggestedUnitPrice: r.unitPrice,
    baseUnitPrice: r.unitPrice,
    rlcKiUnitPrice: r.unitPrice,
    totalNet: r.total,
    rlcKiTotal: r.total,
    confidence: r.confidence,
    riskLevel: r.riskLevel,
    calculationStatus: r.calculationStatus,
    source: r.source,
    gewerk: r.trade,
    bauverfahren: r.bauverfahren,
    leistungsart: r.leistungsart,
    priceBreakdown: r.costLines,
    rlcAutonomousContext: resolved.context,
    rlcAgentSummary: resolved.agents.summary,
    rlcAgentReports: resolved.agents.reports,
    warning: r.warnings.join(" · "),
    aiReason: r.aiReason,
  };
}

import type {
  RlcAutonomousCalcInput,
  RlcAutonomousCalcResult,
  RlcAutonomousCostLine,
  RlcAutonomousProjectContext,
  RlcRiskLevel,
} from "./types";

function n(v: unknown): number {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
}

function s(v: unknown): string {
  return String(v ?? "");
}

function round2(v: number): number {
  return Math.round((v + Number.EPSILON) * 100) / 100;
}

function textOf(row: RlcAutonomousCalcInput): string {
  return `${row.kurztext ?? ""} ${row.langtext ?? ""}`.toLowerCase();
}

function hasAny(text: string, words: string[]): boolean {
  return words.some((w) => text.includes(w));
}

function addLine(
  lines: RlcAutonomousCostLine[],
  group: RlcAutonomousCostLine["group"],
  name: string,
  unitPrice: number,
  unit: string,
  note?: string
): void {
  if (unitPrice <= 0) return;

  lines.push({
    id: `${group.toLowerCase()}-${lines.length + 1}`,
    group,
    name,
    qty: 1,
    unit,
    unitPrice: round2(unitPrice),
    total: round2(unitPrice),
    note,
  });
}

function riskFrom(ctx: RlcAutonomousProjectContext, forced?: RlcRiskLevel): RlcRiskLevel {
  if (forced) return forced;
  if (ctx.difficulty === "high" || ctx.logisticsRisk === "high") return "high";
  if (ctx.difficulty === "medium" || ctx.trafficRisk === "medium" || ctx.durationRisk === "medium") return "medium";
  return "low";
}

function statusFromRisk(risk: RlcRiskLevel): RlcAutonomousCalcResult["calculationStatus"] {
  if (risk === "high") return "needs_review";
  if (risk === "medium") return "warning";
  return "ok";
}

function sum(lines: RlcAutonomousCostLine[]): number {
  return round2(lines.reduce((a, l) => a + n(l.total), 0));
}

function finish(
  row: RlcAutonomousCalcInput,
  ctx: RlcAutonomousProjectContext,
  trade: string,
  bauverfahren: string,
  leistungsart: string,
  lines: RlcAutonomousCostLine[],
  riskLevel: RlcRiskLevel,
  extraWarnings: string[] = []
): RlcAutonomousCalcResult {
  const unit = s(row.einheit || "EH");
  const qty = Math.max(1, n(row.menge));

  const base = sum(lines);
  addLine(lines, "Gemeinkosten", "Baustellengemeinkosten", base * 0.1, unit, "10 % BGK");
  addLine(lines, "Risiko", "Risikopuffer", base * (riskLevel === "high" ? 0.08 : riskLevel === "medium" ? 0.05 : 0.03), unit);
  addLine(lines, "Gewinn", "Gewinnanteil", base * 0.08, unit, "8 % Zielgewinn");

  const marketDistanceFactor = ctx.marketFactor * ctx.distanceFactor;
  if (Math.abs(marketDistanceFactor - 1) > 0.000001) {
    for (const line of lines) {
      line.unitPrice = round2(n(line.unitPrice) * marketDistanceFactor);
      line.total = round2(n(line.total) * marketDistanceFactor);
    }
  }
  const unitPrice = round2(sum(lines));
  const total = round2(unitPrice * qty);

  return {
    unitPrice,
    total,
    confidence: riskLevel === "high" ? 0.6 : riskLevel === "medium" ? 0.7 : 0.8,
    riskLevel,
    source: "rlc-autonomous-urkalkulation-v2-tiefbau-family",
    calculationStatus: statusFromRisk(riskLevel),
    trade,
    bauverfahren,
    leistungsart,
    costLines: lines,
    warnings: [
      ...ctx.warnings,
      ...extraWarnings,
      "RLC Autonomous Tiefbau Family Catalog V2 verwendet. Preis aus Kostenbestandteilen kalkuliert, nicht aus X84.",
    ],
    aiReason:
      `RLC Autonomous Tiefbau Family Catalog V2.\n` +
      `Familie: ${trade}.\n` +
      `Bauverfahren: ${bauverfahren}.\n` +
      `Leistungsart: ${leistungsart}.\n` +
      `Kostenbestandteile: Lohn, Material, Maschinen, Entsorgung/Nachunternehmer, Gemeinkosten, Risiko und Gewinn.\n` +
      `Marktfaktor: ${ctx.marketFactor}, Distanzfaktor: ${ctx.distanceFactor}. Kein X84 als Preisquelle verwendet.`,
  };
}

