    /*
     * Wichtig:
     * Auto-Learning erstellt nur einen Vorschlag.
     * Keine automatische Freigabe und keine Preisänderung.
     */
    reviewRequired: true,
  };

  const existing = await prisma.companyRecipeDb.findUnique({
    where: {
