      priceBreakdown,
    };
  }

  const lightSurface = lightSurfaceRange(text, einheit);

  if (lightSurface.avg > 0) {
    const ep =
      existingEp > 0 && existingEp >= lightSurface.min && existingEp <= lightSurface.max
        ? existingEp
        : lightSurface.avg;

    return make(
      ep,
      lightSurface.group,
      lightSurface.label,
      "Straßenbau / Oberfläche",
