  if (isPflasterNew) {
    const ep = n(range.avg) > 0 && String(range.matches?.[0]?.group || "") !== "Material"
      ? n(range.avg)
      : 75;
    return make(ep, "Fremdleistung", "Pflasterfläche komplett herstellen", "Oberfläche / Pflaster");
  }

  return null;
}


