      unit: einheit || "EH",
      qty: 1,
      price: profitCost,
      total: profitCost,
      note: "8 % aus technischer RLC-Kalkulation",
    }
  );

  return {
    id: row.id,
    posNr: s(row.posNr),
    kurztext: s(row.kurztext),
    langtext: s(row.langtext),
    einheit,
    menge,

