import { findExternalKnowledgeMatches } from "./externalKnowledge/externalKnowledgeEngine";

export type RlcKnowledgeHubInput = {
  kurztext?: string;
  langtext?: string;
  text?: string;
  unit?: string;
  family?: string;
};

export type RlcKnowledgeHubResult = {
  externalMatches: ReturnType<typeof findExternalKnowledgeMatches>;
  hasExternalKnowledge: boolean;
  externalKnowledgeConfidence: number;
  technicalNotes: string[];
};

export function resolveRlcKnowledgeHub(input: RlcKnowledgeHubInput): RlcKnowledgeHubResult {
  const externalMatches = findExternalKnowledgeMatches({
    text: input.text,
    kurztext: input.kurztext,
    langtext: input.langtext,
    unit: input.unit,
    family: input.family,
    limit: 5
  });

  const externalKnowledgeConfidence =
    externalMatches.length > 0
      ? Math.max(...externalMatches.map((x) => x.confidence || 0))
      : 0;

  const technicalNotes = externalMatches.map(
    (x) => `Externes Wissen: ${x.title} (${x.sourceName}, confidence ${x.confidence})`
  );

  return {
    externalMatches,
    hasExternalKnowledge: externalMatches.length > 0,
    externalKnowledgeConfidence,
    technicalNotes
  };
}

import { resolveRlcKnowledgeHub } from "../knowledgeHub";

export type RlcPipelineInput = {
  row: any;
  baseResult: any;
};

function s(v: any): string {
  return String(v ?? "").trim();
}

function norm(v: any): string {
  return s(v)
    .toLowerCase()
    .replace(/[ä]/g, "ae")
    .replace(/[ö]/g, "oe")
    .replace(/[ü]/g, "ue")
    .replace(/[ß]/g, "ss");
}

function includesAny(text: string, words: string[]): boolean {
  return words.some((w) => text.includes(norm(w)));
}

function buildTechnicalBreakdown(row: any, result: any) {
  const text = norm(`${row?.kurztext || ""} ${row?.langtext || ""} ${result?.aiReason || ""}`);
  const unit = norm(row?.einheit);

  const machines: string[] = [];
  const labor: string[] = [];
  const materials: string[] = [];
  const risks: string[] = [];
  const logistics: string[] = [];

  if (includesAny(text, ["aushub", "rohrgraben", "graben", "bodenklasse"])) {
    machines.push("Bagger");
    labor.push("Maschinist", "Tiefbauer");
    risks.push("Bodenklasse prüfen", "Verbau/Wasserhaltung prüfen");
  }

  if (includesAny(text, ["schutzmatte", "kabelschutz", "kabelverlegung"])) {
    materials.push("Schutzmatte/Kabelschutz");
    labor.push("Kolonne Kabelbau");
    risks.push("Trassenabschnitte und Kreuzungen prüfen");
  }

  if (includesAny(text, ["rohr", "hdpe", "pehd", "duktil", "dn ", "da "])) {
    materials.push("Rohrmaterial");
    labor.push("Rohrleger");
    risks.push("DN/DA, Druckstufe und Formstücke prüfen");
  }

  if (includesAny(text, ["pflaster", "asphalt", "forststraße", "forststrasse", "oberfläche", "oberflaeche"])) {
    machines.push("Verdichtungsgerät");
    materials.push("Oberbaumaterial");
    risks.push("Schichtaufbau und Wiederherstellungsstandard prüfen");
  }

  if (includesAny(text, ["entsorgung", "deponie", "haufwerk"])) {
    logistics.push("Transport/Entsorgung");
    risks.push("Deponieklasse und Wiegescheine prüfen");
  }

  if (unit === "psch" || unit === "pauschal") {
    risks.push("Pauschalposition: Dauer, Umfang und Abgrenzung prüfen");
    logistics.push("Baustellenlogistik");
  }

  return {
    machines: Array.from(new Set(machines)),
    labor: Array.from(new Set(labor)),
    materials: Array.from(new Set(materials)),
    logistics: Array.from(new Set(logistics)),
    risks: Array.from(new Set(risks))
  };
}

export function enrichRlcCalculationPipeline(input: RlcPipelineInput): any {
  const { row, baseResult } = input;
  if (!baseResult || typeof baseResult !== "object") return baseResult;

  const knowledgeHub = resolveRlcKnowledgeHub({
    kurztext: row?.kurztext,
    langtext: row?.langtext,
    text: `${row?.kurztext || ""} ${row?.langtext || ""}`,
    unit: row?.einheit,
    family: baseResult?.rlcFamily || baseResult?.family || baseResult?.gewerk || baseResult?.source
  });

  const technicalBreakdown = buildTechnicalBreakdown(row, baseResult);

  console.log("[RLC Pipeline V3]", {
    posNr: row?.posNr,
    externalMatches: knowledgeHub.externalMatches.length,
    externalConfidence: knowledgeHub.externalKnowledgeConfidence,
    machines: technicalBreakdown.machines.length,
    labor: technicalBreakdown.labor.length,
    materials: technicalBreakdown.materials.length,
    risks: technicalBreakdown.risks.length
  });

  return {
    ...baseResult,
    externalKnowledge: knowledgeHub.hasExternalKnowledge ? knowledgeHub.externalMatches : baseResult.externalKnowledge,
    externalKnowledgeConfidence: knowledgeHub.hasExternalKnowledge
      ? knowledgeHub.externalKnowledgeConfidence
      : baseResult.externalKnowledgeConfidence,
    technicalBreakdown,
    explainability: {
      version: "RLC_PIPELINE_V3",
      confidence: baseResult?.confidence ?? null,
      source: baseResult?.source ?? "",
      machines: technicalBreakdown.machines,
      labor: technicalBreakdown.labor,
      materials: technicalBreakdown.materials,
      logistics: technicalBreakdown.logistics,
      risks: technicalBreakdown.risks,
      standards: knowledgeHub.hasExternalKnowledge
        ? knowledgeHub.externalMatches.map((x: any) => x.title || x.sourceName).filter(Boolean)
        : [],
      externalSources: knowledgeHub.hasExternalKnowledge ? knowledgeHub.externalMatches : [],
      assumptions: [
        row?.einheit ? `Einheit: ${row.einheit}` : "",
        row?.menge ? `Menge: ${row.menge}` : "",
        baseResult?.source ? `Quelle: ${baseResult.source}` : ""
      ].filter(Boolean),
      calculationSteps: [
        "Basis-Kalkulation aus bestehender RLC-KI übernommen.",
        "Global Knowledge Hint angewendet, falls vorhanden.",
        "External Knowledge Hub geprüft.",
        "Technical Breakdown für Maschinen, Personal, Material, Logistik und Risiken erzeugt."
      ]
    },
    aiReason: [
      String(baseResult.aiReason || ""),
      ...knowledgeHub.technicalNotes,
      technicalBreakdown.risks.length
        ? `RLC Pipeline V2 technische Prüfung: ${technicalBreakdown.risks.join(" · ")}`
        : ""
    ].filter(Boolean).join("\n\n")
  };
}

export type BaupreisIndexFamily =
  | "UNSUPPORTED"
  | "STRASSENBAU"
  | "KANALBAU"
  | "ERDARBEITEN"
  | "ASPHALT"
  | "PFLASTER"
  | "TIEFBAU";

export type BaupreisIndexPoint = {
  date: string;
  index: number;
};

import {
  detectPrimaryRlcConstructionFamily,
} from "../domain/constructionFamilyRegistry";

import {
  STRASSENBAU_SERIES,
  KANALBAU_SERIES,
  TIEFBAU_SERIES,
  ERDARBEITEN_SERIES,
  ASPHALT_SERIES,
  PFLASTER_SERIES,
} from "./destatisBaupreisIndexData";

export type BaupreisIndexResult = {
  factor: number;
  sourceIndex: number | null;
  targetIndex: number | null;
  sourceDate: string | null;
  targetDate: string | null;
  family: BaupreisIndexFamily;
  source: string;
  reliable: boolean;
};

/*
 * RLC Baupreisindex Service
 *
 * Einzige zulässige Quelle für historische Baupreisfortschreibung.
 *
 * Keine pauschale jährliche Inflationsrate.
 * Keine X84-Preise als Kalkulationsquelle.
 *
 * Die offiziellen Destatis-Zeitreihen werden separat versioniert
 * eingespielt. Solange keine belastbaren Indexpunkte vorhanden sind,
 * liefert der Service neutral Faktor 1.0.
 */

/*
 * Destatis Baupreisindizes Ingenieurbau
 * Basis 2021 = 100.
 *
 * Quelle:
 * Statistisches Bundesamt – Baupreisindizes Ingenieurbau.
 *
 * Referenzmonate:
 * Q1 = Februar
 * Q2 = Mai
 * Q3 = August
 * Q4 = November
 */

const SERIES: Partial<Record<
  BaupreisIndexFamily,
  BaupreisIndexPoint[]
>> = {
  STRASSENBAU: STRASSENBAU_SERIES,
  KANALBAU: KANALBAU_SERIES,
  ASPHALT: ASPHALT_SERIES,
  PFLASTER: PFLASTER_SERIES,
  ERDARBEITEN: ERDARBEITEN_SERIES,
  TIEFBAU: TIEFBAU_SERIES,
};

function normalizeText(value: unknown): string {
  return String(value ?? "")
    .toLowerCase()
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/ß/g, "ss");
}

export function classifyBaupreisIndexFamily(
  text: unknown
): BaupreisIndexFamily {
  const raw = String(text ?? "");
  const t = normalizeText(raw);

  /*
   * Erst fachliche Construction Family bestimmen.
   * Dadurch darf z.B. "Bodenplatte" niemals wegen "boden"
   * als Erdarbeit indexiert werden.
   */
  const constructionFamily =
    detectPrimaryRlcConstructionFamily(raw).id;

  if (constructionFamily === "KANALBAU") {
    return "KANALBAU";
  }

  if (constructionFamily === "ERDARBEITEN") {
    return "ERDARBEITEN";
  }

  if (constructionFamily === "KABELBAU") {
    return "TIEFBAU";
  }

  if (constructionFamily === "STRASSENBAU") {
    if (/asphalt|bitumen|asphaltdecke|asphalttragschicht/.test(t)) {
      return "ASPHALT";
    }

    if (/pflaster|pflasterdecke|natursteinpflaster|betonpflaster/.test(t)) {
      return "PFLASTER";
    }

    return "STRASSENBAU";
  }

  return "UNSUPPORTED";
}

function validDate(value: unknown): Date | null {
  if (!value) return null;

  const d = new Date(String(value));

  return Number.isFinite(d.getTime()) ? d : null;
}

function pointAtOrBefore(
  series: BaupreisIndexPoint[],
  date: Date
): BaupreisIndexPoint | null {
  if (!series.length) return null;

  const target = date.getTime();

  const eligible = series
    .map((p) => ({
      point: p,
      date: validDate(p.date),
    }))
    .filter(
      (x): x is { point: BaupreisIndexPoint; date: Date } =>
        x.date !== null && x.date.getTime() <= target
    )
    .sort((a, b) => b.date.getTime() - a.date.getTime());

  return eligible[0]?.point ?? null;
}

export function getBaupreisIndexFactor(input: {
  sourceDate?: unknown;
  targetDate?: unknown;
  text?: unknown;
  family?: BaupreisIndexFamily;
}): BaupreisIndexResult {
  const family =
    input.family ?? classifyBaupreisIndexFamily(input.text);

  const sourceDate = validDate(input.sourceDate);
  const targetDate = validDate(input.targetDate) ?? new Date();

  if (family === "UNSUPPORTED") {
    return {
      factor: 1,
      sourceIndex: null,
      targetIndex: null,
      sourceDate: sourceDate?.toISOString() ?? null,
      targetDate: targetDate.toISOString(),
      family,
      source: "DESTatis:no-compatible-series",
      reliable: false,
    };
  }

  if (!sourceDate) {
    return {
      factor: 1,
      sourceIndex: null,
      targetIndex: null,
      sourceDate: null,
      targetDate: targetDate.toISOString(),
      family,
      source: "DESTatis:pending-series",
      reliable: false,
    };
  }

  const series = SERIES[family] ?? [];

  if (sourceDate.getTime() > targetDate.getTime()) {
    return {
      factor: 1,
      sourceIndex: null,
      targetIndex: null,
      sourceDate: sourceDate.toISOString(),
      targetDate: targetDate.toISOString(),
      family,
      source: "DESTatis:invalid-date-range",
      reliable: false,
    };
  }

  const sourcePoint = pointAtOrBefore(series, sourceDate);
  const targetPoint = pointAtOrBefore(series, targetDate);

  if (
    !sourcePoint ||
    !targetPoint ||
    sourcePoint.index <= 0 ||
    targetPoint.index <= 0
  ) {
    return {
      factor: 1,
      sourceIndex: sourcePoint?.index ?? null,
      targetIndex: targetPoint?.index ?? null,
      sourceDate: sourceDate.toISOString(),
      targetDate: targetDate.toISOString(),
      family,
      source: "DESTatis:pending-series",
      reliable: false,
    };
  }

  return {
    factor: targetPoint.index / sourcePoint.index,
    sourceIndex: sourcePoint.index,
    targetIndex: targetPoint.index,
    sourceDate: sourcePoint.date,
    targetDate: targetPoint.date,
    family,
    source: "DESTatis",
    reliable: true,
  };
}

import { prisma } from "../../lib/prisma";
import {
  detectPrimaryRlcConstructionFamily,
  type RlcConstructionFamilyId,
} from "../domain/constructionFamilyRegistry";
import {
  isRlcPriceSourceBlocked,
  rlcPriceSourceQualityStatus,
} from "../quality/priceSourceQualityGate";
import { getBaupreisIndexFactor } from "../priceIndex/baupreisIndexService";
import { rlcPreisRangeForText } from "../rlcPreisBibliothek";

export type RlcResolvedPriceSource =
  | "COMPANY_RECIPE"
  | "KALKULATION_DB"
  | "GLOBAL_KNOWLEDGE"
  | "RLC_TIEFBAU_LIBRARY"
  | "UNRESOLVED";

export type RlcPriceResolution = {
  status: "RESOLVED" | "UNRESOLVED";
  source: RlcResolvedPriceSource;
  sourceId?: string;
  family: RlcConstructionFamilyId;
  unit: string;
  unitPrice: number | null;
  originalUnitPrice?: number | null;
  confidence: number;
  qualityStatus?: string;
  priceDate?: string | null;
  priceDateSource?: string | null;
  indexFactor?: number;
  indexApplied?: boolean;
  reason: string;
};

export type RlcPriceResolverInput = {
  companyId: string;
  kurztext: string;
  langtext?: string;
  einheit?: string;
  targetDate?: Date | string;
};

const TIEFBAU_FAMILIES = new Set<RlcConstructionFamilyId>([
  "ERDARBEITEN",
  "KANALBAU",
  "KABELBAU",
  "STRASSENBAU",
]);

function text(v: unknown): string {
  return String(v ?? "").trim();
}

function norm(v: unknown): string {
  return text(v)
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normUnit(v: unknown): string {
  const u = norm(v).replace(/\s/g, "");
  if (u === "m2" || u === "m²") return "m2";
  if (u === "m3" || u === "m³") return "m3";
  if (u === "stk" || u === "stuck" || u === "stück") return "st";
  return u;
}

function tokens(v: unknown): string[] {
  return [...new Set(
    norm(v)
      .split(" ")
      .filter((x) => x.length >= 3)
  )];
}

function similarity(a: unknown, b: unknown): number {
  const left = tokens(a);
  const right = tokens(b);

  if (!left.length || !right.length) return 0;

  const common = left.filter((x) => right.includes(x)).length;

  const precision = common / left.length;
  const recall = common / right.length;

  if (precision + recall === 0) return 0;

  return (2 * precision * recall) / (precision + recall);
}

function sameUnit(a: unknown, b: unknown): boolean {
  const x = normUnit(a);
  const y = normUnit(b);
  return !!x && !!y && x === y;
}

function familyOf(v: unknown): RlcConstructionFamilyId {
  return detectPrimaryRlcConstructionFamily(text(v)).id;
}

function compatibleFamily(
  sourceText: unknown,
  targetFamily: RlcConstructionFamilyId
): boolean {
  const f = familyOf(sourceText);
  return f !== "ALLGEMEIN" && f === targetFamily;
}

function qualityWeight(row: any): number {
  const status = rlcPriceSourceQualityStatus(row);

  if (status === "Freigegeben") return 1;
  if (status === "Geprüft") return 0.95;
  if (status === "KI-Vorschlag") return 0.72;

  return 0.82;
}

function directRecipeTotal(lines: unknown): number {
  if (!Array.isArray(lines)) return 0;

  return lines.reduce((sum, line: any) => {
    const total = Number(line?.total);
    if (Number.isFinite(total) && total > 0) return sum + total;

    const qty = Number(line?.qty || 1);
    const price = Number(line?.price ?? line?.unitPrice);

    if (
      Number.isFinite(qty) &&
      Number.isFinite(price) &&
      qty > 0 &&
      price > 0
    ) {
      return sum + qty * price;
    }

    return sum;
  }, 0);
}

function applyHistoricalIndex(args: {
  price: number;
  priceDate?: Date | null;
  targetDate: Date | string;
  text: string;
}) {
  if (!args.priceDate) {
    return {
      price: args.price,
      factor: 1,
      applied: false,
    };
  }

  const index = getBaupreisIndexFactor({
    sourceDate: args.priceDate,
    targetDate: args.targetDate,
    text: args.text,
  });

  if (!index.reliable || index.factor <= 0) {
    return {
      price: args.price,
      factor: 1,
      applied: false,
    };
  }

  return {
    price: Math.round(args.price * index.factor * 100) / 100,
    factor: index.factor,
    applied: true,
  };
}

export async function resolveRlcPrice(
  input: RlcPriceResolverInput
): Promise<RlcPriceResolution> {
  const kurztext = text(input.kurztext);
  const langtext = text(input.langtext);
  const unit = text(input.einheit);
  const fullText = [kurztext, langtext].filter(Boolean).join(" ");
  const family = familyOf(fullText);
  const targetDate = input.targetDate || new Date();

  if (!input.companyId || !kurztext || !unit) {
    return {
      status: "UNRESOLVED",
      source: "UNRESOLVED",
      family,
      unit,
      unitPrice: null,
      confidence: 0,
      reason: "COMPANY_TEXT_OR_UNIT_MISSING",
    };
  }

  /*
   * 1. CompanyRecipeDb
   * Nur gleiche Einheit + gleiche Construction Family.
   */
  const recipes = await prisma.companyRecipeDb.findMany({
    where: { companyId: input.companyId },
    orderBy: { updatedAt: "desc" },
    take: 300,
  });

  const recipeCandidates = recipes
    .filter((r) => !isRlcPriceSourceBlocked(r))
    .filter((r) => sameUnit(r.unit, unit))
    .filter((r) =>
      compatibleFamily(
        [r.title, r.sourceText, (r.context as any)?.gewerk]
          .filter(Boolean)
          .join(" "),
        family
      )
    )
    .map((r) => {
      const ctx: any = r.context || {};

.filter((r) => !isRlcPriceSourceBlocked(r))
    .filter((r) => sameUnit(r.unit, unit))
    .filter((r) =>
      compatibleFamily(
        [r.title, r.sourceText, (r.context as any)?.gewerk]
          .filter(Boolean)
          .join(" "),
        family
      )
    )
    .map((r) => {
      const ctx: any = r.context || {};
      const finalEp = Number(ctx.finalUnitPrice || 0);
      const linesTotal = directRecipeTotal(r.lines);

      /*
       * Defense in depth:
       * Rezept nur verwenden, wenn EP und Kostenlinien kohärent sind.
       */
      if (!(finalEp > 0) || !(linesTotal > 0)) return null;

      const delta = Math.abs(linesTotal - finalEp);
      const tolerance = Math.max(0.02, finalEp * 0.02);

      if (delta > tolerance) return null;

      const sim = similarity(
        fullText,
        [r.title, r.sourceText].filter(Boolean).join(" ")
      );

      return {
        row: r,
        price: finalEp,
        score: sim * qualityWeight(r),
        similarity: sim,
      };
    })
    .filter(Boolean)
    .filter((x: any) => x.similarity >= 0.62)
    .sort((a: any, b: any) => b.score - a.score);

  if (recipeCandidates.length) {
    const best: any = recipeCandidates[0];
    const status = rlcPriceSourceQualityStatus(best.row);

    return {
      status: "RESOLVED",
      source: "COMPANY_RECIPE",
      sourceId: best.row.id,
      family,
      unit,
      unitPrice: Math.round(best.price * 100) / 100,
      originalUnitPrice: best.price,
      confidence: Math.min(0.98, best.score),
      qualityStatus: status,
      indexFactor: 1,
      indexApplied: false,
      reason: "COMPATIBLE_COMPANY_RECIPE",
    };
  }

  /*
   * 2. KalkulationsDbEntry
   */
  const dbRowsRaw = await prisma.kalkulationsDbEntry.findMany({
    where: {
      companyId: input.companyId,
      unitPriceNet: { gt: 0 },
    },
    orderBy: { updatedAt: "desc" },
    take: 500,
  });

  const dbCandidates = dbRowsRaw
    .filter((r) => !isRlcPriceSourceBlocked(r))
    .filter((r) => sameUnit(r.unit, unit))
    .filter((r) =>
      compatibleFamily(
        [r.shortText, r.longText, r.trade, r.serviceType]
          .filter(Boolean)
          .join(" "),
        family
      )
    )
    .map((r) => {
      const sim = similarity(
        fullText,
        [r.shortText, r.longText, r.trade, r.serviceType]
          .filter(Boolean)
          .join(" ")
      );

      return {
        row: r,
        similarity: sim,
        score:
          sim *
          qualityWeight(r) *
          Math.max(0.4, Math.min(1, Number(r.confidence || 0.75))),
      };
    })
    .filter((x) => x.similarity >= 0.62)
    .sort((a, b) => b.score - a.score);

  if (dbCandidates.length) {
    const best = dbCandidates[0];
    const original = Number(best.row.unitPriceNet);

    const indexed = applyHistoricalIndex({
      price: original,
      priceDate: best.row.priceDate,
      targetDate,
      text: fullText,
    });

    return {
      status: "RESOLVED",
      source: "KALKULATION_DB",
      sourceId: best.row.id,
      family,
      unit,
      unitPrice: indexed.price,
      originalUnitPrice: original,
      confidence: Math.min(0.96, best.score),
      qualityStatus: rlcPriceSourceQualityStatus(best.row),
      priceDate: best.row.priceDate?.toISOString() || null,
      priceDateSource: best.row.priceDateSource || null,
      indexFactor: indexed.factor,
      indexApplied: indexed.applied,
      reason: "COMPATIBLE_KALKULATION_DB_ENTRY",
    };
  }

  /*
   * 3. Global Knowledge.
   * Aggregat = Evidenz niedrigerer Priorität.
   */
  const globals = await prisma.rlcGlobalPriceKnowledge.findMany({
    where: {
      confidence: { gte: 0.55 },
    },
    orderBy: [
      { confidence: "desc" },
      { sampleCount: "desc" },
      { updatedAt: "desc" },
    ],
    take: 500,
  });

  const globalCandidates = globals
    .filter((r) => sameUnit(r.unit, unit))
    .filter((r) =>
      compatibleFamily(
        [r.shortText, r.trade, r.serviceType, r.constructionMethod]
          .filter(Boolean)
          .join(" "),
        family
      )
    )
    .map((r) => {
      const sim = similarity(
        fullText,
        [r.shortText, r.trade, r.serviceType, r.constructionMethod]
          .filter(Boolean)
          .join(" ")
      );

      return {
        row: r,
        similarity: sim,
        score: sim * Math.max(0.4, Math.min(1, Number(r.confidence))),
      };
    })
    .filter((x) => x.similarity >= 0.68)
    .sort((a, b) => b.score - a.score);

  if (globalCandidates.length) {
    const best = globalCandidates[0];
    const price =
      Number(best.row.medianPrice || 0) ||
      Number(best.row.avgPrice || 0);

    if (price > 0) {
      return {
        status: "RESOLVED",
        source: "GLOBAL_KNOWLEDGE",
        sourceId: best.row.id,
        family,
        unit,
        unitPrice: Math.round(price * 100) / 100,
        originalUnitPrice: price,
        confidence: Math.min(0.9, best.score),
        priceDate: null,
        priceDateSource: null,
        indexFactor: 1,
        indexApplied: false,
        reason: "COMPATIBLE_GLOBAL_AGGREGATE_NO_EXACT_PRICE_DATE",
      };
    }
  }

  /*
   * 4. Legacy RLC Preisbibliothek:
   * ausschließlich bekannte Tiefbau-Familien.
   */
  if (TIEFBAU_FAMILIES.has(family)) {
    const range = rlcPreisRangeForText(fullText, unit);

    if (range.matches.length && range.avg > 0) {
      return {
        status: "RESOLVED",
        source: "RLC_TIEFBAU_LIBRARY",

/*
   * 4. Legacy RLC Preisbibliothek:
   * ausschließlich bekannte Tiefbau-Familien.
   */
  if (TIEFBAU_FAMILIES.has(family)) {
    const range = rlcPreisRangeForText(fullText, unit);

    if (range.matches.length && range.avg > 0) {
      return {
        status: "RESOLVED",
        source: "RLC_TIEFBAU_LIBRARY",
        family,
        unit,
        unitPrice: Math.round(range.avg * 100) / 100,
        originalUnitPrice: range.avg,
        confidence: 0.55,
        priceDate: null,
        priceDateSource: null,
        indexFactor: 1,
        indexApplied: false,
        reason: "LEGACY_TIEFBAU_LIBRARY",
      };
    }
  }

  return {
    status: "UNRESOLVED",
    source: "UNRESOLVED",
    family,
    unit,
    unitPrice: null,
    confidence: 0,
    indexFactor: 1,
    indexApplied: false,
    reason: "NO_COMPATIBLE_PRICE_SOURCE",
  };
}

export type RlcPriceSourceQualityStatus =
  | "KI-Vorschlag"
  | "Geprüft"
  | "Freigegeben"
  | "Gesperrt"
  | "Nicht verwenden"
  | "";

function text(value: unknown): string {
  return String(value ?? "").trim();
}

export function rlcPriceSourceQualityStatus(row: any): RlcPriceSourceQualityStatus {
  const raw = text(
    row?.parameters?.qualityGateStatus ??
    row?.parameter?.qualityGateStatus ??
    row?.context?.qualityGateStatus
  );

  const normalized = raw.toLowerCase();

  if (normalized === "ki-vorschlag") return "KI-Vorschlag";
  if (normalized === "geprüft" || normalized === "geprueft") return "Geprüft";
  if (normalized === "freigegeben") return "Freigegeben";
  if (normalized === "gesperrt") return "Gesperrt";
  if (normalized === "nicht verwenden") return "Nicht verwenden";

  return "";
}

export function isRlcPriceSourceBlocked(row: any): boolean {
  const status = rlcPriceSourceQualityStatus(row);

  return status === "Gesperrt" || status === "Nicht verwenden";
}

export function filterUsableRlcPriceSources<T>(rows: T[]): T[] {
  return rows.filter((row) => !isRlcPriceSourceBlocked(row));
}

export type RlcGeometryResult = {
  value: number | null;
  unit: "m" | "m2" | "m3";
  formula: string;
  inputs: Record<string, number>;
  status: "resolved" | "missing_input";
};

function valid(...values: number[]): boolean {
  return values.every((v) => Number.isFinite(v) && v > 0);
}

function round3(value: number): number {
  return Math.round(value * 1000) / 1000;
}

export function rectangleArea(
  lengthM?: number,
  widthM?: number
): RlcGeometryResult {
  if (!valid(Number(lengthM), Number(widthM))) {
    return {
      value: null,
      unit: "m2",
      formula: "L × B",
      inputs: {},
      status: "missing_input",
    };
  }

  return {
    value: round3(Number(lengthM) * Number(widthM)),
    unit: "m2",
    formula: "L × B",
    inputs: {
      lengthM: Number(lengthM),
      widthM: Number(widthM),
    },
    status: "resolved",
  };
}

export function rectangularVolume(
  lengthM?: number,
  widthM?: number,
  heightM?: number
): RlcGeometryResult {
  if (!valid(Number(lengthM), Number(widthM), Number(heightM))) {
    return {
      value: null,
      unit: "m3",
      formula: "L × B × H",
      inputs: {},
      status: "missing_input",
    };
  }

  return {
    value: round3(
      Number(lengthM) * Number(widthM) * Number(heightM)
    ),
    unit: "m3",
    formula: "L × B × H",
    inputs: {
      lengthM: Number(lengthM),
      widthM: Number(widthM),
      heightM: Number(heightM),
    },
    status: "resolved",
  };
}

export function rectanglePerimeter(
  lengthM?: number,
  widthM?: number
): RlcGeometryResult {
  if (!valid(Number(lengthM), Number(widthM))) {
    return {
      value: null,
      unit: "m",
      formula: "2 × (L + B)",
      inputs: {},
      status: "missing_input",
    };
  }

  return {
    value: round3(2 * (Number(lengthM) + Number(widthM))),
    unit: "m",
    formula: "2 × (L + B)",
    inputs: {
      lengthM: Number(lengthM),
      widthM: Number(widthM),
    },
    status: "resolved",
  };
}

export function rectangularWallArea(
  lengthM?: number,
  widthM?: number,
  wallHeightM?: number
): RlcGeometryResult {
  if (!valid(Number(lengthM), Number(widthM), Number(wallHeightM))) {
    return {
      value: null,
      unit: "m2",
      formula: "2 × (L + B) × H",
      inputs: {},
      status: "missing_input",
    };
  }

  return {
    value: round3(
      2 *
        (Number(lengthM) + Number(widthM)) *
        Number(wallHeightM)
    ),
    unit: "m2",
    formula: "2 × (L + B) × H",
    inputs: {
      lengthM: Number(lengthM),
      widthM: Number(widthM),
      wallHeightM: Number(wallHeightM),
    },
    status: "resolved",
  };
}

export type RlcExplicitGeometry = {
  lengthM: number;
  widthM: number;
  heightM?: number;
  source: string;
};

/**
 * Extrahiert ausschließlich ausdrücklich angegebene rechteckige Abmessungen.
 *
 * Beispiele:
 *   8 x 6 m
 *   8 m x 6 m
 *   8 × 6 m
 *   8,5 x 6,2 m
 *   8 x 6 x 2,5 m
 *
 * Keine fachliche Zuordnung zu einer LV-Leistung.
 * Diese erfolgt anschließend semantisch.
 */
export function extractExplicitRectangularGeometry(
  text: string
): RlcExplicitGeometry[] {
  const source = String(text || "");
  const results: RlcExplicitGeometry[] = [];

  const numberPattern = String.raw`\d+(?:[.,]\d+)?`;

  const pattern = new RegExp(
    `(${numberPattern})\\s*(?:m\\s*)?[x×]\\s*` +
      `(${numberPattern})\\s*(?:m\\s*)?` +
      `(?:[x×]\\s*(${numberPattern})\\s*(?:m\\s*)?)?m\\b`,
    "gi"
  );

  for (const match of source.matchAll(pattern)) {
    const lengthM = Number(String(match[1]).replace(",", "."));
    const widthM = Number(String(match[2]).replace(",", "."));
    const heightM = match[3]
      ? Number(String(match[3]).replace(",", "."))
      : undefined;

    if (!valid(lengthM, widthM)) continue;
    if (heightM !== undefined && !valid(heightM)) continue;

    results.push({
      lengthM,
      widthM,
      ...(heightM !== undefined ? { heightM } : {}),
      source: String(match[0]).trim(),
    });
  }

  return results;
}

import { completeRlcAiText } from "../../services/ai/rlcAiGateway";
import { detectPrimaryRlcConstructionFamily } from "../domain/constructionFamilyRegistry";

export type RlcComposedResource = {
  refKey: string;
  type: "LABOR" | "MATERIAL" | "MACHINE" | "TRANSPORT" | "DISPOSAL" | "SUBCONTRACTOR";
  qtyFormula: string;
  mandatory: boolean;
  note?: string;
};

export type RlcComposedRecipe = {
  source: "AI_RESOURCE_COMPOSER";
  family: string;
  title: string;
  unit: string;
  confidence: number;
  components: RlcComposedResource[];
};

const ALLOWED_TYPES = new Set([
  "LABOR",
  "MATERIAL",
  "MACHINE",
  "TRANSPORT",
  "DISPOSAL",
  "SUBCONTRACTOR",
]);

function s(v: unknown): string {
  return String(v ?? "").trim();
}

function safeRefKey(v: unknown): string {
  return s(v)
    .toUpperCase()
    .replace(/Ä/g, "AE")
    .replace(/Ö/g, "OE")
    .replace(/Ü/g, "UE")
    .replace(/ß/g, "SS")
    .replace(/[^A-Z0-9:_-]+/g, "_")
    .replace(/_+/g, "_")
    .replace(/^_|_$/g, "");
}

export async function composeRlcResources(input: {
  kurztext: string;
  langtext?: string;
  einheit: string;
}): Promise<RlcComposedRecipe | null> {
  const text = [input.kurztext, input.langtext].filter(Boolean).join("\n");
  const detected = detectPrimaryRlcConstructionFamily(text);
  const family = s((detected as any)?.id || detected || "ALLGEMEIN");

  try {
    const ai = await completeRlcAiText({
      purpose: "kalkulation",
      temperature: 0,
      responseFormat: "json",
      maxTokens: 1400,
      messages: [
        {
          role: "system",
          content: `Du bist der Resource Composer der RLC-Kalkulation.

Deine einzige Aufgabe ist, eine Bauleistung in notwendige Ressourcen einer Urkalkulation zu zerlegen.

Du darfst KEINE Preise, Einheitspreise, Marktpreise oder Geldbeträge erzeugen.

Erlaubte Ressourcentypen:
LABOR, MATERIAL, MACHINE, TRANSPORT, DISPOSAL, SUBCONTRACTOR.

Regeln:
- Nur Ressourcen, die fachlich für die konkrete Leistung erforderlich sind.
- Keine benachbarten LV-Leistungen hinzufügen.
- Keine Marken oder Lieferanten erfinden.
- refKey muss stabil und allgemein wiederverwendbar sein.
- LABOR refKey beginnt mit LABOR:
- MATERIAL refKey beginnt mit MATERIAL:
- MACHINE refKey beginnt mit MACHINE:
- TRANSPORT refKey beginnt mit TRANSPORT:
- DISPOSAL refKey beginnt mit DISPOSAL:
- SUBCONTRACTOR refKey beginnt mit SUBCONTRACTOR:
- Mengen beziehen sich immer auf EINE Einheit der LV-Position.
- Verwende für typische Bauleistungen realistische Standardansätze pro Einheit.
- Für LABOR, MACHINE und TRANSPORT niemals automatisch 0 verwenden, wenn ein üblicher Bauansatz bekannt ist.
- Verwende params.menge nur für mengenabhängige Berechnungen.
- Beispiele:
  - Erdarbeiten: Personal und Verdichtung als Stundenansatz pro m3.
  - Frostschutzschicht: Material ca. 1 m3/m3, Verdichtung und Einbau mit Standardkoeffizienten.
  - Kanalbau: Verlegeleistung mit Personal und Gerät berücksichtigen.
- Nur wenn fachlich wirklich keine Aussage möglich ist, darf qtyFormula "0" verwendet werden.
- Keine erfundenen technischen Maße.
- Pflichtressourcen mandatory=true.
- Antworte ausschließlich als JSON.

Schema:
{
  "title": "string",
  "confidence": 0.0,
  "components": [
    {
      "refKey": "TYPE:RESOURCE",
      "type": "LABOR|MATERIAL|MACHINE|TRANSPORT|DISPOSAL|SUBCONTRACTOR",
      "qtyFormula": "number or simple params expression",
      "mandatory": true,
      "note": "short reason"
    }
  ]
}`,
        },
        {
          role: "user",
          content: `Baufamilie: ${family}
LV-Einheit: ${input.einheit}
Kurztext: ${input.kurztext}
Langtext: ${input.langtext || ""}`,
        },
      ],
    });

    const parsed = JSON.parse(ai.text || "{}");
    const rawComponents = Array.isArray(parsed.components)
      ? parsed.components
      : [];

    const components: RlcComposedResource[] = [];

    for (const raw of rawComponents) {
      const type = s(raw?.type).toUpperCase();

      if (!ALLOWED_TYPES.has(type)) continue;

      const refKey = safeRefKey(raw?.refKey);
      if (!refKey.startsWith(`${type}:`)) continue;

      const qtyFormula = s(raw?.qtyFormula);
      if (!qtyFormula) continue;

      /*
       * Keine freie JavaScript-Injektion aus KI-Ausgabe.
       * Nur Zahlen und einfache params-Ausdrücke zulassen.
       */
      if (
        !/^[0-9a-zA-Z_.*+\-/()\s]+$/.test(qtyFormula) ||
        (!/^\d+(?:\.\d+)?$/.test(qtyFormula) &&
          !qtyFormula.includes("params."))
      ) {
        continue;
      }

      components.push({
        refKey,
        type: type as RlcComposedResource["type"],
        qtyFormula,
        mandatory: raw?.mandatory !== false,
        note: s(raw?.note) || "RLC Resource Composer",
      });
    }

    if (!components.length) return null;

    return {
      source: "AI_RESOURCE_COMPOSER",
      family,
      title: s(parsed.title) || input.kurztext,
      unit: input.einheit,
      confidence: Math.max(
        0,
        Math.min(1, Number(parsed.confidence) || 0)
      ),
      components,
    };
  } catch (error) {
    console.error("[RLC_RESOURCE_COMPOSER]", error);
    return null;
  }
}

