export function parseRlcTechnicalPosition(input: {
  posNr?: string;
  kurztext?: string;
  langtext?: string;
  einheit?: string;
  menge?: number;
}): RlcTechnicalParseResult {
  const text = `${input.kurztext || ""} ${input.langtext || ""}`;
  const t = norm(text);
  const unit = normUnit(input.einheit || "");
  const menge = n(input.menge);

  const surface = detectSurface(text);
  const soilClass = detectSoilClass(text);
  const thickness_cm = extractThicknessCm(text);
  const depth_m = extractDepth(text);
  const width_m = extractWidth(text);
  const transport_distance_km = extractTransportKm(text);

  const materialHints = detectMaterialHints(text);
  const riskHints = detectRiskHints(text);
  const detected = detectLeistungsart(text);

  const isArea = unit === "m2";
  const isLength = unit === "m";
  const isVolume = unit === "m3";
  const isCount = unit === "st";

  const area_m2 = isArea ? 1 : 0;
  const length_m = isLength ? 1 : 0;
  const volume_m3 = isVolume ? 1 : 0;
  const count = isCount ? 1 : 0;

  function extractLayerCmByKeywords(keys: string[], fallbackCm = 0): number {
    const parts = t.split(" ");
    let best = 0;

    for (let i = 0; i < parts.length; i++) {
      const windowText = parts
        .slice(Math.max(0, i - 8), Math.min(parts.length, i + 10))
        .join(" ");

      const hasKey = keys.some((k) => windowText.includes(k));
      if (!hasKey) continue;

      const patterns = [
        /(\d+(?:[,.]\d+)?)\s*cm\b/,
        /d\s*[=:]?\s*(\d+(?:[,.]\d+)?)\s*cm\b/,
        /staerke\s*(?:von)?\s*(\d+(?:[,.]\d+)?)\s*cm\b/,
        /starke\s*(?:von)?\s*(\d+(?:[,.]\d+)?)\s*cm\b/,
        /dicke\s*(?:von)?\s*(\d+(?:[,.]\d+)?)\s*cm\b/,
        /(\d+(?:[,.]\d+)?)\s*m\b/,
      ];

      for (const p of patterns) {
        const m = windowText.match(p);
        if (!m?.[1]) continue;

        const value = n(m[1]);
        if (value <= 0) continue;

        // Meter-Angaben wie 0,35 m in cm umrechnen.
        const cm = p.source.includes("\\s*m") && value <= 2 ? value * 100 : value;
        best = Math.max(best, cm);
      }
    }

    return best || fallbackCm;
  }

  function hasAnyKeyword(keys: string[]): boolean {
    return keys.some((k) => t.includes(k));
  }

  /*
   * Intelligente Default-Schichtdicken:
   * Nur verwenden, wenn das Material im LV-Text wirklich genannt wird,
   * aber keine konkrete cm/m-Angabe gefunden wurde.
   */
  const sand_cm = extractLayerCmByKeywords(
    ["sandbett", "rohrsand", "kabelsand", "rohrbettung"],
    hasAnyKeyword(["sandbett", "rohrsand", "kabelsand", "rohrbettung"]) ? 10 : 0
  );

  const splitt_cm = extractLayerCmByKeywords(
    ["splittbett", "splitt"],
    hasAnyKeyword(["splittbett", "splitt"]) ? 5 : 0
  );

  const frostschutz_cm = extractLayerCmByKeywords(
    ["frostschutz", "frostschutzschicht"],
    hasAnyKeyword(["frostschutz", "frostschutzschicht"]) ? 30 : 0
  );

  const schotter_cm = extractLayerCmByKeywords(
    ["schottertragschicht", "schotter"],
    hasAnyKeyword(["schottertragschicht", "schotter"]) ? 30 : 0
  );

  const kies_cm = extractLayerCmByKeywords(
    ["kiestragschicht"],
    hasAnyKeyword(["kiestragschicht"]) ? 30 : 0
  );

  const sand_m3_per_m2 = isArea && sand_cm > 0 ? round2(sand_cm / 100) : 0;

const schotter_cm = extractLayerCmByKeywords(
    ["schottertragschicht", "schotter"],
    hasAnyKeyword(["schottertragschicht", "schotter"]) ? 30 : 0
  );

  const kies_cm = extractLayerCmByKeywords(
    ["kiestragschicht"],
    hasAnyKeyword(["kiestragschicht"]) ? 30 : 0
  );

  const sand_m3_per_m2 = isArea && sand_cm > 0 ? round2(sand_cm / 100) : 0;
  const splitt_m3_per_m2 = isArea && splitt_cm > 0 ? round2(splitt_cm / 100) : 0;
  const frostschutz_m3_per_m2 = isArea && frostschutz_cm > 0 ? round2(frostschutz_cm / 100) : 0;
  const schotter_m3_per_m2 = isArea && schotter_cm > 0 ? round2(schotter_cm / 100) : 0;
  const kies_m3_per_m2 = isArea && kies_cm > 0 ? round2(kies_cm / 100) : 0;

  const layer_m3_per_m2 = round2(
    sand_m3_per_m2 +
      splitt_m3_per_m2 +
      frostschutz_m3_per_m2 +
      schotter_m3_per_m2 +
      kies_m3_per_m2
  );

  const trenchWidth_m = width_m > 0 ? width_m : 0.4;

  const isTrenchText =
    t.includes("rohrgraben") ||
    t.includes("leitungsgraben") ||
    t.includes("kabelgraben") ||
    t.includes("graben");

  const trench_m3_per_m =
    isLength && isTrenchText && depth_m > 0
      ? round2(depth_m * trenchWidth_m)
      : 0;

  const bedding_sand_m3_per_m =
    isLength && sand_cm > 0
      ? round2((sand_cm / 100) * trenchWidth_m)
      : 0;

  const backfill_m3_per_m =
    trench_m3_per_m > 0
      ? round2(Math.max(trench_m3_per_m - bedding_sand_m3_per_m, 0))
      : 0;

  const wantsSurfaceRestore =
    isLength &&
    (
      t.includes("wiederherstellen") ||
      t.includes("wieder einbauen") ||
      t.includes("ansaeen") ||
      t.includes("ansäen") ||
      t.includes("oberboden") ||
      t.includes("rasen")
    );

  const surface_m2_per_m =
    wantsSurfaceRestore && surface !== "UNKNOWN"
      ? round2(trenchWidth_m)
      : 0;

  const explicitAuskofferungCm = extractLayerCmByKeywords(
    ["auskofferung", "aushub", "ausheben", "boden abtragen", "boden loesen", "boden lösen"],
    0
  );

  const excludesAushub =
    t.includes("ohne aushub") ||
    t.includes("ohne auskofferung") ||
    t.includes("aushub bauseits") ||
    t.includes("auskofferung bauseits") ||
    t.includes("aushub separat") ||
    t.includes("auskofferung separat") ||
    t.includes("aushub gesondert") ||
    t.includes("auskofferung gesondert");

  const hasExplicitAushub =
    !excludesAushub &&
    (
      t.includes("auskofferung") ||
      t.includes("aushub") ||
      t.includes("ausheben") ||
      t.includes("boden abtragen") ||
      t.includes("boden loesen") ||
      t.includes("boden lösen")
    );

  /*
   * Aushublogik:
   * - Nur Splitt/Sand/Frostschutz erzeugt NICHT automatisch 30 cm Aushub.
   * - Aushub entsteht nur bei ausdrücklich genanntem Aushub/Auskofferung.
   * - Wenn Auskofferung ohne cm genannt ist, nehmen wir den erkannten Schichtaufbau,
   *   mindestens aber 30 cm als technische Mindestannahme.
   */
  const aushub_m3_per_m2 =
    isArea && hasExplicitAushub
      ? round2(
          explicitAuskofferungCm > 0
            ? explicitAuskofferungCm / 100
            : Math.max(layer_m3_per_m2, 0.3)
        )
      : 0;

  const disposal_t_per_m2 =
    aushub_m3_per_m2 > 0 ? round2(aushub_m3_per_m2 * 1.8) : 0;

  const tags = Array.from(
    new Set([
      detected.gewerk,
      detected.leistungsart,
      detected.bauverfahren,
      surface,
      soilClass,
      ...materialHints,
      ...riskHints,
    ].filter(Boolean))
  );

  let confidence = 0.45;
  if (detected.leistungsart !== "Unbekannte Leistung") confidence += 0.25;
  if (surface !== "UNKNOWN") confidence += 0.1;
  if (materialHints.length) confidence += 0.1;
  if (thickness_cm > 0 || depth_m > 0 || width_m > 0 || transport_distance_km > 0) confidence += 0.1;

  return {
    ...detected,
    surface,
    soilClass,

    length_m,
    area_m2,
    volume_m3,
    count,

    depth_m,
    width_m,
    thickness_cm,

    layer_m3_per_m2,

    sand_m3_per_m2,
    splitt_m3_per_m2,
    frostschutz_m3_per_m2,
    schotter_m3_per_m2,
    kies_m3_per_m2,

    aushub_m3_per_m2,
    disposal_t_per_m2,

    trench_m3_per_m,
    bedding_sand_m3_per_m,
    backfill_m3_per_m,
    surface_m2_per_m,

    transport_distance_km,

    materialHints,
    riskHints,
    tags,

    confidence: Math.min(0.98, round2(confidence)),
  };
}

import type {
  RlcTrenchRuleInput,
  RlcTrenchRuleResult,
} from "./types";

function round3(v: number): number {
  return Math.round((v + Number.EPSILON) * 1000) / 1000;
}

export function resolveRlcTrenchRules(
  input: RlcTrenchRuleInput
): RlcTrenchRuleResult {
  const length = Number(input.lengthM || 0);
  const depth = Number(input.depthM || 0);
  const explicitWidth = Number(input.explicitWidthM || 0);

  if (explicitWidth > 0) {
    return {
      widthM: explicitWidth,
      excavationM3:
        length > 0 && depth > 0
          ? round3(length * depth * explicitWidth)
          : null,
      source: {
        ruleId: "PROJECT_EXPLICIT_TRENCH_WIDTH",
        standard: "PROJECT_INPUT",
        edition: "current",
        description: "Explizit vorgegebene Grabenbreite",
      },
      status: "resolved",
      assumptions: [],
      questions: [],
    };
  }

  // DIN 4124:2012-01:
  // Kabel-/Endlosleitungsgraben bis 1,25 m Tiefe,
  // der betreten wird, jedoch keinen Arbeitsraum neben der Leitung benötigt.
  if (input.application === "KABEL" && depth > 0 && depth <= 1.25) {
    let width: number;

    if (depth <= 0.70) width = 0.30;
    else if (depth <= 0.90) width = 0.40;
    else if (depth <= 1.00) width = 0.50;
    else width = 0.60;

    return {
      widthM: width,
      excavationM3:
        length > 0
          ? round3(length * depth * width)
          : null,
      source: {
        ruleId: "DIN4124_KABELGRABEN_MIN_WIDTH",
        standard: "DIN 4124",
        edition: "2012-01",
        section: "9.2 / Mindestbreiten für Gräben ohne Arbeitsraum",
        description:
          "Kabel-/Endlosleitungsgraben bis 1,25 m ohne erforderlichen Arbeitsraum neben der Leitung",
      },
      status: "resolved",
      assumptions: [
        "Graben wird betreten.",
        "Neben der Leitung ist kein Arbeitsraum erforderlich.",
      ],
      questions: [],
    };
  }

  // Abwasserkanäle:
  // Die normative Grabenbreite darf nicht allein aus einer DN-Angabe
  // abgeleitet werden. Dafür wird der tatsächliche Außendurchmesser
  // des verwendeten Rohrsystems benötigt.
  if (input.application === "ABWASSER") {
    const dn = Number(input.nominalDiameterMm || 0);
    const outsideDiameter = Number(input.outsideDiameterM || 0);
    const support = input.trenchSupport || "UNKNOWN";
    const slopeAngle = Number(input.slopeAngleDeg || 0);

    if (!(dn > 0) || !(outsideDiameter > 0)) {
      return {
        widthM: null,
        excavationM3: null,
        source: null,
        status: "missing_input",
        assumptions: [],
        questions: [
          "Für die normative Grabenbreite werden DN und tatsächlicher Außendurchmesser des Abwasserrohres benötigt.",
        ],
      };
    }

    if (
      support === "UNKNOWN" ||
      (support === "UNVERBAUT" && !(slopeAngle > 0))
    ) {
      return {
        widthM: null,
        excavationM3: null,
        source: null,
        status: "missing_input",
        assumptions: [],
        questions: [
          "Wird der Abwassergraben verbaut oder unverbaut hergestellt? Bei unverbautem Graben bitte den Böschungswinkel angeben.",
        ],
      };
    }

    let clearanceM: number;

    if (support === "VERBAUT") {
      if (dn <= 225) clearanceM = 0.40;
      else if (dn <= 350) clearanceM = 0.50;
      else if (dn <= 700) clearanceM = 0.70;
      else if (dn <= 1200) clearanceM = 0.85;
      else clearanceM = 1.00;
    } else {
      // DIN EN 1610: bei unverbautem Graben hängt der Zuschlag
      // vom Böschungswinkel ab.
      if (slopeAngle > 60) {
        if (dn <= 225) clearanceM = 0.40;
        else if (dn <= 350) clearanceM = 0.50;
        else if (dn <= 700) clearanceM = 0.70;
        else if (dn <= 1200) clearanceM = 0.85;
        else clearanceM = 1.00;
      } else {
        clearanceM = 0.40;
      }
    }

    const widthByDiameter = outsideDiameter + clearanceM;

    let widthByDepth = 0;

    if (depth >= 1.00 && depth <= 1.75) widthByDepth = 0.80;
    else if (depth > 1.75 && depth <= 4.00) widthByDepth = 0.90;
    else if (depth > 4.00) widthByDepth = 1.00;

    const width = Math.max(widthByDiameter, widthByDepth);

    const excavationM3 =
      length > 0 && depth > 0
        ? round3(length * depth * width)
        : null;

    const pipeVolumeM3 =
      length > 0 && outsideDiameter > 0
        ? round3(
            Math.PI *
            Math.pow(outsideDiameter, 2) /
            4 *
            length
          )
        : null;

    const beddingThickness =
      Number(input.beddingThicknessM || 0);

    const embedmentHeight =
      Number(input.embedmentHeightM || 0);

    const beddingVolumeM3 =
      length > 0 && beddingThickness > 0
        ? round3(length * width * beddingThickness)
        : null;

    const embedmentVolumeM3 =
      length > 0 &&
      embedmentHeight > 0 &&
      pipeVolumeM3 !== null
        ? round3(
            Math.max(
              0,
              length * width * embedmentHeight - pipeVolumeM3
            )
          )
        : null;

    const netBackfillM3 =
      excavationM3 !== null &&
      beddingVolumeM3 !== null &&
      embedmentVolumeM3 !== null
        ? round3(
            Math.max(
              0,
              excavationM3 -
              beddingVolumeM3 -
              embedmentVolumeM3 -
              (pipeVolumeM3 || 0)
            )
          )
        : null;

    return {
      widthM: round3(width),
      excavationM3,
      pipeVolumeM3,

excavationM3 -
              beddingVolumeM3 -
              embedmentVolumeM3 -
              (pipeVolumeM3 || 0)
            )
          )
        : null;

    return {
      widthM: round3(width),
      excavationM3,
      pipeVolumeM3,
      beddingVolumeM3,
      embedmentVolumeM3,
      netBackfillM3,
      source: {
        ruleId: "DIN_EN_1610_ABWASSER_MIN_TRENCH_WIDTH",
        standard: "DIN EN 1610",
        edition: "2015-12",
        section: "Mindestgrabenbreite",
        description:
          "Mindestgrabenbreite aus Rohrdurchmesser und Grabentiefe; maßgebend ist der größere Wert",
      },
      status: "resolved",
      assumptions: [],
      questions: [],
    };
  }

  /*
   * Normative Tabellen werden hier ausschließlich mit
   * verifizierten Werten hinterlegt.
   *
   * DIN 4124: Baugruben und Gräben / Arbeitsraumbreiten
   * DIN EN 1610: Abwasserleitungen und -kanäle
   *
   * Keine erfundenen DIN-Werte verwenden.
   */

  return {
    widthM: null,
    excavationM3: null,
    source: null,
    status: "rule_not_available",
    assumptions: [],
    questions: [
      "Für diese Grabenart ist noch keine verifizierte normative Breitenregel im RLC-Regelwerk hinterlegt.",
    ],
  };
}

