                ...(Number(result.geometry.widthM) > 0
                  ? { widthM: Number(result.geometry.widthM) }
                  : {}),
                ...(Number(result.geometry.heightM) > 0
                  ? { heightM: Number(result.geometry.heightM) }
                  : {}),
              }
            : undefined,
      };
    }),
  };
}

