import type { Request, Response, NextFunction } from "express";
import { writeAudit } from "../lib/auditLog";

function safePath(req: Request) {
  // originalUrl include query, baseUrl+path è più pulito
  const base = (req.baseUrl || "") + (req.path || "");
  return base || req.originalUrl || "";
}

export function auditTrail() {
  return (req: Request & { id?: string; auth?: any }, res: Response, next: NextFunction) => {
    const start = Date.now();

    res.on("finish", () => {
      try {
        const path = safePath(req);

        // ✅ logga solo API (non static /projects)
        if (!path.startsWith("/api")) return;

        // ✅ evita rumore (health, ecc.)
        if (path === "/api/health") return;

        // ✅ logga solo mutazioni + login
        const m = (req.method || "GET").toUpperCase();
        const isWrite = m !== "GET" && m !== "HEAD" && m !== "OPTIONS";
        const isLogin = path.startsWith("/api/auth") && m === "POST";

        if (!isWrite && !isLogin) return;

        const action = isLogin ? "LOGIN" : `${m} ${path}`;
        const durMs = Date.now() - start;

        void writeAudit({
          req,
          action,
          resource: path,
          meta: {
            requestId: req.id || null,
            status: res.statusCode,
            method: m,
            durationMs: durMs,
            ua: String(req.headers["user-agent"] || ""),
          },
        });
      } catch {
        // never break
      }
    });

    next();
  };
}

import type { Request, Response, NextFunction } from "express";
import { verifyJwt } from "../lib/security/crypto";

export type AuthCtx = {
  sub: string;
  email?: string;
  role: string;
  companyId: string | null;
  companyRole: string | null;
  mode?: string | null;
  device?: string | null;
  emailVerified?: boolean | null;
};

declare global {
  namespace Express {
    interface Request {
      auth?: AuthCtx;
      user?: {
        id?: string;
        email?: string;
        role?: string;
        mode?: string;
        emailVerifiedAt?: string | null;
        emailVerified?: boolean;
      };
    }
  }
}

export function authJwt(req: Request, res: Response, next: NextFunction) {
  const h = req.header("authorization");
  if (!h || !h.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Kein Token" });
  }

  try {
    const decoded: any = verifyJwt(h.slice(7));

    req.auth = {
      sub: String(decoded.sub || ""),
      role: String(decoded.role || decoded.companyRole || "USER"),
      companyId: decoded.companyId ?? decoded.company ?? null,
      companyRole: decoded.companyRole ?? decoded.role ?? null,
      mode: decoded.mode ?? null,
      device: decoded.device ?? null,
      emailVerified: decoded.emailVerified ?? null,
    };

    if (!req.auth.sub) {
      return res.status(401).json({ error: "Ungültiges Token" });
    }

    return next();
  } catch {
    return res.status(401).json({ error: "Ungültiges Token" });
  }
}

export const requireAuth = authJwt;

export function requireVerifiedEmail(
  req: Request,
  res: Response,
  next: NextFunction
) {
  const devOn = (process.env.DEV_AUTH || "").toLowerCase() === "on";
  if (devOn && (req as any)?.user?.id) return next();

  const v =
    (req as any)?.auth?.emailVerified ??
    (req as any)?.user?.emailVerified ??
    ((req as any)?.user?.emailVerifiedAt ? true : undefined);

  if (v === true || v === undefined || v === null) return next();
  return res.status(403).json({ ok: false, error: "EMAIL_NOT_VERIFIED" });
}

