export function findCadSnap(
  cursor: CadPoint,
  features: CadFeature[],
  tolerance: number,
  excludedFeatureIds: string[] = []
): SnapResult | null {
  const excluded = new Set(excludedFeatureIds);
  let best: SnapResult | null = null;

  const consider = (
    point: CadPoint,
    kind: SnapKind,
    featureId: string
  ) => {
    const candidateDistance = distance(cursor, point);
    if (candidateDistance > tolerance) return;
    if (!best || candidateDistance < best.distance) {
      best = {
        point: { ...point },
        kind,
        featureId,
        distance: candidateDistance,
      };
    }
  };

  for (const feature of features) {
    const featureId = String(feature.id || "");
    if (!featureId || excluded.has(featureId)) continue;
    const points = feature.pts || [];
    if (!points.length) continue;

    if (feature.kind === "circle" || feature.kind === "point") {
      consider(points[0], "center", featureId);
    }

    points.forEach((point, index) => {
      const endpoint = index === 0 || index === points.length - 1;
      consider(point, endpoint ? "endpoint" : "vertex", featureId);
    });

    for (let index = 1; index < points.length; index += 1) {
      consider(
        {
          x: (points[index - 1].x + points[index].x) / 2,
          y: (points[index - 1].y + points[index].y) / 2,
        },
        "midpoint",
        featureId
      );
    }

    if (feature.closed && points.length > 2) {
      consider(
        {
          x: (points[points.length - 1].x + points[0].x) / 2,
          y: (points[points.length - 1].y + points[0].y) / 2,
        },
        "midpoint",
        featureId
      );
    }
  }

  return best;
}

function parseDxfPairs(source: string): DxfPair[] {
  const lines = source.replace(/^\uFEFF/, "").split(/\r?\n/);
  const pairs: DxfPair[] = [];
  for (let index = 0; index + 1 < lines.length; index += 2) {
    const code = Number(lines[index].trim());
    if (!Number.isFinite(code)) continue;
    pairs.push({ code, value: lines[index + 1].trim() });
  }
  return pairs;
}

function firstValue(pairs: DxfPair[], code: number, fallback = "") {
  return pairs.find((pair) => pair.code === code)?.value ?? fallback;
}

function numericValue(pairs: DxfPair[], code: number, fallback = 0) {
  return finite(firstValue(pairs, code), fallback);
}

function decodeDxfText(pairs: DxfPair[]) {
  const raw = pairs
    .filter((pair) => pair.code === 1 || pair.code === 3)
    .map((pair) => pair.value)
    .join("");

  return raw
    .replace(/\\U\+([0-9a-f]{4,8})/gi, (_match, hex: string) => {
      const codePoint = Number.parseInt(hex, 16);
      try {
        return Number.isFinite(codePoint)
          ? String.fromCodePoint(codePoint)
          : "";
      } catch {
        return "";
      }
    })
    .replace(/%%d/gi, "°")
    .replace(/%%p/gi, "±")
    .replace(/%%c/gi, "Ø")
    .replace(/\\P/gi, "\n")
    .replace(/\\S([^;]*?)[#^/]([^;]*);/gi, "$1/$2")
    .replace(/\\[ACFHQTW][^;]*;/gi, "")
    .replace(/\\[LlOoKk]/g, "")
    .replace(/\\~/g, " ")
    .replace(/\\\\/g, "\\")
    .replace(/[{}]/g, "")
    .replace(/\u0000/g, "")
    .trim();
}

function indexedPoint(
  pairs: DxfPair[],
  xCode: number,
  yCode: number,
  scale: number
): CadPoint | null {
  const xPair = pairs.find((pair) => pair.code === xCode);
  const yPair = pairs.find((pair) => pair.code === yCode);
  if (!xPair || !yPair) return null;
  return {
    x: finite(xPair.value) * scale,
    y: finite(yPair.value) * scale,
  };
}

function repeatedVertices(pairs: DxfPair[], scale: number) {
  const vertices: DxfVertex[] = [];
  let current:
    | { x: number; y: number | null; bulge: number }
    | null = null;

  const flush = () => {
    if (current && current.y !== null) {
      vertices.push({
        point: { x: current.x, y: current.y },
        bulge: current.bulge,
