  for (const pair of pairs) {
    if (pair.code === 10) {
      flush();
      current = {
        x: finite(pair.value) * scale,
        y: null,
        bulge: 0,
      };
    } else if (pair.code === 20 && current) {
      current.y = finite(pair.value) * scale;
    } else if (pair.code === 42 && current) {
      current.bulge = finite(pair.value);
    }
  }
  flush();
  return vertices;
}

