  const knots =
    rawKnots.length >= requiredKnotCount
      ? rawKnots.slice(0, requiredKnotCount)
      : clampedUniformKnots(controlPoints.length, degree);
  const start = knots[degree];
  const end = knots[controlPoints.length];
  if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
    return controlPoints;
  }

  const nonZeroSpans = Math.max(
    1,
    knots
      .slice(degree, controlPoints.length + 1)
      .filter((value, index, values) => index > 0 && value > values[index - 1])
      .length
  );
  const sampleCount = Math.max(
    24,
    Math.min(720, nonZeroSpans * 16)
  );
  return Array.from({ length: sampleCount + 1 }, (_, index) =>
    deBoorPoint(
      controlPoints,
      knots,
      degree,
      start + ((end - start) * index) / sampleCount
    )
  );
}

export function parseAsciiDxf(
  source: string,
  fileName = "drawing.dxf"
): CadDocument {
  if (!source.trim()) throw new Error("Die DXF-Datei ist leer.");
  const pairs = parseDxfPairs(source);
  const { unitCode, scale } = dxfUnitScale(pairs);
  const layerStyles = dxfLayerStyles(pairs);
  const blocks = extractEntityBlocks(pairs);
  const blockDefinitions = extractBlockDefinitions(pairs, scale);
  const features: CadFeature[] = [];
  const unsupportedTypes = new Set<string>();
  let modelSpaceCount = 0;
  let paperSpaceCount = 0;
  let generatedIndex = 0;

  const emitBlocks = (
    entityBlocks: DxfEntityBlock[],
    inheritedLayer = "",
    matrix: DxfMatrix = IDENTITY_MATRIX,
    idPrefix = "DXF",
    depth = 0,
    inheritedPaperSpace = false,
    inheritedLayout = "Model"
  ) => {
    if (depth > 8) return;

    for (let index = 0; index < entityBlocks.length; index += 1) {
      const block = entityBlocks[index];
      const rawLayer = firstValue(block.pairs, 8, "0");
      const layer =
        inheritedLayer && rawLayer === "0" ? inheritedLayer : rawLayer;
      const handle = firstValue(block.pairs, 5, `${index + 1}`);
      const id = `${idPrefix}_${handle}_${generatedIndex + 1}`;
      const meta = baseDxfMeta(
        block,
        fileName,
        unitCode,
        layerStyles.get(layer)
      );
      if (depth > 0) {
        meta.paperSpace = inheritedPaperSpace;
        meta.layout = inheritedLayout;
      }
      const style = {
        color: String(meta.color || "") || undefined,
        lineType: String(meta.lineType || "") || undefined,
        lineWeight: Number(meta.lineWeight || 0) || undefined,
      };

      if (depth === 0) {
        if (meta.paperSpace) paperSpaceCount += 1;
        else modelSpaceCount += 1;
      }

      const push = (feature: CadFeature) => {
        generatedIndex += 1;
        features.push(
          transformDxfFeature(
            {
              ...feature,
              id,
              layer,
              style: feature.style || style,
              meta: {
                ...meta,
                ...(feature.meta || {}),
              },
            },
            matrix,
            generatedIndex
          )
        );
      };

      if (block.type === "LINE") {
        const start = indexedPoint(block.pairs, 10, 20, scale);
        const end = indexedPoint(block.pairs, 11, 21, scale);
        if (start && end) push({ kind: "line", pts: [start, end] });
        continue;
      }

      if (block.type === "LWPOLYLINE") {
        const closed =
          (Math.trunc(numericValue(block.pairs, 70)) & 1) === 1;
        const vertices = repeatedVertices(block.pairs, scale);
        const points = flattenBulgedPolyline(vertices, closed);
        if (points.length) {
          push({
            kind: closed ? "polygon" : "polyline",
            pts: points,
            closed,
            meta: {
              bulgeSegments: vertices.filter(
                (vertex) => Math.abs(vertex.bulge) > EPSILON
              ).length,
            },
          });
        }
        continue;
      }

      if (block.type === "POLYLINE") {
        const vertices: DxfVertex[] = [];
        const closed =
          (Math.trunc(numericValue(block.pairs, 70)) & 1) === 1;
        let cursor = index + 1;
        while (
          cursor < entityBlocks.length &&
          entityBlocks[cursor].type === "VERTEX"
        ) {
          const point = indexedPoint(
            entityBlocks[cursor].pairs,
            10,
            20,
            scale
          );
          if (point) {
            vertices.push({
              point,
              bulge: numericValue(entityBlocks[cursor].pairs, 42),
            });
          }
          cursor += 1;
        }
        const points = flattenBulgedPolyline(vertices, closed);
        if (points.length) {
          push({
            kind: closed ? "polygon" : "polyline",
            pts: points,
            closed,
            meta: {
              bulgeSegments: vertices.filter(
                (vertex) => Math.abs(vertex.bulge) > EPSILON
              ).length,
            },
          });
        }
        index = Math.max(index, cursor - 1);
        continue;
      }

      if (block.type === "CIRCLE") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const radius = numericValue(block.pairs, 40) * scale;
        if (center && radius > EPSILON) {

