            },
          });
        }
        index = Math.max(index, cursor - 1);
        continue;
      }

      if (block.type === "CIRCLE") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const radius = numericValue(block.pairs, 40) * scale;
        if (center && radius > EPSILON) {
          push({ kind: "circle", pts: [center], radius });
        }
        continue;
      }

      if (block.type === "ARC") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const radius = numericValue(block.pairs, 40) * scale;
        if (center && radius > EPSILON) {
          push({
            kind: "polyline",
            name: "Bogen",
            pts: arcPoints(
              center,
              radius,
              numericValue(block.pairs, 50),
              numericValue(block.pairs, 51)
            ),
          });
        }
        continue;
      }

      if (block.type === "ELLIPSE") {
        const center = indexedPoint(block.pairs, 10, 20, scale);
        const majorAxis = indexedPoint(block.pairs, 11, 21, scale);
        if (center && majorAxis) {
          const startParameter = numericValue(block.pairs, 41, 0);
          const endParameter = numericValue(
            block.pairs,
            42,
            Math.PI * 2
          );
          const points = ellipsePoints(
            center,
            majorAxis,
            Math.abs(numericValue(block.pairs, 40, 1)),
            startParameter,
            endParameter
          );
          const closed =
            Math.abs(endParameter - startParameter) >= Math.PI * 2 - 1e-6;
          if (points.length) {
            if (
              closed &&
              distance(points[0], points[points.length - 1]) < EPSILON
            ) {
              points.pop();
            }
            push({
              kind: closed ? "polygon" : "polyline",
              name: "Ellipse",
              pts: points,
              closed,
            });
          }
        }
        continue;
      }

      if (block.type === "INSERT" || block.type === "DIMENSION") {
        const blockName = firstValue(block.pairs, 2);
        const definition = blockDefinitions.get(blockName);
        const insertion =
          indexedPoint(block.pairs, 10, 20, scale) || { x: 0, y: 0 };
        if (definition) {
          const scaleX = numericValue(block.pairs, 41, 1) || 1;
          const scaleY = numericValue(block.pairs, 42, 1) || 1;
          const rotation = numericValue(block.pairs, 50);
          const columns = Math.max(
            1,
            Math.trunc(numericValue(block.pairs, 70, 1))
          );
          const rows = Math.max(
            1,
            Math.trunc(numericValue(block.pairs, 71, 1))
          );
          const columnSpacing = numericValue(block.pairs, 44) * scale;
          const rowSpacing = numericValue(block.pairs, 45) * scale;
          const rotationRadians = (rotation * Math.PI) / 180;
          const rotationCos = Math.cos(rotationRadians);
          const rotationSin = Math.sin(rotationRadians);

          for (let row = 0; row < rows; row += 1) {
            for (let column = 0; column < columns; column += 1) {
              const localOffsetX = column * columnSpacing * scaleX;
              const localOffsetY = row * rowSpacing * scaleY;
              const instancePoint = {
                x:
                  insertion.x +
                  localOffsetX * rotationCos -
                  localOffsetY * rotationSin,
                y:
                  insertion.y +
                  localOffsetX * rotationSin +
                  localOffsetY * rotationCos,
              };
              const local = insertDxfMatrix(
                instancePoint,
                definition.basePoint,
                scaleX,
                scaleY,
                rotation
              );
              emitBlocks(
                definition.entities,
                layer,
                multiplyDxfMatrices(matrix, local),
                `${id}_${blockName}_${row}_${column}`,
                depth + 1,
                Boolean(meta.paperSpace),
                String(meta.layout || "Model")
              );
            }
          }
        } else {
          push({
            kind: "point",
            name: blockName || "Block",
            pts: [insertion],
            meta: { unresolvedBlock: blockName || true },
          });
        }
        continue;
      }

      if (block.type === "POINT") {
        const point = indexedPoint(block.pairs, 10, 20, scale);
        if (point) push({ kind: "point", name: "Punkt", pts: [point] });
        continue;
      }

      if (
        block.type === "TEXT" ||
        block.type === "MTEXT" ||
        block.type === "ATTRIB" ||
        block.type === "ATTDEF"
      ) {
        const horizontalJustification = Math.trunc(
          numericValue(block.pairs, 72)
        );
        const verticalJustification = Math.trunc(
          numericValue(block.pairs, 73)
        );
        const usesAlignmentPoint =
          block.type !== "MTEXT" &&
          (horizontalJustification !== 0 || verticalJustification !== 0);
        const insertionPoint = indexedPoint(block.pairs, 10, 20, scale);
        const alignmentPoint = indexedPoint(block.pairs, 11, 21, scale);
        const point = usesAlignmentPoint
          ? alignmentPoint || insertionPoint
          : insertionPoint || alignmentPoint;

);
        const verticalJustification = Math.trunc(
          numericValue(block.pairs, 73)
        );
        const usesAlignmentPoint =
          block.type !== "MTEXT" &&
          (horizontalJustification !== 0 || verticalJustification !== 0);
        const insertionPoint = indexedPoint(block.pairs, 10, 20, scale);
        const alignmentPoint = indexedPoint(block.pairs, 11, 21, scale);
        const point = usesAlignmentPoint
          ? alignmentPoint || insertionPoint
          : insertionPoint || alignmentPoint;
        const text = decodeDxfText(block.pairs);
        const attributeTag = firstValue(block.pairs, 2);
        const explicitRotation = block.pairs.some((pair) => pair.code === 50);
        const directionX = numericValue(block.pairs, 11);
        const directionY = numericValue(block.pairs, 21);
        const rotation =
          block.type === "MTEXT" &&
          !explicitRotation &&
          (Math.abs(directionX) > EPSILON ||
            Math.abs(directionY) > EPSILON)
            ? (Math.atan2(directionY, directionX) * 180) / Math.PI
            : numericValue(block.pairs, 50);
        if (point) {
          push({
            kind: "text",
            name: text || attributeTag || "Text",
            text: text || attributeTag,
            rotation,
            pts: [point],
            meta: {
              height: numericValue(block.pairs, 40) * scale,
              width: numericValue(block.pairs, 41) * scale,
              widthFactor:
                block.type === "MTEXT"
                  ? 1
                  : numericValue(block.pairs, 41, 1) || 1,
              textStyle: firstValue(block.pairs, 7),
              attachmentPoint: Math.trunc(
                numericValue(block.pairs, 71, 1)
              ),
              horizontalJustification,
              verticalJustification,
            },
          });
        }
        continue;
      }

      if (block.type === "SPLINE") {
        const points = splinePoints(block.pairs, scale);
        if (points.length > 1) {
          push({
            kind: "polyline",
            name: "Spline",
            pts: points,
            meta: { approximation: "de-boor" },
          });
        }
        continue;
      }

      if (block.type === "MLINE") {
        const points = repeatedPoints(block.pairs, 11, 21, scale);
        const fallbackPoints = repeatedPoints(block.pairs, 10, 20, scale);
        const centerLine = points.length > 1 ? points : fallbackPoints;
        if (centerLine.length > 1) {
          push({
            kind: "polyline",
            name: "Multilinie",
            pts: centerLine,
            meta: { approximation: "center-line" },
          });
        }
        continue;
      }

      if (block.type === "HATCH" || block.type === "LEADER") {
        const points = repeatedVertices(block.pairs, scale).map(
          (vertex) => vertex.point
        );
        if (points.length > 1) {
          const closed = block.type === "HATCH" && points.length > 2;
          push({
            kind: closed ? "polygon" : "polyline",
            name: block.type === "HATCH" ? "Schraffurgrenze" : "Führungslinie",
            pts: points,
            closed,
            meta: { approximation: "boundary-points" },
          });
        }
        continue;
      }

      if (
        block.type === "3DFACE" ||
        block.type === "SOLID" ||
        block.type === "TRACE"
      ) {
        const points = [10, 11, 12, 13]
          .map((xCode) =>
            indexedPoint(block.pairs, xCode, xCode + 10, scale)
          )
          .filter((point): point is CadPoint => Boolean(point));
        const unique = points.filter(
          (point, pointIndex) =>
            pointIndex === 0 ||
            distance(point, points[pointIndex - 1]) > EPSILON
        );
        if (unique.length >= 3) {
          push({
            kind: "polygon",
            pts: unique,
            closed: true,
            style: {
              ...style,
              fill: block.type === "SOLID" || block.type === "TRACE",
            },
          });
        }
        continue;
      }

      if (!["VERTEX", "SEQEND"].includes(block.type)) {
        unsupportedTypes.add(block.type);
      }
    }
  };

  emitBlocks(blocks);

  const normalized = features.map(recalculateCadFeature);
  if (!normalized.length) {
    throw new Error(
      "Die DXF-Datei enthält keine unterstützte 2D-Geometrie (LINE, POLYLINE, CIRCLE, ARC, ELLIPSE, INSERT, POINT, TEXT, SPLINE, MLINE)."
    );
  }

  return createCadDocument("", normalized, {
    fileName,
    format: "DXF",
    importedAt: new Date().toISOString(),
    unitCode,
    unitScale: scale,
    modelSpaceCount,
    paperSpaceCount,
    unsupportedTypes: Array.from(unsupportedTypes).sort(),
    blockDefinitionCount: blockDefinitions.size,
  });
}

import type { ParsedItem } from "./index";
import { parseAsciiDxf, type CadFeature } from "./dxf.engine";

export type RlcCadPoint = { x: number; y: number };
export type RlcCadFeature = {
  id: string;
  kind: "line" | "polyline" | "polygon" | "point" | "circle" | "text";
  layer: string;
  name?: string;
  pts: RlcCadPoint[];
  closed: boolean;
  radius?: number;
  text?: string;
  rotation?: number;
  length: number;
  area: number;
  style?: Record<string, unknown>;
  meta: Record<string, unknown>;
};

function decodeDxfBuffer(buf: Buffer): string {
  const signature = buf.subarray(0, 22).toString("latin1");
  if (signature.startsWith("AutoCAD Binary DXF")) {
    throw new Error(
      "Binäres DXF erkannt. Die Datei muss vor dem Parsen serverseitig in ASCII-DXF konvertiert werden."
    );
  }

  const utf8 = buf.toString("utf8");
  const replacementCount = (utf8.match(/\uFFFD/g) || []).length;
  if (replacementCount <= Math.max(2, Math.floor(utf8.length / 100000))) {
    return utf8;
  }
  return buf.toString("latin1");
}

function normalizeFeature(feature: CadFeature, index: number): RlcCadFeature {
  return {
    id: String(feature.id || `DXF_${String(index + 1).padStart(6, "0")}`),
    kind: (feature.kind || "polyline") as RlcCadFeature["kind"],
    layer: String(feature.layer || "0"),
    name: feature.name,
    pts: Array.isArray(feature.pts)
      ? feature.pts.map((point) => ({ x: Number(point.x), y: Number(point.y) }))
      : [],
    closed: Boolean(feature.closed),
    radius: feature.radius,
    text: feature.text,
    rotation: feature.rotation,
    length: Number(feature.length || 0),
    area: Number(feature.area || 0),
    style: feature.style as Record<string, unknown> | undefined,
    meta: {
      ...(feature.meta || {}),
      source: "DXF",
    },
  };
}

export function parseDXFGeometry(buf: Buffer, fileName = "drawing.dxf"): {
  items: ParsedItem[];
  features: RlcCadFeature[];
  layers: string[];
  source: Record<string, unknown>;
} {
  const document = parseAsciiDxf(decodeDxfBuffer(buf), fileName);
  const features = document.features.map(normalizeFeature);
  const layers = Array.from(new Set(features.map((feature) => feature.layer))).sort();
  const items: ParsedItem[] = [];
  let lineNo = 1;
  let areaNo = 1;
  let pointNo = 1;

  for (const feature of features) {
    const label = feature.name || feature.text || String(feature.meta?.dxfType || feature.kind);
    if (feature.kind === "point" || feature.kind === "text") {
      items.push({
        source: "DXF",
        pos: `DXF.PKT.${String(pointNo++).padStart(3, "0")}`,
        text: label,
        unit: "Stk",
        qty: 1,
      });
    } else if (feature.length > 0) {
      items.push({
        source: "DXF",
        pos: `DXF.LIN.${String(lineNo++).padStart(3, "0")}`,
        text: label,
        unit: "m",
        qty: feature.length,
      });
    }
    if (feature.area > 0) {
      items.push({
        source: "DXF",
        pos: `DXF.AR.${String(areaNo++).padStart(3, "0")}`,
        text: `${label} Fläche`,
        unit: "m²",
        qty: feature.area,
      });
    }
  }

  return {
    items,
    features,
    layers,
    source: document.source || {},
  };
}

export function parseDXF(buf: Buffer): ParsedItem[] {
  return parseDXFGeometry(buf).items;
}

import type { ParsedItem } from "./index";
import { toNumber, hypot2D } from "./index";

/**
 * Parser GSI semplice:
 * - Linee con E N (opz. Z) e ultimo campo come CODE
 * - Raggruppa per CODE e somma lunghezze tra punti consecutivi
 */
export function parseGSI(buf: Buffer): ParsedItem[] {
  const text = buf.toString("utf8");
  const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);

  type Pt = { id: string; e: number; n: number; z?: number; code: string };
  const pts: Pt[] = [];

  for (const l of lines) {
    const parts = l.split(/;|,|\s+/).filter(Boolean);
    if (parts.length < 4) continue;
    const code = String(parts[parts.length - 1]);
    const nums = parts.slice(0, parts.length - 1).map(p => toNumber(p, NaN)).filter(n => !isNaN(n));
    if (nums.length < 2) continue;
    const e = nums[0], n = nums[1], z = nums[2];
    pts.push({ id: parts[0], e, n, z, code });
  }

  const map = new Map<string, Pt[]>();
  for (const p of pts) {
    if (!map.has(p.code)) map.set(p.code, []);
    map.get(p.code)!.push(p);
  }

  const out: ParsedItem[] = [];
  let idx = 1;
  map.forEach((arr, code) => {
    arr.sort((a, b) => {
      const na = toNumber(a.id, NaN), nb = toNumber(b.id, NaN);
      if (isNaN(na) || isNaN(nb)) return a.id.localeCompare(b.id);
      return na - nb;
    });
    let L = 0;
    for (let i = 0; i < arr.length - 1; i++) {
      L += hypot2D(arr[i + 1].e - arr[i].e, arr[i + 1].n - arr[i].n);
    }
    if (L > 0) {
      out.push({ source: "GSI", pos: `GSI.LIN.${String(idx++).padStart(3, "0")}`, text: `Linie (Code ${code})`, unit: "m", qty: L });
    }
  });

  return out;
}

import { parseCsvTxt } from "./csvTxt";
