/** Struttura unificata che il frontend conosce */
export type ParsedItem = {
  source: string;   // "CSV" | "TXT" | "LandXML" | "DXF" | "GSI" | "PDF" | "DWG" | "Datei"
  pos: string;      // es. "100.001"
  text: string;     // descrizione breve
  unit: string;     // "m" | "m²" | "m³" | ...
  qty: number;      // quantità
};

/* ---------- utils condivise ---------- */
export function toNumber(v: any, def = 0): number {
  if (v == null) return def;
  const n = Number(String(v).replace(",", "."));
  return isFinite(n) ? n : def;
}
export function hypot2D(dx: number, dy: number): number {
  return Math.sqrt(dx * dx + dy * dy);
}
export function areaPolygon(points: { x: number; y: number }[]): number {
  let a = 0;
  for (let i = 0; i < points.length; i++) {
    const p = points[i];
    const q = points[(i + 1) % points.length];
    a += p.x * q.y - q.x * p.y;
  }
  return Math.abs(a / 2);
}
/** Applica la scala in base all'unità: m→s, m²→s², m³→s³ */
export function applyScale(qty: number, unit: string, scale: number): number {
  if (!isFinite(qty) || !isFinite(scale)) return qty;
  if (unit === "m")  return qty * scale;
  if (unit === "m²") return qty * scale * scale;
  if (unit === "m³") return qty * scale * scale * scale;
  return qty;
}

/* ---------- ROUTER UNIVERSALE ---------- */
export async function parseByExtension(
  originalName: string,
  buf: Buffer,
  scale = 1
): Promise<{ items: ParsedItem[]; note?: string }> {
  const name = (originalName || "").toLowerCase();

  if (name.endsWith(".csv")) {
    return { items: parseCsvTxt(buf, "CSV") };
  }
  if (name.endsWith(".txt")) {
    return { items: parseCsvTxt(buf, "TXT") };
  }
  if (name.endsWith(".xml")) {
    return { items: parseLandXML(buf) };
  }
  if (name.endsWith(".dxf")) {
    return { items: parseDXF(buf) };
  }
  if (name.endsWith(".gsi")) {
    return { items: parseGSI(buf) };
  }
  if (name.endsWith(".dwg")) {
    return {
      items: [],
      note: "DWG non supportato direttamente: convertire in DXF e riprovare.",
    };
  }
  if (name.endsWith(".pdf")) {
    return {
      items: [],
      note: "PDF vettoriale non supportato direttamente: esportare in DXF/SVG e riprovare.",
    };
  }

  return {
    items: [],
    note: "Formato non riconosciuto. Supportati: CSV, TXT, LandXML, DXF, GSI (PDF/DWG tramite conversione).",
  };
}

import { XMLParser } from "fast-xml-parser";
import type { ParsedItem } from "./index";
import { toNumber, hypot2D } from "./index";

export function parseLandXML(buf: Buffer): ParsedItem[] {
  const xml = buf.toString("utf8");
  const parser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: "" });
  const doc = parser.parse(xml);

  const out: ParsedItem[] = [];
  let k = 1;

  // Alignments (lunghezze)
  const alignments = doc?.LandXML?.Alignments?.Alignment;
  const arrAlign = Array.isArray(alignments) ? alignments : alignments ? [alignments] : [];
  for (const al of arrAlign) {
    const len = toNumber(al?.length ?? al?.Length);
    if (len > 0) {
      out.push({
        source: "LandXML",
        pos: `LX.LIN.${String(k++).padStart(3, "0")}`,
        text: al?.name ? `Alignment ${al.name}` : "Alignment",
        unit: "m",
        qty: len,
      });
      continue;
    }
    const cg = al?.CoordGeom;
    if (cg) {
      const segs = ([] as any[]).concat(
        cg.Line || [],
        cg.LineString || [],
        cg.Spiral || [],
        cg.Curve || []
      );
      const lines: { x: number; y: number }[][] = [];
      for (const s of segs) {
        const sp = s?.Start?.pnt || s?.Start?.Pnt || "";
        const ep = s?.End?.pnt || s?.End?.Pnt || "";
        const [sx, sy] = String(sp).split(/\s+/);
        const [ex, ey] = String(ep).split(/\s+/);
        const SX = toNumber(sx), SY = toNumber(sy), EX = toNumber(ex), EY = toNumber(ey);
        if (isFinite(SX) && isFinite(SY) && isFinite(EX) && isFinite(EY)) {
          lines.push([{ x: SX, y: SY }, { x: EX, y: EY }]);
        }
      }
      if (lines.length) {
        const lenSum = lines.reduce((a, seg) => a + hypot2D(seg[1].x - seg[0].x, seg[1].y - seg[0].y), 0);
        if (lenSum > 0) {
          out.push({
            source: "LandXML",
            pos: `LX.LIN.${String(k++).padStart(3, "0")}`,
            text: al?.name ? `Alignment ${al.name}` : "Alignment",
            unit: "m",
            qty: lenSum,
          });
        }
      }
    }
  }

  // Parcels/Surfaces (aree)
  const parcels = doc?.LandXML?.Parcels?.Parcel;
  const arrParc = Array.isArray(parcels) ? parcels : parcels ? [parcels] : [];
  for (const p of arrParc) {
    const area = toNumber(p?.area ?? p?.Area);
    if (area > 0) {
      out.push({
        source: "LandXML",
        pos: `LX.AR.${String(k++).padStart(3, "0")}`,
        text: p?.name ? `Parcel ${p.name}` : "Parcel",
        unit: "m²",
        qty: area,
      });
    }
  }

  // Volumi
  const vols = doc?.LandXML?.Volumes || doc?.LandXML?.Volume;
  const arrVol = Array.isArray(vols) ? vols : vols ? [vols] : [];
  for (const v of arrVol) {
    const vol = toNumber(v?.volume ?? v?.Volume);
    if (vol > 0) {
      out.push({
        source: "LandXML",
        pos: `LX.VOL.${String(k++).padStart(3, "0")}`,
        text: v?.name ? `Volumen ${v.name}` : "Volumen",
        unit: "m³",
        qty: vol,
      });
    }
  }

  return out;
}

