  const rows = ["Datum;Konto;Gegenkonto;Betrag;Text"];
  for (const l of ledger) rows.push([l.date.toISOString().slice(0,10), l.account, l.contraAccount, l.amount.toString(), l.text || ""].join(";"));
  const fileName = `DATEV_${projectId}.csv`;
