const router = Router();

function companyId(req: any) {
  return String(req.auth?.companyId || "").trim();
}

function num(v: any) {
  const n = Number(v ?? 0);
  return Number.isFinite(n) ? n : 0;
}

function jsonObject(value: any) {
  if (
    value &&
    typeof value === "object" &&
    !Array.isArray(value)
  ) {
    return value;
  }

  return {};
}

async function resolveProject(req: any) {
  const cid = companyId(req);

  if (!cid) {
    throw new Error("COMPANY_REQUIRED");
  }

  const token = String(
    req.query?.projectId ||
    req.body?.projectId ||
    ""
  ).trim();

  if (token) {
    const project = await prisma.project.findFirst({
      where: {
        companyId: cid,
        OR: [
          { id: token },
          { code: token }
        ]
      }
    });

    if (project) return project;
  }

  const project = await prisma.project.findFirst({
    where: { companyId: cid },
    orderBy: { updatedAt: "desc" }
  });

  if (!project) {
    throw new Error("PROJECT_REQUIRED");
  }

  return project;
}

async function context(req: any) {
  const project = await resolveProject(req);

  const accounting = await prisma.accountingRoot.upsert({
    where: { projectId: project.id },
    update: {},
    create: {
      projectId: project.id,
      currency: "EUR"
    }
  });

  return {
    project,
    accounting
  };
}

function errorResponse(res: any, error: any) {
  console.error(error);

  res.status(400).json({
    ok: false,
    error: error?.message || "ACCOUNTING_FAILED"
  });
}

