router.get("/ust", async (req: any, res) => {
  try {
    const { accounting } = await context(req);

    const [invoices, bills] = await Promise.all([
      prisma.invoice.findMany({
        where: {
          accountingId: accounting.id
        }
      }),

      prisma.vendorBill.findMany({
        where: {
          accountingId: accounting.id
        }
      })
    ]);

    const rows = [
      ...invoices.map((x: any) => ({
        id: `I-${x.id}`,
        type: "Einnahme",
        date: x.date,
        number: x.number,
        netAmount: num(x.netAmount),
        taxAmount: num(x.taxAmount),
        grossAmount: num(x.grossAmount),

        taxRate:
          num(x.netAmount) > 0
            ? Math.round(
                (
                  num(x.taxAmount) /
                  num(x.netAmount)
                ) *
                  10000
              ) / 100
            : 0
      })),

      ...bills.map((x: any) => ({
        id: `V-${x.id}`,
        type: "Ausgabe",
        date: x.date,
        number: x.number,
        netAmount: num(x.netAmount),
        taxAmount: num(x.taxAmount),
        grossAmount: num(x.grossAmount),

        taxRate:
          num(x.netAmount) > 0
            ? Math.round(
                (
                  num(x.taxAmount) /
                  num(x.netAmount)
                ) *
                  10000
              ) / 100
            : 0
      }))
    ];

    const umsatzsteuer = invoices.reduce(
      (s, x) => s + num(x.taxAmount),
      0
    );

    const vorsteuer = bills.reduce(
      (s, x) => s + num(x.taxAmount),
      0
    );

    res.json({
      ok: true,
      rows,
      umsatzsteuer,
      vorsteuer,
      zahllast:
        umsatzsteuer - vorsteuer
    });
  } catch (e) {
    errorResponse(res, e);
  }
});

