function coerceQty(v: any): number | null {
  if (v == null) return null;
  if (typeof v === "number" && Number.isFinite(v)) return v;
  const s = String(v).trim();
  if (!s) return null;
  // 12,34 -> 12.34 ; 1.234,5 -> 1234.5 (best effort)
  const normalized = s
    .replace(/\s/g, "")
    .replace(/\.(?=\d{3}(\D|$))/g, "")
    .replace(",", ".");
  const n = Number(normalized);
  return Number.isFinite(n) ? n : null;
}


function clampConfidence(v: any, fallback = 0.62) {
  const n = Number(v);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(0, Math.min(1, n));
}

function normalizeTechnicalText(value: unknown) {
  return String(value ?? "")
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/ß/g, "ss")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

function isAdministrativeOrNonBillable(textRaw: string) {
  const text = normalizeTechnicalText(textRaw);
  if (!text) return true;

  const blocked = [
    /\bplan ?nr\b/,
    /\bplan nummer\b/,
    /\bmassstab\b/,
    /\bblatt(?:grosse|format)?\b/,
    /\bprojekt(?:name)?\b/,
    /\bbauvorhaben\b/,
    /\bbauherr\b/,
    /\bauftraggeber\b/,
    /\bplaner\b/,
    /\bgezeichnet\b/,
    /\bgepruft\b/,
    /\bdatum\b/,
    /\bindex\b/,
    /\bphase\b/,
    /\blegende\b/,
    /\bbezeichnung\b/,
    /\bwerkhof flache\b/,
    /\bzufahrt lange\b/,
    /\bzufahrt breite\b/,
    /\bhohe\b/,
    /\bhohenkote\b/,
    /\bdeckelhohe\b/,
    /\bsohlhohe\b/,
    /\bgelandehohe\b/,
    /\bkoordinate\b/,
    /\bstation(?:ierung)?\b/,
    /\bgefalle\b/,
  ];

  return blocked.some((rx) => rx.test(text));
}

function looksLikeElevationOrDimension(textRaw: string, qty: number | null) {
  const raw = String(textRaw || "").trim();
  const text = normalizeTechnicalText(raw);

  if (/\b(?:ok|uk|d|s)\s*[+-]?\d{2,4}[.,]\d{1,3}\b/i.test(raw)) return true;
  if (/\bhohe\b|\bhohenkote\b|\bdeckel\b|\bsohle\b/.test(text)) return true;
  if (qty != null && qty >= 400 && /\b(?:d|s|ok|uk)\b/.test(text)) return true;
  return false;
}

function technicalPositionKey(p: PhotoPosition) {
  const text = normalizeTechnicalText(p.kurztext)
    .replace(/\b\d+(?:[.,]\d+)?\b/g, "")
    .replace(/\s+/g, " ")
    .trim();
  const unit = String(p.einheit || "").trim().toLowerCase();
  const qty = p.qty == null ? "" : Number(p.qty).toFixed(3);
  return `${text}|${unit}|${qty}`;
}

function filterAndDedupePositions(input: PhotoPosition[]) {
  const out: PhotoPosition[] = [];
  const seen = new Set<string>();

  for (const p of input || []) {
    const kurztext = String(p?.kurztext || "").trim();
    const qty = coerceQty(p?.qty);
    const einheit = String(p?.einheit || "").trim();

    if (!kurztext || !einheit || qty == null || qty <= 0) continue;
    if (isAdministrativeOrNonBillable(kurztext)) continue;
    if (looksLikeElevationOrDimension(kurztext, qty)) continue;

    const normalized: PhotoPosition = {
      ...p,
      kurztext,
      einheit,
      qty,

const qty = coerceQty(p?.qty);
    const einheit = String(p?.einheit || "").trim();

    if (!kurztext || !einheit || qty == null || qty <= 0) continue;
    if (isAdministrativeOrNonBillable(kurztext)) continue;
    if (looksLikeElevationOrDimension(kurztext, qty)) continue;

    const normalized: PhotoPosition = {
      ...p,
      kurztext,
      einheit,
      qty,
      confidence: clampConfidence(p?.confidence),
      evidence: String(p?.evidence || "").trim() || undefined,
    };

    const key = technicalPositionKey(normalized);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(normalized);
  }

  return out;
}

function typeFromUnit(unitRaw: string): "LINE" | "AREA" | "COUNT" {
  const unit = String(unitRaw || "").toLowerCase().replace(/\s+/g, "");
  if (unit === "m2" || unit === "m²") return "AREA";
  if (unit === "m" || unit === "lfm") return "LINE";
  return "COUNT";
}

async function analyzeWithOpenAI(imageDataUrl: string, note: string) {
  const client = getOpenAI();

  const resp = await client.chat.completions.create({
    model: OPENAI_MODEL,
    temperature: 0.1,
    response_format: { type: "json_object" },
    messages: [
      {
        role: "user",
        content: [
          { type: "text", text: visionPrompt(note) },
          {
            type: "image_url",
            image_url: {
              url: imageDataUrl,
              detail: "high",
            },
          },
        ],
      },
    ],
  });

  const text = resp.choices?.[0]?.message?.content || "";

  console.log("[auto-ki] OpenAI model:", OPENAI_MODEL);
  console.log("[auto-ki] OpenAI raw:", text.slice(0, 8000));

  let parsed = safeJsonParse<any>(text, null);

  if (!parsed || !Array.isArray(parsed.positions)) {
    const m = text.match(/\{[\s\S]*\}/);
    parsed = m ? safeJsonParse<any>(m[0], null) : null;
  }

  if (!parsed || !Array.isArray(parsed.positions)) {
    return { summary: "KI-Antwort unlesbar.", positions: [] as PhotoPosition[] };
  }

  const mapped: PhotoPosition[] = parsed.positions
    .map((p: any) => ({
      id: p?.id ? String(p.id) : "",
      kurztext: String(p?.kurztext || p?.label || "").trim(),
      einheit: String(p?.einheit || p?.unit || "").trim(),
      qty: coerceQty(p?.qty),
      typ: p?.typ ? String(p.typ) : undefined,
      status: p?.status ? String(p.status) : undefined,
      confidence: clampConfidence(p?.confidence),
      evidence: String(p?.evidence || "").trim() || undefined,
    }))
    .filter((p: PhotoPosition) => p.kurztext);

  const positions = filterAndDedupePositions(mapped);

  console.log(
    "[auto-ki] parsed positions:",
    mapped.length,
    "accepted:",
    positions.length,
    "filtered:",
    mapped.length - positions.length
  );

  return { summary: String(parsed.summary || ""), positions };
}

/* ===================== AUFMASS EXPORT (Husemann & Fritz style) ===================== */

type SollIstRow = {
  id: string;
  kind: "base" | "mass";
  pos: string;
  text: string;
  unit: string;
  soll: number;
  ist: number; // base: 0 (computed in FE), mass: qty
  ep: number;
  formula?: string;
  source?: string;
  ts?: number;
};

function toNum(v: any, fallback = 0) {
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function readSollIst(fsKey: string): SollIstRow[] {
  const file = sollIstPath(fsKey);
  ensureDir(path.dirname(file));
  if (!fs.existsSync(file)) return [];
  const raw = fs.readFileSync(file, "utf8");
  const arr = safeJsonParse<any[]>(raw, []);
  return Array.isArray(arr) ? (arr as SollIstRow[]) : [];
}

function writeSollIst(fsKey: string, rows: SollIstRow[]) {
  const file = sollIstPath(fsKey);
  ensureDir(path.dirname(file));
  fs.writeFileSync(file, JSON.stringify(rows, null, 2), "utf8");
  return file;
}

function appendMassLines(
  fsKey: string,
  incoming: Array<{ pos: string; text?: string; unit?: string; qty?: number; ep?: number; soll?: number; formula?: string; source?: string }>
) {
  const current = readSollIst(fsKey);

  // index base rows
  const baseByPos = new Map<string, SollIstRow>();
  for (const r of current) {
    if (r?.kind === "base") baseByPos.set(String(r.pos || "").trim(), r);
  }

  const out: SollIstRow[] = [...current];

  for (const x of incoming || []) {
    const pos = String(x?.pos ?? "").trim();
    if (!pos) continue;

    const text = String(x?.text ?? "").trim() || "Auto-KI";
    const unit = String(x?.unit ?? "m").trim() || "m";
    const ep = toNum(x?.ep ?? 0, 0);
    const soll = toNum(x?.soll ?? 0, 0);
    const qty = toNum(x?.qty ?? 0, 0);

    let base = baseByPos.get(pos);
    if (!base) {
      base = {
        id: crypto.randomUUID(),
        kind: "base",
        pos,
        text,
        unit,
        soll,
        ist: 0,
        ep,
      };
      baseByPos.set(pos, base);
      out.push(base);
    } else {
      if ((!base.text || !base.text.trim()) && text) base.text = text;
      if ((!base.unit || !base.unit.trim()) && unit) base.unit = unit;
      if (!base.ep && ep) base.ep = ep;
      if (!base.soll && soll) base.soll = soll;
    }

    // append mass line
    if (qty !== 0) {
      out.push({
        id: crypto.randomUUID(),
        kind: "mass",
        pos,
        text: base.text,
        unit: base.unit,
        soll: base.soll,
        ep: base.ep,
        ist: qty,
        formula: String(x?.formula ?? "KI-Plan").trim(),
        source: String(x?.source ?? "auto-ki").trim(),
        ts: Date.now(),
      });
    }

kind: "mass",
        pos,
        text: base.text,
        unit: base.unit,
        soll: base.soll,
        ep: base.ep,
        ist: qty,
        formula: String(x?.formula ?? "KI-Plan").trim(),
        source: String(x?.source ?? "auto-ki").trim(),
        ts: Date.now(),
      });
    }
  }

  const file = writeSollIst(fsKey, out);
  return { count: out.length, file };
}

