          menge: Number(pp.qty),
        }));

        items = positions.map((pp: any, idx: number) => ({
          id: crypto.randomUUID(),
          pos: `AUTO.${String(idx + 1).padStart(3, "0")}`,
          type: typeFromUnit(pp.einheit),
          descr: String(pp.kurztext || ""),
