import { Router, type Request, type Response } from "express";
import path from "path";
import fs from "fs";
import multer from "multer";

import {
  readTakeoff,
  readUtmCsv,
  getCadImportPaths,
  openCadImport,
} from "../services/cad-import.service";
import { parseByExtension } from "../parsers";
import { parseDXFGeometry } from "../parsers/dxf";
import { cleanupPreparedCadImport, prepareCadImportBuffer } from "../services/cad-converter.service";

import { archiveProjectFileVersion } from "../services/dmsArchive";
const r = Router();

function getProjectId(req: Request) {
  return String(req.query.projectId || "").trim();
}

function jsonError(res: Response, status: number, message: string) {
  return res.status(status).json({ ok: false, message });
}


const cadUpload = multer({
  storage: multer.memoryStorage(),
  limits: {
    fileSize: 100 * 1024 * 1024,
    files: 1,
  },
});

const ALLOWED_CAD_EXTENSIONS = new Set([
  ".dxf",
  ".dwg",
  ".csv",
  ".txt",
  ".xml",
  ".gsi",
  ".pdf",
]);

function safeProjectId(req: Request): string {
  const projectId = String(
    req.query.projectId ||
    req.body?.projectId ||
    ""
  ).trim();

  if (!projectId) {
    throw new Error("projectId fehlt.");
  }

  if (
    projectId.includes("..") ||
    projectId.includes("/") ||
    projectId.includes("\\") ||
    !/^[A-Za-z0-9._-]+$/.test(projectId)
  ) {
    throw new Error("Ungültige projectId.");
  }

  return projectId;
}

function safeFileName(name: string): string {
  const base = path.basename(String(name || "cad-datei"));
  const cleaned = base.replace(/[^A-Za-z0-9ÄÖÜäöüß._-]/g, "_");

  if (!cleaned || cleaned === "." || cleaned === "..") {
    return "cad-datei";
  }

  return cleaned;
}

function getUploadedFile(req: Request): Express.Multer.File | undefined {
  if (req.file) return req.file;

  const files = req.files;
  if (Array.isArray(files) && files.length) {
    return files[0];
  }

  if (files && typeof files === "object") {
    const groups = Object.values(files);
    for (const group of groups) {
      if (Array.isArray(group) && group.length) {
        return group[0];
      }
    }
  }

  return undefined;
}

function resolveStoredCadFile(
  projectId: string,
  requestedValue: unknown
): string | null {
  const paths = getCadImportPaths(projectId);
  const uploadDir = path.join(paths.cadDir, "uploads");

  const requested = String(requestedValue || "").trim();
  if (!requested) return null;

  const base = path.basename(requested);
  if (base !== requested) return null;

  const full = path.resolve(uploadDir, base);
  const uploadRoot = path.resolve(uploadDir) + path.sep;

  if (!full.startsWith(uploadRoot)) return null;
  if (!fs.existsSync(full) || !fs.statSync(full).isFile()) return null;

  return full;
}

/**
 * CAD-Datei hochladen
 * POST /api/cad/upload?projectId=...
 *
 * Multipart-Feld kann "file", "cadFile", "upload" oder ein beliebiger
 * einzelner Dateiname sein.
 */
r.post(
  "/upload",
  cadUpload.any(),
  (req: Request, res: Response) => {
    try {
      const projectId = safeProjectId(req);
      const uploaded = getUploadedFile(req);

      if (!uploaded) {
        return jsonError(res, 400, "Keine CAD-Datei empfangen.");
      }

      const originalName = safeFileName(uploaded.originalname);
      const extension = path.extname(originalName).toLowerCase();

      if (!ALLOWED_CAD_EXTENSIONS.has(extension)) {
        return jsonError(
          res,
          400,
          `Dateiformat nicht unterstützt: ${extension || "ohne Erweiterung"}.`
        );
      }

      const paths = getCadImportPaths(projectId);
      const uploadDir = path.join(paths.cadDir, "uploads");
      fs.mkdirSync(uploadDir, { recursive: true });

      const timestamp = new Date()
        .toISOString()
        .replace(/[-:.TZ]/g, "")
        .slice(0, 14);

      const stem =
        path.basename(originalName, extension)
          .replace(/[^A-Za-z0-9ÄÖÜäöüß_-]/g, "_")
          .slice(0, 100) || "cad";

      const storedName = `${timestamp}-${stem}${extension}`;
      const targetPath = path.join(uploadDir, storedName);

      fs.writeFileSync(targetPath, uploaded.buffer);

      /* CAD_UPLOAD_DMS_V1 */
      {
        const ext = path.extname(originalName).toLowerCase();

        const dmsKind =
          ext === ".pdf"
            ? "PDF"
            : ext === ".png" ||
              ext === ".jpg" ||
              ext === ".jpeg" ||
              ext === ".webp"
            ? "IMAGE"
            : "CAD";

        void archiveProjectFileVersion({
          projectIdOrCode: projectId,
          filename: originalName,
          kind: dmsKind as any,
          localPath: targetPath,
          uploadedBy:
            String(
              (req as any)?.auth?.email ||
              (req as any)?.auth?.userId ||
              (req as any)?.user?.email ||
              (req as any)?.user?.id ||
              ""
            ).trim() || null,
          meta: {
            module: "CAD",
            source: "cad.upload",
            originalName,
            storedName,
            mimeType: uploaded.mimetype || null
          }
        }).catch((dmsError) => {
          console.error("[cad:upload:dms]", dmsError);
        });
      }

      return res.status(201).json({
        ok: true,
        message: "CAD-Datei erfolgreich hochgeladen.",
        projectId,
        uploadId: storedName,
        fileName: storedName,
        storedName,
        originalName,

console.error("[cad:upload:dms]", dmsError);
        });
      }

      return res.status(201).json({
        ok: true,
        message: "CAD-Datei erfolgreich hochgeladen.",
        projectId,
        uploadId: storedName,
        fileName: storedName,
        storedName,
        originalName,
        relativePath: path
          .relative(paths.projectRoot, targetPath)
          .replace(/\\/g, "/"),
        size: uploaded.size,
        mimeType: uploaded.mimetype,
      });
    } catch (e: any) {
      return jsonError(res, 500, String(e?.message || e));
    }
  }
);

/**
 * CAD-Datei importieren/parsen
 * POST /api/cad/import?projectId=...
 *
 * Unterstützt:
 * 1. erneutes Multipart-Upload;
 * 2. JSON/Form-Daten mit uploadId, storedName, fileName oder filename.
 */
r.post(
  "/import",
  cadUpload.any(),
  async (req: Request, res: Response) => {
    try {
      const projectId = safeProjectId(req);
      const uploaded = getUploadedFile(req);

      let originalName = "";
      let storedName = "";
      let sourcePath = "";
      let buffer: Buffer;

      if (uploaded) {
        originalName = safeFileName(uploaded.originalname);
        buffer = uploaded.buffer;

        const extension = path.extname(originalName).toLowerCase();
        if (!ALLOWED_CAD_EXTENSIONS.has(extension)) {
          return jsonError(
            res,
            400,
            `Dateiformat nicht unterstützt: ${extension || "ohne Erweiterung"}.`
          );
        }
      } else {
        const requested =
          req.body?.uploadId ||
          req.body?.storedName ||
          req.body?.fileName ||
          req.body?.filename ||
          req.query.uploadId ||
          req.query.storedName ||
          req.query.fileName ||
          req.query.filename;

        sourcePath = resolveStoredCadFile(projectId, requested) || "";

        if (!sourcePath) {
          return jsonError(
            res,
            400,
            "Keine importierbare Datei gefunden. Zuerst /upload ausführen."
          );
        }

        storedName = path.basename(sourcePath);
        originalName = String(
          req.body?.originalName ||
          req.query.originalName ||
          storedName
        );

        buffer = fs.readFileSync(sourcePath);
      }

      const rawScale =
        req.body?.scale ??
        req.query.scale ??
        1;

      const scale = Number(String(rawScale).replace(",", "."));
      const safeScale =
        Number.isFinite(scale) && scale > 0
          ? scale
          : 1;

      const prepared = prepareCadImportBuffer(originalName, buffer);
      const effectiveExtension = path.extname(prepared.effectiveName).toLowerCase();

      let parsed;
      let dxfGeometry = null as ReturnType<typeof parseDXFGeometry> | null;
      try {
        parsed = await parseByExtension(
          prepared.effectiveName,
          prepared.buffer,
          safeScale
        );
        dxfGeometry =
          effectiveExtension === ".dxf"
            ? parseDXFGeometry(prepared.buffer, prepared.effectiveName)
            : null;
      } finally {
        cleanupPreparedCadImport(prepared);
      }

      const paths = getCadImportPaths(projectId);
      const importDir = path.join(paths.cadDir, "imports");
      fs.mkdirSync(importDir, { recursive: true });

      const importResult = {
        version: "rlc_cad_import_v1",
        projectId,
        importedAt: new Date().toISOString(),
        originalName,
        storedName: storedName || undefined,
        scale: safeScale,
        note: parsed.note,
        items: parsed.items,
        converted: prepared.converted,
        converter: prepared.converter,
        effectiveName: prepared.effectiveName,
      };

      const resultFile = path.join(importDir, "latest-import.json");
      fs.writeFileSync(
        resultFile,
        JSON.stringify(importResult, null, 2),
        "utf8"
      );

      let takeoffFile: string | undefined;
      let takeoffPayload: any = undefined;
      if (dxfGeometry) {
        takeoffPayload = {
          type: "rlc_cad_geometry_v1",
          version: "1.0",
          projectId,
          sourceFile: originalName,
          effectiveSourceFile: prepared.effectiveName,
          convertedFrom: prepared.converted ? originalName : undefined,
          converter: prepared.converter,
          importedAt: importResult.importedAt,
          layers: dxfGeometry.layers.map((name) => ({ name, visible: true, locked: false })),
          features: dxfGeometry.features,
          points: dxfGeometry.features
            .filter((feature) => feature.kind === "point" && feature.pts[0])
            .map((feature) => ({ id: feature.id, x: feature.pts[0].x, y: feature.pts[0].y, label: feature.name })),
          source: dxfGeometry.source,
          normalized: {
            version: "normalized_v1",
            sourceType: "rlc_cad_geometry_v1",
            features: dxfGeometry.features,
            points: [],
          },
          quantities: parsed.items,
        };
        fs.mkdirSync(paths.cadDir, { recursive: true });
        takeoffFile = paths.takeoffJsonPath;
        fs.writeFileSync(takeoffFile, JSON.stringify(takeoffPayload, null, 2), "utf8");
      }

      return res.json({
        ok: true,
        message: parsed.note || `${parsed.items.length} Elemente importiert.`,
        projectId,
        originalName,
        storedName: storedName || undefined,
        scale: safeScale,

fs.mkdirSync(paths.cadDir, { recursive: true });
        takeoffFile = paths.takeoffJsonPath;
        fs.writeFileSync(takeoffFile, JSON.stringify(takeoffPayload, null, 2), "utf8");
      }

      return res.json({
        ok: true,
        message: parsed.note || `${parsed.items.length} Elemente importiert.`,
        projectId,
        originalName,
        storedName: storedName || undefined,
        scale: safeScale,
        count: parsed.items.length,
        items: parsed.items,
        result: importResult,
        note: parsed.note,
        relativeResultPath: path
          .relative(paths.projectRoot, resultFile)
          .replace(/\\/g, "/"),
        takeoffCreated: Boolean(takeoffFile),
        converted: prepared.converted,
        converter: prepared.converter,
        effectiveName: prepared.effectiveName,
        data: takeoffPayload || parsed.items,
        takeoff: takeoffPayload,
        relativeTakeoffPath: takeoffFile
          ? path.relative(paths.projectRoot, takeoffFile).replace(/\\/g, "/")
          : undefined,
      });
    } catch (e: any) {
      return jsonError(res, 500, String(e?.message || e));
    }
  }
);

