function cloudDocumentModule(document: any): string {
  const meta = document?.meta && typeof document.meta === "object" ? document.meta : {};
  return String(meta?.module || meta?.moduleKey || meta?.documentType || document?.module || "")
    .trim().toUpperCase();
}

