import { Router } from "express";
import { prisma } from "../lib/prisma";

const router = Router();

function companyId(req: any) {
  return String(req.auth?.companyId || "").trim();
}

async function resolveProject(cid: string, input: string) {
  const value = String(input || "").trim();

  if (!value) return null;

  return prisma.project.findFirst({
    where: {
      companyId: cid,
      OR: [
        { id: value },
        { code: value }
      ]
    },
    select: {
      id: true,
      code: true,
      name: true
    }
  });
}

function dateValue(value: any) {
  if (!value) return null;

  const d = new Date(String(value));

  return Number.isNaN(d.getTime())
    ? null
    : d;
}

function tagsValue(value: any): string[] {
  if (!Array.isArray(value)) return [];

  return Array.from(
    new Set(
      value
        .map((item) => String(item || "").trim())
        .filter(Boolean)
    )
  );
}

function dto(row: any) {
  return {
    ...row,
    valueNet: Number(row.valueNet || 0)
  };
}

router.get("/", async (req: any, res) => {
  try {
    const cid = companyId(req);

    if (!cid) {
      return res.status(403).json({
        ok: false,
        error: "COMPANY_REQUIRED"
      });
    }

    const projectInput = String(
      req.query.projectId ||
      req.query.projectCode ||
      ""
    ).trim();

    const project = projectInput
      ? await resolveProject(cid, projectInput)
      : null;

    if (projectInput && !project) {
      return res.status(404).json({
        ok: false,
        error: "PROJECT_NOT_FOUND"
      });
    }

    const items = await prisma.contract.findMany({
      where: {
        companyId: cid,
        ...(project ? { projectId: project.id } : {})
      },
      include: {
        document: {
          include: {
            versions: {
              orderBy: {
                version: "desc"
              }
            }
          }
        }
      },
      orderBy: {
        updatedAt: "desc"
      }
    });

    return res.json({
      ok: true,
      items: items.map(dto)
    });
  } catch (error: any) {
    console.error("GET /api/contracts failed", error);

    return res.status(500).json({
      ok: false,
      error: error?.message || "CONTRACT_LIST_FAILED"
    });
  }
});

