r.post("/upload-url", async (req, res) => {
  try {
    const schema = z.object({
      documentId: z.string().min(1),
      filename: z.string().min(1),
      contentType: z.string().min(1),
    });

    const { documentId, filename, contentType } = schema.parse(req.body);

    const doc = await prisma.document.findUnique({ where: { id: documentId } });
    if (!doc) return res.status(404).json({ error: "Dokument nicht gefunden" });

    const last = await prisma.fileVersion.findFirst({
      where: { documentId },
      orderBy: { version: "desc" },
    });
    const nextVersion = (last?.version ?? 0) + 1;

    const key = objectKey(doc.projectId, doc.id, nextVersion, filename);
    const uploadUrl = await presignPut(key, contentType);

    res.json({
      ok: true,
      uploadUrl,
      key,
      documentId: doc.id,
      version: nextVersion,
      contentType
    });
  } catch (e: any) {
    console.error("[files] upload-url error:", e);
    res.status(400).json({ error: e?.message || "Bad request" });
  }
});


r.post("/upload-complete", async (req, res) => {
  try {
    const schema = z.object({
      documentId: z.string().min(1),
      key: z.string().min(1),
      version: z.number().int().positive(),
      contentType: z.string().min(1),
      size: z.number().int().nonnegative().optional(),
    });

    const {
      documentId,
      key,
      version,
      contentType,
      size
    } = schema.parse(req.body);

    const doc = await prisma.document.findUnique({
      where: { id: documentId }
    });

    if (!doc) {
      return res.status(404).json({
        error: "Dokument nicht gefunden"
      });
    }

    const existing = await prisma.fileVersion.findFirst({
      where: {
        documentId,
        version
      }
    });

    if (existing) {
      return res.json({
        ok: true,
        versionId: existing.id,
        existing: true
      });
    }

    const storageId = crypto.randomUUID();

    await prisma.storageObject.create({
      data: {
        id: storageId,
        bucket,
        key,
        size: BigInt(size ?? 0),
        sha256: "",
        mime: contentType,
      },
    });

    const ver = await prisma.fileVersion.create({
      data: {
        documentId,
        storageId,
        version,
      },
    });

    await prisma.document.update({
      where: { id: documentId },
      data: {
        currentVid: ver.id,
        updatedAt: new Date()
      },
    });

    res.json({
      ok: true,
      versionId: ver.id
    });
  } catch (e: any) {
    console.error("[files] upload-complete error:", e);
    res.status(400).json({
      error: e?.message || "Bad request"
    });
  }
});


