function inferMimeFromName(nameOrUrl: string) {
  const s = String(nameOrUrl || "").toLowerCase();
  if (s.endsWith(".png")) return "image/png";
  if (s.endsWith(".webp")) return "image/webp";
  if (s.endsWith(".heic")) return "image/heic";
  if (s.endsWith(".heif")) return "image/heif";
  if (s.endsWith(".pdf")) return "application/pdf";
  if (s.endsWith(".jpg") || s.endsWith(".jpeg")) return "image/jpeg";
  return "application/octet-stream";
}

function toFileMetaFromInboxFile(f: any) {
  const publicUrl = String(f?.publicUrl || "").trim();
  if (!publicUrl) return null;
  const name = String(f?.name || f?.file || "file.bin");
  return {
    uri: publicUrl,
    name,
    type: inferMimeFromName(name || publicUrl),
  };
}

function decorateInboxItem(projectId: string, it: any) {
  const mainMeta = it?.main ? toFileMetaFromInboxFile(it.main) : null; // âœ… FIX: no duplicate
  const fileMetas = Array.isArray(it?.files)
    ? it.files.map(toFileMetaFromInboxFile).filter(Boolean)
    : [];

  const attachments = [mainMeta, ...fileMetas].filter(Boolean);

  return {
    ...it,
    projectId,
    projectCode: projectId,
    imageUri: (mainMeta as any)?.uri || it?.imageUri || undefined,
    attachments,
    photos: attachments,
  };
}

function fotoPdfInputFromSource(opts: {
  pdfPath: string;
  projectId: string;
  source: any;
  company?: any;
}) {
  const source = decorateInboxItem(opts.projectId, opts.source || {});
  const main = source.main
    ? {
        ...source.main,
        name: source.main.name || source.main.file,
        url: source.main.publicUrl || source.main.url,
        publicUrl: source.main.publicUrl,
      }
    : source.imageUri
    ? { name: "Hauptfoto", url: source.imageUri }
    : null;
  const files = [
    ...(Array.isArray(source.files) ? source.files : []),
    ...(Array.isArray(source.attachments) ? source.attachments : []),
    ...(Array.isArray(source.photos) ? source.photos : []),
  ].map((file: any) => ({
    ...file,
    name: file?.name || file?.file || "Datei",
    url: file?.url || file?.publicUrl || file?.uri,
    publicUrl: file?.publicUrl,
  }));

  return {
    pdfPath: opts.pdfPath,
    projectId: opts.projectId,
    projectName: String(source.projectName || source.projectTitle || source.baustelle || opts.projectId),
    date: String(source.date || source.createdAt || new Date().toISOString()).slice(0, 10),
    kostenstelle: String(source.kostenstelle || source.costCenter || ""),
    lvItemPos: source.lvItemPos || source.lvPos || null,
    comment: String(source.comment || source.note || ""),
    bemerkungen: String(source.bemerkungen || source.notes || ""),
    main,
    files,
    extras: Array.isArray(source.extras) ? source.extras : [],
    boxes: Array.isArray(source.boxes) ? source.boxes : [],
    company: opts.company || source.company || source.meta?.company || undefined,
  };
}

