  const list = readMeta(projectId);
  const entry = {
    id: filename,
    file: filename,
    createdAt: new Date().toISOString(),
    note: req.body.note || "",
    extras,
    boxes,
    publicUrl,
  };

  list.push(entry);
  writeMeta(projectId, list);

  res.json(entry);
