function norm(s: any): string {
  return String(s ?? "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .trim();
}

function normalizedKey(row: any): string {
  return [
    norm(row.shortText),
    norm(row.unit),
    norm(row.region),
  ].filter(Boolean).join("|");
}

