router.post(
  "/:id/attachments",
  upload.single("file"),
  async (req: any, res) => {
    const cid = cidOr403(req, res);
    if (!cid) return;

    const handoverId = String(req.params.id || "");
    const file = req.file;

    if (!file) {
      return res.status(400).json({
        ok: false,
        error: "FILE_REQUIRED"
      });
    }

    const handover = await prisma.companyHandover.findFirst({
      where: {
        id: handoverId,
        companyId: cid
      }
    });

    if (!handover) {
      return res.status(404).json({
        ok: false,
        error: "NOT_FOUND"
      });
    }

    const safeName = file.originalname.replace(
      /[^a-zA-Z0-9._-]+/g,
      "_"
    );

    const key =
      `companies/${cid}/handover/${handoverId}/` +
      `${Date.now()}-${crypto.randomUUID()}-${safeName}`;

    await storage.put({
      key,
      body: file.buffer,
      contentType:
        file.mimetype || "application/octet-stream"
    });

    const stored = await prisma.storageObject.create({
      data: {
        id: crypto.randomUUID(),
        bucket,
        key,
        size: BigInt(file.size),
        sha256: crypto
          .createHash("sha256")
          .update(file.buffer)
          .digest("hex"),
        mime:
          file.mimetype || "application/octet-stream"
      }
    });

    const item = await prisma.companyHandoverAttachment.create({
      data: {
        handoverId,
        storageId: stored.id,
        name: file.originalname,
        mime:
          file.mimetype || "application/octet-stream",
        size: file.size
      }
    });

    if (handover.projectId) {
      const kind =
        file.mimetype === "application/pdf"
          ? "PDF"
          : file.mimetype.startsWith("image/")
          ? "IMAGE"
          : "DOC";

      await registerExistingStorageVersion({
        projectIdOrCode: handover.projectId,
        filename: file.originalname,
        kind,
        storageId: stored.id,
        uploadedBy: req.auth?.sub || null,
        meta: {
          module: "UEBERGABE",
          handoverId,
          source: "handover-attachment"
        }
      });
    }

    return res.json({ ok: true, item });
  }
);

