router.post("/:id/finalize", async (req: any, res) => {
  try {
    const cid = cidOr403(req, res);
    if (!cid) return;

    const id = String(req.params.id || "");

    const handover = await prisma.companyHandover.findFirst({
      where: {
        id,
        companyId: cid
      },
      include: {
        items: {
          orderBy: {
            createdAt: "asc"
          }
        },
        signatures: true
      }
    });

    if (!handover) {
      return res.status(404).json({
        ok: false,
        error: "NOT_FOUND"
      });
    }

    if (!handover.projectId) {
      return res.status(400).json({
        ok: false,
        error: "PROJECT_REQUIRED"
      });
    }

    const pdfPath = handoverPdfPath(
      handover.projectId,
      handover.id
    );

    const result = await createHandoverPdf({
      pdfPath,
      projectId: handover.projectId,
      title: handover.title,
      client: handover.client,
      address: handover.address,
      date: handover.date,
      status: "ABGESCHLOSSEN",
      notes: handover.notes,
      items: handover.items,
      signatures: handover.signatures
    });

    await archiveProjectFileVersion({
      projectIdOrCode: handover.projectId,
      filename: result.fileName,
      kind: "PDF",
      localPath: result.filePath,
      uploadedBy: req.auth?.sub || null,
      meta: {
        module: "UEBERGABE",
        handoverId: handover.id,
        source: "handover-final"
      }
    });

    const item = await prisma.companyHandover.update({
      where: {
        id: handover.id
      },
      data: {
        status: "ABGESCHLOSSEN"
      }
    });

    return res.json({
      ok: true,
      item,
      pdfUrl: result.pdfUrl,
      fileName: result.fileName
    });
  } catch (error: any) {
    console.error(
      "POST /api/handover/:id/finalize failed",
      error
    );

    return res.status(500).json({
      ok: false,
      error:
        error?.message ||
        "HANDOVER_FINALIZE_FAILED"
    });
  }
});

router.get("/:id/pdf", async (req: any, res) => {
  try {
    const cid = cidOr403(req, res);
    if (!cid) return;

    const handover =
      await prisma.companyHandover.findFirst({
        where: {
          id: String(req.params.id || ""),
          companyId: cid
        }
      });

    if (!handover) {
      return res.status(404).json({
        ok: false,
        error: "NOT_FOUND"
      });
    }

    if (!handover.projectId) {
      return res.status(400).json({
        ok: false,
        error: "PROJECT_REQUIRED"
      });
    }

    const pdfPath = handoverPdfPath(
      handover.projectId,
      handover.id
    );

    if (!fs.existsSync(pdfPath)) {
      return res.status(404).json({
        ok: false,
        error: "PDF_NOT_FOUND"
      });
    }

    const contextProjectRoot = path.join(
      process.cwd(),
      "data",
      "projects",
      handover.projectId
    );

    const relative = path
      .relative(
        contextProjectRoot,
        pdfPath
      )
      .split(path.sep)
      .map(encodeURIComponent)
      .join("/");

    return res.json({
      ok: true,
      pdfUrl:
        `/projects/${encodeURIComponent(
          handover.projectId
        )}/${relative}`
    });
  } catch (error: any) {
    return res.status(500).json({
      ok: false,
      error:
        error?.message ||
        "PDF_OPEN_FAILED"
    });
  }
});

