      saved++;
    }

    return res.json({
      ok: true,
      source,
      imported: saved,
      skipped,
      total: parsed.length,
    });
  } catch (e: any) {
    console.error("[kalkulation.datenbank] import-csv failed:", e);
    return res.status(500).json({
      ok: false,
      error: e?.message || "IMPORT_CSV_FAILED",
    });
  }
});


