  const total = qty > 0 ? round2(fallbackEp * qty) : n((result as any).totalNet ?? (result as any).gesamt ?? (result as any).totalPrice);

  const oldEp = n(
    (result as any).finalUnitPrice ??
    (result as any).rlcKiUnitPrice ??
    (result as any).unitPrice ??
