    let fahrer = "";

    for (let t of tokens) {
      if (!menge && /^\d+(\.\d+)?$/.test(t)) {
        menge = Number(t);
        continue;
      }

      if (!material && /kies|schotter|sand|asphalt/i.test(t)) {
        material = t;
        continue;
      }

      if (!ort) {
        ort = t;
        continue;
      }

      if (!fahrer) {
        fahrer = t;
        continue;
      }
    }

    if (material) fp.material = material;
    if (menge != null) fp.menge = menge;
    if (!fp.einheit && material) fp.einheit = "m3";
    if (ort) fp.kostenstelle = ort;
    if (fahrer) fp.fahrer = fahrer;

    if (!__rlcStr(fp.textBeschreibung) && material) {
      fp.textBeschreibung =
        `${material}` +
        `${menge != null ? ` (${menge} ${fp.einheit || "m3"})` : ""}` +
        `${ort ? ` zur Baustelle ${ort}` : ""}` +
        ` geliefert` +
        `${fahrer ? ` (Fahrer: ${fahrer})` : ""}.`;
    }

    if (!__rlcStr(fp.bemerkungen) && __rlcStr(fp.textBeschreibung)) {
      fp.bemerkungen = fp.textBeschreibung;
    }

    s0.fieldPatches = fp;
    if (!s0.notes) {
      s0.notes = "Fachlogik aktiv: Lieferschein vollständig interpretiert.";
    }

    suggestions[0] = s0;
    return suggestions;
  }

  return suggestions;
}

export function parseLieferschein(
  ocrResults: Array<{ file: string; text: string }>
): Array<{
  lieferant?: string;
  datum?: string;
  material?: string;
  menge?: number;
  einheit?: string;
  preis?: number;
  kostenstelle?: string;
}> {
  const out: any[] = [];
  for (const r of ocrResults) {
    const t = String(r.text || "");
    if (/Lieferschein/i.test(t)) {
      const lieferant = (t.match(/Firma\s+([^\n]+)/i) || [, ""])[1];

datum?: string;
  material?: string;
  menge?: number;
  einheit?: string;
  preis?: number;
  kostenstelle?: string;
}> {
  const out: any[] = [];
  for (const r of ocrResults) {
    const t = String(r.text || "");
    if (/Lieferschein/i.test(t)) {
      const lieferant = (t.match(/Firma\s+([^\n]+)/i) || [, ""])[1];
      const material = (t.match(/Material:\s*([^\n]+)/i) || [, ""])[1];
      const mengeStr = (t.match(/Menge:\s*([0-9.,]+)/i) || [, "0"])[1];
      const menge = Number(String(mengeStr).replace(",", "."));
      const einheit = /\bt\b/i.test(t) ? "t" : "stk";
      const datum = (t.match(/Datum:\s*([0-9\-./]+)/i) || [, ""])[1];
      const kostenstelle = (t.match(/Kostenstelle:\s*([^\n]+)/i) || [, ""])[1];
      out.push({
        lieferant: lieferant || undefined,
        datum: datum || undefined,
        material: material || undefined,
        menge: isFinite(menge) ? menge : undefined,
        einheit,
        preis: undefined,
        kostenstelle: kostenstelle || undefined,
      });
    }
  }
  return out;
}

router.post("/lieferschein-parse", async (req, res) => {
  try {
    const body = req.body || {};
    const ocrResults = Array.isArray(body.ocrResults) ? body.ocrResults : [];
