    const total = n(r.zeilen ?? r.total ?? qty * ep);

    // Keine leeren Kapitel-/Schmutzzeilen ins Angebot
    if (!txt && qty === 0 && total === 0) return false;
    if (pos.toUpperCase().startsWith("BA-")) return false;

    return true;
  });
}

