      .lineTo(sumX + sumW - 12, sumY + 12 + rowH * 2 - 4)
      .stroke();

    doc.font("Helvetica-Bold").fontSize(11).fillColor("#0F172A");
    doc.text("Brutto", sumX + 12, sumY + 12 + rowH * 2, { width: 80 });
