      align: "right",
    });

    doc.restore();

    doc.y = sumY + rowH * 3 + 38;

    const notes = s(
      body.notes ||
        offer.notes ||
        body.options?.payment ||
        body.meta?.offer?.notes ||
        ""
    );

    if (notes) {
      doc.font("Helvetica").fontSize(9).fillColor("#334155");
      doc.text(notes, 56, doc.y, { width: 484 });
    }
  });
}



