  "/:id/documents",
  employeeUpload.single("file"),
  async (req: any, res) => {
    try {
      const cid = companyId(req);
      const employeeId = String(req.params.id || "");
      const file = req.file;

      if (!file) {
        return res.status(400).json({
          ok: false,
          error: "FILE_REQUIRED"
        });
      }

      const employee = await prisma.companyEmployee.findFirst({
        where: {
          id: employeeId,
          companyId: cid,
          active: true
        }
      });

      if (!employee) {
        return res.status(404).json({
          ok: false,
          error: "EMPLOYEE_NOT_FOUND"
        });
      }

      const filename =
        String(file.originalname || "document.bin")
          .replace(/[^\w.\-]+/g, "_");

      const storageId = crypto.randomUUID();

      const key =
        `companies/${cid}/employees/${employeeId}/${storageId}/${filename}`;

      await storage.put({
        key,
        body: file.buffer,
        contentType:
          file.mimetype ||
          "application/octet-stream"
      });

      const item = await prisma.$transaction(async (tx) => {
        await tx.storageObject.create({
          data: {
            id: storageId,
            bucket,
            key,
            size: BigInt(file.size),
            sha256: "",
            mime:
              file.mimetype ||
              "application/octet-stream"
          }
        });

        return tx.companyEmployeeDocument.create({
          data: {
            employeeId,
            storageId,
            name: file.originalname || filename,
            mime:
              file.mimetype ||
              "application/octet-stream",
            size: file.size
          }
        });
      });

      return res.json({
        ok: true,
        item
      });
    } catch (e: any) {
      console.error("POST personal document failed", e);

      return res.status(500).json({
        ok: false,
        error: e?.message || "DOCUMENT_UPLOAD_FAILED"
      });
    }
  }
);

