  });

  res.json({ ok: true });
});


router.post(
  "/materials/:id/attachments",
  materialUpload.single("file"),
  async (req: any, res) => {
    try {
      const cid = cidOr403(req, res);
      if (!cid) return;

      const materialId = String(req.params.id || "");
      const file = req.file;

      if (!file) {
        return res.status(400).json({
          ok: false,
          error: "FILE_REQUIRED"
        });
      }

      const material = await prisma.companyMaterial.findFirst({
        where: {
          id: materialId,
          companyId: cid,
          active: true
        }
      });

      if (!material) {
        return res.status(404).json({
          ok: false,

const material = await prisma.companyMaterial.findFirst({
        where: {
          id: materialId,
          companyId: cid,
          active: true
        }
      });

      if (!material) {
        return res.status(404).json({
          ok: false,
          error: "MATERIAL_NOT_FOUND"
        });
      }

      const storageId = crypto.randomUUID();

      const filename = String(
        file.originalname || "document.bin"
      ).replace(/[^\w.\-]+/g, "_");

      const key =
        `companies/${cid}/materials/${materialId}/` +
        `${storageId}/${filename}`;

      await storage.put({
        key,
        body: file.buffer,
        contentType:
          file.mimetype ||
          "application/octet-stream"
      });

      const item = await prisma.$transaction(async (tx) => {
        await tx.storageObject.create({
          data: {
            id: storageId,
            bucket,
            key,
            size: BigInt(file.size),
            sha256: crypto
              .createHash("sha256")
              .update(file.buffer)
              .digest("hex"),
            mime:
              file.mimetype ||
              "application/octet-stream"
          }
        });

        return tx.companyMaterialAttachment.create({
          data: {
            materialId,
            storageId,
            name: file.originalname || filename,
            mime:
              file.mimetype ||
              "application/octet-stream",
            size: file.size
          }
        });
      });

      if (material.projectId) {
        try {
          await registerExistingStorageVersion({
            projectIdOrCode: material.projectId,
            filename: file.originalname || filename,
            kind: materialDmsKind(
              file.mimetype ||
              "application/octet-stream"
            ),
            storageId,
            uploadedBy: req.auth?.sub || null,
            meta: {
              module: "MATERIAL",
              source: "material-attachment",
              materialId,
              materialName: material.name
            }
          });
        } catch (dmsError) {
          console.error(
            "[Material DMS] Anhang konnte nicht registriert werden",
            dmsError
          );
        }
      }

      return res.json({
        ok: true,
        item
      });
    } catch (error: any) {
      console.error(
        "POST material attachment failed",
        error
      );

      return res.status(500).json({
        ok: false,
        error:
          error?.message ||
          "MATERIAL_ATTACHMENT_UPLOAD_FAILED"
      });
    }
  }
);

