router.post(
  "/machines/:id/attachments",
  machineUpload.single("file"),
  async (req: any, res) => {
    try {
      const cid = cidOr403(req, res);
      if (!cid) return;

      const machineId = String(req.params.id || "");
      const file = req.file;

      if (!file) {
        return res.status(400).json({
          ok: false,
          error: "FILE_REQUIRED"
        });
      }

      const machine = await prisma.companyMachine.findFirst({
        where: {
          id: machineId,
          companyId: cid,
          active: true
        }
      });

      if (!machine) {
        return res.status(404).json({
          ok: false,
          error: "MACHINE_NOT_FOUND"
        });
      }

      const storageId = crypto.randomUUID();

      const filename = String(
        file.originalname || "document.bin"
      ).replace(/[^\w.\-]+/g, "_");

      const key =
        `companies/${cid}/machines/${machineId}/` +
        `${storageId}/${filename}`;

      await storage.put({
        key,
        body: file.buffer,
        contentType:
          file.mimetype ||
          "application/octet-stream"
      });

      const item = await prisma.$transaction(async (tx) => {
        await tx.storageObject.create({
          data: {
            id: storageId,
            bucket,
            key,
            size: BigInt(file.size),
            sha256: crypto
              .createHash("sha256")
              .update(file.buffer)
              .digest("hex"),
            mime:
              file.mimetype ||
              "application/octet-stream"
          }
        });

        return tx.companyMachineAttachment.create({
          data: {
            machineId,
            storageId,
            name: file.originalname || filename,
            mime:
              file.mimetype ||
              "application/octet-stream",
            size: file.size
          }
        });
      });

      if (machine.projectId) {
        try {
          await registerExistingStorageVersion({
            projectIdOrCode: machine.projectId,
            filename: file.originalname || filename,
            kind: machineDmsKind(
              file.mimetype ||
              "application/octet-stream"
            ),
            storageId,
            uploadedBy: req.auth?.sub || null,
            meta: {
              module: "MASCHINEN",
              source: "machine-attachment",
              machineId,
              machineName: machine.name
            }
          });
        } catch (dmsError) {
          console.error(
            "[Machine DMS] Anhang konnte nicht registriert werden",
            dmsError
          );
        }
      }

      return res.json({
        ok: true,
        item
      });
    } catch (error: any) {
      console.error(
        "POST machine attachment failed",
        error
      );

      return res.status(500).json({
        ok: false,
        error:
          error?.message ||
          "MACHINE_ATTACHMENT_UPLOAD_FAILED"
      });
    }
  }
);

