router.get("/machine-costs", async (req: any, res) => {
  const cid = cidOr403(req, res);
  if (!cid) return;

  const from = String(req.query.from || "").trim();
  const to = String(req.query.to || "").trim();
  const projectId = String(req.query.projectId || "").trim();

  const machines = await prisma.companyMachine.findMany({
    where: {
      companyId: cid,
      active: true
    }
  });

  const assignments = await prisma.resourceAssignment.findMany({
    where: {
      companyId: cid,
      resourceType: "MACHINE",
      ...(projectId ? { projectId } : {}),
      ...(from && to
        ? {
            date: {
              gte: new Date(`${from}T00:00:00.000Z`),
              lte: new Date(`${to}T23:59:59.999Z`)
            }
          }
        : {})
    }
  });

  const maintenance =
    await prisma.companyMachineMaintenance.findMany({
      where: {
        companyId: cid,
        ...(from && to
          ? {
              date: {
                gte: new Date(`${from}T00:00:00.000Z`),
                lte: new Date(`${to}T23:59:59.999Z`)
              }
            }
          : {})
      }
    });

  const items = machines.map((machine: any) => {
    const machineAssignments = assignments.filter(
      (a: any) => a.resourceId === machine.id
    );

    const plannedHours = machineAssignments.reduce(
      (sum: number, a: any) =>
        sum + Number(a.hours || 0),
      0
    );

    const hourlyRate = Number(
      machine.hourlyRate || 0
    );

    const usageCost =
      Number(machine.hours || 0) * hourlyRate;

    const maintenanceCost = maintenance
      .filter(
        (m: any) => m.machineId === machine.id
      )
      .reduce(
        (sum: number, m: any) =>
          sum + Number(m.costNet || 0),
        0
      );

    return {
      machineId: machine.id,
      machineName: machine.name,
      projectId: machine.projectId,
      plannedHours,
      operatingHours: Number(machine.hours || 0),
      hourlyRate,
      usageCost,
      maintenanceCost,
      totalCost:
        usageCost + maintenanceCost
    };
  });

  return res.json({
    ok: true,
    items,
    totals: {
      plannedHours: items.reduce(
        (s: number, i: any) =>
          s + i.plannedHours,
        0
      ),
      usageCost: items.reduce(
        (s: number, i: any) =>
          s + i.usageCost,
        0
      ),
      maintenanceCost: items.reduce(
        (s: number, i: any) =>
          s + i.maintenanceCost,
        0
      ),
      totalCost: items.reduce(
        (s: number, i: any) =>
          s + i.totalCost,
        0
      )
    }
  });
});

