router.post(
  "/:id/documents",
  upload.single("file"),
  async (req: any, res) => {
    try {
      const cid = cidOr403(req, res);
      if (!cid) return;

      const instructionId = String(req.params.id || "");
      const file = req.file;

      if (!file) {
        return res.status(400).json({
          ok: false,
          error: "FILE_REQUIRED"
        });
      }

      const instruction =
        await prisma.safetyInstruction.findFirst({
          where: {
            id: instructionId,
            companyId: cid
          }
        });

      if (!instruction) {
        return res.status(404).json({
          ok: false,
          error: "NOT_FOUND"
        });
      }

      const safeName = file.originalname.replace(
        /[^a-zA-Z0-9._-]+/g,
        "_"
      );

      const key =
        `companies/${cid}/safety/${instructionId}/` +
        `${Date.now()}-${crypto.randomUUID()}-${safeName}`;

      await storage.put({
        key,
        body: file.buffer,
        contentType:
          file.mimetype || "application/octet-stream"
      });

      const stored = await prisma.storageObject.create({
        data: {
            id: crypto.randomUUID(),
            bucket,
            key,
            size: BigInt(file.size),
            sha256: crypto
              .createHash("sha256")
              .update(file.buffer)
              .digest("hex"),
            mime: file.mimetype || "application/octet-stream"
          }
      });

      const document =
        await prisma.safetyInstructionDocument.create({
          data: {
            instructionId,
            storageId: stored.id,
            name: file.originalname,
            mime:
              file.mimetype ||
              "application/octet-stream",
            size: file.size
          }
        });

      if (instruction.projectId) {
        try {
          await registerExistingStorageVersion({
            projectIdOrCode: instruction.projectId,
            filename: file.originalname,
            kind: dmsKindFromMime(
              file.mimetype || "application/octet-stream"
            ),
            storageId: stored.id,
            uploadedBy: req.auth?.sub || null,
            meta: {
              module: "SICHERHEIT",
              source: "safety-instruction",
              instructionId
            }
          });
        } catch (dmsError) {
          console.error(

file.mimetype || "application/octet-stream"
            ),
            storageId: stored.id,
            uploadedBy: req.auth?.sub || null,
            meta: {
              module: "SICHERHEIT",
              source: "safety-instruction",
              instructionId
            }
          });
        } catch (dmsError) {
          console.error(
            "[Safety DMS] Unterweisungsdokument konnte nicht registriert werden",
            dmsError
          );
        }
      }

      return res.json({
        ok: true,
        item: document
      });
    } catch (error: any) {
      console.error(
        "POST /api/safety/:id/documents failed",
        error
      );

      return res.status(500).json({
