router.post(
  "/attachments/:entityType/:entityId",
  upload.single("file"),
  async (req: any, res) => {
    try {
      const cid = cidOr403(req, res);
      if (!cid) return;

      const entityType = String(req.params.entityType || "").toUpperCase();
      const entityId = String(req.params.entityId || "");
      const file = req.file;

      if (!file) {
        return res.status(400).json({
          ok: false,
          error: "FILE_REQUIRED"
        });
      }

      if (!(await safetyEntityExists(entityType, entityId, cid))) {
        return res.status(404).json({
          ok: false,
          error: "NOT_FOUND"
        });
      }

      const safeName = file.originalname.replace(
        /[^a-zA-Z0-9._-]+/g,
        "_"
      );

      const key =
        `companies/${cid}/safety/${entityType.toLowerCase()}/${entityId}/` +
        `${Date.now()}-${crypto.randomUUID()}-${safeName}`;

      await storage.put({
        key,
        body: file.buffer,
        contentType: file.mimetype || "application/octet-stream"
      });

      const stored = await prisma.storageObject.create({
        data: {
            id: crypto.randomUUID(),
            bucket,
            key,
            size: BigInt(file.size),
            sha256: crypto
              .createHash("sha256")
              .update(file.buffer)
              .digest("hex"),
            mime: file.mimetype || "application/octet-stream"
          }
      });

      const item = await prisma.safetyAttachment.create({
        data: {
          companyId: cid,
          entityType,
          entityId,
          storageId: stored.id,
          name: file.originalname,
