  }

  console.log("🔍 Suche Projekt mit Code / Nummer:", projectCode);

  const project =
    (await prisma.project.findFirst({
      where: {
        OR: [{ code: projectCode }, { number: projectCode }],
      },
    })) || null;

  if (!project) {
    console.error("❌ Projekt nicht gefunden:", projectCode);
    process.exit(1);
  }

