import fs from "fs";
import path from "path";
import { PrismaClient, Prisma } from "@prisma/client";

const prisma = new PrismaClient();

type FsLvRow = {
  pos: string;
  text: string;
  unit: string;
  ep?: number;
  soll?: number;
  langtext?: string;
};

async function main() {
  const arg = process.argv[2];

  if (!arg) {
    console.error("❌ Bitte Projekt-ID oder -Code als Argument angeben.");
    console.error("   Beispiel: npx ts-node src/scripts/import_lv_from_fs.ts BA-2025-DEMO");
    process.exit(1);
  }

  console.log("🔧 Importiere LV aus lv.json für Projekt:", arg);

  const project = await prisma.project.findFirst({
    where: {
      OR: [{ id: arg }, { code: arg }],
    },
  });

  if (!project) {
    console.error("❌ Projekt mit ID/Code nicht gefunden:", arg);
    process.exit(1);
  }

  console.log("✅ Projekt gefunden:", project.code, "-", project.name);

  const projectsRoot = path.resolve(__dirname, "..", "..", "data", "projects");
  console.log("📁 Projects root:", projectsRoot);

  if (!fs.existsSync(projectsRoot)) {
    console.error("❌ Projects-Root nicht gefunden:", projectsRoot);
    process.exit(1);
  }

  const projFolder = path.join(projectsRoot, project.id);

  if (!fs.existsSync(projFolder)) {
    console.error("❌ Projektordner nicht gefunden:", projFolder);
    process.exit(1);
  }

  const lvPath = path.join(projFolder, "lv.json");

  if (!fs.existsSync(lvPath)) {
    console.error("❌ lv.json nicht gefunden:", lvPath);
    process.exit(1);
  }

  console.log("📄 Lese lv.json:", lvPath);
  const raw = fs.readFileSync(lvPath, "utf8");

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    console.error("❌ Konnte lv.json nicht parsen:", e);
    process.exit(1);
  }

  if (!Array.isArray(parsed)) {
    console.error("❌ Erwartet ein Array in lv.json ([])");
    process.exit(1);
  }

  const rows = parsed as FsLvRow[];

  if (rows.length === 0) {
    console.error("❌ lv.json enthält keine Positionen.");
    process.exit(1);
  }

  console.log("✅ lv.json enthält", rows.length, "Positionen.");

  // Alte LV-Version(en) löschen
  const oldHeaders = await prisma.lVHeader.findMany({
    where: { projectId: project.id },
    select: { id: true },
  });

  if (oldHeaders.length > 0) {
    console.log("🧹 Lösche vorhandene LV-Versionen (%d)...", oldHeaders.length);
    const headerIds = oldHeaders.map((h) => h.id);
    await prisma.lVPosition.deleteMany({
      where: { lvId: { in: headerIds } },
    });
    await prisma.lVHeader.deleteMany({
      where: { id: { in: headerIds } },
    });
  }

  // Neue Version = 1 (oder max+1, wenn du willst – hier 1 für sauberen Import)
  const header = await prisma.lVHeader.create({
    data: {
      projectId: project.id,
      title: "LV aus lv.json",
      version: 1,
      currency: "EUR",
    },
  });

  console.log("🆕 LVHeader angelegt:", header.id);

  const data: Prisma.LVPositionCreateManyInput[] = rows.map((r, idx) => {
    const mengeVal = r.soll ?? 0;
    const epVal = r.ep ?? 0;
    const gesamtVal = mengeVal * epVal;

    return {
      lvId: header.id,
      position: r.pos || `001.${(idx + 1).toString().padStart(3, "0")}`,
      kurztext: r.text || "Position ohne Kurztext",
      langtext: r.langtext ?? null,
      einheit: r.unit || "St",
      menge: new Prisma.Decimal(mengeVal),
      einzelpreis: new Prisma.Decimal(epVal.toFixed(2)),
      gesamt: new Prisma.Decimal(gesamtVal.toFixed(2)),
      parentPos: undefined,
    };
  });

  console.log("➡️  Insert von", data.length, "LV-Positionen aus lv.json…");
  await prisma.lVPosition.createMany({ data });

  console.log("✅ Import abgeschlossen. Projekt:", project.code);
}

main()
  .catch((e) => {
    console.error("Fehler beim Import lv.json → DB:", e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

import { prisma } from "../lib/prisma";
import { filterUsableRlcPriceSources } from "../kalkulation/quality/priceSourceQualityGate";

function norm(v: any) {
  return String(v || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/[.,;:|]+$/g, "")
    .trim();
}

function normUnit(v: any) {
  const u = String(v || "").trim();
  if (u.toLowerCase() === "m2") return "m²";
  if (u.toLowerCase() === "m3") return "m³";
  return u;
}

function keyOf(r: any) {
  return [
    norm(r.shortText),
    normUnit(r.unit).toLowerCase(),
    norm(r.trade),
    norm(r.serviceType),
    norm(r.constructionMethod),
    norm(r.soilClass),
  ].join("||");
}

function median(values: number[]) {
  if (!values.length) return 0;
  const sorted = [...values].sort((a, b) => a - b);
  const mid = Math.floor(sorted.length / 2);
  return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
}

function round2(v: number) {
  return Math.round((v + Number.EPSILON) * 100) / 100;
}

function plausibleRange(unit: string) {
  const u = normUnit(unit);
  if (u === "m") return { min: 0.5, max: 1500 };
  if (u === "m²") return { min: 0.5, max: 1500 };
  if (u === "m³") return { min: 1, max: 2500 };
  if (u === "h") return { min: 20, max: 350 };
  if (u === "St") return { min: 1, max: 25000 };
  if (u === "Psch") return { min: 1, max: 100000 };
  return { min: 0.5, max: 50000 };
}

function qualityConfidence(args: {
  prices: number[];
  companyCount: number;
  unit: string;
}) {
  const { prices, companyCount, unit } = args;
  const avg = prices.reduce((a, b) => a + b, 0) / prices.length;
  const max = Math.max(...prices);
  const min = Math.min(...prices);
  const range = plausibleRange(unit);

  let confidence = 0.55;

  confidence += Math.min(prices.length, 10) * 0.03;
  confidence += Math.min(companyCount, 5) * 0.04;

  if (prices.length < 2) confidence -= 0.12;
  if (companyCount < 2) confidence -= 0.08;
  if (avg < range.min) confidence -= 0.25;
  if (max > range.max) confidence -= 0.25;
  if (min <= 0) confidence -= 0.3;

  return Math.max(0.2, Math.min(0.95, round2(confidence)));
}

async function main() {
  await prisma.rlcGlobalPriceKnowledge.deleteMany();

  const rowsRaw = await prisma.kalkulationsDbEntry.findMany({
    where: {
      unitPriceNet: { gt: 0 },
      shortText: { not: "" },
    },
    orderBy: { updatedAt: "desc" },
  });

  const rows = filterUsableRlcPriceSources(rowsRaw);

  const groups = new Map<string, any[]>();

  for (const r of rows) {
    const key = keyOf(r);
    if (!key || key.startsWith("||")) continue;
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key)!.push(r);
  }

  let created = 0;

  for (const [normalizedKey, g] of groups.entries()) {
    const prices = g
      .map((x) => Number(x.unitPriceNet || 0))
      .filter((x) => Number.isFinite(x) && x > 0);

    if (!prices.length) continue;

    const newest = g[0];
    const companies = new Set(g.map((x) => x.companyId).filter(Boolean));
    const minPrice = Math.min(...prices);
    const maxPrice = Math.max(...prices);
    const avgPrice = prices.reduce((a, b) => a + b, 0) / prices.length;
    const medianPrice = median(prices);
    const unit = normUnit(newest.unit);

    await prisma.rlcGlobalPriceKnowledge.create({
      data: {
        normalizedKey,
        positionNumber: newest.positionNumber || null,
        shortText: newest.shortText || "",
        unit,
        trade: newest.trade || null,
        serviceType: newest.serviceType || null,
        constructionMethod: newest.constructionMethod || null,
        soilClass: newest.soilClass || null,
        minPrice: round2(minPrice),
        avgPrice: round2(avgPrice),
        maxPrice: round2(maxPrice),
        medianPrice: round2(medianPrice),
        sampleCount: prices.length,
        sourceCompanyCount: companies.size,
        country: "DE",
        priceYear: new Date().getFullYear(),
        confidence: qualityConfidence({
          prices,
          companyCount: companies.size,
          unit,
        }),
        firstSeenAt: new Date(),
        lastSeenAt: new Date(),
      },
    });

    created++;
  }

  console.log("SOURCE_ROWS_WITH_PRICE:", rows.length);
  console.log("GLOBAL_GROUPS_CREATED:", created);
  console.log("GLOBAL_TOTAL:", await prisma.rlcGlobalPriceKnowledge.count());
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

