  const mode = getRlcAiMode();
  if (mode === "LOCAL") return !!ollamaBaseUrl();

return result;
  } catch (localError) {
    runtimeState.lastError = `OpenAI: ${safeError(primaryError)} | Ollama: ${safeError(
