export function isRlcAiTextConfigured(): boolean {
  const mode = getRlcAiMode();
  if (mode === "LOCAL") return !!ollamaBaseUrl();
  if (mode === "OPENAI") return !!clean(process.env.OPENAI_API_KEY);
