export function getRlcAiRuntimeStatus() {
  const mode = getRlcAiMode();
  return {
    mode,
    openai: {
      configured: !!clean(process.env.OPENAI_API_KEY),
      model: getOpenAiModel("generic"),
      supportModel: getOpenAiModel("copilot"),
