}

export async function checkOllamaHealth(timeoutMs = 5_000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${ollamaBaseUrl()}/api/tags`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      return { ok: false, status: response.status, models: [] as string[] };
    }
    const payload: any = await response.json();
    const models = Array.isArray(payload?.models)
      ? payload.models
          .map((item: any) => clean(item?.name || item?.model))
          .filter(Boolean)
      : [];
    const expected = getOllamaModel("generic");
    return {
      ok: true,
      expectedModel: expected,
      modelInstalled: models.some(
        (name: string) => name === expected || name.startsWith(`${expected}:`)
      ),
      models,
    };
  } catch (error) {
    return { ok: false, error: safeError(error), models: [] as string[] };
  } finally {
    clearTimeout(timer);
  }
}

import fs from "fs";
import os from "os";
import path from "path";
import { spawnSync } from "child_process";

export type PreparedCadImport = {
  originalName: string;
  effectiveName: string;
  buffer: Buffer;
  converted: boolean;
  converter?: string;
  temporaryDirectory?: string;
};

function isBinaryDxf(buffer: Buffer) {
  return buffer.subarray(0, 22).toString("latin1").startsWith("AutoCAD Binary DXF");
}

function quoteShell(value: string) {
  return `'${value.replace(/'/g, `'"'"'`)}'`;
}

function runTemplate(commandTemplate: string, input: string, output: string) {
  const command = commandTemplate
    .replace(/\{input\}/g, quoteShell(input))
    .replace(/\{output\}/g, quoteShell(output));
  const result = spawnSync("/bin/sh", ["-lc", command], {
    encoding: "utf8",
    timeout: 180000,
    maxBuffer: 8 * 1024 * 1024,
  });
  return {
    ok: result.status === 0 && fs.existsSync(output) && fs.statSync(output).size > 0,
    detail: String(result.stderr || result.stdout || "").trim(),
  };
}

function tryDwg2Dxf(input: string, output: string) {
  const executable = String(process.env.DWG2DXF_BIN || "dwg2dxf").trim();
  const result = spawnSync(executable, ["-o", output, input], {
    encoding: "utf8",
    timeout: 180000,
    maxBuffer: 8 * 1024 * 1024,
  });
  return {
    ok: result.status === 0 && fs.existsSync(output) && fs.statSync(output).size > 0,
    detail: String(result.stderr || result.stdout || "").trim(),
    executable,
  };
}

function findGeneratedDxf(directory: string) {
  try {
    return fs
      .readdirSync(directory)
      .filter((name) => path.extname(name).toLowerCase() === ".dxf")
      .map((name) => path.join(directory, name))
      .find((file) => fs.statSync(file).size > 0) || null;
  } catch {
    return null;
  }
}

function tryOda(input: string, output: string, tempDirectory: string) {
  const executable = String(
    process.env.ODA_FILE_CONVERTER || process.env.ODA_CONVERTER_BIN || "ODAFileConverter"
  ).trim();
  const inputDirectory = path.join(tempDirectory, "oda-input");
  const outputDirectory = path.join(tempDirectory, "oda-output");
  fs.mkdirSync(inputDirectory, { recursive: true });
  fs.mkdirSync(outputDirectory, { recursive: true });
  const copiedInput = path.join(inputDirectory, path.basename(input));
  fs.copyFileSync(input, copiedInput);

  const result = spawnSync(
    executable,
    [inputDirectory, outputDirectory, "ACAD2018", "DXF", "0", "1"],
    {
      encoding: "utf8",
      timeout: 240000,
      maxBuffer: 8 * 1024 * 1024,
    }
  );
  const generated = findGeneratedDxf(outputDirectory);
  if (result.status === 0 && generated) {
    fs.copyFileSync(generated, output);
  }
  return {
    ok: result.status === 0 && fs.existsSync(output) && fs.statSync(output).size > 0,
    detail: String(result.stderr || result.stdout || "").trim(),
    executable,
  };
}

export function prepareCadImportBuffer(
  originalName: string,
  sourceBuffer: Buffer
): PreparedCadImport {
  const extension = path.extname(originalName).toLowerCase();
  const mustConvert = extension === ".dwg" || (extension === ".dxf" && isBinaryDxf(sourceBuffer));
  if (!mustConvert) {
    return {
      originalName,
      effectiveName: originalName,
      buffer: sourceBuffer,
      converted: false,
    };
  }

  const tempDirectory = fs.mkdtempSync(path.join(os.tmpdir(), "rlc-cad-convert-"));
  const inputPath = path.join(tempDirectory, path.basename(originalName));
  const outputPath = path.join(
    tempDirectory,
    `${path.basename(originalName, extension) || "drawing"}.dxf`
  );
  fs.writeFileSync(inputPath, sourceBuffer);

  const errors: string[] = [];
  const template = String(process.env.RLC_CAD_CONVERTER_COMMAND || "").trim();
  if (template) {
    const result = runTemplate(template, inputPath, outputPath);
    if (result.ok) {
      return {
        originalName,
        effectiveName: path.basename(outputPath),
        buffer: fs.readFileSync(outputPath),
        converted: true,
        converter: "RLC_CAD_CONVERTER_COMMAND",
        temporaryDirectory: tempDirectory,
      };
    }
    errors.push(`RLC_CAD_CONVERTER_COMMAND: ${result.detail || "fehlgeschlagen"}`);
  }

  const dwg2dxf = tryDwg2Dxf(inputPath, outputPath);
  if (dwg2dxf.ok) {
    return {
      originalName,
      effectiveName: path.basename(outputPath),
      buffer: fs.readFileSync(outputPath),
      converted: true,
      converter: dwg2dxf.executable,
      temporaryDirectory: tempDirectory,
    };
  }
  errors.push(`${dwg2dxf.executable}: ${dwg2dxf.detail || "nicht verfügbar/fehlgeschlagen"}`);

  const oda = tryOda(inputPath, outputPath, tempDirectory);
  if (oda.ok) {
    return {
      originalName,
      effectiveName: path.basename(outputPath),
      buffer: fs.readFileSync(outputPath),
      converted: true,
      converter: oda.executable,
      temporaryDirectory: tempDirectory,
    };
  }
  errors.push(`${oda.executable}: ${oda.detail || "nicht verfügbar/fehlgeschlagen"}`);

  throw new Error(
    `${extension === ".dwg" ? "DWG" : "Binäres DXF"} konnte nicht in ASCII-DXF konvertiert werden. ` +
      `Installiere dwg2dxf/ODA File Converter oder setze RLC_CAD_CONVERTER_COMMAND. ` +
      errors.join(" | ")
  );
}

export function cleanupPreparedCadImport(prepared: PreparedCadImport) {
  if (!prepared.temporaryDirectory) return;
  try {
    fs.rmSync(prepared.temporaryDirectory, { recursive: true, force: true });
  } catch {

throw new Error(
    `${extension === ".dwg" ? "DWG" : "Binäres DXF"} konnte nicht in ASCII-DXF konvertiert werden. ` +
      `Installiere dwg2dxf/ODA File Converter oder setze RLC_CAD_CONVERTER_COMMAND. ` +
      errors.join(" | ")
  );
}

export function cleanupPreparedCadImport(prepared: PreparedCadImport) {
  if (!prepared.temporaryDirectory) return;
  try {
    fs.rmSync(prepared.temporaryDirectory, { recursive: true, force: true });
  } catch {
    // Temporäre Dateien werden vom Betriebssystem später entfernt.
  }
}

import fs from "fs";
import path from "path";
import { spawn } from "child_process";

export type CadImportPaths = {
  projectRoot: string;
  cadDir: string;
  utmCsvPath: string;
  takeoffJsonPath: string;
  snapshotPngPath: string; // ✅ NEW
};

export type TakeoffPayload = {
  ok?: boolean;
  message?: string;

  // Formati "vecchi" o generici
  features?: any[];
  points?: any[];
  data?: any;

  // ✅ RLC Takeoff v2 (plugin attuale)
  type?: string; // "rlc_takeoff_v2"
  rows?: any[];

  // ✅ formato normalizzato (sempre presente se ok=true)
  normalized?: {
    version: string;
    sourceType?: string;
    features: any[];
    points: any[];
  };
};

function exists(p: string) {
  try {
    return fs.existsSync(p);
  } catch {
    return false;
  }
}

function readText(p: string) {
  return fs.readFileSync(p, "utf8");
}

/**
 * Rende il testo più "parseable" su Windows/plugin:
 * - rimuove BOM
 * - rimuove null bytes
 * - trim
 */
function sanitizeJsonText(raw: string) {
  if (!raw) return "";
  let s = raw;

  // BOM (UTF-8)
  if (s.charCodeAt(0) === 0xfeff) s = s.slice(1);

  // null bytes
  s = s.replace(/\u0000/g, "");

  return s.trim();
}

/**
 * Parse robusto:
 * 1) prova parse diretto
 * 2) se fallisce, prova a estrarre il JSON tra prima "{" e ultima "}"
 *    (utile se il file contiene log/garbage attorno)
 */
function robustJsonParse<T>(
  raw: string
): { ok: boolean; value?: T; error?: string } {
  const s0 = sanitizeJsonText(raw);
  if (!s0) return { ok: false, error: "Empty file." };

  try {
    return { ok: true, value: JSON.parse(s0) as T };
  } catch (e1: any) {
    // tenta estrazione tra { ... }
    const first = s0.indexOf("{");
    const last = s0.lastIndexOf("}");
    if (first >= 0 && last > first) {
      const sliced = s0.slice(first, last + 1);
      try {
        return { ok: true, value: JSON.parse(sliced) as T };
      } catch (e2: any) {
        return {
          ok: false,
          error:
            `JSON.parse failed (direct + sliced). ` +
            `DirectError: ${String(e1?.message || e1)} ` +
            `SlicedError: ${String(e2?.message || e2)}`,
        };
      }
    }

    return { ok: false, error: `JSON.parse failed. ${String(e1?.message || e1)}` };
  }
}

export function getProjectsRoot() {
  return process.env.PROJECTS_ROOT || path.join(process.cwd(), "data", "projects");
}

export function getCadImportPaths(projectId: string): CadImportPaths {
  const PROJECTS_ROOT = getProjectsRoot();
  const projectRoot = path.join(PROJECTS_ROOT, projectId);
  const cadDir = path.join(projectRoot, "cad");

  return {
    projectRoot,
    cadDir,
    utmCsvPath: path.join(cadDir, "utm.csv"),
    takeoffJsonPath: path.join(cadDir, "takeoff.json"),
    snapshotPngPath: path.join(cadDir, "snapshot.png"), // ✅ NEW
  };
}

export function readUtmCsv(projectId: string): {
  ok: boolean;
  message?: string;
  csv?: string;
  paths: CadImportPaths;
} {
  const paths = getCadImportPaths(projectId);

  if (!exists(paths.utmCsvPath)) {
    return {
      ok: false,
      message:
        `utm.csv nicht gefunden.\n` +
        `Erwarteter Pfad:\n${paths.utmCsvPath}\n\n` +
        `Hinweis: Plugin muss die Datei unter data/projects/<projectId>/cad/utm.csv schreiben.`,
      paths,
    };
  }

  const csv = readText(paths.utmCsvPath);
  if (!csv.trim()) {
    return { ok: false, message: "utm.csv ist leer.", paths };
  }

  return { ok: true, csv, paths };
}

function normalizeTakeoff(payload: any): {
  ok: boolean;
  message?: string;
  normalized: TakeoffPayload["normalized"];
} {
  const empty = {
    version: "normalized_v1",
    sourceType: typeof payload?.type === "string" ? payload.type : "unknown",
    features: [] as any[],
    points: [] as any[],
  };

  // ✅ Case A: RLC Takeoff v2
  const type = String(payload?.type || "");
  const rows = Array.isArray(payload?.rows) ? payload.rows : null;

  if (type === "rlc_takeoff_v2" && rows) {
    const features = rows
      .map((r: any, idx: number) => {
        const handle = String(r?.handle || "").trim();
        const layer = String(r?.layer || "").trim();
        const entityType = String(r?.entityType || "").trim();
        const lvPos = String(r?.lvPos || "").trim();
        const lvText = String(r?.lvText || "").trim();

        const length = Number(r?.length);
        const area = Number(r?.area);

        const id = handle ? `H_${handle}` : `ROW_${idx + 1}`;

        const kind =
          entityType.toLowerCase().includes("polyline")
            ? "polyline"
            : entityType.toLowerCase().includes("line")
            ? "line"
            : entityType.toLowerCase().includes("arc")
            ? "line"
            : "polyline";

        const safeLength = Number.isFinite(length) ? length : 0;
        const safeArea = Number.isFinite(area) ? area : 0;

        return {
          id,
          kind,
          layer: layer || undefined,
          name: lvText || undefined,
          length: safeLength,
          area: safeArea,

          // Non abbiamo i vertici: viewer può usare lista/preview quantitativa
          pts: [],
          closed: false,

          meta: {
            source: "rlc_takeoff_v2",
            entityType,
            handle,
            lvPos,
            lvText,
          },
        };
      })
      .filter((f: any) => f && f.id);

    if (!features.length) {
      return {
        ok: false,
        message:

handle,
            lvPos,
            lvText,
          },
        };
      })
      .filter((f: any) => f && f.id);

    if (!features.length) {
      return {
        ok: false,
        message:
          "rlc_takeoff_v2 erkannt, aber rows enthält keine verwertbaren Einträge.",
        normalized: empty,
      };
    }

    return {
      ok: true,
      normalized: { ...empty, sourceType: "rlc_takeoff_v2", features, points: [] },
    };
  }

  // Case B: features/points standard
  const features =
    Array.isArray(payload?.features)
      ? payload.features
      : Array.isArray(payload?.data?.features)
      ? payload.data.features
      : [];

  const points =
    Array.isArray(payload?.points)
      ? payload.points
      : Array.isArray(payload?.data?.points)
      ? payload.data.points
      : [];

  if (features.length || points.length) {
    return {
      ok: true,
      normalized: { ...empty, sourceType: "features_points", features, points },
    };
  }

  return {
    ok: false,
    message:
      "takeoff.json enthält keine 'features' oder 'points' und ist auch nicht 'rlc_takeoff_v2'.\n" +
      "Erwartet: { features:[...] } oder { data:{ features:[...] } } oder { type:'rlc_takeoff_v2', rows:[...] }.",
    normalized: empty,
  };
}

export function readTakeoff(projectId: string): {
  ok: boolean;
  message?: string;
  payload?: TakeoffPayload;
  paths: CadImportPaths;
} {
  const paths = getCadImportPaths(projectId);

  if (!exists(paths.takeoffJsonPath)) {
    return {
      ok: false,
      message:
        `takeoff.json nicht gefunden.\n` +
        `Erwarteter Pfad:\n${paths.takeoffJsonPath}\n\n` +
        `Hinweis: Plugin muss die Datei unter data/projects/<projectId>/cad/takeoff.json schreiben.`,
      paths,
    };
  }

  const raw = readText(paths.takeoffJsonPath);

  const parsed = robustJsonParse<any>(raw);
  if (!parsed.ok || !parsed.value || typeof parsed.value !== "object") {
    const s = sanitizeJsonText(raw);
    const head = s.slice(0, 200);
    const tail = s.slice(Math.max(0, s.length - 200));

    return {
      ok: false,
      message:
        "takeoff.json ist kein gültiges JSON-Objekt.\n" +
        (parsed.error ? `Parse-Fehler: ${parsed.error}\n\n` : "\n") +
        `Debug (Head 200): ${head}\n\nDebug (Tail 200): ${tail}`,
      paths,
    };
  }

  const norm = normalizeTakeoff(parsed.value);

  const outPayload: TakeoffPayload = {
    ...(parsed.value as any),
    normalized: norm.normalized,
  };

  if (!norm.ok) {
    return { ok: false, message: norm.message, payload: outPayload, paths };
  }

  return { ok: true, payload: outPayload, paths };
}

