/* ============================================================
   ✅ RLC CAD öffnen (Windows) — robust
   ============================================================ */

function isWindows() {
  return process.platform === "win32";
}

function sanitizeProjectId(input: string) {
  const v = String(input || "").trim();
  return v.replace(/[^a-zA-Z0-9._-]/g, "");
}

function assertProjectDirExists(projectIdRaw: string) {
  const projectId = sanitizeProjectId(projectIdRaw);
  if (!projectId) throw new Error("projectId fehlt.");

  const projectRoot = path.join(getProjectsRoot(), projectId);
  if (!exists(projectRoot)) {
    throw new Error(`Projektordner existiert nicht: ${projectRoot}`);
  }

  return { projectId, projectRoot };
}

function findFirstDwg(projectRoot: string): string | null {
  const candidates = [
    path.join(projectRoot, "cad", "current.dwg"),
    path.join(projectRoot, "cad", "plan.dwg"),
    path.join(projectRoot, "cad", "current.dwg"),
    path.join(projectRoot, "cad", "plan.dwg"),
    path.join(projectRoot, "current.dwg"),
    path.join(projectRoot, "plan.dwg"),
  ];

  for (const c of candidates) {
    if (exists(c)) return c;
  }

  const maxDepth = 3;

  const walk = (dir: string, depth: number): string | null => {
    if (depth > maxDepth) return null;
    let entries: fs.Dirent[];
    try {
      entries = fs.readdirSync(dir, { withFileTypes: true });
    } catch {
      return null;
    }

    for (const e of entries) {
      const full = path.join(dir, e.name);
      if (e.isDirectory()) {
        const r = walk(full, depth + 1);
        if (r) return r;
      } else if (e.isFile() && path.extname(e.name).toLowerCase() === ".dwg") {
        return full;
      }
    }
    return null;
  };

  return walk(projectRoot, 0);
}

export function openCadImport(projectIdRaw: string): {
  ok: boolean;
  projectId: string;
  projectRoot: string;
  exe: string;
  openedFile: string | null;
  message: string;
} {
  if (!isWindows()) {
    throw new Error("RLC CAD öffnen ist aktuell nur für Windows vorgesehen.");
  }

  const { projectId, projectRoot } = assertProjectDirExists(projectIdRaw);

projectId: string;
  projectRoot: string;
  exe: string;
  openedFile: string | null;
  message: string;
} {
  if (!isWindows()) {
    throw new Error("RLC CAD öffnen ist aktuell nur für Windows vorgesehen.");
  }

  const { projectId, projectRoot } = assertProjectDirExists(projectIdRaw);

  const exe =
    (process.env.RLC_CAD_EXE || "").trim() ||
    "C:\\Programme\\Bricsys\\RLC CAD V24 de_DE\\bricscad.exe";

  if (!exists(exe)) {
    throw new Error(
      `RLC CAD EXE nicht gefunden.\n` +
        `Setze RLC_CAD_EXE in apps/server/.env\n` +
        `Aktuell: ${exe}`
    );
  }

  const dwg = findFirstDwg(projectRoot);

  const args = ["/c", "start", '""', exe, ...(dwg ? [dwg] : [])];

  const child = spawn("cmd.exe", args, {
    cwd: projectRoot,
    detached: true,
    stdio: "ignore",
    windowsHide: false,
  });

  child.unref();

  return {
    ok: true,
    projectId,
    projectRoot,
    exe,
    openedFile: dwg,
    message: dwg
      ? `RLC CAD gestartet mit DWG: ${path.basename(dwg)}`
      : "RLC CAD gestartet (kein DWG gefunden, nur App geöffnet).",
  };
}

