    }), "utf8");
    generatedPaths.push(xmlPath);
  }

  if (requested.has("csv")) {
    const csvPath = path.join(outputDir, `${baseName}.csv`);
    fs.writeFileSync(csvPath, buildCsv(input.data ?? {}), "utf8");
    generatedPaths.push(csvPath);
  }

  if (requested.has("xlsx")) {
    const xlsxPath = path.join(outputDir, `${baseName}.xlsx`);
    await writeWorkbook(xlsxPath, { ...input, projectId, moduleKey });
    generatedPaths.push(xlsxPath);
  }

  if (requested.has("pdf")) {
    const requestedPdfName = String(
      input.pdfFileName || `${baseName}.pdf`
    ).replace(/[\\/:*?"<>|]+/g, "_");

    const pdfFileName = requestedPdfName.toLowerCase().endsWith(".pdf")
      ? requestedPdfName
      : `${requestedPdfName}.pdf`;

    const pdfPath = path.join(outputDir, pdfFileName);

    const inlinePdfBase64 = String(input.pdfBase64 || "")
      .replace(/^data:application\/pdf[^,]*,/, "")
      .replace(/\s+/g, "");

    let written = false;

    /*
     * Priorità assoluta al renderer specialistico del server.
     * Il PDF locale/mobile rimane soltanto fallback.
     */
    written = await writeSpecializedModulePdf(pdfPath, {
      ...input,
      projectId,
      moduleKey,
    });


    if (inlinePdfBase64) {
      const pdfBuffer = Buffer.from(inlinePdfBase64, "base64");

      if (
        pdfBuffer.length < 5 ||
        pdfBuffer.subarray(0, 5).toString("ascii") !== "%PDF-"
      ) {
        throw new Error("Ung?ltige PDF-Daten vom Fachmodul.");
      }

      fs.writeFileSync(pdfPath, pdfBuffer);
      written = true;
    }

    if (!written && input.pdfUrl) {
      written = copyExistingPdf(projectId, input.pdfUrl, pdfPath);
    }

    if (!written && moduleKey === "aufmass") {
      throw new Error(
        "Aufma?-PDF fehlt: Das Fachmodul hat keine PDF-Daten geliefert."
      );
    }

    /*
     * Nur echter Fallback:
     * Der generische Renderer darf niemals ein vorhandenes Fachlayout ersetzen.
     */
    if (!written) {
      await writeGenericPdf(pdfPath, {
        ...input,
        projectId,
        moduleKey,
      });
      written = true;
    }

    generatedPaths.push(pdfPath);
  }

  const attachmentDir = path.join(outputDir, "Anlagen");
  const copiedAttachments: string[] = [];
  for (const attachment of input.attachments || []) {
    const resolved = resolveProjectAttachment(projectId, attachment);
    if (!resolved) continue;
    fs.mkdirSync(attachmentDir, { recursive: true });
    let target = path.join(attachmentDir, safeKey(resolved.name, "Anhang"));
    const ext = resolved.sourcePath ? path.extname(resolved.sourcePath) : "";
    if (ext && !path.extname(target)) target += ext;
    let suffix = 1;
    const base = target;
    while (fs.existsSync(target)) {
      const parsed = path.parse(base);
      target = path.join(parsed.dir, `${parsed.name}_${suffix++}${parsed.ext}`);
    }
    if (resolved.sourcePath) fs.copyFileSync(resolved.sourcePath, target);
    else if (resolved.buffer) fs.writeFileSync(target, resolved.buffer);
    copiedAttachments.push(target);
  }

  const preliminaryFiles = [...generatedPaths, ...copiedAttachments].map((filePath) => describeFile(projectId, filePath));
  const manifest = {
    schema: "RLC-DOCUMENT-DELIVERY-1.0",
    exportId,
    projectId,
    projectName: input.projectName || "",
    moduleKey,
    moduleLabel: moduleLabel(moduleKey),
    documentId: input.documentId || "",
    title: input.title || moduleLabel(moduleKey),
    date: input.date || "",
    confidential: Boolean(input.confidential),
    exportedAt: nowIso(),
    createdBy: input.createdBy || "",
    files: preliminaryFiles.map(({ name, url, mime, size, sha256 }) => ({ name, url, mime, size, sha256 })),
    specialistFormats: moduleKey.includes("kalkulation") || moduleKey === "angebot" || moduleKey === "gaeb"
      ? ["GAEB X83/X84/X86/X89 via Fachmodul"]
      : moduleKey === "aufmass"
        ? ["REB X31", "DA11 via Fachmodul"]
        : moduleKey === "cad"
          ? ["DWG", "DXF", "IFC", "BCF", "LandXML via Fachmodul"]
          : [],
  };

  const manifestPath = path.join(outputDir, "manifest.json");
  fs.writeFileSync(manifestPath, JSON.stringify(manifest, null, 2), "utf8");
  const manifestFile = describeFile(projectId, manifestPath);

  const zip = new AdmZip();
  for (const filePath of generatedPaths) zip.addLocalFile(filePath);
  if (fs.existsSync(attachmentDir)) zip.addLocalFolder(attachmentDir, "Anlagen");
  zip.addLocalFile(manifestPath);
  const packagePath = path.join(outputDir, `${baseName}_Exportpaket.zip`);
  zip.writeZip(packagePath);
  const packageFile = describeFile(projectId, packagePath);

  let encryptedPackageFile: DeliveryFile | undefined;
  const password = String(input.encryptionPassword || "");
  if (input.confidential && password.length < 8) {
    throw new Error("Vertrauliche Exporte benötigen ein Passwort mit mindestens 8 Zeichen.");
  }
  if (input.confidential) {
    const encryptedPath = `${packagePath}.rlcenc`;
    encryptPackage(packagePath, encryptedPath, password);
    encryptedPackageFile = describeFile(projectId, encryptedPath);
  }

  const files = [...preliminaryFiles, manifestFile];

  appendAudit(projectId, {
    action: "EXPORT_PACKAGE",
    exportId,
    moduleKey,
    documentId: input.documentId || "",
    confidential: Boolean(input.confidential),
    encrypted: Boolean(encryptedPackageFile),
    createdBy: input.createdBy || "",

}

  const files = [...preliminaryFiles, manifestFile];

  appendAudit(projectId, {
    action: "EXPORT_PACKAGE",
    exportId,
    moduleKey,
    documentId: input.documentId || "",
    confidential: Boolean(input.confidential),
    encrypted: Boolean(encryptedPackageFile),
    createdBy: input.createdBy || "",
    files: files.map((file) => ({ name: file.name, sha256: file.sha256 })),
  });

  return {
    exportId,
    projectId,
    moduleKey,
    outputDir,
    files,
    packageFile,
    encryptedPackageFile,
    manifestFile,
  };
}

export function auditDeliveryAction(projectId: string, entry: Record<string, any>): void {
  appendAudit(safeKey(projectId, "project"), entry);
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { PROJECTS_ROOT } from "../lib/projectsRoot";
import { getRlcAiMode } from "./ai/rlcAiGateway";

export type RlcServerPairingPayload = {
  type: "RLC_SERVER_PAIRING";
  version: 1;
  serverId: string;
  serverName: string;
  companyCode?: string;
  apiUrl: string;
  issuedAt: number;
  expiresAt: number;
  nonce: string;
};

function clean(value: unknown): string {
  return String(value ?? "").trim();
}

function configDir(): string {
  return (
    clean(process.env.RLC_CONFIG_DIR) || path.join(path.dirname(PROJECTS_ROOT), "config")
  );
}

function readOrCreatePrivateValue(
  envName: string,
  fileName: string,
  bytes: number,
  prefix = ""
): string {
  const fromEnv = clean(process.env[envName]);
  if (fromEnv) return fromEnv;

  const dir = configDir();
  const file = path.join(dir, fileName);
  try {
    const existing = clean(fs.readFileSync(file, "utf8"));
    if (existing) return existing;
  } catch {}

  fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
  const value = `${prefix}${crypto.randomBytes(bytes).toString("hex")}`;
  fs.writeFileSync(file, `${value}\n`, { encoding: "utf8", mode: 0o600 });
  return value;
}

export function getRlcServerId(): string {
  return readOrCreatePrivateValue("RLC_SERVER_ID", "server-id", 16, "rlc-");
}

function getPairingSecret(): string {
  return readOrCreatePrivateValue("RLC_PAIRING_SECRET", "pairing-secret", 32);
}

function normalizeApiUrl(input: string): string {
  const value = clean(input).replace(/\/$/, "");
  if (!value) throw new Error("RLC_PUBLIC_API_URL fehlt");

  let parsed: URL;
  try {
    parsed = new URL(value);
  } catch {
    throw new Error("RLC_PUBLIC_API_URL ist ungültig");
  }

  const local = ["localhost", "127.0.0.1", "::1"].includes(parsed.hostname);
  const allowInsecure = clean(process.env.RLC_ALLOW_INSECURE_PAIRING).toLowerCase() === "on";
  if (parsed.protocol !== "https:" && !local && !allowInsecure) {
    throw new Error("Private Server benötigen HTTPS für das Mobile-Pairing");
  }

  return parsed.toString().replace(/\/$/, "");
}

export function getRlcServerIdentity() {
  const apiUrl = normalizeApiUrl(
    clean(process.env.RLC_PUBLIC_API_URL) || clean(process.env.API_PUBLIC_URL)
  );
  return {
    type: "RLC_SERVER_IDENTITY" as const,
    version: 1 as const,
    serverId: getRlcServerId(),
    serverName: clean(process.env.RLC_SERVER_NAME) || "RLC Private Server",
    companyCode: clean(process.env.RLC_COMPANY_CODE) || undefined,
    apiUrl,
    aiMode: getRlcAiMode(),
    capabilities: [
      "MOBILE_SYNC",
      "WEB",
      "RLC_COPILOT",
      "CONSTRUCTION_INTELLIGENCE_V2",
      "LOCAL_AI_FALLBACK",
    ],
  };
}

function b64url(value: string | Buffer): string {
  return Buffer.from(value).toString("base64url");
}

function sign(encodedPayload: string): string {
  return crypto
    .createHmac("sha256", getPairingSecret())
    .update(encodedPayload)
    .digest("base64url");
}

export function createRlcServerPairing(expiresInSeconds = 10 * 60) {
  const identity = getRlcServerIdentity();
  const now = Date.now();
  const ttl = Math.max(60, Math.min(60 * 60, Math.floor(expiresInSeconds)));
  const payload: RlcServerPairingPayload = {
    type: "RLC_SERVER_PAIRING",
    version: 1,
    serverId: identity.serverId,
    serverName: identity.serverName,
    companyCode: identity.companyCode,
    apiUrl: identity.apiUrl,
    issuedAt: now,
    expiresAt: now + ttl * 1000,
    nonce: crypto.randomBytes(12).toString("hex"),
  };

  const encoded = b64url(JSON.stringify(payload));
  const token = `${encoded}.${sign(encoded)}`;
  const qrValue = JSON.stringify({
    type: "RLC_SERVER_PAIRING",
    version: 1,
    apiUrl: payload.apiUrl,
    token,
  });

  return { payload, token, qrValue };
}

export function verifyRlcServerPairing(token: string): RlcServerPairingPayload {
  const [encoded, signature, extra] = clean(token).split(".");
  if (!encoded || !signature || extra) throw new Error("Ungültiger Pairing-Token");

  const expected = sign(encoded);
  const actualBuffer = Buffer.from(signature);
  const expectedBuffer = Buffer.from(expected);
  if (
    actualBuffer.length !== expectedBuffer.length ||
    !crypto.timingSafeEqual(actualBuffer, expectedBuffer)
  ) {
    throw new Error("Pairing-Signatur ungültig");
  }

  let payload: RlcServerPairingPayload;
  try {
    payload = JSON.parse(Buffer.from(encoded, "base64url").toString("utf8"));
  } catch {
    throw new Error("Pairing-Daten ungültig");
  }

  if (payload?.type !== "RLC_SERVER_PAIRING" || payload?.version !== 1) {
    throw new Error("Pairing-Version nicht unterstützt");
  }
  if (payload.serverId !== getRlcServerId()) {
    throw new Error("Pairing gehört zu einem anderen Server");
  }
  if (payload.expiresAt <= Date.now()) throw new Error("Pairing-QR ist abgelaufen");

  const current = getRlcServerIdentity();
  if (payload.apiUrl !== current.apiUrl) {
    throw new Error("Server-URL wurde seit Erstellung des QR geändert");
  }

  return payload;
}

