export function parseLieferschein(
  ocrResults: Array<{ file: string; text: string }>
): Array<{
  lieferant?: string;
  datum?: string;
  material?: string;
  menge?: number;
  einheit?: string;
  preis?: number;
  kostenstelle?: string;
}> {
  const out: any[] = [];
  for (const r of ocrResults) {
    const t = r.text;
    if (/Lieferschein/i.test(t)) {
      const lieferant = (t.match(/Firma\s+([^\n]+)/i) || [,"Muster GmbH"])[1];
      const material = (t.match(/Material:\s*([^\n]+)/i) || [,"Material"])[1];
      const mengeStr = (t.match(/Menge:\s*([0-9.,]+)/i) || [,"0"])[1];
      const menge = Number(mengeStr.replace(",", "."));
      const einheit = /t\b/i.test(t) ? "t" : "stk";
      const datum = (t.match(/Datum:\s*([0-9\-./]+)/i) || [,""])[1];
      const kostenstelle = (t.match(/Kostenstelle:\s*([^\n]+)/i) || [,""])[1];
      out.push({ lieferant, datum, material, menge, einheit, preis: undefined, kostenstelle });
    }
  }
  return out;
}

export function matchLVPositions(
  ocrResults: Array<{ file: string; text: string }>
): Array<{ position?: string; kurztext?: string; einheit?: string; menge?: number; kommentar?: string }> {
  const out: any[] = [];
  for (const r of ocrResults) {
    const t = r.text.toLowerCase();
    if (t.includes("graben")) {
      const m = t.match(/(\d+(?:[.,]\d+)?)\s*m/);
      out.push({
        position: "ERD-1001",
        kurztext: "Graben herstellen",
        einheit: "m",
        menge: m ? Number(m[1].replace(",", ".")) : 1,
        kommentar: "aus Foto/OCR",
      });
    }
    if (t.includes("speedpipe")) {
      out.push({
        position: "LTG-2040",
        kurztext: "Speedpipe DN40 verlegen",
        einheit: "m",
        menge: 10,
        kommentar: "Schätzung KI",
      });
    }
  }
  return out;
}

// apps/server/src/services/mailer.ts
import type { SentMessageInfo } from "nodemailer";
import { sendMailLogged } from "../lib/mailer";

type MailAttachment = { filename: string; path: string };

export type MailResult =
  | {
      ok: true;
      skipped?: true;
      messageId?: string;
      accepted?: any;
      rejected?: any;
      response?: string;
    }
  | { ok: false; error: string };

function env(name: string) {
  return String(process.env[name] || "").trim();
}

function isDev() {
  return (process.env.NODE_ENV || "").toLowerCase() !== "production";
}

function disabled() {
  return env("DISABLE_EMAIL") === "1";
}

/**
 * ✅ Single source of truth:
 * - Invio reale delegato a lib/mailer.ts (transport + logging)
 * - Qui solo wrapper + tipo risultato
 */
export async function verifyMailerOnce() {
  // opzionale: se vuoi, puoi chiamare verifyMailerOnce del lib
  // ma non è obbligatorio; teniamo "no-crash"
  if (disabled()) {
    console.log("[MAIL] DISABLE_EMAIL=1 -> verify skipped");
    return;
  }
  try {
    // import lazy per evitare circular/edge cases
    const { verifyMailerOnce: verifyCore } = await import("../lib/mailer");
    await verifyCore();
  } catch (e: any) {
    console.error("[MAIL] verify FAILED:", String(e?.message || e));
    throw e;
  }
}

export async function sendMangelMail(opts: {
  to: string;
  subject: string;
  html: string;
  attachments?: MailAttachment[];
}): Promise<MailResult> {
  if (disabled()) {
    console.log("[MAIL] disabled -> skip", {
      to: opts.to,
      subject: opts.subject,
      hasAttachments: !!opts.attachments?.length,
    });
    return { ok: true, skipped: true };
  }

  try {
    // lib/mailer.ts già logga accepted/rejected/response
    const info: SentMessageInfo = await sendMailLogged({
      to: opts.to,
      subject: opts.subject,
      html: opts.html,
      // text opzionale: puoi aggiungerlo se vuoi
    });

    // In DEV ritorniamo più info utili anche al chiamante
    if (isDev()) {
      return {
        ok: true,
        messageId: (info as any)?.messageId,
        accepted: (info as any)?.accepted,
        rejected: (info as any)?.rejected,
        response: (info as any)?.response,
      };
    }

    return { ok: true, messageId: (info as any)?.messageId };
  } catch (e: any) {
    const msg = String(e?.message || e || "MAIL_SEND_FAILED");
    console.error("[MAIL] send FAILED:", msg);
    return { ok: false, error: msg };
  }
}

import {
  createRlcPdfDocument,
  drawRlcInfoField,
  drawRlcSectionTitle,
  RLC_PDF_THEME,
  type RlcPdfCompany,
} from "./rlcPdfCore";

export type CreateAufmassPdfInput = {
  pdfPath: string;
  projectId?: string;
  projectName?: string;
  title?: string;
  date?: string;
  company?: RlcPdfCompany;
  data?: any;
  payload?: any;
  document?: any;
};

function s(value: unknown): string {
  return String(value ?? "").trim();
}

function germanNumber(value: unknown): string {
  const number = Number(value ?? 0);

  return new Intl.NumberFormat("de-DE", {
    minimumFractionDigits: 0,
    maximumFractionDigits: 3,
  }).format(Number.isFinite(number) ? number : 0);
}

export async function createAufmassPdf(input: CreateAufmassPdfInput) {
  const source = input.data || input.payload || input.document || {};

  const projectId = s(
    input.projectId ||
    source.projectId ||
    source.projectKey ||
    source.project?.id ||
    source.project?.code ||
    "Projekt"
  );

  const projectName = s(
    input.projectName ||
    source.projectName ||
    source.projectTitle ||
    source.project?.name ||
    projectId
  );

  const date = s(
    input.date ||
    source.date ||
    source.datum ||
    source.options?.dateISO ||
    new Date().toISOString().slice(0, 10)
  ).slice(0, 10);

  const rows = Array.isArray(source.rows)
    ? source.rows
    : Array.isArray(source.lines)
      ? source.lines
      : Array.isArray(source.aufmass)
        ? source.aufmass
        : Array.isArray(source.entries)
          ? source.entries
          : [];

  const pdf = createRlcPdfDocument({
    pdfPath: input.pdfPath,
    title: "Aufma?blatt",
    documentType: "Aufma?",
    projectId,
    projectName,
    date,
    company: input.company || source.company,
    subject: `Aufma? ${projectId}`,
  });

  const { doc } = pdf;

  let y = pdf.startCurrentPage();

  const marginX = RLC_PDF_THEME.marginX;
  const contentWidth = doc.page.width - marginX * 2;
  const gap = 8;
  const fieldWidth = (contentWidth - gap * 3) / 4;

  drawRlcInfoField(doc, marginX, y, fieldWidth, "Projekt", projectId);

  drawRlcInfoField(
    doc,
    marginX + fieldWidth + gap,
    y,
    fieldWidth,
    "Bezeichnung",
    projectName
  );

  drawRlcInfoField(
    doc,
    marginX + (fieldWidth + gap) * 2,
    y,
    fieldWidth,
    "Ort",
    s(source.ort || source.location || source.ortName) || "?"
  );

  drawRlcInfoField(
    doc,
    marginX + (fieldWidth + gap) * 3,
    y,
    fieldWidth,
    "Zeilen",
    String(rows.length)
  );

  y += 64;
  y = drawRlcSectionTitle(doc, "Aufma?zeilen", y);

  const columns = [
    { label: "Kreis", x: 34, width: 34 },
    { label: "Blatt", x: 72, width: 38 },
    { label: "Nr.", x: 114, width: 32 },
    { label: "REB", x: 150, width: 34 },
    { label: "Pos.", x: 188, width: 54 },
    { label: "Bezeichnung / Rechenansatz", x: 246, width: 190 },
    { label: "Menge", x: 440, width: 58, align: "right" as const },
    { label: "ME", x: 502, width: 59 },
  ];

  function drawHeader() {
    if (y > pdf.contentBottom() - 44) {
      y = pdf.addPage();
    }

    doc
      .roundedRect(marginX, y, contentWidth, 24, 4)
      .fill(RLC_PDF_THEME.blueSoft);

    doc
      .font("Helvetica-Bold")
      .fontSize(8)
      .fillColor(RLC_PDF_THEME.blueDark);

    for (const column of columns) {
      doc.text(column.label, column.x, y + 8, {
        width: column.width,
        align: column.align || "left",
      });
    }

    y += 30;
  }

  drawHeader();

  for (const row of rows) {
    const description = [
      s(row.kurztext || row.bezeichnung || row.text),
      s(row.langtext),
      s(row.rechenansatz || row.formula || row.formel),
    ]
      .filter(Boolean)
      .join("\n");

    const rowHeight = Math.max(
      27,
      doc.heightOfString(description || "?", {
        width: 184,
        lineGap: 1,
      }) + 12
    );

    if (y + rowHeight > pdf.contentBottom()) {
      y = pdf.addPage();
      drawHeader();
    }

    const values = [
      s(row.kreis),
      s(row.blatt),
      s(row.nr || row.nummer),
      s(row.reb),
      s(row.posNr || row.position || row.pos),
      description || "?",
      germanNumber(
        row.ergebnis ??
        row.result ??
        row.menge ??
        row.ist
      ),
      s(row.einheit || row.unit),
    ];

    doc
      .font("Helvetica")
      .fontSize(7.5)
      .fillColor(RLC_PDF_THEME.text);

    values.forEach((value, index) => {
      const column = columns[index];

      doc.text(value || "?", column.x, y + 5, {
        width: column.width,
        align: column.align || "left",
        lineGap: 1,
      });
    });

    doc
      .strokeColor(RLC_PDF_THEME.line)
      .lineWidth(0.35)
      .moveTo(marginX, y + rowHeight)
      .lineTo(marginX + contentWidth, y + rowHeight)
      .stroke();

    y += rowHeight + 4;
  }

  await pdf.finish();

  return {
    pdfPath: input.pdfPath,
    rowCount: rows.length,
  };
}

