  drawRlcInfoField(doc, x0 + quarter + gap, y, quarter, "Zeitraum", period);
  drawRlcInfoField(
    doc,
    x0 + (quarter + gap) * 2,
    y,
    quarter,
    "Tagesberichte",
    String(reports.length),
  );
  drawRlcInfoField(
    doc,
    x0 + (quarter + gap) * 3,
    y,
    quarter,
    "Gesamtstunden",
    rlcGermanNumber(totalHours),
  );
  y += 62;

  const third = (width - gap * 2) / 3;
  drawRlcInfoField(doc, x0, y, third, "Tage", String(new Set(dates).size));
  drawRlcInfoField(
    doc,
    x0 + third + gap,
    y,
    third,
    "Vorkommnisse",
    String(issueCount),
  );
  drawRlcInfoField(
    doc,
    x0 + (third + gap) * 2,
    y,
    third,

doc,
