        .fillColor(RLC_PDF_THEME.blueDark)
        .font("Helvetica-Bold")
        .fontSize(8)
        .text(
          `${index + 1}. ${statusLabel(item.status)}`,
          x0 + 8,
          y + 8,
          {
            width: 90,
          }
        );

      doc
        .fillColor("#172033")
        .font("Helvetica")
        .fontSize(9)
        .text(
          rlcFirstText(item.text),
          x0 + 105,
          y + 8,
          {
            width: width - 113,
          }
        );

      if (item.note) {
        doc
          .fillColor(RLC_PDF_THEME.muted)
          .font("Helvetica")
          .fontSize(8)
          .text(
            `Bemerkung: ${item.note}`,
            x0 + 105,
            y + 27,
            {
              width: width - 113,
            }
          );
      }

      y += rowHeight + 6;
    }
  }

  if (input.notes) {
    y = drawRlcTextPanel(
      runtime,
      "Abschlussbemerkungen",
      input.notes,
      y,
      {
        minHeight: 70,
        maxHeight: 180,
      }
    );
  }

  if (y > pdf.contentBottom() - 180) {
    pdf.addPage();
    y = pdf.startCurrentPage();
  }

  y = drawRlcSectionTitle(
    doc,
    "Unterschriften",
    y
  );

if (y > pdf.contentBottom() - 180) {
    pdf.addPage();
    y = pdf.startCurrentPage();
  }

  y = drawRlcSectionTitle(
    doc,
    "Unterschriften",
    y
  );

  const signatures = input.signatures || [];

  const contractor = signatures.find(
    (s) =>
      String(s.role).toUpperCase() ===
      "AUFTRAGNEHMER"
  );

  const client = signatures.find(
    (s) =>
      String(s.role).toUpperCase() ===
      "AUFTRAGGEBER"
  );

  const signatureWidth = (width - gap) / 2;

  for (const entry of [
    {
      x: x0,
      title: "Auftragnehmer",
      signature: contractor,
    },
    {
      x: x0 + signatureWidth + gap,
      title: "Auftraggeber",
      signature: client,
    },
  ]) {
    doc
      .roundedRect(
        entry.x,
        y,
        signatureWidth,
        120,
        6
      )
      .stroke("#DCE5F0");

    doc
      .fillColor(RLC_PDF_THEME.blueDark)
      .font("Helvetica-Bold")
      .fontSize(9)
      .text(
        entry.title,
        entry.x + 10,
        y + 10,
        {
          width: signatureWidth - 20,
        }
      );

    if (entry.signature) {
      const image = signatureBuffer(
        entry.signature.imageData
      );

      if (image) {
        try {
          doc.image(
            image,
            entry.x + 12,
            y + 30,
            {
              fit: [
                signatureWidth - 24,
                52,
              ],
              align: "center",
            }
          );
        } catch {
        }
      }

      doc
        .font("Helvetica")
        .fontSize(8)
        .fillColor("#172033")
        .text(
          rlcFirstText(
            entry.signature.name,
            "Unterschrieben"
          ),
          entry.x + 10,
          y + 88,
          {
            width: signatureWidth - 20,
          }
        );

      if (entry.signature.signedAt) {
        doc
          .fontSize(7.5)
          .fillColor(RLC_PDF_THEME.muted)
          .text(
            rlcGermanDate(
              String(
                entry.signature.signedAt
              )
            ),
            entry.x + 10,
            y + 103,
            {
              width: signatureWidth - 20,
            }
          );
      }
    } else {
      doc
        .font("Helvetica")
        .fontSize(8)
        .fillColor(RLC_PDF_THEME.muted)
        .text(
          "Nicht unterschrieben",
          entry.x + 10,
          y + 55,
          {
            width: signatureWidth - 20,
            align: "center",
          }
        );
    }
  }

  await pdf.finish();

  const fileName =
    path.basename(input.pdfPath);

  const context =
    resolveRlcPdfPathContext(
      input.pdfPath
    );

  const relative = path
    .relative(
      context.projectRoot,
      input.pdfPath
    )
    .split(path.sep)
    .map(encodeURIComponent)
    .join("/");

  const pdfUrl =
    `/projects/${encodeURIComponent(
      context.projectKey
    )}/${relative}`;

  return {
    filePath: input.pdfPath,
    pdfUrl,
    fileName,
  };
}

import {
  createRlcPdfDocument,
  drawRlcInfoField,
  drawRlcSectionTitle,
  RLC_PDF_THEME,
  type RlcPdfCompany,
} from "./rlcPdfCore";

export type KaufmaennischePdfInput = {
  pdfPath: string;
  projectId?: string;
  projectName?: string;
  title?: string;
  date?: string;
  documentId?: string;
  company?: RlcPdfCompany;
  data?: any;
  payload?: any;
  document?: any;
};

function s(value: unknown): string {
  return String(value ?? "").trim();
}

function n(value: unknown): number {
  const parsed = Number(
    typeof value === "string"
      ? value.replace(/\s/g, "").replace(/\./g, "").replace(",", ".")
      : value
  );

  return Number.isFinite(parsed) ? parsed : 0;
}

function money(value: unknown): string {
  return new Intl.NumberFormat("de-DE", {
    style: "currency",
    currency: "EUR",
  }).format(n(value));
}

function number(value: unknown, digits = 3): string {
  return new Intl.NumberFormat("de-DE", {
    minimumFractionDigits: 0,
    maximumFractionDigits: digits,
  }).format(n(value));
}

function array(value: unknown): any[] {
  return Array.isArray(value) ? value : [];
}

function resolveRows(source: any): any[] {
  return (
    array(source?.rows).length
      ? array(source.rows)
      : array(source?.items).length
        ? array(source.items)
        : array(source?.positions).length
          ? array(source.positions)
          : array(source?.lines).length
            ? array(source.lines)
            : array(source?.data?.rows)
  );
}

function resolveDocumentType(input: KaufmaennischePdfInput): string {
  const source = input.data || input.payload || input.document || {};
  const raw = s(
    source.documentType ||
    source.type ||
    source.art ||
    input.title
  ).toLowerCase();

  if (raw.includes("schluss")) return "Schlussrechnung";
  if (raw.includes("abschlag")) return "Abschlagsrechnung";
  if (raw.includes("angebot")) return "Angebot";
  if (raw.includes("menge")) return "Mengenermittlung";
  if (raw.includes("rechnung")) return "Rechnung";

  return input.title || "Dokument";
}

export async function createKaufmaennischesDokumentPdf(
  input: KaufmaennischePdfInput
) {
  const source = input.data || input.payload || input.document || {};
  const project = source.project || {};

  const documentType = resolveDocumentType(input);

  const projectId = s(
    input.projectId ||
    source.projectId ||
    source.projectKey ||
    project.id ||
    project.code ||
    "Projekt"
  );

  const projectName = s(
    input.projectName ||
    source.projectName ||
    source.projectTitle ||
    project.name ||
    project.title ||
    projectId
  );

  const clientName = s(
    source.clientName ||
    source.auftraggeber ||
    source.client?.name ||
    project.client ||
    project.auftraggeber
  );

  const date = s(
    input.date ||
    source.date ||
    source.datum ||
    source.options?.dateISO ||
    new Date().toISOString().slice(0, 10)
  ).slice(0, 10);

  const documentNumber = s(
    input.documentId ||
    source.documentId ||
    source.number ||
    source.nr ||
    source.offerNo ||
    source.angebotNr ||
    source.rechnungNr
  );

  const rows = resolveRows(source);
  const totals = source.totals || source.summary || {};

  const pdf = createRlcPdfDocument({
    pdfPath: input.pdfPath,
    title: documentType,
    documentType,
    projectId,
    projectName,
    date,
    company: input.company || source.company,
    subject: `${documentType} ${projectId}`,
  });

  const { doc } = pdf;

  let y = pdf.startCurrentPage();

  const marginX = RLC_PDF_THEME.marginX;
  const contentWidth = doc.page.width - marginX * 2;
  const gap = 8;
  const fieldWidth = (contentWidth - gap * 3) / 4;

  drawRlcInfoField(
    doc,
    marginX,
    y,
    fieldWidth,
    documentType === "Angebot" ? "Angebot Nr." : "Dokument Nr.",
    documentNumber || "?"
  );

  drawRlcInfoField(
    doc,
    marginX + fieldWidth + gap,
    y,
    fieldWidth,
    "Projekt",
    projectId
  );

  drawRlcInfoField(
    doc,
    marginX + (fieldWidth + gap) * 2,
    y,
    fieldWidth,
    "Auftraggeber",
    clientName || "?"
  );

  drawRlcInfoField(
    doc,
    marginX + (fieldWidth + gap) * 3,
    y,
    fieldWidth,
    "Datum",
    date
  );

  y += 64;

  y = drawRlcSectionTitle(
    doc,
    documentType === "Mengenermittlung"
      ? "Ermittelte Mengen"
      : "Leistungspositionen",
    y
  );

  const columns =
    documentType === "Mengenermittlung"
      ? [
          { label: "Pos.", x: 34, width: 60 },
          { label: "Leistungsbeschreibung", x: 98, width: 282 },
          { label: "ME", x: 384, width: 38 },
          { label: "Menge", x: 426, width: 70, align: "right" as const },
          { label: "Faktor", x: 500, width: 61, align: "right" as const },
        ]
      : [
          { label: "Pos.", x: 34, width: 54 },
          { label: "Leistungsbeschreibung", x: 92, width: 235 },
          { label: "ME", x: 331, width: 32 },
          { label: "Menge", x: 367, width: 52, align: "right" as const },
          { label: "EP", x: 423, width: 62, align: "right" as const },
          { label: "Gesamt", x: 489, width: 72, align: "right" as const },
        ];

  function drawTableHeader() {
    if (y > pdf.contentBottom() - 45) {
      y = pdf.addPage();
    }

    doc
      .roundedRect(marginX, y, contentWidth, 24, 4)
      .fill(RLC_PDF_THEME.blueSoft);

    doc
      .font("Helvetica-Bold")
      .fontSize(8)
      .fillColor(RLC_PDF_THEME.blueDark);

y = pdf.addPage();
    }

    doc
      .roundedRect(marginX, y, contentWidth, 24, 4)
      .fill(RLC_PDF_THEME.blueSoft);

    doc
      .font("Helvetica-Bold")
      .fontSize(8)
      .fillColor(RLC_PDF_THEME.blueDark);

    for (const column of columns) {
      doc.text(column.label, column.x, y + 8, {
        width: column.width,
        align: column.align || "left",
      });
    }

    y += 30;
  }

  drawTableHeader();

  let calculatedNet = 0;

  for (const row of rows) {
    const position = s(
      row.posNr ||
      row.lvPos ||
      row.position ||
      row.pos ||
      row.nr
    );

    const description = [
      s(row.kurztext || row.text || row.title || row.bezeichnung),
      s(row.langtext),
      s(row.rechenansatz || row.formula || row.formel),
    ]
      .filter(Boolean)
      .join("\n");

    const unit = s(row.einheit || row.unit || row.me);
    const qty = n(
      row.menge ??
      row.qty ??
      row.quantity ??
      row.ergebnis ??
      row.result ??
      row.ist
    );

    const factor = n(row.faktor ?? row.factor ?? 1) || 1;

    const ep = n(
      row.finalUnitPrice ??
      row.rlcKiUnitPrice ??
      row.preis ??
      row.ep ??
      row.unitPrice
    );

    const total = n(
      row.gesamt ??
      row.total ??
      row.zeilen ??
      row.rlcKiTotal ??
      qty * ep
    );

    calculatedNet += total;

    const descriptionWidth =
      documentType === "Mengenermittlung" ? 274 : 225;

    const rowHeight = Math.max(
      28,
      doc.heightOfString(description || "?", {
        width: descriptionWidth,
        lineGap: 1,
      }) + 12
    );

    if (y + rowHeight > pdf.contentBottom()) {
      y = pdf.addPage();
      drawTableHeader();
    }

    doc
      .font("Helvetica")
      .fontSize(7.6)
      .fillColor(RLC_PDF_THEME.text);

    const values =
      documentType === "Mengenermittlung"
        ? [
            position || "?",
            description || "?",
            unit || "?",
            number(qty),
            number(factor),
          ]
        : [
            position || "?",
            description || "?",
            unit || "?",
            number(qty),
            money(ep),
            money(total),
          ];

    values.forEach((value, index) => {
      const column = columns[index];

      doc.text(value, column.x, y + 5, {
        width: column.width,
        align: column.align || "left",
        lineGap: 1,
      });
    });

    doc
      .strokeColor(RLC_PDF_THEME.line)
      .lineWidth(0.35)
      .moveTo(marginX, y + rowHeight)
      .lineTo(marginX + contentWidth, y + rowHeight)
      .stroke();

    y += rowHeight + 4;
  }

  if (documentType !== "Mengenermittlung") {
    const netto = n(
      totals.netto ??
      totals.totalNet ??
      totals.summeNetto ??
      source.netto ??
      calculatedNet
    );

    const mwstRate = n(
      totals.mwstRate ??
      source.mwstRate ??
      source.mwst ??
      source.options?.mwst ??
      19
    );

    const tax = n(
      totals.steuer ??
      totals.tax ??
      totals.mwst ??
      netto * mwstRate / 100
    );

    const brutto = n(
      totals.brutto ??
      totals.totalGross ??
      source.brutto ??
      netto + tax
    );

    if (y > pdf.contentBottom() - 130) {
      y = pdf.addPage();
    }

    y = drawRlcSectionTitle(doc, "Summen", y);

    const sumWidth = (contentWidth - gap * 2) / 3;

    drawRlcInfoField(
      doc,
      marginX,
      y,
      sumWidth,
      "Netto",
      money(netto)
    );

    drawRlcInfoField(
      doc,
      marginX + sumWidth + gap,
      y,
      sumWidth,
      `MwSt. ${number(mwstRate, 2)} %`,
      money(tax)
    );

    drawRlcInfoField(
      doc,
      marginX + (sumWidth + gap) * 2,
      y,
      sumWidth,
      "Brutto",
      money(brutto)
    );

    y += 70;

    const paymentText = s(
      source.payment ||
      source.zahlungsbedingungen ||
      source.options?.payment
    );

    if (paymentText) {
      doc
        .font("Helvetica")
        .fontSize(9)
        .fillColor(RLC_PDF_THEME.text)
        .text(paymentText, marginX, y, {
          width: contentWidth,
        });
    }
  }

  await pdf.finish();

  return {
    pdfPath: input.pdfPath,
    rowCount: rows.length,
    documentType,
  };
}

import path from "path";
import {
  RLC_PDF_THEME,
  createRlcPdfDocument,
  drawRlcInfoField,
  drawRlcRoundedBox,
  drawRlcSectionTitle,
  resolveRlcPdfPathContext,
  rlcFirstText,
  rlcGermanDate,
  rlcGermanNumber,
  rlcNumber,
  type RlcPdfAsset,
  type RlcPdfCompany,
} from "./rlcPdfCore";
import {
  drawRlcPhotoDocumentation,
  drawRlcSignatureSection,
  drawRlcTextPanel,
  uniqueRlcAssets,
} from "./rlcDocumentBlocks";

export type LieferscheinPdfInput = {
  pdfPath: string;
  projectId: string;
  projectName?: string;
  date?: string;
  lieferscheinNummer?: string;
  supplier?: string;
  site?: string;
  driver?: string;
  material?: string;
  quantity?: number | string;
  unit?: string;
  kostenstelle?: string;
  lvItemPos?: string | null;
  comment?: string;
  bemerkungen?: string;
  attachments?: RlcPdfAsset[];
  photos?: RlcPdfAsset[];
  company?: RlcPdfCompany;
  rows?: any[];
};

function normalizedRows(input: LieferscheinPdfInput): any[] {
  const rows = Array.isArray(input.rows) && input.rows.length ? input.rows : [input];
  return rows.filter(Boolean);
}

export async function createLieferscheinPdf(
  input: LieferscheinPdfInput
): Promise<{ filePath: string; pdfUrl: string; fileName: string }> {
  const rows = normalizedRows(input);
  const first = rows[0] || input;
  const safeDate = rlcFirstText(input.date, first.date, new Date().toISOString().slice(0, 10)).slice(0, 10);
  const projectName = rlcFirstText(input.projectName, first.projectName, first.site, input.projectId);
  const lsNumber = rlcFirstText(input.lieferscheinNummer, first.lieferscheinNummer, first.number);
  const supplier = rlcFirstText(input.supplier, first.supplier, first.lieferant);
  const site = rlcFirstText(input.site, first.site, first.baustelle, projectName);
  const driver = rlcFirstText(input.driver, first.driver, first.fahrer);
  const costCenter = rlcFirstText(input.kostenstelle, first.kostenstelle, first.costCenter);
  const notes = rlcFirstText(input.bemerkungen, first.bemerkungen, first.notes);

  const assets = uniqueRlcAssets([
    ...(input.photos || []),
    ...(input.attachments || []),
    ...rows.flatMap((row) => [
      ...(Array.isArray(row?.photos) ? row.photos : []),
      ...(Array.isArray(row?.attachments) ? row.attachments : []),
      ...(Array.isArray(row?.files) ? row.files : []),
    ]),
  ]);

  const pdf = createRlcPdfDocument({
    pdfPath: input.pdfPath,
    title: "Lieferschein",
    documentType: "Lieferschein",
    projectId: input.projectId,
    projectName,
    date: safeDate,
    company: input.company,
    subject: `Lieferschein ${lsNumber || safeDate}`,
  });

  const { doc } = pdf;
  const runtime = { doc, addPage: pdf.addPage, contentBottom: pdf.contentBottom };
  let y = pdf.startCurrentPage();
  const x0 = RLC_PDF_THEME.marginX;
  const width = doc.page.width - x0 * 2;
  const gap = 8;

  const quarter = (width - gap * 3) / 4;
  drawRlcInfoField(doc, x0, y, quarter, "LS-Nr.", lsNumber);
  drawRlcInfoField(doc, x0 + quarter + gap, y, quarter, "Datum", rlcGermanDate(safeDate));
  drawRlcInfoField(doc, x0 + (quarter + gap) * 2, y, quarter, "Projekt", projectName);
  drawRlcInfoField(doc, x0 + (quarter + gap) * 3, y, quarter, "Kostenstelle", costCenter);
  y += 58;

  const half = (width - gap) / 2;
  drawRlcInfoField(doc, x0, y, half, "Lieferant / Anschrift", supplier, 54);
  drawRlcInfoField(doc, x0 + half + gap, y, half, "Baustelle / Lieferort", site, 54);
  y += 64;

  drawRlcInfoField(doc, x0, y, half, "Fahrer / Fahrzeug", driver);
  drawRlcInfoField(doc, x0 + half + gap, y, half, "Positionen", String(rows.length));
  y += 62;

  y = drawRlcSectionTitle(doc, "Lieferpositionen", y);

  const columns = [
    { key: "lv", label: "LV-Pos.", width: 70 },
    { key: "material", label: "Material / Leistung", width: 210 },
    { key: "quantity", label: "Menge", width: 70, align: "right" as const },
    { key: "unit", label: "Einheit", width: 55 },
    { key: "comment", label: "Beschreibung", width: width - 405 },
  ];

  const drawHeader = () => {
    doc.roundedRect(x0, y, width, 24, 5).fill(RLC_PDF_THEME.blueDark);
    let x = x0;
    for (const column of columns) {
      doc
        .fillColor(RLC_PDF_THEME.white)
        .font("Helvetica-Bold")
        .fontSize(7.7)
        .text(column.label, x + 5, y + 8, {
          width: column.width - 10,
          align: column.align || "left",
          lineBreak: false,
          ellipsis: true,
        });
      x += column.width;
    }
    y += 28;
  };

  drawHeader();

  for (let index = 0; index < rows.length; index++) {
    const row = rows[index] || {};
    const quantityRaw = row.quantity ?? row.qty ?? input.quantity;
    const values: Record<string, string> = {
      lv: rlcFirstText(row.lvItemPos, row.lvPos, input.lvItemPos),
      material: rlcFirstText(row.material, input.material),
      quantity: rlcNumber(quantityRaw) ? rlcGermanNumber(quantityRaw) : rlcFirstText(quantityRaw),
      unit: rlcFirstText(row.unit, input.unit),
      comment: rlcFirstText(row.comment, row.text, input.comment),
    };

    let rowHeight = 36;
    for (const column of columns) {
      rowHeight = Math.max(
        rowHeight,
        doc.font("Helvetica").fontSize(7.8).heightOfString(values[column.key] || "—", {
          width: column.width - 10,
          align: column.align || "left",
        }) + 14
      );
    }
    rowHeight = Math.min(rowHeight, 76);

    if (y + rowHeight > pdf.contentBottom()) {
      y = pdf.addPage();

rowHeight = Math.max(
        rowHeight,
        doc.font("Helvetica").fontSize(7.8).heightOfString(values[column.key] || "—", {
          width: column.width - 10,
          align: column.align || "left",
        }) + 14
      );
    }
    rowHeight = Math.min(rowHeight, 76);

    if (y + rowHeight > pdf.contentBottom()) {
      y = pdf.addPage();
      y = drawRlcSectionTitle(doc, "Lieferpositionen", y);
      drawHeader();
    }

    drawRlcRoundedBox(
      doc,
      x0,
      y,
      width,
      rowHeight,
      index % 2 === 0 ? RLC_PDF_THEME.white : RLC_PDF_THEME.background,
      RLC_PDF_THEME.line,
      4
    );

    let x = x0;
    for (const column of columns) {
      doc
        .fillColor(RLC_PDF_THEME.text)
        .font("Helvetica")
        .fontSize(7.8)
        .text(values[column.key] || "—", x + 5, y + 7, {
          width: column.width - 10,
          height: rowHeight - 12,
          ellipsis: true,
          align: column.align || "left",
        });
      x += column.width;
    }
    y += rowHeight + 5;
  }

  const descriptions = rows
    .map((row) => rlcFirstText(row?.comment, row?.text))
    .filter(Boolean)
    .join("\n");
  const combinedNotes = [descriptions, notes].filter(Boolean).join("\n\n");
  if (combinedNotes) y = drawRlcTextPanel(runtime, "Beschreibung und Bemerkungen", combinedNotes, y);

  y = drawRlcSignatureSection(runtime, y, ["Lieferant / Fahrer", "Empfänger / Bauleitung"]);
  y = drawRlcPhotoDocumentation(runtime, input.pdfPath, assets, y);

  await pdf.finish();

  const fileName = path.basename(input.pdfPath);
  const context = resolveRlcPdfPathContext(input.pdfPath);
  const relative = path
    .relative(context.projectRoot, input.pdfPath)
    .split(path.sep)
    .map(encodeURIComponent)
    .join("/");
  const pdfUrl = `/projects/${encodeURIComponent(context.projectKey)}/${relative}`;

  return { filePath: input.pdfPath, pdfUrl, fileName };
}

import PDFDocument from "pdfkit";
import fs from "fs";

export default {
  create(items: any[], outPath: string) {
    return new Promise<void>((resolve, reject) => {
      const doc = new PDFDocument({ margin: 32 });
      const stream = fs.createWriteStream(outPath);
      doc.pipe(stream);

      doc.fontSize(18).text("Mängelprotokoll", { align: "center" });
      doc.moveDown();

      items.forEach((m, idx) => {
        doc.fontSize(12).text(`${idx+1}. ${m.titel}  [${m.prioritaet}]  —  Status: ${m.status}`);
        doc.fontSize(10).text(`Kategorie: ${m.kategorie}    Ort: ${m.ort||"-"}    Fällig: ${m.faelligAm||"-"}`);
        doc.text(`LV-Pos.: ${m.lvPos||"-"}    Regiebericht: ${m.regieberichtId||"-"}`);
        if (m.beschreibung) doc.text(m.beschreibung);
        if (m.notiz) doc.text("Notiz: " + m.notiz);

        if (m.foto) {
          try {
            const local = m.foto.startsWith("/files/") ? "uploads" + m.foto.replace("/files","") : m.foto;
            if (fs.existsSync(local)) { doc.moveDown(0.3); doc.image(local, { width: 220 }); }
          } catch {}
        }
        doc.moveDown();
        doc.moveTo(32, doc.y).lineTo(580, doc.y).strokeColor("#dddddd").stroke();
        doc.moveDown();
      });

      doc.end();
      stream.on("finish", resolve);
      stream.on("error", reject);
    });
  }
};

import type { Request } from "express";
import type { RlcPdfCompany } from "./rlcPdfCore";

function text(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "string" || typeof value === "number") {
    return String(value).trim();
  }
  return "";
}

function first(...values: unknown[]): string {
  for (const value of values) {
    const result = text(value);
    if (result) return result;
  }
  return "";
}

function unwrap(payload: any): any {
  let current = payload;
  for (let index = 0; index < 5; index++) {
    if (!current || typeof current !== "object") break;
    const next =
      current.company ||
      current.header ||
      current.data ||
      current.profile ||
      current.settings;
    if (!next || next === current) break;
    current = next;
  }
  return current && typeof current === "object" ? current : {};
}

function forwardedHeaders(req: Request): Record<string, string> {
  const headers: Record<string, string> = { Accept: "application/json" };
  for (const name of [
    "authorization",
    "cookie",
    "x-company-id",
    "x-rlc-company-id",
    "x-tenant-id",
    "x-request-id",
  ]) {
    const raw = req.headers[name];
    if (Array.isArray(raw)) headers[name] = raw.join(",");
    else if (raw) headers[name] = String(raw);
  }
  return headers;
}

async function fetchInternal(req: Request, endpoints: string[]): Promise<Response | null> {
  const base = `http://127.0.0.1:${process.env.PORT || 4000}`;
  const headers = forwardedHeaders(req);

  for (const endpoint of endpoints) {
    try {
      const response = await fetch(`${base}${endpoint}`, { headers });
      if (response.ok) return response;
    } catch (error) {
      console.warn(`[RLC PDF] Company endpoint ${endpoint} nicht erreichbar`, error);
    }
  }

  return null;
}

export async function loadRlcPdfCompanyFromRequest(
  req: Request
): Promise<RlcPdfCompany | undefined> {
  const headerResponse = await fetchInternal(req, [
    "/api/company/header",
    "/api/company/admin/header",
    "/api/company/admin/dashboard",
  ]);

  let rawHeader: any = {};
  if (headerResponse) {
    try {
      rawHeader = await headerResponse.json();
    } catch {
      rawHeader = {};
    }
  }

  const source = unwrap(rawHeader);
  const address =
    source?.address && typeof source.address === "object" ? source.address : {};

  let logoDataUrl = first(
    source?.logoDataUrl,
    source?.logo?.dataUrl,
    source?.branding?.logoDataUrl
  );

  if (!logoDataUrl) {
    const logoResponse = await fetchInternal(req, [
      "/api/company/logo",
      "/api/company/admin/logo",
    ]);

    if (logoResponse) {
      try {
        const contentType = logoResponse.headers.get("content-type") || "image/png";
        const logoBuffer = Buffer.from(await logoResponse.arrayBuffer());
        if (logoBuffer.length > 0) {
          logoDataUrl = `data:${contentType};base64,${logoBuffer.toString("base64")}`;
        }
      } catch (error) {
        console.warn("[RLC PDF] Firmenlogo konnte nicht gelesen werden", error);
      }
    }
  }

  const company: RlcPdfCompany = {
    name: first(
      source?.name,
      source?.companyName,
      source?.firmenname,
      source?.firma,
      source?.legalName
    ),
    legalName: first(source?.legalName, source?.companyLegalName),
    street: first(
      source?.street,
      source?.strasse,
      source?.adresse,
      typeof source?.address === "string" ? source.address : "",
      address?.street,
      address?.addressLine1
    ),
    postalCode: first(
      source?.postalCode,
      source?.zip,
      source?.plz,
      address?.postalCode,
      address?.zip
    ),
    city: first(source?.city, source?.ort, address?.city),
    country: first(source?.country, source?.land, address?.country),
    phone: first(source?.phone, source?.telefon, source?.contact?.phone),
    mobile: first(source?.mobile, source?.mobil, source?.contact?.mobile),
    email: first(source?.email, source?.mail, source?.contact?.email),
    website: first(source?.website, source?.web, source?.url),
    taxNumber: first(source?.taxNumber, source?.steuernummer),
    vatId: first(source?.vatId, source?.ustId, source?.ustIdNr),
    iban: first(source?.iban, source?.bank?.iban),
    bic: first(source?.bic, source?.bank?.bic),
    bankName: first(source?.bankName, source?.bank?.name),
    managingDirector: first(
      source?.managingDirector,
      source?.geschaeftsfuehrer,
      source?.owner
    ),
    logoDataUrl,
  };

  const useful = Boolean(
    company.name || company.street || company.phone || company.email || company.logoDataUrl
  );

  console.log("[RLC PDF] Firmendaten", {
    loaded: useful,
    name: company.name || null,
    hasAddress: Boolean(company.street || company.city),
    hasPhone: Boolean(company.phone || company.mobile),
    hasEmail: Boolean(company.email),
    hasLogo: Boolean(company.logoDataUrl),
  });

  return useful ? company : undefined;
}

