]);

const MAX_FILE_BYTES = 600_000;
const MAX_CHUNK_CHARS = 5_500;
const CHUNK_OVERLAP_LINES = 12;

function norm(value: unknown): string {
  return String(value ?? "")
    .replace(/\r/g, "")
    .replace(/[ \t]+/g, " ")
    .trim();
}

function searchable(value: unknown): string {
  return String(value ?? "")
    .replace(/ä/g, "ae")
    .replace(/ö/g, "oe")
    .replace(/ü/g, "ue")
    .replace(/Ä/g, "Ae")
    .replace(/Ö/g, "Oe")
    .replace(/Ü/g, "Ue")
    .replace(/ß/g, "ss")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[_./\\-]+/g, " ")
    .replace(/[^\p{L}\p{N}]+/gu, " ")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function terms(value: unknown): string[] {
  return Array.from(
    new Set(
      searchable(value)
        .split(" ")
        .map((x) => x.trim())
        .filter((x) => x.length >= 2)
    )
  );
}

function relativeFile(file: string): string {
  return path
    .relative(REPO_ROOT, file)
    .replace(/\\/g, "/");
}

function hash(value: string): string {
  return crypto
    .createHash("sha1")
    .update(value)
    .digest("hex")
    .slice(0, 16);
}

function walk(dir: string): string[] {
  if (!fs.existsSync(dir)) return [];

  const out: string[] = [];

  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.name.startsWith(".")) continue;

    if (entry.isDirectory()) {
      if (SKIP_DIRS.has(entry.name)) continue;
      out.push(...walk(path.join(dir, entry.name)));
      continue;
    }

    const full = path.join(dir, entry.name);
    const ext = path.extname(entry.name).toLowerCase();

    if (!ALLOWED_EXT.has(ext)) continue;

    try {
      if (fs.statSync(full).size > MAX_FILE_BYTES) continue;
    } catch {
      continue;
    }

    out.push(full);
  }

  return out;
}

function detectKind(
  file: string,
  platform: Platform
): SourceKind {
  const f = file.toLowerCase();

  if (platform === "MOBILE" && f.includes("/screens/")) return "SCREEN";
  if (platform === "WEB" && f.includes("/pages/")) return "PAGE";

  if (
    platform === "SERVER" &&
    (
      f.includes("/routes/") ||
      /\.routes?\.ts$/.test(f)
    )
  ) {
    return "ROUTE";
  }

  if (f.includes("/services/")) return "SERVICE";
  if (f.includes("/components/")) return "COMPONENT";
  if (f.includes("/api/")) return "API";
  if (f.includes("/exporters/")) return "EXPORTER";
  if (f.includes("store.")) return "STORE";
  if (f.includes("/lib/")) return "LIB";

  if (
    f.endsWith(".json") ||
    f.includes("config") ||
    f.includes("tsconfig")
  ) {
    return "CONFIG";
  }

  return "OTHER";
}

