import path from "path";

export type StorageConfig = {
  provider: "local" | "s3";
  localRoot: string;
  s3: {
    endpoint?: string;
    region: string;
    bucket: string;
    accessKeyId?: string;
    secretAccessKey?: string;
    forcePathStyle: boolean;
  };
};

function required(name: string, value?: string): string {
  if (!value?.trim()) throw new Error(`[storage] Missing environment variable ${name}`);
  return value.trim();
}

export function loadStorageConfig(): StorageConfig {
  const provider = (process.env.STORAGE_PROVIDER || "local").toLowerCase();
  if (provider !== "local" && provider !== "s3") {
    throw new Error(`[storage] Unsupported STORAGE_PROVIDER=${provider}`);
  }

  const config: StorageConfig = {
    provider,
    localRoot: path.resolve(process.env.STORAGE_LOCAL_ROOT || process.env.PROJECTS_ROOT || "/app/data/projects"),
    s3: {
      endpoint: process.env.S3_ENDPOINT?.trim() || undefined,
      region: process.env.S3_REGION?.trim() || "eu-central-1",
      bucket: process.env.S3_BUCKET?.trim() || "rlc-storage",
      accessKeyId: process.env.S3_ACCESS_KEY?.trim() || undefined,
      secretAccessKey: process.env.S3_SECRET_KEY?.trim() || undefined,
      forcePathStyle: String(process.env.S3_FORCE_PATH_STYLE || "false").toLowerCase() === "true",
    },
  };

  if (provider === "s3") {
    required("S3_BUCKET", process.env.S3_BUCKET);
    required("S3_ACCESS_KEY", process.env.S3_ACCESS_KEY);
    required("S3_SECRET_KEY", process.env.S3_SECRET_KEY);
  }

  return config;
}

import fs from "fs";
import path from "path";
import type { PutInput, StorageHealth, StorageProvider } from "../types";

export class LocalStorageProvider implements StorageProvider {
  readonly name = "local";
  constructor(private readonly root: string) {
    fs.mkdirSync(root, { recursive: true });
  }

  private resolve(key: string): string {
    const normalized = key.replace(/\\/g, "/").replace(/^\/+/, "");
    const absolute = path.resolve(this.root, normalized);
    const base = path.resolve(this.root) + path.sep;
    if (absolute !== path.resolve(this.root) && !absolute.startsWith(base)) {
      throw new Error("Invalid storage key");
    }
    return absolute;
  }

  async health(): Promise<StorageHealth> {
    try {
      await fs.promises.access(this.root, fs.constants.R_OK | fs.constants.W_OK);
      return { ok: true, provider: this.name, endpoint: this.root };
    } catch (error: any) {
      return { ok: false, provider: this.name, endpoint: this.root, error: error?.message || String(error) };
    }
  }

  async put(input: PutInput): Promise<void> {
    const target = this.resolve(input.key);
    await fs.promises.mkdir(path.dirname(target), { recursive: true });
    await fs.promises.writeFile(target, input.body);
  }

  get(key: string): Promise<Buffer> { return fs.promises.readFile(this.resolve(key)); }
  async delete(key: string): Promise<void> { await fs.promises.rm(this.resolve(key), { force: true }); }
  async exists(key: string): Promise<boolean> { try { await fs.promises.access(this.resolve(key)); return true; } catch { return false; } }
  async presignPut(): Promise<string> { throw new Error("Presigned URLs require STORAGE_PROVIDER=s3"); }
  async presignGet(): Promise<string> { throw new Error("Presigned URLs require STORAGE_PROVIDER=s3"); }
}

import {
  DeleteObjectCommand,
  GetObjectCommand,
  HeadBucketCommand,
  HeadObjectCommand,
  PutObjectCommand,
  S3Client,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";
import type { StorageConfig } from "../config";
import type { PutInput, StorageHealth, StorageProvider } from "../types";

async function streamToBuffer(body: any): Promise<Buffer> {
  if (!body) return Buffer.alloc(0);
  if (typeof body.transformToByteArray === "function") {
    return Buffer.from(await body.transformToByteArray());
  }
  const chunks: Buffer[] = [];
  for await (const chunk of body) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
  return Buffer.concat(chunks);
}

export class S3StorageProvider implements StorageProvider {
  readonly name = "s3";
  readonly bucket: string;
  readonly endpoint?: string;
  readonly client: S3Client;

  constructor(config: StorageConfig["s3"]) {
    this.bucket = config.bucket;
    this.endpoint = config.endpoint;
    this.client = new S3Client({
      region: config.region,
      endpoint: config.endpoint,
      forcePathStyle: config.forcePathStyle,
      credentials: config.accessKeyId && config.secretAccessKey
        ? { accessKeyId: config.accessKeyId, secretAccessKey: config.secretAccessKey }
        : undefined,
    });
  }

  async health(): Promise<StorageHealth> {
    try {
      await this.client.send(new HeadBucketCommand({ Bucket: this.bucket }));
      return { ok: true, provider: this.name, bucket: this.bucket, endpoint: this.endpoint };
    } catch (error: any) {
      return {
        ok: false,
        provider: this.name,
        bucket: this.bucket,
        endpoint: this.endpoint,
        error: error?.message || String(error),
      };
    }
  }

  async put(input: PutInput): Promise<void> {
    await this.client.send(new PutObjectCommand({
      Bucket: this.bucket,
      Key: input.key,
      Body: input.body,
      ContentType: input.contentType,
      Metadata: input.metadata,
    }));
  }

  async get(key: string): Promise<Buffer> {
    const result = await this.client.send(new GetObjectCommand({ Bucket: this.bucket, Key: key }));
    return streamToBuffer(result.Body);
  }

  async delete(key: string): Promise<void> {
    await this.client.send(new DeleteObjectCommand({ Bucket: this.bucket, Key: key }));
  }

  async exists(key: string): Promise<boolean> {
    try {
      await this.client.send(new HeadObjectCommand({ Bucket: this.bucket, Key: key }));
      return true;
    } catch (error: any) {
      if (error?.$metadata?.httpStatusCode === 404 || error?.name === "NotFound") return false;
      throw error;
    }
  }

  presignPut(key: string, contentType = "application/octet-stream", expiresIn = 900): Promise<string> {
    return getSignedUrl(this.client, new PutObjectCommand({
      Bucket: this.bucket,
      Key: key,
      ContentType: contentType,
    }), { expiresIn });
  }

  presignGet(key: string, expiresIn = 900): Promise<string> {
    return getSignedUrl(this.client, new GetObjectCommand({ Bucket: this.bucket, Key: key }), { expiresIn });
  }
}

